//! First closed AV1 leaf-block reconstruction class.
//!
//! This module is decoder-private codec machinery. It is deliberately not a
//! reusable transform, prediction, color-conversion, or raster-processing API.

// AV1 block coordinates are validated against the frame and tile geometry
// before reaching this module. The decoder then uses saturating/checked
// coordinate arithmetic together with bounded slice accessors while mirroring
// the specification's fixed-size block equations. Keep this exception local
// to the block decoder; it does not weaken the crate's no-raw-pointer policy.
#![allow(clippy::arithmetic_side_effects)]

use super::entropy::RangeDecoder;
use super::geometry::{BlockSize, IntraTxPlan, PixelLayout, TxSize};
use super::large_cdfs::{
    LargeCoefficientCdfDefaults, QCAT1_LARGE_COEFFICIENT_CDFS, QCAT3_LARGE_COEFFICIENT_CDFS,
};
use super::mc::{MotionScratch, PredictionRequest, blend_obmc_left, blend_obmc_top};
use super::motion::{
    InterpolationFilter, MotionVector, PreparedGlobalWarp, PreparedLocalWarp, ScaleFactors,
};
use super::quantization;
use super::sample_depth::SampleDepth;
use super::surface::FrameSurface;
use super::tile_state::NeighborMeta;
use super::transform;
use bytemuck::cast;
use wide::{i16x8, i32x8, u16x8};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) struct PortableUnavailable;

pub(super) type PortableResult<T> = Result<T, PortableUnavailable>;

trait PortableOptionExt<T> {
    fn portable(self) -> PortableResult<T>;
}

impl<T> PortableOptionExt<T> for Option<T> {
    fn portable(self) -> PortableResult<T> {
        self.ok_or(PortableUnavailable)
    }
}

type TransformCoefficients = [i32; 16];
type PlaneCoefficients = [TransformCoefficients; 64];
type LosslessSquare64TransformCoefficients = [TransformCoefficients; 256];

/// Maximum number of 4x4 transform-edge contexts retained by the complete
/// lossless 4:4:4 walker.  The 64-pixel rectangular grids use sixteen edge
/// segments on their long axis; Square64 remains closed because it needs 256
/// transform carriers rather than a wider edge array.
const LOSSLESS444_NEIGHBOR_CAPACITY: usize = 16;

/// Maximum number of four-pixel neighbor leaves needed to cover one complete
/// 128-pixel AV1 edge.  The monochrome frame walker keeps this bounded array
/// instead of allocating a temporary list while assembling intra references.
pub(super) const MONOCHROME_NEIGHBOR_CAPACITY: usize = 32;
type LossyTransformCoefficients = [i32; 64];
type Lossy4x8TransformCoefficients = [i32; 32];
type Lossy16x16TransformCoefficients = [i32; 256];
type Lossy32x32TransformCoefficients = [i32; 1024];
type Lossy16x32TransformCoefficients = [i32; 512];
type Lossy16x64TransformCoefficients = [i32; 512];
type LossyRectTransformCoefficients = [i32; 128];
type Lossy16x8TransformCoefficients = [i32; 128];
type Lossy8x32TransformCoefficients = [i32; 256];
type Lossy8x16TransformCoefficients = [i32; 128];
type Lossy4x16TransformCoefficients = [i32; 64];
type Lossy32x16TransformCoefficients = [i32; 512];
type Lossy64x16TransformCoefficients = [i32; 512];
type Lossy32x8TransformCoefficients = [i32; 256];
type Lossy16x4TransformCoefficients = [i32; 64];
type LossyLuma4x4SplitCoefficients = [Option<TransformCoefficients>; 4];
type LossyLuma4x4GridSplitCoefficients = [Option<TransformCoefficients>; 8];
type LossyLuma8x4SplitCoefficients = [Option<Lossy4x8TransformCoefficients>; 2];
type LossyLuma8x8SplitCoefficients = [Option<LossyTransformCoefficients>; 4];
type LossyLuma8x8GridSplitCoefficients = [Option<LossyTransformCoefficients>; 8];
type LossyLuma16x16SplitCoefficients = [Option<Lossy16x16TransformCoefficients>; 4];

const PALETTE_CAPACITY: usize = 8;
const MAX_PALETTE_MAP_SAMPLES: usize = 64 * 64;
const MAX_PALETTE_LEAF_SAMPLES: usize = MAX_PALETTE_MAP_SAMPLES * 2;

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct PalettePlane {
    size: u8,
    colors: [u16; PALETTE_CAPACITY],
}

impl PalettePlane {
    const fn is_present(self) -> bool {
        self.size != 0
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(super) struct PaletteCacheState {
    y: PalettePlane,
    u: PalettePlane,
}

/// Generation-checked ownership of one exact coded palette index map.
///
/// Palette maps are reconstructed before the next leaf starts, so a compact
/// descriptor keeps `BlockSyntax` copyable without retaining a 4 KiB inline
/// array. Geometry travels with the span so no consumer can infer a height
/// from unused arena capacity.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PaletteMapSpan {
    offset: u16,
    len: u16,
    stride: u16,
    width: u16,
    height: u16,
    generation: u64,
}

#[derive(Clone, Copy)]
struct PaletteMapView<'a> {
    indices: &'a [u8],
    stride: usize,
    width: usize,
    height: usize,
}

/// Reusable exact palette-map storage for one decoded leaf.
struct PaletteMapArena {
    generation: u64,
    indices: Vec<u8>,
}

impl PaletteMapArena {
    fn new() -> Self {
        Self {
            generation: 0,
            indices: Vec::new(),
        }
    }

    fn begin_leaf(&mut self) -> PortableResult<()> {
        self.generation = self.generation.checked_add(1).portable()?;
        self.indices.clear();
        Ok(())
    }

    fn allocate_map(&mut self, width: usize, height: usize) -> PortableResult<PaletteMapSpan> {
        let len = width.checked_mul(height).portable()?;
        (self.generation != 0
            && width != 0
            && height != 0
            && width <= 64
            && height <= 64
            && len <= MAX_PALETTE_MAP_SAMPLES)
            .then_some(())
            .portable()?;
        let offset = self.indices.len();
        let end = offset.checked_add(len).portable()?;
        (end <= MAX_PALETTE_LEAF_SAMPLES).then_some(()).portable()?;
        self.indices
            .try_reserve(end.saturating_sub(self.indices.len()))
            .map_err(|_| PortableUnavailable)?;
        self.indices.resize(end, 0);
        Ok(PaletteMapSpan {
            offset: u16::try_from(offset).map_err(|_| PortableUnavailable)?,
            len: u16::try_from(len).map_err(|_| PortableUnavailable)?,
            stride: u16::try_from(width).map_err(|_| PortableUnavailable)?,
            width: u16::try_from(width).map_err(|_| PortableUnavailable)?,
            height: u16::try_from(height).map_err(|_| PortableUnavailable)?,
            generation: self.generation,
        })
    }

    fn range(&self, span: PaletteMapSpan) -> PortableResult<std::ops::Range<usize>> {
        (span.generation == self.generation
            && span.width == span.stride
            && span.len != 0
            && usize::from(span.len) <= MAX_PALETTE_MAP_SAMPLES
            && usize::from(span.len)
                == usize::from(span.stride)
                    .checked_mul(usize::from(span.height))
                    .ok_or(PortableUnavailable)?)
        .then_some(())
        .portable()?;
        let start = usize::from(span.offset);
        let end = start.checked_add(usize::from(span.len)).portable()?;
        (end <= self.indices.len() && self.indices.len() <= MAX_PALETTE_LEAF_SAMPLES)
            .then_some(start..end)
            .portable()
    }

    fn map_mut(&mut self, span: PaletteMapSpan) -> PortableResult<&mut [u8]> {
        let range = self.range(span)?;
        self.indices.get_mut(range).portable()
    }

    fn view(&self, span: PaletteMapSpan) -> PortableResult<PaletteMapView<'_>> {
        let range = self.range(span)?;
        Ok(PaletteMapView {
            indices: self.indices.get(range).portable()?,
            stride: usize::from(span.stride),
            width: usize::from(span.width),
            height: usize::from(span.height),
        })
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct PaletteSyntax {
    y: PalettePlane,
    u: PalettePlane,
    v: PalettePlane,
    y_map: Option<PaletteMapSpan>,
    uv_map: Option<PaletteMapSpan>,
}

impl PaletteSyntax {
    const fn is_present(self) -> bool {
        self.y.is_present() || self.u.is_present() || self.v.is_present()
    }

    const fn cache_state(self) -> PaletteCacheState {
        PaletteCacheState {
            y: self.y,
            u: self.u,
        }
    }

    fn y_view(self, arena: &PaletteMapArena) -> PortableResult<PaletteMapView<'_>> {
        (self.y.is_present() && self.y_map.is_some())
            .then_some(())
            .portable()?;
        arena.view(self.y_map.ok_or(PortableUnavailable)?)
    }

    fn uv_view(self, arena: &PaletteMapArena) -> PortableResult<PaletteMapView<'_>> {
        ((self.u.is_present() || self.v.is_present()) && self.uv_map.is_some())
            .then_some(())
            .portable()?;
        arena.view(self.uv_map.ok_or(PortableUnavailable)?)
    }

    fn validate_for_geometry(
        self,
        arena: &PaletteMapArena,
        geometry: PaletteGeometry,
        chroma_sampling: ChromaSampling,
        sample_depth: SampleDepth,
    ) -> PortableResult<()> {
        fn validate_plane(
            plane: PalettePlane,
            map: Option<PaletteMapView<'_>>,
            geometry: PalettePlaneGeometry,
            maximum: u16,
        ) -> PortableResult<()> {
            if !plane.is_present() {
                return map.is_none().then_some(()).portable();
            }
            let size = usize::from(plane.size);
            (size >= 2 && size <= PALETTE_CAPACITY)
                .then_some(())
                .portable()?;
            plane
                .colors
                .get(..size)
                .filter(|colors| colors.iter().all(|&color| color <= maximum))
                .is_some()
                .then_some(())
                .portable()?;
            let map = map.ok_or(PortableUnavailable)?;
            (map.stride == geometry.coded_width
                && map.width == geometry.coded_width
                && map.height == geometry.coded_height
                && map.indices.len()
                    == geometry
                        .coded_width
                        .checked_mul(geometry.coded_height)
                        .ok_or(PortableUnavailable)?
                && map.indices.iter().all(|&index| usize::from(index) < size))
            .then_some(())
            .portable()
        }

        let y_map = self.y_map.map(|span| arena.view(span)).transpose()?;
        validate_plane(self.y, y_map, geometry.y, sample_depth.maximum())?;
        let has_u = self.u.is_present();
        let has_v = self.v.is_present();
        (has_u == has_v && (!has_u || self.u.size == self.v.size))
            .then_some(())
            .portable()?;
        if matches!(chroma_sampling, ChromaSampling::Monochrome) {
            (!has_u && !has_v && self.uv_map.is_none() && geometry.uv.is_none())
                .then_some(())
                .portable()?;
        } else {
            let uv_geometry = geometry.uv.ok_or(PortableUnavailable)?;
            let uv_map = self.uv_map.map(|span| arena.view(span)).transpose()?;
            validate_plane(self.u, uv_map, uv_geometry, sample_depth.maximum())?;
            if has_v {
                let size = usize::from(self.v.size);
                self.v
                    .colors
                    .get(..size)
                    .filter(|colors| {
                        size >= 2
                            && size <= PALETTE_CAPACITY
                            && colors.iter().all(|&color| color <= sample_depth.maximum())
                    })
                    .is_some()
                    .then_some(())
                    .portable()?;
            }
        }
        Ok(())
    }
}

/// Padded-frame palette extent in luma pixels for the current coded block.
///
/// This differs from the nominal block size only at the right or bottom
/// coded-frame boundary. AV1 still stores the resulting map with the nominal
/// coded stride and repeats the final decoded column/row into the clipped
/// region.
#[derive(Clone, Copy)]
struct PaletteEntropyDimensions {
    width: u32,
    height: u32,
}

impl PaletteEntropyDimensions {
    fn from_visible(
        block_size: BlockSize,
        visible_width: u32,
        visible_height: u32,
    ) -> PortableResult<Self> {
        let (coded_width, coded_height) = block_size.pixel_dimensions();
        let width = visible_width
            .div_ceil(4)
            .checked_mul(4)
            .portable()?
            .min(coded_width);
        let height = visible_height
            .div_ceil(4)
            .checked_mul(4)
            .portable()?
            .min(coded_height);
        (visible_width != 0
            && visible_height != 0
            && visible_width <= coded_width
            && visible_height <= coded_height
            && width != 0
            && height != 0)
            .then_some(Self { width, height })
            .portable()
    }
}

#[derive(Clone, Copy)]
struct PalettePlaneGeometry {
    coded_width: usize,
    coded_height: usize,
    entropy_width: usize,
    entropy_height: usize,
}

#[derive(Clone, Copy)]
struct PaletteGeometry {
    y: PalettePlaneGeometry,
    uv: Option<PalettePlaneGeometry>,
}

impl PaletteGeometry {
    fn new(
        block_size: BlockSize,
        chroma_sampling: ChromaSampling,
        entropy_dimensions: Option<PaletteEntropyDimensions>,
    ) -> PortableResult<Self> {
        fn subsampled_axis(
            coded: usize,
            entropy: usize,
            subsampled: bool,
        ) -> PortableResult<(usize, usize)> {
            if !subsampled {
                return Ok((coded, entropy));
            }
            (coded.is_multiple_of(4) && entropy.is_multiple_of(4))
                .then_some(())
                .portable()?;
            // Chroma palette dimensions are expressed in complete 4x4
            // chroma units. Convert each eight-luma-pixel span independently
            // and round a partial final span up; this also promotes a 4px
            // sub-8 luma axis to one complete 4px chroma unit.
            let coded = coded.div_ceil(8).checked_mul(4).portable()?;
            let entropy = entropy.div_ceil(8).checked_mul(4).portable()?;
            Ok((coded, entropy))
        }

        let (coded_width, coded_height) = block_size.pixel_dimensions();
        let entropy_dimensions = entropy_dimensions.unwrap_or(PaletteEntropyDimensions {
            width: coded_width,
            height: coded_height,
        });
        (entropy_dimensions.width != 0
            && entropy_dimensions.height != 0
            && entropy_dimensions.width <= coded_width
            && entropy_dimensions.height <= coded_height
            && entropy_dimensions.width % 4 == 0
            && entropy_dimensions.height % 4 == 0)
            .then_some(())
            .portable()?;
        let coded_width = usize::try_from(coded_width).map_err(|_| PortableUnavailable)?;
        let coded_height = usize::try_from(coded_height).map_err(|_| PortableUnavailable)?;
        let entropy_width =
            usize::try_from(entropy_dimensions.width).map_err(|_| PortableUnavailable)?;
        let entropy_height =
            usize::try_from(entropy_dimensions.height).map_err(|_| PortableUnavailable)?;
        let y = PalettePlaneGeometry {
            coded_width,
            coded_height,
            entropy_width,
            entropy_height,
        };
        let uv = match chroma_sampling {
            ChromaSampling::Monochrome => None,
            ChromaSampling::Full => Some(y),
            ChromaSampling::Subsampled420 | ChromaSampling::Subsampled422 => {
                let (coded_width, entropy_width) =
                    subsampled_axis(coded_width, entropy_width, true)?;
                let subsampled_y = matches!(chroma_sampling, ChromaSampling::Subsampled420);
                let (coded_height, entropy_height) =
                    subsampled_axis(coded_height, entropy_height, subsampled_y)?;
                Some(PalettePlaneGeometry {
                    coded_width,
                    coded_height,
                    entropy_width,
                    entropy_height,
                })
            }
        };
        Ok(Self { y, uv })
    }
}

