/// Shape tag for one coefficient payload owned by a large full-resolution
/// chroma transform. The two rectangles have different scans, context
/// neighborhoods, and inverse transforms even though their active storage
/// lengths are equal.
#[derive(Clone, Copy, PartialEq, Eq)]
enum FullLargeChromaShape {
    Vertical16x32,
    Horizontal32x16,
    Square32,
}

impl FullLargeChromaShape {
    const fn coefficient_count(self) -> usize {
        match self {
            Self::Vertical16x32 | Self::Horizontal32x16 => 512,
            Self::Square32 => 1024,
        }
    }
}

/// Checked ownership descriptor for one transform stored in the decoder's
/// reusable large-coefficient arena. Keeping the payload out of `BlockSyntax`
/// avoids copying up to 32 KiB every time syntax is dispatched while the
/// generation prevents a descriptor from observing a later leaf's storage.
#[derive(Clone, Copy)]
struct FullLargeChromaCoefficients {
    shape: FullLargeChromaShape,
    offset: u16,
    len: u16,
    generation: u32,
}

struct LargeCoefficientScratch {
    tokens: Vec<u32>,
    levels: Vec<u8>,
    nonzero_positions: Vec<usize>,
}

impl LargeCoefficientScratch {
    fn new() -> Self {
        Self {
            tokens: Vec::new(),
            levels: Vec::new(),
            nonzero_positions: Vec::new(),
        }
    }
}

/// One allocation-backed arena is reused for every leaf decoded by a tile
/// walker. A Full S64 block has at most eight active 1024-coefficient chroma
/// children (four U, then four V), so 8192 entries is the exact bounded peak.
struct LargeCoefficientArena {
    generation: u32,
    coefficients: Vec<i32>,
    scratch: LargeCoefficientScratch,
}

/// A leaf-local arena for the TX4x4 carriers of a lossless large full-resolution
/// or monochrome block. The payload is deliberately kept outside
/// `BlockSyntax`: lossy syntax remains compact and `Copy`, while the complete
/// walkers consume each span before decoding the next leaf. The 256-carrier
/// backing store covers the 128-carrier 32x64/64x32 grids and the 256-carrier
/// 64x64 grid without exposing a heap-bearing syntax field.
#[derive(Default)]
struct LosslessSquare64CoefficientArena {
    generation: u32,
    coefficients: Vec<TransformCoefficients>,
}

#[derive(Clone, Copy)]
struct LosslessSquare64CoefficientSpan {
    offset: u16,
    len: u16,
    generation: u32,
}

/// Maximum number of output samples produced by one normative AV1 transform.
/// Coefficients are separately capped to 32x32, but Tx64 output still covers
/// the complete 64x64 prediction rectangle.
const MAX_TRANSFORM_SAMPLES: usize = 64 * 64;

/// Allocation-backed work buffers reused across every transform in one tile.
///
/// `prediction` is needed only when a transform child must later be copied
/// into a strided parent raster. `rows` and `residual` are the two exact
/// inverse-transform passes. Keeping CfL AC separate lets U/V reconstruction
/// borrow it while the transform buffers continue to mutate.
struct TransformScratch {
    prediction: Vec<u16>,
    rows: Vec<i32>,
    residual: Vec<i32>,
}

struct ReconstructionScratch {
    transform: TransformScratch,
    cfl_ac: Vec<i32>,
}

impl ReconstructionScratch {
    fn new() -> Self {
        Self {
            transform: TransformScratch {
                prediction: Vec::with_capacity(MAX_TRANSFORM_SAMPLES),
                rows: Vec::with_capacity(MAX_TRANSFORM_SAMPLES),
                residual: Vec::with_capacity(MAX_TRANSFORM_SAMPLES),
            },
            cfl_ac: Vec::with_capacity(MAX_TRANSFORM_SAMPLES),
        }
    }
}

impl LargeCoefficientArena {
    const MAX_COEFFICIENTS: usize = 8192;

    fn new() -> Self {
        Self {
            generation: 0,
            coefficients: Vec::new(),
            scratch: LargeCoefficientScratch::new(),
        }
    }

    fn begin_leaf(&mut self) {
        self.generation = self.generation.wrapping_add(1);
        if self.generation == 0 {
            self.generation = 1;
        }
        self.coefficients.clear();
        self.scratch.tokens.clear();
        self.scratch.levels.clear();
        self.scratch.nonzero_positions.clear();
    }

    fn coefficients(&self, span: FullLargeChromaCoefficients) -> PortableResult<&[i32]> {
        (span.generation == self.generation
            && usize::from(span.len) == span.shape.coefficient_count())
        .then_some(())
        .portable()?;
        let start = usize::from(span.offset);
        let end = start.checked_add(usize::from(span.len)).portable()?;
        self.coefficients.get(start..end).portable()
    }
}

impl LosslessSquare64CoefficientArena {
    const TRANSFORM_COUNT: usize = 16 * 16;
    const MAX_COEFFICIENTS: usize = 3 * Self::TRANSFORM_COUNT;

    fn new() -> Self {
        Self::default()
    }

    fn begin_leaf(&mut self) -> PortableResult<()> {
        self.generation = self.generation.wrapping_add(1);
        if self.generation == 0 {
            self.generation = 1;
        }
        self.coefficients.clear();
        self.coefficients
            .try_reserve_exact(Self::MAX_COEFFICIENTS)
            .map_err(|_| PortableUnavailable)
    }

    fn store(
        &mut self,
        coefficients: &[TransformCoefficients],
    ) -> PortableResult<LosslessSquare64CoefficientSpan> {
        (!coefficients.is_empty() && coefficients.len() <= Self::MAX_COEFFICIENTS)
            .then_some(())
            .portable()?;
        let offset = u16::try_from(self.coefficients.len()).map_err(|_| PortableUnavailable)?;
        let end = self
            .coefficients
            .len()
            .checked_add(coefficients.len())
            .ok_or(PortableUnavailable)?;
        (end <= Self::MAX_COEFFICIENTS).then_some(()).portable()?;
        self.coefficients.extend_from_slice(coefficients);
        Ok(LosslessSquare64CoefficientSpan {
            offset,
            len: u16::try_from(coefficients.len()).map_err(|_| PortableUnavailable)?,
            generation: self.generation,
        })
    }

    fn coefficients(
        &self,
        span: LosslessSquare64CoefficientSpan,
    ) -> PortableResult<&[TransformCoefficients]> {
        (span.generation == self.generation
            && usize::from(span.len) <= Self::MAX_COEFFICIENTS
            && span.len != 0)
            .then_some(())
            .portable()?;
        let start = usize::from(span.offset);
        let end = start
            .checked_add(usize::from(span.len))
            .ok_or(PortableUnavailable)?;
        self.coefficients.get(start..end).portable()
    }
}

#[derive(Clone, Copy)]
