/// One normalized unsplit transform payload.
///
/// `coefficients` retains AV1's compact column-major coefficient window;
/// `width` and `height` are the coded transform dimensions.  Keeping both
/// dimensions beside the slice avoids guessing orientation from legacy field
/// names such as `lossy_luma_4x8_coefficients`, which intentionally carries
/// both R4x8 and R8x4 syntax.
struct CoeffBlockRef<'a> {
    width: usize,
    height: usize,
    coefficients: Option<&'a [i32]>,
    transform: Av1TransformType,
}

/// Maximum complete coded intra edge. A 128x128 block needs 128 top plus 128
/// left samples; terminal-transform prediction still consumes only the exact
/// checked prefix for that transform.
pub(super) const MAX_INTRA_EDGE_SAMPLES: usize = 256;
const MAX_CFL_BORDER: usize = 4;
const MAX_CFL_STRIP_SAMPLES: usize = MAX_INTRA_EDGE_SAMPLES * 2;

/// Reconstructed luma samples immediately before a narrow subsampled owner.
///
/// AV1's minimum chroma transform is 4×4. A luma block with a four-pixel
/// subsampled axis therefore owns chroma covering the preceding four luma
/// pixels on that axis as well. The frame canvas supplies those causal strips
/// before the current leaf is decoded; reconstruction combines them with the
/// current luma plane when (and only when) CfL is selected.
#[derive(Clone, Debug)]
pub(super) struct CflLumaContext {
    above: [u16; MAX_CFL_STRIP_SAMPLES],
    left: [u16; MAX_CFL_STRIP_SAMPLES],
    corner: [u16; MAX_CFL_BORDER * MAX_CFL_BORDER],
    missing_x: usize,
    missing_y: usize,
}

impl CflLumaContext {
    const fn current_only() -> Self {
        Self {
            above: [0; MAX_CFL_STRIP_SAMPLES],
            left: [0; MAX_CFL_STRIP_SAMPLES],
            corner: [0; MAX_CFL_BORDER * MAX_CFL_BORDER],
            missing_x: 0,
            missing_y: 0,
        }
    }

    pub(super) fn prepare(
        luma_width: usize,
        luma_height: usize,
        missing_x: usize,
        missing_y: usize,
        above: &[u16],
        left: &[u16],
        corner: &[u16],
    ) -> PortableResult<Self> {
        (missing_x <= MAX_CFL_BORDER && missing_y <= MAX_CFL_BORDER)
            .then_some(())
            .portable()?;
        let above_len = luma_width.checked_mul(missing_y).portable()?;
        let left_len = luma_height.checked_mul(missing_x).portable()?;
        let corner_len = missing_x.checked_mul(missing_y).portable()?;
        (above.len() == above_len
            && left.len() == left_len
            && corner.len() == corner_len
            && above_len <= MAX_CFL_STRIP_SAMPLES
            && left_len <= MAX_CFL_STRIP_SAMPLES
            && corner_len <= MAX_CFL_BORDER * MAX_CFL_BORDER)
            .then_some(())
            .portable()?;
        let mut context = Self::current_only();
        context.above[..above_len].copy_from_slice(above);
        context.left[..left_len].copy_from_slice(left);
        context.corner[..corner_len].copy_from_slice(corner);
        context.missing_x = missing_x;
        context.missing_y = missing_y;
        Ok(context)
    }
}

impl Lossy420Decoder {
    #[expect(
        clippy::too_many_arguments,
        reason = "the mixed square compositor carries topology, prediction, entropy edges, quantization, raster, and callback state explicitly"
    )]
    fn decode_inter_split_luma_square_topology(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        prediction: &[u16],
        raster: &mut PrivatePlaneRaster,
        quantization: LossyQuantization,
        tools: BlockTools,
        coefficient_contexts: InterCoefficientContexts,
        topology: SquareSplitTopology,
        qindex_policy: InterSplitQindexPolicy,
        decode_transform_type: &mut impl FnMut(
            &mut RangeDecoder<'_, '_, '_>,
            TxSize,
        ) -> PortableResult<Av1TransformType>,
    ) -> PortableResult<(LosslessGridContexts, Av1TransformType)> {
        let (block_width, child_tx_size, split_tx_size, child_splits) = match topology {
            SquareSplitTopology::B16 { child_splits } => {
                (16_usize, TxSize::Tx8x8, TxSize::Tx4x4, child_splits)
            }
            SquareSplitTopology::B32 { child_splits } => {
                (32_usize, TxSize::Tx16x16, TxSize::Tx8x8, child_splits)
            }
        };
        let block_height = block_width;
        let sample_count = block_width.checked_mul(block_height).portable()?;
        let grid_width = block_width.checked_div(4).portable()?;
        let grid_height = grid_width;
        let (child_width, child_height) = (
            block_width.checked_div(2).portable()?,
            block_height.checked_div(2).portable()?,
        );
        let child_cell_width = child_width.checked_div(4).portable()?;
        let child_cell_height = child_height.checked_div(4).portable()?;
        let split_width = child_width.checked_div(2).portable()?;
        let split_height = child_height.checked_div(2).portable()?;
        let split_cell_width = split_width.checked_div(4).portable()?;
        let split_cell_height = split_height.checked_div(4).portable()?;
        (prediction.len() == sample_count
            && raster.coded_width == block_width
            && raster.coded_height == block_height
            && raster.active_width == block_width
            && raster.active_height == block_height
            && matches!((grid_width, grid_height), (4, 4) | (8, 8))
            && child_cell_width == child_cell_height
            && split_cell_width == split_cell_height
            && child_tx_size.pixel_dimensions().0
                == u32::try_from(child_width).map_err(|_| PortableUnavailable)?
            && child_tx_size.pixel_dimensions().1
                == u32::try_from(child_height).map_err(|_| PortableUnavailable)?
            && split_tx_size.pixel_dimensions().0
                == u32::try_from(split_width).map_err(|_| PortableUnavailable)?
            && split_tx_size.pixel_dimensions().1
                == u32::try_from(split_height).map_err(|_| PortableUnavailable)?
            && tools.sample_depth == quantization.sample_depth
            && matches!(tools.sample_depth.bits(), 8 | 10 | 12)
            && tools.transform_mode == 2
            && (quantization.segment_qindex > 0
                || (matches!(qindex_policy, InterSplitQindexPolicy::Mode2SplitB16)
                    && block_width == 16)
                || (matches!(qindex_policy, InterSplitQindexPolicy::Mode2SplitB32)
                    && block_width == 32))
            && !quantization.segment_lossless
            && child_splits.iter().flatten().any(|&split| split)
            && child_splits.iter().flatten().any(|&split| !split))
        .then_some(())
        .portable()?;

        let mut residual_contexts =
            [[0x40_u8; LOSSLESS_GRID_EDGE_CAPACITY]; LOSSLESS_GRID_EDGE_CAPACITY];
        let mut first_transform = Av1TransformType::DctDct;
        for child_index in 0_usize..4 {
            let child_row = child_index / 2;
            let child_column = child_index % 2;
            let child_cell_x = child_column.checked_mul(child_cell_width).portable()?;
            let child_cell_y = child_row.checked_mul(child_cell_height).portable()?;
            let child_split = child_splits[child_row][child_column];
            let (
                tx_size,
                terminal_width,
                terminal_height,
                terminal_cell_width,
                terminal_cell_height,
            ) = if child_split {
                (
                    split_tx_size,
                    split_width,
                    split_height,
                    split_cell_width,
                    split_cell_height,
                )
            } else {
                (
                    child_tx_size,
                    child_width,
                    child_height,
                    child_cell_width,
                    child_cell_height,
                )
            };
            let terminal_rows: usize = if child_split { 2 } else { 1 };
            let terminal_columns = terminal_rows;
            for local_row in 0..terminal_rows {
                for local_column in 0..terminal_columns {
                    let cell_x = child_cell_x
                        .checked_add(local_column.checked_mul(terminal_cell_width).portable()?)
                        .portable()?;
                    let cell_y = child_cell_y
                        .checked_add(local_row.checked_mul(terminal_cell_height).portable()?)
                        .portable()?;
                    let above_end = cell_x.checked_add(terminal_cell_width).portable()?;
                    let mut above_context = [0x40_u8; 4];
                    if cell_y == 0 {
                        above_context[..terminal_cell_width].copy_from_slice(
                            coefficient_contexts.above[0]
                                .get(cell_x..above_end)
                                .portable()?,
                        );
                    } else {
                        above_context[..terminal_cell_width].copy_from_slice(
                            residual_contexts[cell_y - 1]
                                .get(cell_x..above_end)
                                .portable()?,
                        );
                    }
                    let left_end = cell_y.checked_add(terminal_cell_height).portable()?;
                    let mut left_context = [0x40_u8; 4];
                    if cell_x == 0 {
                        left_context[..terminal_cell_height].copy_from_slice(
                            coefficient_contexts.left[0]
                                .get(cell_y..left_end)
                                .portable()?,
                        );
                    } else {
                        for (destination, source) in left_context[..terminal_cell_height]
                            .iter_mut()
                            .zip(residual_contexts.get(cell_y..left_end).portable()?.iter())
                        {
                            *destination = source[cell_x - 1];
                        }
                    }
                    let txb_skipped = self.decode_inter_txb_skip(
                        decoder,
                        0,
                        tx_size,
                        block_width,
                        block_height,
                        &above_context[..terminal_cell_width],
                        &left_context[..terminal_cell_height],
                        false,
                    )?;
                    let terminal_transform = if txb_skipped {
                        Av1TransformType::DctDct
                    } else {
                        decode_transform_type(decoder, tx_size)?
                    };
                    let terminal = decode_inter_lossy_terminal(
                        decoder,
                        0,
                        &mut self.cdfs,
                        &mut self.large_coeff_arena,
                        quantization,
                        tx_size,
                        block_width,
                        block_height,
                        &above_context[..terminal_cell_width],
                        &left_context[..terminal_cell_height],
                        txb_skipped,
                        terminal_transform,
                    )?;
                    let coefficients = if terminal.skipped {
                        None
                    } else {
                        Some(
                            self.large_coeff_arena
                                .coefficients
                                .get(..terminal.coefficient_count)
                                .portable()?,
                        )
                    };
                    let offset_x = cell_x.checked_mul(4).portable()?;
                    let offset_y = cell_y.checked_mul(4).portable()?;
                    let sample_count = terminal_width.checked_mul(terminal_height).portable()?;
                    let mut terminal_prediction = Vec::new();
                    terminal_prediction
                        .try_reserve_exact(sample_count)
                        .map_err(|_| PortableUnavailable)?;
                    for row in 0..terminal_height {
                        let source_start = offset_y
                            .checked_add(row)
                            .and_then(|value| value.checked_mul(block_width))
                            .and_then(|value| value.checked_add(offset_x))
                            .portable()?;
                        let source_end = source_start.checked_add(terminal_width).portable()?;
                        terminal_prediction.extend_from_slice(
                            prediction.get(source_start..source_end).portable()?,
                        );
                    }
                    let ReconstructionScratch {
                        transform: scratch, ..
                    } = &mut self.reconstruction_scratch;
                    let TransformScratch { rows, residual, .. } = scratch;
                    reconstruct_full_unsplit_prediction_in_place(
                        &mut terminal_prediction,
                        CoeffBlockRef {
                            width: terminal_width,
                            height: terminal_height,
                            coefficients,
                            transform: match terminal.transform {
                                GenericTerminalTransform::Lossy(value) => value,
                                GenericTerminalTransform::LosslessWht4x4 => {
                                    return Err(PortableUnavailable);
                                }
                            },
                        },
                        tools.sample_depth,
                        rows,
                        residual,
                    )?;
                    raster.commit_transform(
                        offset_x,
                        offset_y,
                        terminal_width,
                        terminal_height,
                        &terminal_prediction,
                        tools.sample_depth,
                    )?;
                    let context_end_x = cell_x.checked_add(terminal_cell_width).portable()?;
                    let context_end_y = cell_y.checked_add(terminal_cell_height).portable()?;
                    for row in cell_y..context_end_y {
                        residual_contexts[row]
                            .get_mut(cell_x..context_end_x)
                            .portable()?
                            .fill(terminal.residual_context);
                    }
                    if child_index == 0 && local_row == 0 && local_column == 0 {
                        first_transform = terminal_transform;
                    }
                }
            }
        }

        let mut right = [0x40_u8; LOSSLESS_GRID_EDGE_CAPACITY];
        let mut bottom = [0x40_u8; LOSSLESS_GRID_EDGE_CAPACITY];
        let last_column = grid_width.checked_sub(1).portable()?;
        let last_row = grid_height.checked_sub(1).portable()?;
        for row in 0..grid_height {
            right[row] = residual_contexts[row][last_column];
        }
        for column in 0..grid_width {
            bottom[column] = residual_contexts[last_row][column];
        }
        Ok((
            LosslessGridContexts {
                bottom_right: residual_contexts[last_row][last_column],
                right,
                bottom,
            },
            first_transform,
        ))
    }
}

impl CflLumaContext {
    #[expect(
        clippy::too_many_arguments,
        reason = "CfL sampling keeps current visible geometry and the aligned extended coordinate explicit"
    )]
    fn sample(
        &self,
        luma: &[u16],
        luma_width: usize,
        luma_height: usize,
        reconstructed_width: usize,
        reconstructed_height: usize,
        source_x: usize,
        source_y: usize,
    ) -> PortableResult<u16> {
        let required_width = self.missing_x.checked_add(luma_width).portable()?;
        let required_height = self.missing_y.checked_add(luma_height).portable()?;
        (source_x < required_width
            && source_y < required_height
            && reconstructed_width != 0
            && reconstructed_width <= luma_width
            && reconstructed_height != 0
            && reconstructed_height <= luma_height)
            .then_some(())
            .portable()?;
        if source_y < self.missing_y {
            if source_x < self.missing_x {
                let index = source_y
                    .checked_mul(self.missing_x)
                    .and_then(|offset| offset.checked_add(source_x))
                    .portable()?;
                return self.corner.get(index).copied().portable();
            }
            let x = source_x.saturating_sub(self.missing_x);
            let index = source_y
                .checked_mul(luma_width)
                .and_then(|offset| offset.checked_add(x))
                .portable()?;
            return self.above.get(index).copied().portable();
        }
        if source_x < self.missing_x {
            let y = source_y.saturating_sub(self.missing_y);
            let index = y
                .checked_mul(self.missing_x)
                .and_then(|offset| offset.checked_add(source_x))
                .portable()?;
            return self.left.get(index).copied().portable();
        }
        let x = source_x
            .saturating_sub(self.missing_x)
            .min(reconstructed_width.saturating_sub(1));
        let y = source_y
            .saturating_sub(self.missing_y)
            .min(reconstructed_height.saturating_sub(1));
        let index = y
            .checked_mul(luma_width)
            .and_then(|offset| offset.checked_add(x))
            .portable()?;
        luma.get(index).copied().portable()
    }
}

/// One normalized contiguous intra edge.
///
/// `logical_len` is the prepared slice exposed to predictors. `valid_len`
/// counts only samples that were both authorized and reconstructed before
/// edge repetition/defaulting; neutral compatibility fill never increases
/// it. The fixed 256-sample capacity covers one maximum 128x128 coded block
/// while terminal-transform predictors borrow only their checked prefix.
#[derive(Clone, Debug)]
struct EdgeLine {
    samples: [u16; MAX_INTRA_EDGE_SAMPLES],
    logical_len: usize,
    valid_len: usize,
}

impl EdgeLine {
    fn prepare(
        input: &[u16],
        logical_len: usize,
        valid_len: usize,
        default: u16,
    ) -> PortableResult<Self> {
        (valid_len <= logical_len
            && logical_len <= MAX_INTRA_EDGE_SAMPLES
            && input.len() >= valid_len)
            .then_some(())
            .portable()?;
        let mut samples = [default; MAX_INTRA_EDGE_SAMPLES];
        if valid_len != 0 {
            samples[..valid_len].copy_from_slice(&input[..valid_len]);
            let repeat = samples[valid_len.saturating_sub(1)];
            samples[valid_len..logical_len].fill(repeat);
        }
        Ok(Self {
            samples,
            logical_len,
            valid_len,
        })
    }

    const fn valid_len(&self) -> usize {
        self.valid_len
    }

    fn as_slice(&self) -> &[u16] {
        &self.samples[..self.logical_len]
    }
}

impl std::ops::Deref for EdgeLine {
    type Target = [u16];

    fn deref(&self) -> &Self::Target {
        self.as_slice()
    }
}

/// Normalized AV1 intra edges for one full-resolution plane.
///
/// The fixed lines are prepared once per block and contain enough repeated
/// extension for every directional zone. Availability and extension flags
/// remain explicit geometry facts; sample equality is never used to infer
/// whether a neighbor exists.
#[derive(Clone, Debug)]
pub(super) struct FullIntraPlaneEdges {
    top: EdgeLine,
    left: EdgeLine,
    top_left: u16,
    has_top: bool,
    has_left: bool,
    have_above_right: bool,
    have_below_left: bool,
    smooth: bool,
}

#[derive(Clone, Debug)]
pub(super) struct FullIntraEdges {
    planes: [FullIntraPlaneEdges; 3],
    cfl_luma: CflLumaContext,
}

impl FullIntraPlaneEdges {
    #[expect(
        clippy::too_many_arguments,
        reason = "edge samples and each AV1 availability fact are independent inputs"
    )]
    pub(super) fn prepare(
        width: usize,
        height: usize,
        sample_depth: SampleDepth,
        top: &[u16],
        left: &[u16],
        top_left: Option<u16>,
        has_top: bool,
        has_left: bool,
        have_above_right: bool,
        have_below_left: bool,
        smooth: bool,
    ) -> PortableResult<Self> {
        Self::prepare_with_valid_lengths(
            width,
            height,
            sample_depth,
            top,
            left,
            top.len(),
            left.len(),
            top_left,
            has_top,
            has_left,
            have_above_right,
            have_below_left,
            smooth,
        )
    }

    #[expect(
        clippy::too_many_arguments,
        reason = "logical edge samples, real-prefix lengths, and each AV1 availability fact are independent inputs"
    )]
    fn prepare_with_valid_lengths(
        width: usize,
        height: usize,
        sample_depth: SampleDepth,
        top: &[u16],
        left: &[u16],
        top_valid_len: usize,
        left_valid_len: usize,
        top_left: Option<u16>,
        has_top: bool,
        has_left: bool,
        have_above_right: bool,
        have_below_left: bool,
        smooth: bool,
    ) -> PortableResult<Self> {
        let edge_length = width.checked_add(height).portable()?;
        (width != 0 && height != 0 && edge_length <= MAX_INTRA_EDGE_SAMPLES)
            .then_some(())
            .portable()?;
        if top_valid_len > top.len()
            || left_valid_len > left.len()
            || (has_top && top.is_empty())
            || (has_left && left.is_empty())
        {
            return Err(PortableUnavailable);
        }
        let top_input_limit = if have_above_right {
            width.saturating_mul(2).min(edge_length)
        } else {
            width.min(edge_length)
        };
        let left_input_limit = if have_below_left {
            height.saturating_mul(2).min(edge_length)
        } else {
            height.min(edge_length)
        };
        // The raster reader proves every supplied sample was reconstructed.
        // At a cropped frame edge the supplied prefix can be shorter than the
        // nominal coded edge; AV1 extends that final real sample across the
        // remaining logical edge, while `valid_len` retains the distinction.
        let top_valid = if has_top {
            top_valid_len.min(top_input_limit)
        } else {
            0
        };
        let left_valid = if has_left {
            left_valid_len.min(left_input_limit)
        } else {
            0
        };
        let first_top = top.first().copied();
        let first_left = left.first().copied();
        let top_default = if has_top {
            first_top.ok_or(PortableUnavailable)?
        } else if has_left {
            first_left.ok_or(PortableUnavailable)?
        } else {
            sample_depth.top_edge_default()
        };
        let left_default = if has_left {
            first_left.ok_or(PortableUnavailable)?
        } else if has_top {
            first_top.ok_or(PortableUnavailable)?
        } else {
            sample_depth.left_edge_default()
        };
        let prepared_top = EdgeLine::prepare(top, edge_length, top_valid, top_default)?;
        let prepared_left = EdgeLine::prepare(left, edge_length, left_valid, left_default)?;
        let top_left = match (has_top, has_left) {
            (true, true) => top_left.ok_or(PortableUnavailable)?,
            (true, false) => first_top.ok_or(PortableUnavailable)?,
            (false, true) => first_left.ok_or(PortableUnavailable)?,
            (false, false) => sample_depth.midpoint(),
        };
        Ok(Self {
            top: prepared_top,
            left: prepared_left,
            top_left,
            has_top,
            has_left,
            have_above_right,
            have_below_left,
            smooth,
        })
    }

    pub(super) fn origin(
        width: usize,
        height: usize,
        sample_depth: SampleDepth,
    ) -> PortableResult<Self> {
        Self::prepare(
            width,
            height,
            sample_depth,
            &[],
            &[],
            None,
            false,
            false,
            false,
            false,
            false,
        )
    }
}

impl FullIntraEdges {
    pub(super) const fn from_planes(planes: [FullIntraPlaneEdges; 3]) -> Self {
        Self {
            planes,
            cfl_luma: CflLumaContext::current_only(),
        }
    }

    pub(super) fn with_cfl_luma(mut self, cfl_luma: CflLumaContext) -> Self {
        self.cfl_luma = cfl_luma;
        self
    }

    fn origin_for_sampling(
        luma_grid_width: usize,
        luma_grid_height: usize,
        chroma_sampling: ChromaSampling,
        sample_depth: SampleDepth,
    ) -> PortableResult<Self> {
        let luma_width = luma_grid_width.checked_mul(4).portable()?;
        let luma_height = luma_grid_height.checked_mul(4).portable()?;
        let (chroma_grid_width, chroma_grid_height) =
            chroma_sampling.transform_grid(luma_grid_width, luma_grid_height, 1);
        let chroma_width = chroma_grid_width.checked_mul(4).portable()?;
        let chroma_height = chroma_grid_height.checked_mul(4).portable()?;
        Ok(Self::from_planes([
            FullIntraPlaneEdges::origin(luma_width, luma_height, sample_depth)?,
            FullIntraPlaneEdges::origin(chroma_width, chroma_height, sample_depth)?,
            FullIntraPlaneEdges::origin(chroma_width, chroma_height, sample_depth)?,
        ]))
    }

    fn plane(&self, plane: usize) -> Option<&FullIntraPlaneEdges> {
        self.planes.get(plane)
    }
}

impl BlockSyntax {
    fn has_luma_transform_split(&self) -> bool {
        self.lossy_luma_64x64_split.is_some()
            || self.lossy_luma_4x4_split.is_some()
            || self.lossy_luma_4x4_grid_split.is_some()
            || self.lossy_luma_8x4_split.is_some()
            || self.lossy_luma_8x8_split.is_some()
            || self.lossy_luma_8x8_grid_split.is_some()
            || self.lossy_luma_16x16_split.is_some()
            || self.lossy_luma_16x16_horizontal_split.is_some()
            || self.lossy_luma_32x16_horizontal_split.is_some()
            || self.lossy_luma_16x16_vertical_split.is_some()
    }

    fn luma_unsplit_carrier_count(&self) -> usize {
        // Two legacy skip branches use the generic 8×8-sized zero carrier as
        // a sentinel even though the coded transform is rectangular or
        // 16×16. It represents no residual and must not compete with the
        // normalized geometry-specific carrier selected below.
        let legacy_zero_skip_alias = matches!(
            self.transform_grid,
            TransformGrid::Horizontal8x4 | TransformGrid::Square16
        ) && self
            .lossy_luma_coefficients
            .as_ref()
            .is_some_and(|values| values.iter().all(|&value| value == 0));
        [
            self.lossy_luma_coefficients.is_some() && !legacy_zero_skip_alias,
            self.lossy_luma_4x8_coefficients.is_some(),
            self.lossy_luma_16x16_coefficients.is_some(),
            self.lossy_luma_32x32_coefficients.is_some(),
            self.lossy_luma_16x32_coefficients.is_some(),
            self.lossy_luma_64x64_coefficients.is_some(),
            self.lossy_luma_8x32_coefficients.is_some(),
            self.lossy_luma_16x64_coefficients.is_some(),
            self.lossy_luma_32x16_coefficients.is_some(),
            self.lossy_luma_32x8_coefficients.is_some(),
            self.lossy_luma_64x16_coefficients.is_some(),
            self.lossy_luma_16x8_coefficients.is_some(),
            self.lossy_luma_rect_coefficients.is_some(),
        ]
        .into_iter()
        .filter(|present| *present)
        .count()
    }

    fn chroma_unsplit_carrier_count(&self, plane: usize) -> PortableResult<usize> {
        let index = plane.checked_sub(1).filter(|&index| index < 2).portable()?;
        Ok([
            self.lossy_chroma_coefficients[index].is_some(),
            self.lossy_chroma_8x8_coefficients[index].is_some(),
            self.lossy_chroma_8x4_coefficients[index].is_some(),
            self.lossy_chroma_16x16_coefficients[index].is_some(),
            self.lossy_chroma_32x32_coefficients[index].is_some(),
            self.lossy_chroma_8x32_coefficients[index].is_some(),
            self.lossy_chroma_8x16_coefficients[index].is_some(),
            self.lossy_chroma_16x32_coefficients[index].is_some(),
            self.lossy_chroma_32x8_coefficients[index].is_some(),
            self.lossy_chroma_4x16_coefficients[index].is_some(),
            self.lossy_chroma_16x4_coefficients[index].is_some(),
            self.lossy_chroma_16x8_coefficients[index].is_some(),
            self.full_large_chroma_grids[index].is_some(),
        ]
        .into_iter()
        .filter(|present| *present)
        .count())
    }

    fn luma_unsplit_transform(
        &self,
        width: usize,
        height: usize,
    ) -> PortableResult<Av1TransformType> {
        if width.max(height) >= 32 {
            if matches!(self.transform_grid, TransformGrid::Vertical16x32)
                && !matches!(
                    self.lossy_luma_16x32_transform,
                    Lossy16x16TransformKind::DctDct
                )
            {
                return Err(PortableUnavailable);
            }
            return Ok(Av1TransformType::DctDct);
        }
        Ok(match self.transform_grid {
            TransformGrid::Square4 | TransformGrid::Square8 => self.lossy_luma_transform.into(),
            TransformGrid::Vertical4x8 | TransformGrid::Vertical4x16 => {
                self.lossy_luma_4x8_transform.into()
            }
            TransformGrid::Horizontal8x4 => self.lossy_luma_4x8_transform.into(),
            TransformGrid::Square16 => self.lossy_luma_16x16_transform.into(),
            TransformGrid::Horizontal16x4 => self.lossy_luma_16x4_transform.into(),
            TransformGrid::Horizontal16x8 => self.lossy_luma_16x8_transform.into(),
            TransformGrid::Vertical8x16 => self.lossy_luma_rect_transform.into(),
            TransformGrid::Vertical16x32 => self.lossy_luma_16x32_transform.into(),
            TransformGrid::Vertical16x64
            | TransformGrid::Vertical32x64
            | TransformGrid::Horizontal32x16
            | TransformGrid::Horizontal64x32
            | TransformGrid::Horizontal64x16
            | TransformGrid::Horizontal32x8
            | TransformGrid::Vertical8x32
            | TransformGrid::Square32
            | TransformGrid::Square64 => Av1TransformType::DctDct,
        })
    }

    fn unsplit_coefficients(&self, plane: usize) -> PortableResult<CoeffBlockRef<'_>> {
        if plane == 0 {
            (!self.has_luma_transform_split())
                .then_some(())
                .portable()?;
        }
        let (grid_width, grid_height, _) = self.transform_grid.properties();
        let (plane_grid_width, plane_grid_height) =
            self.chroma_sampling
                .transform_grid(grid_width, grid_height, plane);
        let width = plane_grid_width.checked_mul(4).portable()?;
        let height = plane_grid_height.checked_mul(4).portable()?;
        let compact_count = width.min(32).checked_mul(height.min(32)).portable()?;

        if plane == 0 {
            let carrier_count = self.luma_unsplit_carrier_count();
            (carrier_count <= 1).then_some(()).portable()?;
            let coefficients: Option<&[i32]> = match self.transform_grid {
                TransformGrid::Square4 => self
                    .lossy_luma_coefficients
                    .as_ref()
                    .map(|values| &values[..16]),
                TransformGrid::Square8
                | TransformGrid::Vertical4x16
                | TransformGrid::Horizontal16x4 => {
                    self.lossy_luma_coefficients.as_ref().map(AsRef::as_ref)
                }
                TransformGrid::Vertical4x8 | TransformGrid::Horizontal8x4 => {
                    self.lossy_luma_4x8_coefficients.as_ref().map(AsRef::as_ref)
                }
                TransformGrid::Square16 => self
                    .lossy_luma_16x16_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Horizontal16x8 => self
                    .lossy_luma_16x8_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Vertical8x16 => self
                    .lossy_luma_rect_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Vertical16x32 => self
                    .lossy_luma_16x32_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Vertical16x64 => self
                    .lossy_luma_16x64_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Horizontal32x16 => self
                    .lossy_luma_32x16_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Horizontal64x16 => self
                    .lossy_luma_64x16_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Horizontal32x8 => self
                    .lossy_luma_32x8_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Vertical8x32 => self
                    .lossy_luma_8x32_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Square32 => self
                    .lossy_luma_32x32_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Square64 => self
                    .lossy_luma_64x64_coefficients
                    .as_ref()
                    .map(AsRef::as_ref),
                TransformGrid::Vertical32x64 | TransformGrid::Horizontal64x32 => {
                    return Err(PortableUnavailable);
                }
            };
            coefficients
                .is_none_or(|values| values.len() == compact_count)
                .then_some(())
                .portable()?;
            (carrier_count == usize::from(coefficients.is_some()))
                .then_some(())
                .portable()?;
            return Ok(CoeffBlockRef {
                width,
                height,
                coefficients,
                transform: self.luma_unsplit_transform(width, height)?,
            });
        }

        let index = plane.checked_sub(1).filter(|&index| index < 2).portable()?;
        let carrier_count = self.chroma_unsplit_carrier_count(plane)?;
        (carrier_count <= 1).then_some(()).portable()?;
        let coefficients: Option<&[i32]> = match (width, height) {
            (4, 4) => self.lossy_chroma_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (4, 8) | (8, 4) => self.lossy_chroma_8x4_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (4, 16) => self.lossy_chroma_4x16_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (8, 8) => self.lossy_chroma_8x8_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (16, 16) => self.lossy_chroma_16x16_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (16, 4) => self.lossy_chroma_16x4_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (16, 8) => self.lossy_chroma_16x8_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (8, 16) => self.lossy_chroma_8x16_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (16, 32) => self.lossy_chroma_16x32_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (32, 8) => self.lossy_chroma_32x8_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (8, 32) => self.lossy_chroma_8x32_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            (32, 32) => self.lossy_chroma_32x32_coefficients[index]
                .as_ref()
                .map(AsRef::as_ref),
            // AV1 caps one transform axis at 32 samples. Larger chroma block
            // footprints require an explicit child grid; never reinterpret a
            // smaller legacy carrier as the whole plane.
            _ => return Err(PortableUnavailable),
        };
        coefficients
            .is_none_or(|values| values.len() == compact_count)
            .then_some(())
            .portable()?;
        (carrier_count == usize::from(coefficients.is_some()))
            .then_some(())
            .portable()?;
        let transform = if width.max(height) >= 32 {
            Av1TransformType::DctDct
        } else {
            Av1TransformType::from(chroma_transform_kind(self.chroma_predictor))
        };
        Ok(CoeffBlockRef {
            width,
            height,
            coefficients,
            transform,
        })
    }
}

#[derive(Clone, Copy)]
struct CdefMetadata {
    active: bool,
    index: usize,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
