/// Shared adaptive block state for the first complete 4:4:4 frame class.
pub(super) struct Lossless444Decoder {
    cdfs: BlockCdfs,
    palette_map_arena: PaletteMapArena,
    lossless_square64_arena: LosslessSquare64CoefficientArena,
    sample_depth: SampleDepth,
}

impl MonochromeLeaf {
    pub(super) fn contains_sample(&self, x: u32, y: u32) -> bool {
        x >= self.origin_x
            && y >= self.origin_y
            && x.saturating_sub(self.origin_x) < self.width
            && y.saturating_sub(self.origin_y) < self.height
    }

    pub(super) const fn origin_x(&self) -> u32 {
        self.origin_x
    }

    pub(super) const fn origin_y(&self) -> u32 {
        self.origin_y
    }

    pub(super) const fn width(&self) -> u32 {
        self.width
    }

    pub(super) const fn height(&self) -> u32 {
        self.height
    }

    pub(super) const fn block_skipped(&self) -> bool {
        self.block_skipped
    }

    pub(super) fn plane(&self) -> &ReconstructedPlane {
        &self.plane
    }

    pub(super) fn into_first_leaf(self) -> FirstLeaf {
        let plane = self.plane;
        FirstLeaf {
            width: self.width,
            height: self.height,
            block_skipped: self.block_skipped,
            planes: [plane.clone(), plane.clone(), plane],
            luma_predictor: self.predictor,
            chroma_predictor: None,
            luma_context: 0x40,
            chroma_contexts: [0x40; 2],
            chroma_right_contexts: [[0x40; 16]; 2],
            chroma_bottom_contexts: [[0x40; 16]; 2],
            tx_context_width: 0,
            tx_context_height: 0,
            luma_transform_split: false,
            luma_right_contexts: std::array::from_fn(|index| self.right_contexts[index]),
            luma_bottom_contexts: std::array::from_fn(|index| self.bottom_contexts[index]),
            wide_coefficient_contexts: None,
            palette_cache: self.palette_cache,
            #[cfg(coverage)]
            entropy_operations: Vec::new(),
        }
    }
}

struct MonochromeDecodeContext<'a> {
    geometry: MonochromeBlockGeometry,
    spatial_luma_context: SpatialLumaContext,
    above_contexts: [u8; 16],
    left_contexts: [u8; 16],
    tools: BlockTools,
    above_left: Option<&'a MonochromeLeaf>,
    above: Option<&'a MonochromeLeaf>,
    above_right: [Option<&'a MonochromeLeaf>; MONOCHROME_NEIGHBOR_CAPACITY],
    left: Option<&'a MonochromeLeaf>,
    left_below: [Option<&'a MonochromeLeaf>; MONOCHROME_NEIGHBOR_CAPACITY],
}

pub(super) struct MonochromeNeighbors<'a> {
    pub(super) above_left: Option<&'a MonochromeLeaf>,
    pub(super) above: Option<&'a MonochromeLeaf>,
    pub(super) above_right: [Option<&'a MonochromeLeaf>; MONOCHROME_NEIGHBOR_CAPACITY],
    pub(super) left: Option<&'a MonochromeLeaf>,
    pub(super) left_below: [Option<&'a MonochromeLeaf>; MONOCHROME_NEIGHBOR_CAPACITY],
}

/// Neighboring reconstructed leaves needed by a vertical 4:2:0 child.
pub(super) struct VerticalNeighbors<'a> {
    pub(super) above_left: &'a FirstLeaf,
    pub(super) above_right: &'a FirstLeaf,
    pub(super) above_left_width: u32,
    pub(super) above_right_width: u32,
    /// Horizontal luma-sample offset of the current block inside the upper-left leaf.
    pub(super) above_left_x_offset: u32,
    /// Horizontal luma-sample offset of the current block's extension inside the upper-right leaf.
    pub(super) above_right_x_offset: u32,
    /// The only following Vertical8x16 filter-intra mode admitted by the
    /// complete-walker witness gate. `None` keeps synthetic/test callers and
    /// all other geometries on the existing unsupported path.
    pub(super) following_v8x16_filter_intra_mode: Option<usize>,
    /// Optional luma leaf immediately after an 8×8 block's top edge. Zone-1
    /// angular prediction uses this continuation without changing the
    /// above-right leaf used by the other transform families.
    pub(super) above_luma_extension: Option<&'a FirstLeaf>,
    pub(super) above_luma_extension_x_offset: u32,
    /// Optional chroma leaf immediately after the current block's top edge.
    /// Chroma Zone-1 prediction needs this continuation independently of the
    /// luma edge extension.
    pub(super) above_chroma_extension: Option<&'a FirstLeaf>,
    pub(super) above_chroma_extension_x_offset: u32,
    /// Coefficient contexts for the complete luma edge immediately above this
    /// block. The partition walker assembles this edge with the current
    /// block's horizontal position, because a large upper leaf can cover more
    /// than the left portion of the current block.
    pub(super) above_luma_contexts: [u8; 16],
    /// Coefficient contexts for the complete chroma edge immediately above
    /// this block, indexed by U/V plane. The walker uses a 4-pixel stride for
    /// I444 and the AV1 8-pixel stride for 4:2:0.
    pub(super) above_chroma_contexts: [[u8; 16]; 2],
    /// Reconstructed chroma leaf immediately above this block. Chroma
    /// availability is not identical to luma availability for a 4:2:0 4×4
    /// leaf: an even/even luma leaf has no coded chroma block.
    pub(super) above_chroma: Option<&'a FirstLeaf>,
    /// Chroma-pixel offset of this block inside `above_chroma`.
    pub(super) above_chroma_x_offset: u32,
    pub(super) left_top: Option<&'a FirstLeaf>,
    /// Left neighbor covering the first luma row of this block. Syntax and
    /// transform-size contexts use this edge; reconstruction may still need
    /// `left` for the final/bottom edge of a taller block.
    pub(super) left_luma_top: Option<&'a FirstLeaf>,
    pub(super) left: Option<&'a FirstLeaf>,
    /// Coefficient contexts for the complete luma edge immediately left of
    /// this block. A vertical block can span several smaller leaves, so the
    /// single `left` pointer is not sufficient to reconstruct this edge.
    pub(super) left_luma_contexts: [u8; 16],
    /// Reconstructed luma samples immediately left of an 8×8 block. The
    /// partition walker assembles this when the edge is split across smaller
    /// neighboring leaves.
    pub(super) left_luma_edge_8: Option<[u16; 8]>,
    /// Reconstructed luma samples immediately left of an 8×16 or 16×16
    /// block. The partition walker returns this only when all rows are
    /// covered by positioned neighboring leaves.
    pub(super) left_luma_edge_16: Option<[u16; 16]>,
    /// Reconstructed luma samples immediately left of a 32×32 block. The
    /// partition walker assembles this from every neighboring leaf because a
    /// single neighbor pointer may cover only the final segment.
    pub(super) left_luma_edge_32: Option<[u16; 32]>,
    /// Coefficient contexts for the complete chroma edge immediately left of
    /// this block, indexed by U/V plane. The walker uses a 4-pixel stride for
    /// I444 and the AV1 8-pixel stride for 4:2:0.
    pub(super) left_chroma_contexts: [[u8; 16]; 2],
    /// Left neighbor covering the first coded chroma row. Luma and chroma
    /// edges do not always select the same leaf when a large luma block
    /// spans several smaller leaves on its left edge.
    pub(super) left_chroma: Option<&'a FirstLeaf>,
    /// Full-resolution chroma samples immediately left of an 8×16 block.
    /// Each entry is complete only when all sixteen rows are covered.
    pub(super) left_chroma_edges_16: [Option<[u16; 16]>; 2],
    /// Luma-row offset of `left` inside the neighboring leaf.
    pub(super) left_y_offset: u32,
    /// Chroma-row offset of `left_chroma` inside the neighboring leaf.
    pub(super) left_chroma_y_offset: u32,
    /// Four luma samples immediately below the current left edge, when the
    /// neighboring leaf covers them. Zone-3 4×4 upsampling needs this edge.
    pub(super) left_luma_bottom: Option<[u16; 8]>,
    /// Four chroma samples immediately below each current left edge, when the
    /// neighboring leaf covers them. Zone-3 4×4 chroma upsampling needs this
    /// continuation because chroma blocks are half the luma height.
    pub(super) left_chroma_bottom: [Option<[u16; 4]>; 2],
    /// Eight full-resolution chroma samples immediately below each current
    /// left edge, when the neighboring leaves cover them. Full-resolution
    /// 8×8 Zone-3 prediction consumes this continuation instead of repeating
    /// the final sample of the primary left edge.
    pub(super) left_full_chroma_bottom_8: [Option<[u16; 8]>; 2],
}

/// Owner-bearing scalar and coefficient context for one following block.
/// Pixel prediction edges are supplied separately by `FullIntraEdges`.
#[derive(Clone, Copy)]
pub(super) struct SpatialNeighbors {
    pub(super) above: Option<NeighborMeta>,
    /// Owner crossing the top sample of the current left edge. Intra mode
    /// context is anchored here even when a tall block spans several owners.
    pub(super) left: Option<NeighborMeta>,
    /// Left-edge owner selected by the partition dispatch for AV1 transform
    /// context: top-left when an above neighbor exists, otherwise the
    /// terminal/bottom-left owner used by a top-row horizontal dispatch.
    pub(super) tx_left: Option<NeighborMeta>,
    pub(super) above_luma_contexts: [u8; 32],
    pub(super) left_luma_contexts: [u8; 32],
    pub(super) above_chroma_contexts: [[u8; 32]; 2],
    pub(super) left_chroma_contexts: [[u8; 32]; 2],
}

/// Spatial state for the streamed all-block intra engine. Prediction edges
/// remain borrowed from the frame canvas while compact owner/context metadata
/// is copied, so no reconstructed neighbor plane is cloned at dispatch.
pub(super) enum LargeIntraSpatial<'a> {
    Origin,
    Following {
        neighbors: SpatialNeighbors,
        edges: &'a FullIntraEdges,
    },
}

pub(super) const fn uses_streamed_intra(_block_size: BlockSize) -> bool {
    true
}

fn legacy_coefficient_contexts(contexts: &[u8; 32]) -> [u8; 16] {
    std::array::from_fn(|index| contexts[index])
}

fn full_resolution_chroma_top_left(neighbors: &VerticalNeighbors<'_>, plane: usize) -> Option<u16> {
    let left_source = neighbors
        .left_chroma
        .and_then(|neighbor| {
            (neighbors.left_chroma_y_offset < neighbor.height)
                .then_some((neighbor, neighbors.left_chroma_y_offset))
        })
        .or_else(|| {
            neighbors.left.and_then(|neighbor| {
                (neighbors.left_y_offset < neighbor.height)
                    .then_some((neighbor, neighbors.left_y_offset))
            })
        });

    if let Some((left, row_offset)) = left_source {
        if row_offset > 0 {
            return Some(
                right_edge_at::<1>(
                    &left.planes[plane],
                    left.width,
                    left.height,
                    row_offset.saturating_sub(1),
                )[0],
            );
        }
        if let Some(left_top) = neighbors.left_top
            && left_top.width > 0
            && left_top.height > 0
        {
            return Some(
                right_edge_at::<1>(
                    &left_top.planes[plane],
                    left_top.width,
                    left_top.height,
                    left_top.height.saturating_sub(1),
                )[0],
            );
        }
    }

    neighbors
        .above_left_x_offset
        .checked_sub(1)
        .filter(|&offset| offset < neighbors.above_left_width)
        .filter(|_| neighbors.above_left.height > 0)
        .map(|offset| {
            bottom_sample_at(
                &neighbors.above_left.planes[plane],
                neighbors.above_left_width,
                offset,
            )
        })
}

/// Neighbors needed by the bounded 8×16 lossy 4:2:0 terminal.
#[allow(
    dead_code,
    reason = "the safe R8x16 terminal is test-backed before full-frame walker integration"
)]
pub(super) struct RectangularNeighbors<'a> {
    pub(super) above_left: Option<&'a FirstLeaf>,
    pub(super) above_right: Option<&'a FirstLeaf>,
    pub(super) left_top: Option<&'a FirstLeaf>,
    pub(super) left_bottom: Option<&'a FirstLeaf>,
}

/// Frame-level delta-loop-filter syntax with tile-local accumulator state
/// intentionally kept outside retained CDF snapshots.
#[derive(Clone, Copy)]
struct DeltaLfSyntax {
    present: bool,
    resolution_log2: u32,
    multi: bool,
    monochrome: bool,
}

impl DeltaLfSyntax {
    const DISABLED: Self = Self {
        present: false,
        resolution_log2: 0,
        multi: false,
        monochrome: false,
    };
}

/// Canonical block-level adaptive state retained by an AV1 reference frame.
///
/// The working decoder still carries a number of fixture-era duplicate
/// coefficient tables.  Those tables and the last-residual scratch values are
/// deliberately absent here: reference CDF publication must retain exactly
/// one normative coefficient family and no block-local scratch.
#[derive(Clone)]
pub(super) struct BlockCdfState {
    coefficient: super::coefficient_cdfs::CoefficientCdfs,
    transform_type: super::coefficient_cdfs::TransformTypeCdfs,
    skip: [[u16; 2]; 3],
    delta_q: [u16; 4],
    delta_lf: [[u16; 4]; 5],
    transform_size: [[[u16; 4]; 3]; 4],
    /// Key/intra luma-mode (`kfym`) state.  This is consumed by key and
    /// intra-only tiles but is intentionally not replaced during reference
    /// CDF publication, matching scalar dav1d's context-update boundary.
    luma_mode: [[u16; 13]; 25],
    luma_angle: [[u16; 7]; 8],
    chroma_mode: [[u16; 13]; 13],
    subsampled_chroma_mode: [[u16; 14]; 13],
    cfl_sign: [u16; 8],
    cfl_alpha: [[u16; 16]; 6],
    palette_y: [[[u16; 2]; 3]; 7],
    palette_uv: [[u16; 2]; 2],
    palette_size: [[[u16; 7]; 7]; 2],
    color_map: [[[[u16; 8]; 5]; 7]; 2],
    use_filter_intra: [[u16; 2]; 22],
    filter_intra: [u16; 5],
}

impl BlockCdfState {
    pub(super) fn defaults_for_qindex(qindex: u32) -> Option<Self> {
        BlockCdfs::defaults_for_qindex([0, 0], qindex).map(|cdfs| cdfs.snapshot())
    }

    /// Publish the canonical coefficient/common-mode subset adapted by an
    /// intra tile while preserving the input key-intra luma table.
    pub(super) fn publish_intra_from(&mut self, adapted: &Self) {
        let luma_mode = self.luma_mode;
        *self = adapted.clone();
        self.reset_counts();
        // `kfym` is outside scalar dav1d's publication/reset subset: retain
        // both its probabilities and the adaptation counts from the input.
        self.luma_mode = luma_mode;
    }

    fn reset_counts(&mut self) {
        fn reset<const N: usize>(cdf: &mut [u16; N], count_index: usize) {
            if let Some(count) = cdf.get_mut(count_index) {
                *count = 0;
            }
        }

        let coefficient = &mut self.coefficient;
        for plane in &mut coefficient.eob_bin_16 {
            for cdf in plane {
                reset(cdf, 4);
            }
        }
        for plane in &mut coefficient.eob_bin_32 {
            for cdf in plane {
                reset(cdf, 5);
            }
        }
        for plane in &mut coefficient.eob_bin_64 {
            for cdf in plane {
                reset(cdf, 6);
            }
        }
        for plane in &mut coefficient.eob_bin_128 {
            for cdf in plane {
                reset(cdf, 7);
            }
        }
        for plane in &mut coefficient.eob_bin_256 {
            for cdf in plane {
                reset(cdf, 8);
            }
        }
        for cdf in &mut coefficient.eob_bin_512 {
            reset(cdf, 9);
        }
        for cdf in &mut coefficient.eob_bin_1024 {
            reset(cdf, 10);
        }
        for tx in &mut coefficient.eob_base_tok {
            for plane in tx {
                for cdf in plane {
                    reset(cdf, 2);
                }
            }
        }
        for tx in &mut coefficient.base_tok {
            for plane in tx {
                for cdf in plane {
                    reset(cdf, 3);
                }
            }
        }
        for tx in &mut coefficient.br_tok {
            for plane in tx {
                for cdf in plane {
                    reset(cdf, 3);
                }
            }
        }
        for tx in &mut coefficient.eob_hi_bit {
            for plane in tx {
                for cdf in plane {
                    reset(cdf, 1);
                }
            }
        }
        for tx in &mut coefficient.skip {
            for cdf in tx {
                reset(cdf, 1);
            }
        }
        for plane in &mut coefficient.dc_sign {
            for cdf in plane {
                reset(cdf, 1);
            }
        }
        for size in &mut self.transform_type.intra1 {
            for cdf in size {
                reset(cdf, 6);
            }
        }
        for size in &mut self.transform_type.intra2 {
            for cdf in size {
                reset(cdf, 4);
            }
        }
        for cdf in &mut self.skip {
            reset(cdf, 1);
        }
        reset(&mut self.delta_q, 3);
        for cdf in &mut self.delta_lf {
            reset(cdf, 3);
        }
        for (row, contexts) in self.transform_size.iter_mut().enumerate() {
            let count_index = row.saturating_add(1).min(2);
            for cdf in contexts {
                reset(cdf, count_index);
            }
        }
        for cdf in &mut self.luma_angle {
            reset(cdf, 6);
        }
        for cdf in &mut self.chroma_mode {
            reset(cdf, 12);
        }
        for cdf in &mut self.subsampled_chroma_mode {
            reset(cdf, 13);
        }
        reset(&mut self.cfl_sign, 7);
        for cdf in &mut self.cfl_alpha {
            reset(cdf, 15);
        }
        for block in &mut self.palette_y {
            for cdf in block {
                reset(cdf, 1);
            }
        }
        for cdf in &mut self.palette_uv {
            reset(cdf, 1);
        }
        for plane in &mut self.palette_size {
            for cdf in plane {
                reset(cdf, 6);
            }
        }
        for plane in &mut self.color_map {
            for (size_index, contexts) in plane.iter_mut().enumerate() {
                for cdf in contexts {
                    // `size_index` is palette size minus two.
                    reset(cdf, size_index.saturating_add(1));
                }
            }
        }
        for cdf in &mut self.use_filter_intra {
            reset(cdf, 1);
        }
        reset(&mut self.filter_intra, 4);
    }
}

