#[allow(
    dead_code,
    reason = "the pinned EOB-15 body remains separately named to preserve its trace provenance"
)]
fn decode_luma_eob_fifteen_trace(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    sign_context: usize,
    cdfs: &mut BlockCdfs,
) -> PortableResult<TransformCoefficients> {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:403-718, src/scan.c:35-40,
    // src/cdf.c:881-907, 1316-1340, and the pinned Slice 28 scalar trace.
    // scan_4x4[15] == 15 is final. The reverse loop visits every remaining
    // AC raster position through contexts proved by the trace.
    (decoder.adaptive_symbol(&mut cdfs.eob_base_luma[3], 2) == 0)
        .then_some(())
        .portable()?;

    for _ in 0..3 {
        (decoder.adaptive_symbol(&mut cdfs.base_luma[22], 3) == 1)
            .then_some(())
            .portable()?;
    }
    (decoder.adaptive_symbol(&mut cdfs.base_luma[23], 3) == 1)
        .then_some(())
        .portable()?;
    (decoder.adaptive_symbol(&mut cdfs.base_luma[22], 3) == 1)
        .then_some(())
        .portable()?;

    (decoder.adaptive_symbol(&mut cdfs.base_luma[7], 3) == 3)
        .then_some(())
        .portable()?;
    let coefficient_three_token = decode_high_token(decoder, &mut cdfs.high_luma[15]);
    (coefficient_three_token == 4).then_some(()).portable()?;
    for _ in 0..2 {
        (decoder.adaptive_symbol(&mut cdfs.base_luma[8], 3) == 1)
            .then_some(())
            .portable()?;
    }
    (decoder.adaptive_symbol(&mut cdfs.base_luma[7], 3) == 3)
        .then_some(())
        .portable()?;
    let coefficient_twelve_token = decode_high_token(decoder, &mut cdfs.high_luma[15]);
    (coefficient_twelve_token == 4).then_some(()).portable()?;
    (decoder.adaptive_symbol(&mut cdfs.base_luma[9], 3) == 3)
        .then_some(())
        .portable()?;
    let coefficient_eight_token = decode_high_token(decoder, &mut cdfs.high_luma[17]);
    (coefficient_eight_token == 4).then_some(()).portable()?;
    (decoder.adaptive_symbol(&mut cdfs.base_luma[9], 3) == 1)
        .then_some(())
        .portable()?;
    (decoder.adaptive_symbol(&mut cdfs.base_luma[9], 3) == 3)
        .then_some(())
        .portable()?;
    let coefficient_two_token = decode_high_token(decoder, &mut cdfs.high_luma[17]);
    (coefficient_two_token == 4).then_some(()).portable()?;
    (decoder.adaptive_symbol(&mut cdfs.base_luma[5], 3) == 3)
        .then_some(())
        .portable()?;
    let coefficient_one_token = decode_high_token(decoder, &mut cdfs.high_luma[10]);
    (coefficient_one_token == 4).then_some(()).portable()?;
    (decoder.adaptive_symbol(&mut cdfs.base_luma[5], 3) == 3)
        .then_some(())
        .portable()?;
    let coefficient_four_token = decode_high_token(decoder, &mut cdfs.high_luma[10]);
    (coefficient_four_token == 4).then_some(()).portable()?;

    // The neighboring levels select DC high-token context five. The nonzero
    // link chain visits all AC positions in raster order 4, 1, 2, 5, 8, 12,
    // 9, 6, 3, 7, 10, 13, 14, 11, and 15.
    let (dc_token, dc_negative) = decode_luma_dc_after_ac(decoder, sign_context, cdfs, 5)?;
    let coefficient_four_negative = decoder.equal();
    let coefficient_one_negative = decoder.equal();
    let coefficient_two_negative = decoder.equal();
    let coefficient_five_negative = decoder.equal();
    let coefficient_eight_negative = decoder.equal();
    let coefficient_twelve_negative = decoder.equal();
    let coefficient_nine_negative = decoder.equal();
    let coefficient_six_negative = decoder.equal();
    let coefficient_three_negative = decoder.equal();
    let coefficient_seven_negative = decoder.equal();
    let coefficient_ten_negative = decoder.equal();
    let coefficient_thirteen_negative = decoder.equal();
    let coefficient_fourteen_negative = decoder.equal();
    let coefficient_eleven_negative = decoder.equal();
    let coefficient_fifteen_negative = decoder.equal();

    let mut coefficients = [0_i32; 16];
    coefficients[0] = dequantize_lossless_coefficient(dc_token, dc_negative);
    coefficients[1] =
        dequantize_lossless_coefficient(coefficient_one_token, coefficient_one_negative);
    coefficients[2] =
        dequantize_lossless_coefficient(coefficient_two_token, coefficient_two_negative);
    coefficients[3] =
        dequantize_lossless_coefficient(coefficient_three_token, coefficient_three_negative);
    coefficients[4] =
        dequantize_lossless_coefficient(coefficient_four_token, coefficient_four_negative);
    coefficients[5] = dequantize_lossless_coefficient(1, coefficient_five_negative);
    coefficients[6] = dequantize_lossless_coefficient(1, coefficient_six_negative);
    coefficients[7] = dequantize_lossless_coefficient(1, coefficient_seven_negative);
    coefficients[8] =
        dequantize_lossless_coefficient(coefficient_eight_token, coefficient_eight_negative);
    coefficients[9] = dequantize_lossless_coefficient(1, coefficient_nine_negative);
    coefficients[10] = dequantize_lossless_coefficient(1, coefficient_ten_negative);
    coefficients[11] = dequantize_lossless_coefficient(1, coefficient_eleven_negative);
    coefficients[12] =
        dequantize_lossless_coefficient(coefficient_twelve_token, coefficient_twelve_negative);
    coefficients[13] = dequantize_lossless_coefficient(1, coefficient_thirteen_negative);
    coefficients[14] = dequantize_lossless_coefficient(1, coefficient_fourteen_negative);
    coefficients[15] = dequantize_lossless_coefficient(1, coefficient_fifteen_negative);
    Ok(coefficients)
}

fn decode_luma_eob_nine_ten_twelve_or_fifteen_after_eob(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    sign_context: usize,
    cdfs: &mut BlockCdfs,
) -> PortableResult<TransformCoefficients> {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:403-438 and pinned Slice
    // 25-28 traces. Symbol four uses high-bit context two and two
    // equiprobable extra bits. The safe generic body now covers EOB 9, 10,
    // 8 through 15. The shared generic body keeps all of these legal EOB
    // sentences on one checked scan/context implementation.
    let high = decoder.adaptive_bool(&mut cdfs.eob_high_luma[2]);
    if high {
        let first_equal = decoder.equal();
        if first_equal {
            let third_equal = decoder.equal();
            if third_equal {
                decode_luma_eob_fifteen_coefficients(decoder, sign_context, cdfs)
            } else {
                decode_luma_eob_fourteen_coefficients(decoder, sign_context, cdfs)
            }
        } else {
            let second_equal = decoder.equal();
            if second_equal {
                decode_luma_eob_thirteen_coefficients(decoder, sign_context, cdfs)
            } else {
                decode_luma_eob_twelve_coefficients(decoder, sign_context, cdfs)
            }
        }
    } else if decoder.equal() {
        let second_equal = decoder.equal();
        if second_equal {
            decode_luma_eob_eleven_coefficients(decoder, sign_context, cdfs)
        } else {
            decode_luma_eob_ten_coefficients(decoder, sign_context, cdfs)
        }
    } else {
        let second_equal = decoder.equal();
        if second_equal {
            decode_luma_eob_nine_coefficients(decoder, sign_context, cdfs)
        } else {
            decode_luma_eob_eight_coefficients(decoder, sign_context, cdfs)
        }
    }
}

fn decode_chroma_high_dc_after_ac(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    sign_context: usize,
    cdfs: &mut BlockCdfs,
) -> PortableResult<(u32, bool)> {
    (decoder.adaptive_symbol(&mut cdfs.base_chroma[0], 3) == 3)
        .then_some(())
        .portable()?;
    let dc_token = decode_high_token(decoder, &mut cdfs.high_chroma[2]);
    (dc_token == 4).then_some(()).portable()?;
    let dc_negative = decoder.adaptive_bool(&mut cdfs.dc_sign[1][sign_context]);
    Ok((dc_token, dc_negative))
}

fn decode_chroma_eob_one_after_eob(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    sign_context: usize,
    cdfs: &mut BlockCdfs,
) -> PortableResult<TransformCoefficients> {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:443-718, src/scan.c:35-40,
    // and the pinned Slice 31 scalar trace. Chroma EOB one ends at raster
    // four and uses EOB-base context one plus high-token context seven.
    (decoder.adaptive_symbol(&mut cdfs.eob_base_chroma[1], 2) == 2)
        .then_some(())
        .portable()?;
    let coefficient_four_token = decode_high_token(decoder, &mut cdfs.high_chroma[7]);
    (coefficient_four_token == 4).then_some(()).portable()?;
    let (dc_token, dc_negative) = decode_chroma_high_dc_after_ac(decoder, sign_context, cdfs)?;
    let coefficient_four_negative = decoder.equal();

    let mut coefficients = [0_i32; 16];
    coefficients[0] = dequantize_lossless_coefficient(dc_token, dc_negative);
    coefficients[4] =
        dequantize_lossless_coefficient(coefficient_four_token, coefficient_four_negative);
    Ok(coefficients)
}

fn decode_chroma_eob_two_after_eob(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    sign_context: usize,
    cdfs: &mut BlockCdfs,
) -> PortableResult<TransformCoefficients> {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:403-718, src/scan.c:35-40,
    // and the pinned Slice 31 scalar trace. EOB two ends at raster one and
    // then visits raster four with base-token context one.
    (!decoder.adaptive_bool(&mut cdfs.eob_high_chroma[0]))
        .then_some(())
        .portable()?;
    (decoder.adaptive_symbol(&mut cdfs.eob_base_chroma[1], 2) == 2)
        .then_some(())
        .portable()?;
    let coefficient_one_token = decode_high_token(decoder, &mut cdfs.high_chroma[7]);
    (coefficient_one_token == 4).then_some(()).portable()?;
    (decoder.adaptive_symbol(&mut cdfs.base_chroma[1], 3) == 0)
        .then_some(())
        .portable()?;
    let (dc_token, dc_negative) = decode_chroma_high_dc_after_ac(decoder, sign_context, cdfs)?;
    let coefficient_one_negative = decoder.equal();

    let mut coefficients = [0_i32; 16];
    coefficients[0] = dequantize_lossless_coefficient(dc_token, dc_negative);
    coefficients[1] =
        dequantize_lossless_coefficient(coefficient_one_token, coefficient_one_negative);
    Ok(coefficients)
}

fn decode_chroma_eob_four_after_eob(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    sign_context: usize,
    cdfs: &mut BlockCdfs,
) -> PortableResult<TransformCoefficients> {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:403-718, src/scan.c:35-40,
    // and the pinned Slice 31 scalar trace. This direct-token EOB-four body
    // visits rasters five, two, one, and four before DC.
    let high = decoder.adaptive_bool(&mut cdfs.eob_high_chroma[1]);
    (!high).then_some(()).portable()?;
    (!decoder.equal()).then_some(()).portable()?;
    let eob_base = decoder.adaptive_symbol(&mut cdfs.eob_base_chroma[2], 2);
    (eob_base == 1).then_some(()).portable()?;
    let token_one = decoder.adaptive_symbol(&mut cdfs.base_chroma[6], 3);
    (token_one == 0).then_some(()).portable()?;
    let token_two = decoder.adaptive_symbol(&mut cdfs.base_chroma[2], 3);
    (token_two == 2).then_some(()).portable()?;
    let token_three = decoder.adaptive_symbol(&mut cdfs.base_chroma[2], 3);
    (token_three == 2).then_some(()).portable()?;
    let token_four = decoder.adaptive_symbol(&mut cdfs.base_chroma[0], 3);
    (token_four == 2).then_some(()).portable()?;
    let dc_negative = decoder.adaptive_bool(&mut cdfs.dc_sign[1][sign_context]);
    let coefficient_four_negative = decoder.equal();
    let coefficient_one_negative = decoder.equal();
    let coefficient_five_negative = decoder.equal();

    let mut coefficients = [0_i32; 16];
    coefficients[0] = dequantize_lossless_coefficient(2, dc_negative);
    coefficients[1] = dequantize_lossless_coefficient(2, coefficient_one_negative);
    coefficients[4] = dequantize_lossless_coefficient(2, coefficient_four_negative);
    coefficients[5] = dequantize_lossless_coefficient(2, coefficient_five_negative);
    Ok(coefficients)
}

fn decode_nonzero_lossless_transform(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    sign_context: usize,
    allow_ac: bool,
    cdfs: &mut BlockCdfs,
) -> PortableResult<TransformCoefficients> {
    let eob_bin = decode_eob_bin(decoder, plane, cdfs);
    match eob_bin {
        0 => decode_dc_only_after_eob(decoder, plane, sign_context, cdfs),
        1 if allow_ac && plane == 0 => decode_luma_eob_one_after_eob(decoder, sign_context, cdfs),
        2 if allow_ac && plane == 0 => decode_luma_eob_two_after_eob(decoder, sign_context, cdfs),
        3 if allow_ac && plane == 0 => {
            decode_luma_eob_four_or_six_after_eob(decoder, sign_context, cdfs)
        }
        4 if allow_ac && plane == 0 => {
            decode_luma_eob_nine_ten_twelve_or_fifteen_after_eob(decoder, sign_context, cdfs)
        }
        1 if allow_ac => decode_chroma_eob_one_after_eob(decoder, sign_context, cdfs),
        2 if allow_ac => decode_chroma_eob_two_after_eob(decoder, sign_context, cdfs),
        3 if allow_ac => decode_chroma_eob_four_after_eob(decoder, sign_context, cdfs),
        4 if allow_ac => decode_chroma_eob_eight_to_fifteen_after_eob(decoder, sign_context, cdfs),
        _ => Err(PortableUnavailable),
    }
}

fn decode_nonzero_lossless_transform_general(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    sign_context: usize,
    allow_ac: bool,
    cdfs: &mut BlockCdfs,
) -> PortableResult<TransformCoefficients> {
    let eob_bin = decode_eob_bin(decoder, plane, cdfs);
    match eob_bin {
        0 => decode_dc_only_after_eob_general(decoder, plane, sign_context, cdfs),
        1..=4 if allow_ac && plane == 0 => {
            decode_luma_eob_general_after_bin(decoder, sign_context, cdfs, eob_bin)
        }
        1 if allow_ac => decode_chroma_eob_one_after_eob(decoder, sign_context, cdfs),
        2 if allow_ac => decode_chroma_eob_two_after_eob(decoder, sign_context, cdfs),
        3 if allow_ac => decode_chroma_eob_four_after_eob(decoder, sign_context, cdfs),
        4 if allow_ac => decode_chroma_eob_eight_to_fifteen_after_eob(decoder, sign_context, cdfs),
        _ => Err(PortableUnavailable),
    }
}

fn decode_nonzero_lossless_transform_chroma_general(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    sign_context: usize,
    allow_ac: bool,
    cdfs: &mut BlockCdfs,
) -> PortableResult<TransformCoefficients> {
    let eob_bin = decode_eob_bin(decoder, plane, cdfs);
    match eob_bin {
        0 => decode_dc_only_after_eob_general(decoder, plane, sign_context, cdfs),
        1..=4 if allow_ac => {
            decode_chroma_eob_general_after_bin(decoder, sign_context, cdfs, eob_bin)
        }
        _ => Err(PortableUnavailable),
    }
}

fn decode_dc_coefficients(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    cdfs: &mut BlockCdfs,
    transform_grid_width: usize,
    transform_grid_height: usize,
    single_subsampled_chroma_transform: bool,
) -> PortableResult<PlaneCoefficients> {
    let transform_count = transform_grid_width.saturating_mul(transform_grid_height);
    let mut coefficients = [[0_i32; 16]; 64];
    let coefficient_context = usize::from(plane != 0);
    let first_zero = if single_subsampled_chroma_transform {
        // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:328-345 and the pinned
        // Slice 32 scalar traces. The sole 4:2:0 chroma transform in an 8x8
        // lossless block selects coefficient-skip context seven.
        decoder.adaptive_bool(&mut cdfs.subsampled_chroma_coefficient_skip[0][0])
    } else {
        decoder.adaptive_bool(&mut cdfs.coefficient_skip[coefficient_context])
    };
    if first_zero {
        // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:754-838 and the pinned
        // Slice 12 scalar traces. With no top-left coefficient context, every
        // remaining transform in the 2x2 or 4x4 grid uses the base skip CDF.
        for _ in 1..transform_count {
            let skipped = decoder.adaptive_bool(&mut cdfs.coefficient_skip[coefficient_context]);
            skipped.then_some(()).portable()?;
        }
        return Ok(coefficients);
    }
    coefficients[0] = decode_nonzero_lossless_transform(decoder, plane, 0, false, cdfs)?;
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:754-838. A nonzero top-left
    // transform changes the coefficient context of exactly its right and
    // lower neighbors. All later row-major transforms return to the base CDF.
    for transform_index in 1..transform_count {
        let skipped = if transform_index == 1 || transform_index == transform_grid_width {
            decoder.adaptive_bool(&mut cdfs.trailing_coefficient_skip[coefficient_context])
        } else {
            decoder.adaptive_bool(&mut cdfs.coefficient_skip[coefficient_context])
        };
        skipped.then_some(()).portable()?;
    }
    Ok(coefficients)
}

fn coefficient_residual_context(coefficients: &[i32]) -> u8 {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:556-734. Q-index-zero
    // dequantization is four, so converting each magnitude back to its token
    // and capping their sum reproduces dav1d's `cul_level`. Bits six and
    // seven retain the negative, zero, or positive DC sign class.
    let magnitude = coefficients.iter().fold(0_u32, |sum, coefficient| {
        sum.saturating_add(coefficient.unsigned_abs() / 4)
    });
    let magnitude = u8::try_from(magnitude.min(63)).unwrap_or(63);
    let dc_sign = match coefficients[0].cmp(&0) {
        std::cmp::Ordering::Less => 0,
        std::cmp::Ordering::Equal => 0x40,
        std::cmp::Ordering::Greater => 0x80,
    };
    magnitude | dc_sign
}

fn lossy_luma_context(syntax: &BlockSyntax) -> u8 {
    if let Some(split) = syntax.lossy_luma_64x64_split.as_ref() {
        return split.children[3].residual_context;
    }
    if let Some(split) = syntax.lossy_luma_8x4_split.as_ref() {
        return split.right_context;
    }
    if let Some(context) = syntax.lossy_luma_residual_context {
        return context;
    }
    if let Some(coefficients) = syntax.lossy_luma_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_4x8_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_16x16_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(split) = syntax.lossy_luma_16x16_horizontal_split.as_ref()
        && let Some(coefficients) = split.coefficients[1].as_ref()
    {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_32x32_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_16x32_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_64x64_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_8x32_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_16x64_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_32x16_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_32x8_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_64x16_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_16x8_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    if let Some(coefficients) = syntax.lossy_luma_rect_coefficients.as_ref() {
        return coefficient_residual_context(coefficients);
    }
    coefficient_residual_context(&syntax.coefficients[0][0])
}

fn coefficient_dc_sign_context(above: u8, left: u8) -> usize {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:140-159. A 4x4 transform
    // combines the two two-bit sign classes and maps negative, neutral, and
    // positive sums to contexts one, zero, and two.
    let sum = i32::from(above >> 6)
        .wrapping_add(i32::from(left >> 6))
        .wrapping_sub(2);
    usize::from(sum != 0).wrapping_add(usize::from(sum > 0))
}

fn coefficient_dc_sign_context_8x8(above: [u8; 2], left: [u8; 2]) -> usize {
    // `get_dc_sign_ctx(TX_8X8)` consumes two 4x4 edge contexts from each
    // side, unlike the TX_4X4 helper above. Each context stores the
    // negative/neutral/positive DC class in bits 7..6.
    let sum = above
        .into_iter()
        .chain(left)
        .map(|context| i32::from(context >> 6))
        .sum::<i32>()
        .saturating_sub(4);
    usize::from(sum != 0).saturating_add(usize::from(sum > 0))
}

fn coefficient_dc_sign_context_for_grid(
    transform_grid: TransformGrid,
    above: &[u8; 16],
    left: &[u8; 16],
) -> usize {
    let (width, height, _) = transform_grid.properties();
    coefficient_dc_sign_context_for_dimensions(width, height, above, left)
}

fn coefficient_dc_sign_context_for_dimensions(
    width: usize,
    height: usize,
    above: &[u8],
    left: &[u8],
) -> usize {
    let sum = above
        .iter()
        .take(width)
        .chain(left.iter().take(height))
        .map(|context| i32::from(context >> 6))
        .sum::<i32>()
        .saturating_sub(i32::try_from(width.saturating_add(height)).unwrap_or(i32::MAX));
    usize::from(sum != 0).saturating_add(usize::from(sum > 0))
}

fn chroma_contextual_skip_cdf(above: u8, left: u8) -> CoefficientSkipCdf {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:68-100. One 4x4
    // transform inside an 8x8 4:4:4 chroma block starts at context ten
    // and adds one for each non-skipped neighbor.
    match (above == 0x40, left == 0x40) {
        (true, true) => CoefficientSkipCdf::Base,
        (false, false) => CoefficientSkipCdf::TwoNonzeroNeighbors,
        _ => CoefficientSkipCdf::OneNonzeroNeighbor,
    }
}

fn single_transform_chroma_skip_cdf(above: u8, left: u8) -> CoefficientSkipCdf {
    // ✅ VERIFIED: dav1d 1.5.3 `get_skip_ctx()` in src/recon_tmpl.c:68-100.
    // A 4x4 4:4:4 chroma transform uses the subsampled-chroma CDF family,
    // even though the image itself is not subsampled.  For a single transform
    // the transform-size context is zero; the two external coefficient edges
    // select contexts seven, eight, or nine.
    let skip_context = 7_usize
        .saturating_add(usize::from(above != 0x40))
        .saturating_add(usize::from(left != 0x40));
    CoefficientSkipCdf::Subsampled {
        transform_context: 0,
        skip_context,
    }
}

fn subsampled_chroma_one_neighbor_skip_cdf(context: u8) -> CoefficientSkipCdf {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:59-105. A single 4x4
    // chroma transform in a following 8x8 4:2:0 luma leaf has exactly one
    // previously decoded external edge by geometry. It uses context seven
    // when that edge is neutral and context eight when it is nonzero. The
    // transform-size context is zero for this 4x4 chroma transform.
    CoefficientSkipCdf::Subsampled {
        transform_context: 0,
        skip_context: if context == 0x40 { 7 } else { 8 },
    }
}

fn contextual_skip_cdf(plane: usize, above: u8, left: u8) -> PortableResult<CoefficientSkipCdf> {
    if plane != 0 {
        return Ok(chroma_contextual_skip_cdf(above, left));
    }

    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:101-137 and
    // src/tables.c:297-303. This slice admits q-context-zero luma skip
    // contexts one and three; context six and the intermediate classes remain
    // closed until a fixture proves their complete downstream syntax.
    Ok(CoefficientSkipCdf::LumaContext(luma_skip_context(
        above, left,
    )))
}

fn luma_skip_context(above: u8, left: u8) -> usize {
    const LUMA_SKIP_CONTEXTS: [[u8; 5]; 5] = [
        [1, 2, 2, 2, 3],
        [2, 4, 4, 4, 5],
        [2, 4, 4, 4, 5],
        [2, 4, 4, 4, 5],
        [3, 5, 5, 5, 6],
    ];
    let above_magnitude = usize::from((above & 63).min(4));
    let left_magnitude = usize::from((left & 63).min(4));
    usize::from(LUMA_SKIP_CONTEXTS[above_magnitude][left_magnitude])
}

fn decode_contextual_skip(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    coefficient_context: usize,
    skip_cdf: CoefficientSkipCdf,
    cdfs: &mut BlockCdfs,
) -> bool {
    match skip_cdf {
        CoefficientSkipCdf::LumaContext(context) => {
            // `LUMA_SKIP_CONTEXTS` produces only contexts one through six;
            // the seven-entry table also reserves index zero for the same
            // bounded AV1 context family.
            decoder.adaptive_bool(&mut cdfs.luma_coefficient_skip[context])
        }
        CoefficientSkipCdf::LossyLuma8x8Context(context) => {
            decoder.adaptive_bool(&mut cdfs.lossy_luma_8x8_coefficient_skip[context])
        }
        CoefficientSkipCdf::LossyLuma16x16Context(context) => {
            decoder.adaptive_bool(&mut cdfs.lossy_luma_16x16_coefficient_skip_contexts[context])
        }
        CoefficientSkipCdf::LossyLuma32x16Context(context) => {
            decoder.adaptive_bool(&mut cdfs.lossy_luma_context_three_coefficient_skip[context])
        }
        CoefficientSkipCdf::LossyLuma32x32Context(context) => {
            decoder.adaptive_bool(&mut cdfs.lossy_luma_context_three_coefficient_skip[context])
        }
        CoefficientSkipCdf::LossyLumaContextFour(context) => {
            decoder.adaptive_bool(&mut cdfs.lossy_luma_context_four_coefficient_skip[context])
        }
        CoefficientSkipCdf::Base => {
            decoder.adaptive_bool(&mut cdfs.coefficient_skip[coefficient_context])
        }
        CoefficientSkipCdf::OneNonzeroNeighbor => {
            decoder.adaptive_bool(&mut cdfs.trailing_coefficient_skip[coefficient_context])
        }
        CoefficientSkipCdf::TwoNonzeroNeighbors => {
            decoder.adaptive_bool(&mut cdfs.double_neighbor_coefficient_skip[coefficient_context])
        }
        CoefficientSkipCdf::Subsampled {
            transform_context,
            skip_context,
        } => {
            let cdf =
                &mut cdfs.subsampled_chroma_coefficient_skip[transform_context][skip_context - 7];
            decoder.adaptive_bool(cdf)
        }
    }
}

fn decode_lossy_luma_tx_context_two_skip(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
) -> bool {
    // A direct transform-context-two terminal uses row zero of the same
    // normative adaptive state consumed by contextual split children.
    decode_contextual_skip(
        decoder,
        0,
        CoefficientSkipCdf::LossyLuma16x16Context(0),
        cdfs,
    )
}

fn decode_contextual_top_left_coefficients(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    cdfs: &mut BlockCdfs,
) -> PortableResult<PlaneCoefficients> {
    let coefficient_context = usize::from(plane != 0);
    let mut coefficients = [[0_i32; 16]; 64];
    let mut above_contexts = [0x40_u8; 2];
    let mut left_context = 0x40_u8;

    for (transform_index, coefficients) in coefficients.iter_mut().enumerate().take(4) {
        let column = transform_index % 2;
        if column == 0 {
            left_context = 0x40;
        }
        let above_context = above_contexts[column];
        let skip_cdf = contextual_skip_cdf(plane, above_context, left_context)?;
        let skipped = decode_contextual_skip(decoder, coefficient_context, skip_cdf, cdfs);
        let residual_context = if skipped {
            0x40
        } else {
            let sign_context = coefficient_dc_sign_context(above_context, left_context);
            let allow_ac =
                (plane == 0 && transform_index != 0) || (plane != 0 && transform_index == 3);
            let transform =
                decode_nonzero_lossless_transform(decoder, plane, sign_context, allow_ac, cdfs)?;
            *coefficients = transform;
            coefficient_residual_context(&transform)
        };
        above_contexts[column] = residual_context;
        left_context = residual_context;
    }
    Ok(coefficients)
}

/// Decode a full-resolution color-frame TX4x4 grid into a caller-provided
/// carrier.  The same row-major kernel is used for origin, one-edge, and
/// two-edge leaves; only the initial above/left contexts differ.  A checked
/// destination slice keeps the ordinary 64-carrier path and the dedicated
/// Square64 arena on one CDF implementation without silently truncating a
/// larger grid.
fn decode_color_frame_coefficients_into(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    cdfs: &mut BlockCdfs,
    transform_grid_width: usize,
    transform_grid_height: usize,
    context: ColorFrameCoefficientContext,
    coefficients: &mut [TransformCoefficients],
) -> PortableResult<()> {
    let Some(transform_count) = transform_grid_width.checked_mul(transform_grid_height) else {
        return Err(PortableUnavailable);
    };
    if !(1..=LOSSLESS444_NEIGHBOR_CAPACITY).contains(&transform_grid_width)
        || !(1..=LOSSLESS444_NEIGHBOR_CAPACITY).contains(&transform_grid_height)
        || transform_count > coefficients.len()
    {
        return Err(PortableUnavailable);
    }
    let mut above_contexts = [0x40_u8; LOSSLESS444_NEIGHBOR_CAPACITY];
    let mut external_left = [0x40_u8; LOSSLESS444_NEIGHBOR_CAPACITY];
    match context {
        ColorFrameCoefficientContext::TopLeft => {}
        ColorFrameCoefficientContext::Following {
            neighbor_contexts,
            orientation,
        } => match orientation {
            SplitOrientation::Horizontal => {
                external_left[..transform_grid_height]
                    .copy_from_slice(&neighbor_contexts[..transform_grid_height]);
            }
            SplitOrientation::Vertical => {
                above_contexts[..transform_grid_width]
                    .copy_from_slice(&neighbor_contexts[..transform_grid_width]);
            }
        },
        ColorFrameCoefficientContext::Boundary {
            above_contexts: external_above,
            left_contexts: external_left_contexts,
        } => {
            above_contexts[..transform_grid_width]
                .copy_from_slice(&external_above[..transform_grid_width]);
            external_left[..transform_grid_height]
                .copy_from_slice(&external_left_contexts[..transform_grid_height]);
        }
    }

    let coefficient_context = usize::from(plane != 0);
    let mut left_context = 0x40_u8;
    for (transform_index, coefficient) in coefficients.iter_mut().enumerate().take(transform_count)
    {
        let column = transform_index % transform_grid_width;
        let row = transform_index / transform_grid_width;
        if column == 0 {
            left_context = external_left[row];
        }
        let above_context = above_contexts[column];
        let skip_cdf = if transform_grid_width == 1 && transform_grid_height == 1 {
            if plane == 0 {
                CoefficientSkipCdf::LumaContext(0)
            } else {
                single_transform_chroma_skip_cdf(above_context, left_context)
            }
        } else {
            contextual_skip_cdf(plane, above_context, left_context)?
        };
        let skipped = decode_contextual_skip(decoder, coefficient_context, skip_cdf, cdfs);
        let residual_context = if skipped {
            0x40
        } else {
            let sign_context = coefficient_dc_sign_context(above_context, left_context);
            let transform = if plane == 0 {
                decode_nonzero_lossless_transform_general(decoder, plane, sign_context, true, cdfs)?
            } else {
                decode_nonzero_lossless_transform_chroma_general(
                    decoder,
                    plane,
                    sign_context,
                    true,
                    cdfs,
                )?
            };
            *coefficient = transform;
            coefficient_residual_context(&transform)
        };
        above_contexts[column] = residual_context;
        left_context = residual_context;
    }
    Ok(())
}

