fn coefficient_edge_contexts(
    coefficients: &[PlaneCoefficients; 3],
    orientation: SplitOrientation,
    chroma_sampling: ChromaSampling,
) -> [[u8; 2]; 3] {
    let transform_indices = match orientation {
        SplitOrientation::Horizontal => [1, 3],
        SplitOrientation::Vertical => [2, 3],
    };
    std::array::from_fn(|plane| {
        if plane != 0 && matches!(chroma_sampling, ChromaSampling::Subsampled420) {
            [coefficient_residual_context(&coefficients[plane][0]); 2]
        } else {
            transform_indices.map(|index| coefficient_residual_context(&coefficients[plane][index]))
        }
    })
}

fn coefficient_edge_contexts_wide(
    coefficients: &[PlaneCoefficients; 3],
    orientation: SplitOrientation,
    transform_grid: TransformGrid,
    chroma_sampling: ChromaSampling,
) -> PortableResult<[[u8; LOSSLESS444_NEIGHBOR_CAPACITY]; 3]> {
    let (luma_grid_width, luma_grid_height, _) = transform_grid.properties();
    let mut edge_contexts = [[0x40_u8; LOSSLESS444_NEIGHBOR_CAPACITY]; 3];
    for (plane, edge_context) in edge_contexts.iter_mut().enumerate() {
        let (grid_width, grid_height) =
            chroma_sampling.transform_grid(luma_grid_width, luma_grid_height, plane);
        let edge_count = match orientation {
            SplitOrientation::Horizontal => grid_height,
            SplitOrientation::Vertical => grid_width,
        };
        let Some(transform_count) = grid_width.checked_mul(grid_height) else {
            return Err(PortableUnavailable);
        };
        if edge_count > LOSSLESS444_NEIGHBOR_CAPACITY || transform_count > 64 {
            return Err(PortableUnavailable);
        }
        if plane != 0 && matches!(chroma_sampling, ChromaSampling::Subsampled420) {
            edge_context.fill(coefficient_residual_context(&coefficients[plane][0]));
            continue;
        }
        for (edge_index, context) in edge_context.iter_mut().enumerate().take(edge_count) {
            let transform_index = match orientation {
                SplitOrientation::Horizontal => edge_index
                    .saturating_mul(grid_width)
                    .saturating_add(grid_width.saturating_sub(1)),
                SplitOrientation::Vertical => edge_index
                    .saturating_add(grid_height.saturating_sub(1).saturating_mul(grid_width)),
            };
            *context =
                coefficient_residual_context(coefficients[plane].get(transform_index).portable()?);
        }
    }
    Ok(edge_contexts)
}

fn lossless_large_edge_contexts(
    syntax: &BlockSyntax,
    arena: &LosslessSquare64CoefficientArena,
    orientation: SplitOrientation,
) -> PortableResult<[[u8; LOSSLESS444_NEIGHBOR_CAPACITY]; 3]> {
    matches!(
        syntax.transform_grid,
        TransformGrid::Vertical16x64
            | TransformGrid::Vertical32x64
            | TransformGrid::Horizontal64x16
            | TransformGrid::Horizontal64x32
            | TransformGrid::Square64
    )
    .then_some(())
    .portable()?;
    let (grid_width, grid_height, _) = syntax.transform_grid.properties();
    let transform_count = grid_width.checked_mul(grid_height).portable()?;
    let zero = [[0_i32; 16]; LosslessSquare64CoefficientArena::TRANSFORM_COUNT];
    let mut edge_contexts = [[0x40_u8; LOSSLESS444_NEIGHBOR_CAPACITY]; 3];
    for (plane, edge_context) in edge_contexts.iter_mut().enumerate() {
        let coefficients: &[TransformCoefficients] =
            match syntax.lossless_square64_coefficients[plane] {
                Some(span) => arena.coefficients(span)?,
                None => zero.get(..transform_count).portable()?,
            };
        (coefficients.len() == transform_count)
            .then_some(())
            .portable()?;
        let edge_count = match orientation {
            SplitOrientation::Horizontal => grid_height,
            SplitOrientation::Vertical => grid_width,
        };
        for (edge_index, context) in edge_context.iter_mut().enumerate().take(edge_count) {
            let transform_index = match orientation {
                SplitOrientation::Horizontal => edge_index
                    .checked_mul(grid_width)
                    .and_then(|index| index.checked_add(grid_width.saturating_sub(1)))
                    .ok_or(PortableUnavailable)?,
                SplitOrientation::Vertical => edge_index
                    .checked_add(
                        grid_height
                            .saturating_sub(1)
                            .checked_mul(grid_width)
                            .ok_or(PortableUnavailable)?,
                    )
                    .ok_or(PortableUnavailable)?,
            };
            *context = coefficient_residual_context(coefficients.get(transform_index).portable()?);
        }
    }
    Ok(edge_contexts)
}

fn widen_contexts(contexts: [u8; 2]) -> [u8; LOSSLESS444_NEIGHBOR_CAPACITY] {
    let mut widened = [0x40_u8; LOSSLESS444_NEIGHBOR_CAPACITY];
    widened[..2].copy_from_slice(&contexts);
    widened
}

fn lossless444_neighbor_contexts(
    neighbors: [Option<&Lossless444Leaf>; LOSSLESS444_NEIGHBOR_CAPACITY],
    geometry: Lossless444BlockGeometry,
    above: bool,
) -> PortableResult<[[u8; LOSSLESS444_NEIGHBOR_CAPACITY]; 3]> {
    let (grid_width, grid_height, _) = geometry.transform_grid.properties();
    let edge_count = if above { grid_width } else { grid_height };
    (edge_count <= LOSSLESS444_NEIGHBOR_CAPACITY)
        .then_some(())
        .portable()?;
    let mut contexts = [[0x40_u8; LOSSLESS444_NEIGHBOR_CAPACITY]; 3];
    if neighbors.iter().all(Option::is_none) {
        return Ok(contexts);
    }
    for (edge_index, neighbor) in neighbors.iter().enumerate().take(edge_count) {
        let leaf = neighbor.as_ref().copied().portable()?;
        if above {
            (leaf.origin_y.saturating_add(leaf.height) == geometry.origin_y)
                .then_some(())
                .portable()?;
            let segment_origin = geometry
                .origin_x
                .checked_add(
                    u32::try_from(edge_index.saturating_mul(4)).map_err(|_| PortableUnavailable)?,
                )
                .ok_or(PortableUnavailable)?;
            let offset = segment_origin
                .checked_sub(leaf.origin_x)
                .filter(|offset| offset % 4 == 0)
                .portable()?;
            let index = usize::try_from(offset / 4).map_err(|_| PortableUnavailable)?;
            for (plane, context) in contexts.iter_mut().enumerate() {
                context[edge_index] = *leaf.bottom_contexts[plane].get(index).portable()?;
            }
        } else {
            (leaf.origin_x.saturating_add(leaf.width) == geometry.origin_x)
                .then_some(())
                .portable()?;
            let segment_origin = geometry
                .origin_y
                .checked_add(
                    u32::try_from(edge_index.saturating_mul(4)).map_err(|_| PortableUnavailable)?,
                )
                .ok_or(PortableUnavailable)?;
            let offset = segment_origin
                .checked_sub(leaf.origin_y)
                .filter(|offset| offset % 4 == 0)
                .portable()?;
            let index = usize::try_from(offset / 4).map_err(|_| PortableUnavailable)?;
            for (plane, context) in contexts.iter_mut().enumerate() {
                context[edge_index] = *leaf.right_contexts[plane].get(index).portable()?;
            }
        }
    }
    Ok(contexts)
}

fn decode_contextual_following_coefficients(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    cdfs: &mut BlockCdfs,
    context: FollowingCoefficientContext,
) -> PortableResult<PlaneCoefficients> {
    let FollowingCoefficientContext {
        neighbor_contexts,
        orientation,
        transform_grid_width,
        transform_grid_height,
        single_subsampled_chroma_transform,
        require_skipped,
        general_luma,
    } = context;
    let axis_limit = if general_luma {
        LOSSLESS444_NEIGHBOR_CAPACITY
    } else {
        8
    };
    let Some(transform_count) = transform_grid_width.checked_mul(transform_grid_height) else {
        return Err(PortableUnavailable);
    };
    if !(1..=axis_limit).contains(&transform_grid_width)
        || !(1..=axis_limit).contains(&transform_grid_height)
        || transform_count > 64
    {
        return Err(PortableUnavailable);
    }
    let coefficient_context = usize::from(plane != 0);
    let mut coefficients = [[0_i32; 16]; 64];
    let mut above_contexts = match orientation {
        SplitOrientation::Horizontal => [0x40; LOSSLESS444_NEIGHBOR_CAPACITY],
        SplitOrientation::Vertical => neighbor_contexts,
    };
    let mut left_context = 0x40;

    for (transform_index, coefficients) in coefficients.iter_mut().enumerate().take(transform_count)
    {
        let column = transform_index.rem_euclid(transform_grid_width);
        let row = transform_index.div_euclid(transform_grid_width);
        if column == 0 {
            left_context = match orientation {
                SplitOrientation::Horizontal => neighbor_contexts[row],
                SplitOrientation::Vertical => 0x40,
            };
        }
        let above_context = above_contexts[column];
        let skip_cdf = if general_luma && transform_grid_width == 1 && transform_grid_height == 1 {
            if plane == 0 {
                // ✅ VERIFIED: dav1d 1.5.3 `get_skip_ctx()` in
                // src/recon_tmpl.c:101-137. Every BLOCK_4X4 luma leaf uses
                // context zero, including leaves reached through a horizontal
                // or vertical split.
                CoefficientSkipCdf::LumaContext(0)
            } else {
                single_transform_chroma_skip_cdf(above_context, left_context)
            }
        } else if general_luma && plane == 0 {
            contextual_skip_cdf(0, above_context, left_context)?
        } else if single_subsampled_chroma_transform {
            let external_context = match orientation {
                SplitOrientation::Horizontal => left_context,
                SplitOrientation::Vertical => above_context,
            };
            subsampled_chroma_one_neighbor_skip_cdf(external_context)
        } else if plane == 0 {
            // Following luma is required skipped, so it can retain only its
            // one external coded edge and never has two nonzero neighbors.
            if above_context == 0x40 && left_context == 0x40 {
                CoefficientSkipCdf::Base
            } else {
                CoefficientSkipCdf::OneNonzeroNeighbor
            }
        } else {
            chroma_contextual_skip_cdf(above_context, left_context)
        };
        let skipped = decode_contextual_skip(decoder, coefficient_context, skip_cdf, cdfs);
        let chroma_ac_position = match orientation {
            SplitOrientation::Horizontal => transform_index >= transform_grid_width,
            SplitOrientation::Vertical => column != 0,
        };
        let residual_context = if skipped {
            0x40
        } else {
            (!require_skipped).then_some(()).portable()?;
            let sign_context = coefficient_dc_sign_context(above_context, left_context);
            let transform = if general_luma && plane == 0 {
                decode_nonzero_lossless_transform_general(decoder, plane, sign_context, true, cdfs)?
            } else if general_luma {
                decode_nonzero_lossless_transform_chroma_general(
                    decoder,
                    plane,
                    sign_context,
                    true,
                    cdfs,
                )?
            } else {
                (plane != 0 && chroma_ac_position)
                    .then_some(())
                    .portable()?;
                decode_nonzero_lossless_transform(decoder, plane, sign_context, true, cdfs)?
            };
            *coefficients = transform;
            coefficient_residual_context(&transform)
        };
        above_contexts[column] = residual_context;
        left_context = residual_context;
    }

    Ok(coefficients)
}

#[expect(
    clippy::too_many_arguments,
    reason = "the checked monochrome coefficient kernel keeps nominal and active grids explicit"
)]
fn decode_monochrome_contextual_coefficients_into(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
    transform_grid_width: usize,
    transform_grid_height: usize,
    active_grid_width: usize,
    active_grid_height: usize,
    mut above_contexts: [u8; 16],
    left_contexts: [u8; 16],
    coefficients: &mut [TransformCoefficients],
) -> PortableResult<()> {
    if !(1..=16).contains(&transform_grid_width)
        || !(1..=16).contains(&transform_grid_height)
        || !(1..=16).contains(&active_grid_width)
        || !(1..=16).contains(&active_grid_height)
        || active_grid_width > transform_grid_width
        || active_grid_height > transform_grid_height
    {
        return Err(PortableUnavailable);
    }
    let transform_count = transform_grid_width
        .checked_mul(transform_grid_height)
        .portable()?;
    let active_count = active_grid_width
        .checked_mul(active_grid_height)
        .portable()?;
    (transform_count <= coefficients.len() && active_count <= transform_count)
        .then_some(())
        .portable()?;
    coefficients
        .get_mut(..transform_count)
        .portable()?
        .fill([0_i32; 16]);
    for row in 0..active_grid_height {
        let mut left_context = *left_contexts.get(row).ok_or(PortableUnavailable)?;
        for column in 0..active_grid_width {
            let transform_index = row
                .checked_mul(transform_grid_width)
                .and_then(|offset| offset.checked_add(column))
                .portable()?;
            let coefficient = coefficients
                .get_mut(transform_index)
                .ok_or(PortableUnavailable)?;
            let above_context = *above_contexts.get(column).ok_or(PortableUnavailable)?;
            let skip_cdf_result = if transform_grid_width == 1 && transform_grid_height == 1 {
                // In lossless AV1 the sole transform in a BLOCK_4X4 block is
                // also TX_4X4. dav1d's get_skip_ctx() therefore selects
                // coefficient skip context zero and does not consult the
                // external coefficient edge contexts.
                Ok(CoefficientSkipCdf::LumaContext(0))
            } else {
                contextual_skip_cdf(0, above_context, left_context)
            };
            let skip_cdf = skip_cdf_result?;
            let skipped = decode_contextual_skip(decoder, 0, skip_cdf, cdfs);
            let residual_context = if skipped {
                0x40
            } else {
                let sign_context = coefficient_dc_sign_context(above_context, left_context);
                let transform_result =
                    decode_nonzero_lossless_transform_general(decoder, 0, sign_context, true, cdfs);
                let transform = transform_result?;
                *coefficient = transform;
                coefficient_residual_context(&transform)
            };
            above_contexts[column] = residual_context;
            left_context = residual_context;
        }
    }
    Ok(())
}

