fn decode_contextual_boundary_coefficients(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    cdfs: &mut BlockCdfs,
    above_contexts: [u8; 2],
    left_contexts: [u8; 2],
    transform_grid_width: usize,
    transform_grid_height: usize,
) -> PortableResult<PlaneCoefficients> {
    if plane == 0 || (above_contexts == [0x40; 2] && left_contexts == [0x40; 2]) {
        return decode_boundary_coefficients(
            decoder,
            plane,
            cdfs,
            transform_grid_width,
            transform_grid_height,
        );
    }

    let coefficient_context = usize::from(plane != 0);
    let mut above_contexts = above_contexts;
    let mut left_context = 0x40;
    for transform_index in 0..4 {
        let column = transform_index % 2;
        if column == 0 {
            left_context = left_contexts[transform_index / 2];
        }
        let skip_cdf = chroma_contextual_skip_cdf(above_contexts[column], left_context);
        let skipped = decode_contextual_skip(decoder, coefficient_context, skip_cdf, cdfs);
        skipped.then_some(()).portable()?;
        above_contexts[column] = 0x40;
        left_context = 0x40;
    }
    Ok([[0_i32; 16]; 64])
}

fn decode_subsampled_boundary_coefficients(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    cdfs: &mut BlockCdfs,
) -> PortableResult<PlaneCoefficients> {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:59-105 and the Slice 33
    // scalar traces. Both side leaves are decoded with `require_skipped`, so
    // their single chroma transforms are neutral by construction. The
    // bottom-right transform therefore uses context seven and sign context
    // zero; context nine cannot be represented by this closed policy.
    let skipped = decode_contextual_skip(
        decoder,
        1,
        CoefficientSkipCdf::Subsampled {
            transform_context: 0,
            skip_context: 7,
        },
        cdfs,
    );
    let mut coefficients = [[0_i32; 16]; 64];
    if !skipped {
        coefficients[0] = decode_nonzero_lossless_transform(decoder, plane, 0, false, cdfs)?;
    }
    Ok(coefficients)
}

fn decode_boundary_coefficients(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    cdfs: &mut BlockCdfs,
    transform_grid_width: usize,
    transform_grid_height: usize,
) -> PortableResult<PlaneCoefficients> {
    ((transform_grid_width, transform_grid_height) == (2, 2))
        .then_some(())
        .portable()?;
    let coefficient_context = usize::from(plane != 0);
    let first_skipped = decoder.adaptive_bool(&mut cdfs.coefficient_skip[coefficient_context]);
    let mut coefficients = [[0_i32; 16]; 64];
    if first_skipped {
        // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:59-105, 1282-1545 and
        // pinned Slice 21 traces. If the first boundary transform is skipped,
        // all four transforms retain the same base skip context.
        for _ in 1..4 {
            decoder
                .adaptive_bool(&mut cdfs.coefficient_skip[coefficient_context])
                .then_some(())
                .portable()?;
        }
        return Ok(coefficients);
    }
    coefficients[0] = decode_nonzero_lossless_transform(decoder, plane, 0, true, cdfs)?;
    let sign_context = if coefficients[0][0].is_negative() {
        1
    } else {
        2
    };
    for coefficient in &mut coefficients[1..3] {
        (!decoder.adaptive_bool(&mut cdfs.trailing_coefficient_skip[coefficient_context]))
            .then_some(())
            .portable()?;
        *coefficient = decode_nonzero_lossless_transform(decoder, plane, sign_context, true, cdfs)?;
    }
    decoder
        .adaptive_bool(&mut cdfs.double_neighbor_coefficient_skip[coefficient_context])
        .then_some(())
        .portable()?;
    Ok(coefficients)
}

fn decode_skipped_coefficients(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    plane: usize,
    cdfs: &mut BlockCdfs,
    transform_grid_width: usize,
    transform_grid_height: usize,
) -> PortableResult<PlaneCoefficients> {
    let transform_count = transform_grid_width.saturating_mul(transform_grid_height);
    let coefficient_context = usize::from(plane != 0);
    for _ in 0..transform_count {
        decoder
            .adaptive_bool(&mut cdfs.coefficient_skip[coefficient_context])
            .then_some(())
            .portable()?;
    }
    Ok([[0_i32; 16]; 64])
}

// ✅ VERIFIED: dav1d 1.5.3 src/decode.c:963-983 and src/cdf.c:410-411.
// The fourth delta-q CDF symbol is an escape followed by a bounded
// subexponential magnitude sentence; the sign is read only after that
// sentence. AV1 clamps a nonzero delta-q result to the 1..=255 qindex range.
fn decode_delta_q(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
    initial_qindex: u32,
    resolution_log2: u32,
) -> PortableResult<u32> {
    let symbol = decoder.adaptive_symbol(&mut cdfs.delta_q, 3);
    let magnitude = if symbol == 3 {
        let n_bits = decoder.bits(3).saturating_add(1);
        decoder
            .bits(n_bits)
            .saturating_add(1)
            .saturating_add(1_u32.wrapping_shl(n_bits))
    } else {
        symbol
    };
    if magnitude == 0 {
        return Ok(initial_qindex);
    }
    // AV1 writes one sign bit only for a non-zero magnitude. The scalar
    // reference uses sign=1 for a negative delta.
    let negative = decoder.equal();
    let delta = magnitude.wrapping_shl(resolution_log2);
    if negative {
        Ok(initial_qindex.saturating_sub(delta).clamp(1, 255))
    } else {
        Ok(initial_qindex.saturating_add(delta).clamp(1, 255))
    }
}

// ✅ VERIFIED: AV1 specification `read_delta_lf`; rav1d-safe 0.5.7
// `decode.rs:1574-1610`. The accumulator is initialized once per tile and
// carries across superblocks; only the delta-q-owned read opportunity is
// consumed per superblock.
fn decode_delta_lf(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
) -> PortableResult<()> {
    let syntax = cdfs.delta_lf_syntax;
    if !syntax.present {
        return Ok(());
    }
    let component_count = if syntax.multi {
        if syntax.monochrome { 2 } else { 4 }
    } else {
        1
    };
    for component in 0_usize..component_count {
        let row = component.saturating_add(usize::from(syntax.multi));
        let symbol = decoder.adaptive_symbol(cdfs.delta_lf.get_mut(row).portable()?, 3);
        let magnitude = if symbol == 3 {
            let bit_count = decoder.bits(3).saturating_add(1);
            decoder
                .bits(bit_count)
                .checked_add(1)
                .and_then(|value| value.checked_add(1_u32.checked_shl(bit_count)?))
                .portable()?
        } else {
            symbol
        };
        if magnitude == 0 {
            continue;
        }
        let magnitude = i64::from(magnitude.checked_shl(syntax.resolution_log2).portable()?);
        let delta = if decoder.equal() {
            magnitude.saturating_neg()
        } else {
            magnitude
        };
        cdfs.last_delta_lf[component] = i32::try_from(
            i64::from(cdfs.last_delta_lf[component])
                .saturating_add(delta)
                .clamp(-63, 63),
        )
        .map_err(|_| PortableUnavailable)?;
    }
    Ok(())
}

