// ✅ VERIFIED: dav1d 1.5.3 `src/scan.c` `scan_32x32`.
// Coefficients are stored column-major as `row + 32 * column`.
const fn make_lossy_luma_32x32_scan() -> [u16; 1024] {
    let mut scan = [0_u16; 1024];
    let mut position = 0_usize;
    let mut diagonal = 0_usize;
    while diagonal < 63 {
        if diagonal & 1 == 0 {
            let mut x = if diagonal < 31 { diagonal } else { 31 };
            loop {
                let y = diagonal.saturating_sub(x);
                if y < 32 {
                    #[expect(
                        clippy::cast_possible_truncation,
                        reason = "the generated 32x32 raster index is bounded below 1024"
                    )]
                    let index = y.saturating_mul(32).saturating_add(x) as u16;
                    scan[position] = index;
                    position = position.saturating_add(1);
                }
                if x == 0 {
                    break;
                }
                x = x.saturating_sub(1);
            }
        } else {
            let mut x = diagonal.saturating_sub(31);
            let end = if diagonal < 31 { diagonal } else { 31 };
            while x <= end {
                let y = diagonal.saturating_sub(x);
                #[expect(
                    clippy::cast_possible_truncation,
                    reason = "the generated 32x32 raster index is bounded below 1024"
                )]
                let index = y.saturating_mul(32).saturating_add(x) as u16;
                scan[position] = index;
                position = position.saturating_add(1);
                x = x.saturating_add(1);
            }
        }
        diagonal = diagonal.saturating_add(1);
    }
    scan
}

const LOSSY_LUMA_32X32_SCAN: [u16; 1024] = make_lossy_luma_32x32_scan();

