const LOSSY_LUMA_16X8_LEVEL_STRIDE: usize = 8;
const LOSSY_LUMA_16X8_LEVELS: usize = LOSSY_LUMA_16X8_LEVEL_STRIDE * 18;

const LOSSY_LUMA_32X16_LEVEL_STRIDE: usize = 16;
const LOSSY_LUMA_32X16_LEVELS: usize = LOSSY_LUMA_32X16_LEVEL_STRIDE * 34;

const LOSSY_LUMA_32X8_LEVEL_STRIDE: usize = 8;
const LOSSY_LUMA_32X8_LEVELS: usize = LOSSY_LUMA_32X8_LEVEL_STRIDE * 34;

const LOSSY_CHROMA_4X16_LEVEL_STRIDE: usize = 16;
const LOSSY_CHROMA_4X16_LEVELS: usize = LOSSY_CHROMA_4X16_LEVEL_STRIDE * 12;

const LOSSY_LUMA_8X32_LEVEL_STRIDE: usize = 32;
const LOSSY_LUMA_8X32_LEVELS: usize = LOSSY_LUMA_8X32_LEVEL_STRIDE * 34;

const LOSSY_LUMA_16X16_LEVEL_STRIDE: usize = 16;
const LOSSY_LUMA_16X16_LEVELS: usize = LOSSY_LUMA_16X16_LEVEL_STRIDE * 18;

const LOSSY_LUMA_32X32_LEVEL_STRIDE: usize = 32;
const LOSSY_LUMA_32X32_LEVELS: usize = LOSSY_LUMA_32X32_LEVEL_STRIDE * 34;

fn lossy_luma_level_index(row: usize, column: usize) -> Option<usize> {
    row.checked_mul(LOSSY_LUMA_LEVEL_STRIDE)?
        .checked_add(column)
        .filter(|&index| index < LOSSY_LUMA_LEVELS)
}

fn lossy_luma_level(levels: &[u8; LOSSY_LUMA_LEVELS], row: usize, column: usize) -> Option<u8> {
    let index = lossy_luma_level_index(row, column)?;
    levels.get(index).copied()
}

fn set_lossy_luma_level(
    levels: &mut [u8; LOSSY_LUMA_LEVELS],
    row: usize,
    column: usize,
    value: u8,
) -> PortableResult<()> {
    let index = lossy_luma_level_index(row, column).portable()?;
    *levels.get_mut(index).portable()? = value;
    Ok(())
}

fn lossy_luma_low_context(
    levels: &[u8; LOSSY_LUMA_LEVELS],
    x: usize,
    y: usize,
) -> PortableResult<(usize, u32)> {
    // ✅ VERIFIED: rav1d 1.1.0 src/recon.rs:476-519 and src/tables.rs:506-529.
    // The reference passes a slice beginning at `x * stride + y` into
    // `get_lo_ctx`; reproduce that relative neighborhood safely with checked
    // offsets instead of pointer arithmetic.
    let origin = x
        .checked_mul(LOSSY_LUMA_LEVEL_STRIDE)
        .and_then(|index| index.checked_add(y))
        .filter(|&index| index < LOSSY_LUMA_LEVELS)
        .portable()?;
    let level_at = |row: usize, column: usize| {
        origin
            .checked_add(row.checked_mul(LOSSY_LUMA_LEVEL_STRIDE).portable()?)
            .and_then(|index| index.checked_add(column))
            .and_then(|index| levels.get(index).copied())
            .portable()
    };
    let mut high_magnitude = u32::from(level_at(0, 1)?);
    high_magnitude = high_magnitude
        .saturating_add(u32::from(level_at(1, 0)?))
        .saturating_add(u32::from(level_at(1, 1)?));
    let mut magnitude = high_magnitude
        .saturating_add(u32::from(level_at(0, 2)?))
        .saturating_add(u32::from(level_at(2, 0)?));
    const LO_CONTEXT_OFFSETS: [[u8; 5]; 5] = [
        [0, 1, 6, 6, 21],
        [1, 6, 6, 21, 21],
        [6, 6, 21, 21, 21],
        [6, 21, 21, 21, 21],
        [21, 21, 21, 21, 21],
    ];
    let offset = usize::from(LO_CONTEXT_OFFSETS[y.min(4)][x.min(4)]);
    magnitude = if magnitude > 512 {
        4
    } else {
        (magnitude.saturating_add(64)) >> 7
    };
    let low_context = offset
        .checked_add(usize::try_from(magnitude).map_err(|_| PortableUnavailable)?)
        .filter(|&context| context < 26)
        .portable()?;
    Ok((low_context, high_magnitude))
}

fn lossy_luma_8x8_1d_low_context(
    levels: &[u8; LOSSY_LUMA_8X8_1D_LEVELS],
    x: usize,
    y: usize,
) -> PortableResult<(usize, u32)> {
    // ✅ VERIFIED: dav1d 1.5.3 src/recon_tmpl.c:get_lo_ctx. For TX_CLASS_H
    // and TX_CLASS_V the reference uses a 16-byte stride and a one-dimensional
    // context offset based on y; the checked layout keeps the same guard rows.
    let origin = x
        .checked_mul(LOSSY_LUMA_8X8_1D_LEVEL_STRIDE)
        .and_then(|index| index.checked_add(y))
        .filter(|&index| index < LOSSY_LUMA_8X8_1D_LEVELS)
        .portable()?;
    let level_at = |row: usize, column: usize| {
        origin
            .checked_add(row.checked_mul(LOSSY_LUMA_8X8_1D_LEVEL_STRIDE).portable()?)
            .and_then(|index| index.checked_add(column))
            .and_then(|index| levels.get(index).copied())
            .portable()
    };
    let mut high_magnitude = u32::from(level_at(0, 1)?);
    high_magnitude = high_magnitude
        .saturating_add(u32::from(level_at(1, 0)?))
        .saturating_add(u32::from(level_at(0, 2)?));
    let magnitude = high_magnitude
        .saturating_add(u32::from(level_at(0, 3)?))
        .saturating_add(u32::from(level_at(0, 4)?));
    let offset = 26_usize.saturating_add(if y > 1 { 10 } else { y.saturating_mul(5) });
    let magnitude = if magnitude > 512 {
        4
    } else {
        (magnitude.saturating_add(64)) >> 7
    };
    let low_context = offset
        .checked_add(usize::try_from(magnitude).map_err(|_| PortableUnavailable)?)
        .filter(|&context| context < 41)
        .portable()?;
    Ok((low_context, high_magnitude))
}

