fn decode_lossy_luma_16x8_coefficients(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    luma_mode: usize,
    cdfs: &mut BlockCdfs,
    quantization: LossyQuantization,
    dc_sign_context: usize,
) -> PortableResult<(Lossy16x8TransformCoefficients, Lossy4x8TransformKind)> {
    let skipped = decode_lossy_luma_tx_context_two_skip(decoder, cdfs);
    if skipped {
        return Ok(([0_i32; 128], Lossy4x8TransformKind::DctDct));
    }

    let transform_type = decoder.adaptive_symbol(
        cdfs.lossy_luma_8x8_transform_type
            .get_mut(luma_mode)
            .portable()?,
        6,
    );
    let transform_kind = match transform_type {
        0 => Lossy4x8TransformKind::IdentityIdentity,
        1 => Lossy4x8TransformKind::DctDct,
        2 => Lossy4x8TransformKind::IdentityDct,
        3 => Lossy4x8TransformKind::DctIdentity,
        4 => Lossy4x8TransformKind::AdstAdst,
        5 => Lossy4x8TransformKind::AdstDct,
        6 => Lossy4x8TransformKind::DctAdst,
        _ => return Err(PortableUnavailable),
    };
    let one_dimensional = matches!(
        transform_kind,
        Lossy4x8TransformKind::IdentityDct | Lossy4x8TransformKind::DctIdentity
    );
    let eob_bin = if one_dimensional {
        decoder.adaptive_symbol(&mut cdfs.lossy_luma_8x16_eob_bin_1d, 7)
    } else {
        decoder.adaptive_symbol(&mut cdfs.lossy_luma_8x16_eob_bin, 7)
    };
    if one_dimensional {
        let (coefficients, residual_context) = decode_lossy_luma_8x16_1d_coefficients(
            decoder,
            cdfs,
            quantization,
            eob_bin,
            matches!(transform_type, 2),
            dc_sign_context,
            LossyOneDimensionalGeometry::R16x8,
        )?;
        cdfs.last_lossy_luma_residual_context = Some(residual_context);
        return Ok((coefficients, transform_kind));
    }
    let coefficients = decode_lossy_large_two_d_coefficients(
        decoder,
        0,
        cdfs,
        quantization,
        Some(dc_sign_context),
        LossyLargeCoefficientLayout {
            eob_bin,
            scan: &LOSSY_LUMA_16X8_SCAN,
            coefficient_count: 128,
            shift: 3,
            mask: 7,
            levels_stride: LOSSY_LUMA_16X8_LEVEL_STRIDE,
            levels_len: LOSSY_LUMA_16X8_LEVELS,
            eob_thresholds: (16, 32),
            cdf_set: LossyLargeCdfSet::Luma16x8,
        },
    )?;
    Ok((
        coefficients.try_into().map_err(|_| PortableUnavailable)?,
        transform_kind,
    ))
}

