fn decode_subsampled_chroma_angle(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
    block_size: BlockSize,
    chroma_mode: u32,
    base_angle: i32,
) -> PortableResult<i32> {
    // ✅ VERIFIED: dav1d 1.5.3 src/decode.c:1099-1116. Chroma angular
    // predictors use the same angle-delta CDF family as luma whenever the
    // coded block reaches BLOCK_8X8. The mode-specific acceptance interval
    // is part of the bitstream contract, so reject an impossible delta
    // instead of consuming later syntax with a mismatched state.
    let angle_delta = if block_size.has_angle_delta() {
        let angle_index =
            usize::try_from(chroma_mode.saturating_sub(1)).map_err(|_| PortableUnavailable)?;
        #[expect(
            clippy::cast_possible_wrap,
            reason = "the decoded symbol is bounded to 0..=6"
        )]
        {
            (decoder.adaptive_symbol(cdfs.luma_angle.get_mut(angle_index).portable()?, 6) as i32)
                .wrapping_sub(3)
        }
    } else {
        0
    };
    let angle = base_angle.saturating_add(3_i32.saturating_mul(angle_delta));
    let accepted = match chroma_mode {
        1 | 2 => 0 < angle && angle < 270,
        3 | 8 => 0 < angle && angle < 90,
        4..=6 => 90 < angle && angle < 180,
        7 => 180 < angle && angle < 270,
        _ => false,
    };
    accepted.then_some(angle).portable()
}

fn decode_cfl_chroma_predictor(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
) -> PortableResult<ChromaPredictor> {
    let sign = decoder
        .adaptive_symbol(&mut cdfs.cfl_sign, 7)
        .saturating_add(1);
    let sign_u = sign / 3;
    let sign_v = sign.saturating_sub(sign_u.saturating_mul(3));
    let alpha = |decoder: &mut RangeDecoder<'_, '_, '_>,
                 cdfs: &mut BlockCdfs,
                 sign: u32,
                 other_sign: u32|
     -> i32 {
        let context = usize::from(sign == 2)
            .saturating_mul(3)
            .saturating_add(usize::try_from(other_sign).unwrap_or(0));
        let value = decoder.adaptive_symbol(&mut cdfs.cfl_alpha[context], 15);
        let value = i32::try_from(value.saturating_add(1)).unwrap_or(i32::MAX);
        if sign == 1 {
            value.saturating_neg()
        } else {
            value
        }
    };
    let alpha_u = if sign_u == 0 {
        0
    } else {
        alpha(decoder, cdfs, sign_u, sign_v)
    };
    let alpha_v = if sign_v == 0 {
        0
    } else {
        alpha(decoder, cdfs, sign_v, sign_u)
    };
    Ok(ChromaPredictor::Cfl { alpha_u, alpha_v })
}

fn palette_cache_entries(
    above: PalettePlane,
    above_available: bool,
    left: PalettePlane,
    left_available: bool,
) -> ([u16; PALETTE_CAPACITY * 2], usize) {
    let mut entries = [0_u16; PALETTE_CAPACITY * 2];
    let mut count = 0_usize;
    for palette in [
        above_available.then_some(above),
        left_available.then_some(left),
    ]
    .into_iter()
    .flatten()
    {
        for color in palette.colors.into_iter().take(usize::from(palette.size)) {
            if !entries[..count].contains(&color)
                && let Some(slot) = entries.get_mut(count)
            {
                *slot = color;
                count = count.saturating_add(1);
            }
        }
    }
    entries[..count].sort_unstable();
    (entries, count)
}

fn decode_palette_plane(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
    sample_depth: SampleDepth,
    plane: usize,
    size_context: usize,
    neighbors: PalettePlaneContext,
) -> PortableResult<PalettePlane> {
    let size_symbol = decoder.adaptive_symbol(
        cdfs.palette_size
            .get_mut(plane)
            .and_then(|contexts| contexts.get_mut(size_context))
            .ok_or(PortableUnavailable)?,
        6,
    );
    let size = usize::try_from(size_symbol.saturating_add(2)).map_err(|_| PortableUnavailable)?;
    (2..=PALETTE_CAPACITY)
        .contains(&size)
        .then_some(())
        .portable()?;

    let (cache, cache_count) = palette_cache_entries(
        neighbors.above,
        neighbors.above_cache_available,
        neighbors.left,
        neighbors.left_cache_available,
    );
    let mut used_cache = [0_u16; PALETTE_CAPACITY];
    let mut used_count = 0_usize;
    for &color in cache.iter().take(cache_count) {
        if used_count >= size {
            break;
        }
        if decoder.equal()
            && let Some(slot) = used_cache.get_mut(used_count)
        {
            *slot = color;
            used_count = used_count.saturating_add(1);
        }
    }

    let mut new_colors = [0_u16; PALETTE_CAPACITY];
    let mut new_count = used_count;
    if new_count < size {
        let max_color = u32::from(sample_depth.maximum());
        let increment = u32::from(plane == 0);
        let mut previous = decoder.bits(sample_depth.bits()).min(max_color);
        new_colors[new_count] = u16::try_from(previous).map_err(|_| PortableUnavailable)?;
        new_count = new_count.saturating_add(1);
        if new_count < size {
            let mut delta_bits = sample_depth
                .bits()
                .saturating_sub(3)
                .saturating_add(decoder.bits(2));
            while new_count < size {
                let delta = decoder.bits(delta_bits);
                previous = previous
                    .saturating_add(delta)
                    .saturating_add(increment)
                    .min(max_color);
                new_colors[new_count] = u16::try_from(previous).map_err(|_| PortableUnavailable)?;
                new_count = new_count.saturating_add(1);
                if previous.saturating_add(increment) >= max_color {
                    for color in new_colors.iter_mut().take(size).skip(new_count) {
                        *color = u16::try_from(max_color).unwrap_or(u16::MAX);
                    }
                    new_count = size;
                    break;
                }
                let remaining = max_color.saturating_sub(previous).saturating_sub(increment);
                let remaining_bits = 1_u32.saturating_add(remaining.ilog2());
                delta_bits = delta_bits.min(remaining_bits);
            }
        }
    }

    let mut colors = [0_u16; PALETTE_CAPACITY];
    let mut cache_index = 0_usize;
    let mut new_index = used_count;
    for color in colors.iter_mut().take(size) {
        let use_cached = cache_index < used_count
            && (new_index >= new_count || used_cache[cache_index] <= new_colors[new_index]);
        if use_cached {
            *color = used_cache[cache_index];
            cache_index = cache_index.saturating_add(1);
        } else {
            *color = *new_colors.get(new_index).ok_or(PortableUnavailable)?;
            new_index = new_index.saturating_add(1);
        }
    }
    Ok(PalettePlane {
        size: u8::try_from(size).map_err(|_| PortableUnavailable)?,
        colors,
    })
}

fn decode_palette_v_plane(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    sample_depth: SampleDepth,
    size: u8,
) -> PortableResult<PalettePlane> {
    let size = usize::from(size);
    let delta_coded = decoder.equal();
    let mut colors = [0_u16; PALETTE_CAPACITY];
    if delta_coded {
        let delta_bits = sample_depth
            .bits()
            .saturating_sub(4)
            .saturating_add(decoder.bits(2));
        let mut previous = i32::try_from(decoder.bits(sample_depth.bits())).unwrap_or(i32::MAX);
        colors[0] = u16::try_from(previous).map_err(|_| PortableUnavailable)?;
        for color in colors.iter_mut().take(size).skip(1) {
            let magnitude = i32::try_from(decoder.bits(delta_bits)).unwrap_or(i32::MAX);
            let delta = if magnitude != 0 && decoder.equal() {
                magnitude.saturating_neg()
            } else {
                magnitude
            };
            previous = previous.saturating_add(delta) & i32::from(sample_depth.maximum());
            *color = u16::try_from(previous).map_err(|_| PortableUnavailable)?;
        }
    } else {
        for color in colors.iter_mut().take(size) {
            *color = u16::try_from(decoder.bits(sample_depth.bits())).unwrap_or(u16::MAX);
        }
    }
    Ok(PalettePlane {
        size: u8::try_from(size).map_err(|_| PortableUnavailable)?,
        colors,
    })
}

fn palette_index_order(
    indices: &[u8],
    row: usize,
    column: usize,
    stride: usize,
    width: usize,
    height: usize,
    palette_size: usize,
) -> PortableResult<(usize, [u8; PALETTE_CAPACITY])> {
    (stride == width
        && row < height
        && column < width
        && stride.checked_mul(height) == Some(indices.len()))
    .then_some(())
    .portable()?;
    let mut order = [0_u8; PALETTE_CAPACITY];
    let mut order_len = 0_usize;
    let mut add = |value: u8| {
        if !order[..order_len].contains(&value)
            && let Some(slot) = order.get_mut(order_len)
        {
            *slot = value;
            order_len = order_len.saturating_add(1);
        }
    };
    let top = row
        .checked_sub(1)
        .and_then(|top_row| indices.get(top_row.saturating_mul(stride).saturating_add(column)))
        .copied();
    let left = column
        .checked_sub(1)
        .and_then(|left_column| indices.get(row.saturating_mul(stride).saturating_add(left_column)))
        .copied();
    let top_left = row
        .checked_sub(1)
        .zip(column.checked_sub(1))
        .and_then(|(top_row, left_column)| {
            indices.get(top_row.saturating_mul(stride).saturating_add(left_column))
        })
        .copied();
    let context = match (top, left, top_left) {
        (None, Some(left), _) | (Some(left), None, _) => {
            add(left);
            0
        }
        (Some(top), Some(left), Some(top_left)) if top == left && top == top_left => {
            add(top);
            4
        }
        (Some(top), Some(left), Some(top_left)) if top == left => {
            add(top);
            add(top_left);
            3
        }
        (Some(top), Some(left), Some(top_left)) if top == top_left => {
            add(top_left);
            add(left);
            2
        }
        (Some(top), Some(left), Some(top_left)) if left == top_left => {
            add(top_left);
            add(top);
            2
        }
        (Some(top), Some(left), Some(top_left)) => {
            add(top.min(left));
            add(top.max(left));
            add(top_left);
            1
        }
        _ => 0,
    };
    for index in 0..palette_size {
        let index = u8::try_from(index).unwrap_or(u8::MAX);
        add(index);
    }
    Ok((context, order))
}

#[expect(
    clippy::too_many_arguments,
    reason = "palette decoding keeps coded stride and clipped entropy extents explicit"
)]
fn decode_palette_indices_into(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
    arena: &mut PaletteMapArena,
    plane: usize,
    palette_size: u8,
    coded_width: u32,
    coded_height: u32,
    entropy_width: u32,
    entropy_height: u32,
) -> PortableResult<PaletteMapSpan> {
    let coded_width = usize::try_from(coded_width).map_err(|_| PortableUnavailable)?;
    let coded_height = usize::try_from(coded_height).map_err(|_| PortableUnavailable)?;
    let entropy_width = usize::try_from(entropy_width).map_err(|_| PortableUnavailable)?;
    let entropy_height = usize::try_from(entropy_height).map_err(|_| PortableUnavailable)?;
    let sample_count = coded_width
        .checked_mul(coded_height)
        .ok_or(PortableUnavailable)?;
    (sample_count > 0 && sample_count <= MAX_PALETTE_MAP_SAMPLES)
        .then_some(())
        .portable()?;
    (entropy_width > 0
        && entropy_height > 0
        && entropy_width <= coded_width
        && entropy_height <= coded_height)
        .then_some(())
        .portable()?;
    let palette_size = usize::from(palette_size);
    (2..=PALETTE_CAPACITY)
        .contains(&palette_size)
        .then_some(())
        .portable()?;
    // Reserve and zero the complete coded map before the first range-coded
    // index. A later failure is terminal, but no partially decoded span is
    // published into `PaletteSyntax`.
    let span = arena.allocate_map(coded_width, coded_height)?;
    let indices = arena.map_mut(span)?;
    indices[0] = u8::try_from(decoder.uniform(u32::try_from(palette_size).unwrap_or(0)))
        .map_err(|_| PortableUnavailable)?;
    for diagonal in 1..entropy_width
        .saturating_add(entropy_height)
        .saturating_sub(1)
    {
        let first_column = diagonal.min(entropy_width.saturating_sub(1));
        let last_column = diagonal.saturating_sub(entropy_height.saturating_sub(1));
        for column in (last_column..=first_column).rev() {
            let row = diagonal.saturating_sub(column);
            let (context, order) = palette_index_order(
                indices,
                row,
                column,
                coded_width,
                coded_width,
                coded_height,
                palette_size,
            )?;
            let symbol = decoder.adaptive_symbol(
                cdfs.color_map
                    .get_mut(plane)
                    .and_then(|maps| {
                        maps.get_mut(palette_size.saturating_sub(2))
                            .and_then(|contexts| contexts.get_mut(context))
                    })
                    .ok_or(PortableUnavailable)?,
                palette_size.saturating_sub(1),
            );
            let symbol = usize::try_from(symbol).map_err(|_| PortableUnavailable)?;
            let value = *order.get(symbol).ok_or(PortableUnavailable)?;
            let index = row.saturating_mul(coded_width).saturating_add(column);
            *indices.get_mut(index).ok_or(PortableUnavailable)? = value;
        }
    }
    if entropy_width < coded_width {
        for row in 0..entropy_height {
            let row_start = row.checked_mul(coded_width).ok_or(PortableUnavailable)?;
            let filler = *indices
                .get(
                    row_start
                        .checked_add(entropy_width.saturating_sub(1))
                        .ok_or(PortableUnavailable)?,
                )
                .ok_or(PortableUnavailable)?;
            let fill_start = row_start
                .checked_add(entropy_width)
                .ok_or(PortableUnavailable)?;
            let fill_end = row_start
                .checked_add(coded_width)
                .ok_or(PortableUnavailable)?;
            indices
                .get_mut(fill_start..fill_end)
                .ok_or(PortableUnavailable)?
                .fill(filler);
        }
    }
    if entropy_height < coded_height {
        let source_start = entropy_height
            .saturating_sub(1)
            .checked_mul(coded_width)
            .ok_or(PortableUnavailable)?;
        let source_end = source_start
            .checked_add(coded_width)
            .filter(|&end| end <= sample_count)
            .ok_or(PortableUnavailable)?;
        for row in entropy_height..coded_height {
            let destination_start = row.checked_mul(coded_width).ok_or(PortableUnavailable)?;
            destination_start
                .checked_add(coded_width)
                .filter(|&end| end <= sample_count)
                .ok_or(PortableUnavailable)?;
            indices.copy_within(source_start..source_end, destination_start);
        }
    }
    Ok(span)
}

fn decode_palette_syntax(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
    block_size: BlockSize,
    chroma_sampling: ChromaSampling,
    luma_predictor: LumaPredictor,
    chroma_predictor: ChromaPredictor,
    tools: BlockTools,
) -> PortableResult<PaletteSyntax> {
    if !tools.allow_screen_content_tools || !block_size.palette_allowed() {
        return Ok(PaletteSyntax::default());
    }
    let palette_context = tools.palette_context;
    let size_context = block_size
        .palette_size_context()
        .ok_or(PortableUnavailable)?;
    let use_y = if matches!(luma_predictor, LumaPredictor::Dc) {
        let context =
            usize::from(palette_context.above_available && palette_context.above.y.is_present())
                .saturating_add(usize::from(
                    palette_context.left_available && palette_context.left.y.is_present(),
                ));
        decoder.adaptive_bool(
            cdfs.palette_y
                .get_mut(size_context)
                .and_then(|contexts| contexts.get_mut(context))
                .ok_or(PortableUnavailable)?,
        )
    } else {
        false
    };

    let y = if use_y {
        decode_palette_plane(
            decoder,
            cdfs,
            tools.sample_depth,
            0,
            size_context,
            PalettePlaneContext {
                above: palette_context.above.y,
                above_cache_available: palette_context.above_cache_available,
                left: palette_context.left.y,
                left_cache_available: palette_context.left_available,
            },
        )?
    } else {
        PalettePlane::default()
    };
    let use_uv = if !matches!(chroma_sampling, ChromaSampling::Monochrome)
        && matches!(chroma_predictor, ChromaPredictor::Dc)
    {
        decoder.adaptive_bool(&mut cdfs.palette_uv[usize::from(y.is_present())])
    } else {
        false
    };
    if !use_y && !use_uv {
        return Ok(PaletteSyntax::default());
    }
    let (u, v) = if use_uv {
        let u = decode_palette_plane(
            decoder,
            cdfs,
            tools.sample_depth,
            1,
            size_context,
            PalettePlaneContext {
                above: palette_context.above.u,
                above_cache_available: palette_context.above_cache_available,
                left: palette_context.left.u,
                left_cache_available: palette_context.left_available,
            },
        )?;
        let v = decode_palette_v_plane(decoder, tools.sample_depth, u.size)?;
        (u, v)
    } else {
        (PalettePlane::default(), PalettePlane::default())
    };
    Ok(PaletteSyntax {
        y,
        u,
        v,
        ..PaletteSyntax::default()
    })
}

fn decode_palette_index_maps(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
    arena: &mut PaletteMapArena,
    geometry: PaletteGeometry,
    palette: &mut PaletteSyntax,
) -> PortableResult<()> {
    if palette.y.is_present() {
        let span = decode_palette_indices_into(
            decoder,
            cdfs,
            arena,
            0,
            palette.y.size,
            u32::try_from(geometry.y.coded_width).map_err(|_| PortableUnavailable)?,
            u32::try_from(geometry.y.coded_height).map_err(|_| PortableUnavailable)?,
            u32::try_from(geometry.y.entropy_width).map_err(|_| PortableUnavailable)?,
            u32::try_from(geometry.y.entropy_height).map_err(|_| PortableUnavailable)?,
        )?;
        palette.y_map = Some(span);
    }
    if palette.u.is_present() || palette.v.is_present() {
        (palette.u.is_present() && palette.v.is_present() && palette.u.size == palette.v.size)
            .then_some(())
            .portable()?;
        let uv = geometry.uv.ok_or(PortableUnavailable)?;
        let span = decode_palette_indices_into(
            decoder,
            cdfs,
            arena,
            1,
            palette.u.size,
            u32::try_from(uv.coded_width).map_err(|_| PortableUnavailable)?,
            u32::try_from(uv.coded_height).map_err(|_| PortableUnavailable)?,
            u32::try_from(uv.entropy_width).map_err(|_| PortableUnavailable)?,
            u32::try_from(uv.entropy_height).map_err(|_| PortableUnavailable)?,
        )?;
        palette.uv_map = Some(span);
    }
    Ok(())
}

