fn reconstruct_lossy_luma_16x4_from_prediction(
    prediction: [u16; 64],
    coefficients: Option<LossyTransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        Lossy4x8TransformKind::IdentityIdentity => transform::inverse_identity16x4(&coefficients),
        Lossy4x8TransformKind::DctDct => transform::inverse_dct16x4(&coefficients),
        Lossy4x8TransformKind::IdentityDct => transform::inverse_identity_dct16x4(&coefficients),
        Lossy4x8TransformKind::DctIdentity => transform::inverse_dct_identity16x4(&coefficients),
        Lossy4x8TransformKind::AdstAdst => transform::inverse_adst_adst16x4(&coefficients),
        // Keep this mapping pinned to dav1d's transform type rather than to
        // the helper names: for R16x4, the column-major safe
        // `inverse_adst_dct16x4` helper is the exact scalar realization of
        // dav1d's DCT_ADST sentence.
        Lossy4x8TransformKind::AdstDct => transform::inverse_dct_adst16x4(&coefficients),
        Lossy4x8TransformKind::DctAdst => transform::inverse_adst_dct16x4(&coefficients),
    };
    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

