fn reconstruct_lossy_luma_32x16_diagonal_z2(
    top: [u16; 32],
    left: [u16; 16],
    angle: i32,
    coefficients: Option<Lossy32x16TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let mut dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let mut dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;
    let upsample_above = angle.saturating_sub(90) < 40;
    let upsample_left = 180_i32.saturating_sub(angle) < 40;

    const WIDTH: usize = 32;
    const HEIGHT: usize = 16;
    const TOP_LEFT: usize = 256;
    let mut edge = [0_u16; WIDTH * HEIGHT];
    edge[TOP_LEFT] = top[0];
    if upsample_above {
        let mut source = [0_u16; 33];
        source[0] = top[0];
        source[1..].copy_from_slice(&top);
        let mut upsampled = [0_u16; 65];
        const KERNEL: [i32; 4] = [-1, 9, 9, -1];
        for index in 0_usize..32 {
            upsampled[index.saturating_mul(2)] = source[index];
            let mut sum = 0_i32;
            for (tap, weight) in KERNEL.into_iter().enumerate() {
                let source_index = index
                    .saturating_add(tap)
                    .saturating_sub(1)
                    .min(source.len().saturating_sub(1));
                sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
            }
            #[expect(
                clippy::cast_sign_loss,
                reason = "the upsampled angular edge is explicitly clamped"
            )]
            {
                upsampled[index.saturating_mul(2).saturating_add(1)] =
                    ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
            }
        }
        upsampled[64] = source[32];
        edge[TOP_LEFT..TOP_LEFT.saturating_add(65)].copy_from_slice(&upsampled);
        dx = dx.saturating_mul(2);
    } else {
        edge[TOP_LEFT.saturating_add(1)..TOP_LEFT.saturating_add(33)].copy_from_slice(&top);
    }

    if upsample_left {
        let mut source = [0_u16; 17];
        source[..16].copy_from_slice(&[
            left[15], left[14], left[13], left[12], left[11], left[10], left[9], left[8], left[7],
            left[6], left[5], left[4], left[3], left[2], left[1], left[0],
        ]);
        source[16] = top[0];
        let mut upsampled = [0_u16; 33];
        const KERNEL: [i32; 4] = [-1, 9, 9, -1];
        for index in 0_usize..16 {
            upsampled[index.saturating_mul(2)] = source[index];
            let mut sum = 0_i32;
            for (tap, weight) in KERNEL.into_iter().enumerate() {
                let source_index = index
                    .saturating_add(tap)
                    .saturating_sub(1)
                    .min(source.len().saturating_sub(1));
                sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
            }
            #[expect(
                clippy::cast_sign_loss,
                reason = "the upsampled angular edge is explicitly clamped"
            )]
            {
                upsampled[index.saturating_mul(2).saturating_add(1)] =
                    ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
            }
        }
        upsampled[32] = source[16];
        edge[TOP_LEFT.saturating_sub(32)..=TOP_LEFT].copy_from_slice(&upsampled);
        dy = dy.saturating_mul(2);
    } else {
        for (index, sample) in left.into_iter().enumerate() {
            edge[TOP_LEFT.saturating_sub(1).saturating_sub(index)] = sample;
        }
    }

    let base_increment = if upsample_above { 2_i32 } else { 1_i32 };
    let left_index = TOP_LEFT.saturating_sub(if upsample_left { 2 } else { 1 });
    let mut prediction = [0_u16; WIDTH * HEIGHT];
    for y_index in 0_usize..HEIGHT {
        let y = i32::try_from(y_index).map_err(|_| PortableUnavailable)?;
        let xpos = (if upsample_above { 2_i32 } else { 1_i32 })
            .saturating_mul(64)
            .saturating_sub(dx.saturating_mul(y.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x_index in 0_usize..WIDTH {
            let x = i32::try_from(x_index).map_err(|_| PortableUnavailable)?;
            let base_x = base_x.saturating_add(base_increment.saturating_mul(x));
            let ypos = y
                .saturating_mul(if upsample_left { 128 } else { 64 })
                .saturating_sub(dy.saturating_mul(x.saturating_add(1)));
            let sample = if base_x >= 0 {
                let first_index = usize::try_from(
                    i32::try_from(TOP_LEFT)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_add(base_x),
                )
                .map_err(|_| PortableUnavailable)?;
                let second_index = first_index.saturating_add(1);
                let first = i32::from(*edge.get(first_index).portable()?);
                let second = i32::from(*edge.get(second_index).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let base_y = ypos >> 6;
                let frac_y = ypos & 0x3e;
                let first_index = usize::try_from(
                    i32::try_from(left_index)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(base_y),
                )
                .map_err(|_| PortableUnavailable)?;
                let second_index = usize::try_from(
                    i32::try_from(left_index)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(base_y.saturating_add(1)),
                )
                .map_err(|_| PortableUnavailable)?;
                let first = i32::from(*edge.get(first_index).portable()?);
                let second = i32::from(*edge.get(second_index).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            #[expect(
                clippy::cast_sign_loss,
                reason = "the directional predictor is explicitly clamped to eight-bit range"
            )]
            let sample = sample.clamp(0, 255) as u16;
            *prediction
                .get_mut(y_index.saturating_mul(WIDTH).saturating_add(x_index))
                .portable()? = sample;
        }
    }
    Ok(reconstruct_lossy_luma_32x16_from_prediction(
        prediction,
        coefficients,
    ))
}

fn reconstruct_lossy_luma_32x16_diagonal_z3(
    left: [u16; 16],
    _top_left: u16,
    angle: i32,
    coefficients: Option<Lossy32x16TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (180 < angle && angle < 270).then_some(()).portable()?;
    let dy_index =
        usize::try_from(270_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let full_left: [u16; 32] =
        std::array::from_fn(|index| left[index.min(left.len().saturating_sub(1))]);
    let mut prediction = [0_u16; 512];
    for y in 0_usize..16 {
        for x in 0_usize..32 {
            prediction[y.saturating_mul(32).saturating_add(x)] =
                diagonal_z3_predictor_sample(&full_left, 31, dy, 1, x, y)?;
        }
    }
    Ok(reconstruct_lossy_luma_32x16_from_prediction(
        prediction,
        coefficients,
    ))
}

fn reconstruct_lossy_luma_64x16(
    predictor: u16,
    coefficients: Option<Lossy64x16TransformCoefficients>,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 512]);
    let residual = transform::inverse_dct64x16(&coefficients);
    reconstruct_lossy_residual_plane(predictor, &residual)
}

fn reconstruct_lossy_luma_64x16_from_prediction(
    prediction: [u16; 1024],
    coefficients: Option<Lossy64x16TransformCoefficients>,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 512]);
    let residual = transform::inverse_dct64x16(&coefficients);
    reconstruct_lossy_predicted_plane(&prediction, &residual)
}

/// Reconstruct an R64x16 luma block with AV1's smooth-horizontal predictor.
///
/// The predictor blends the right-most top sample with each sample on the
/// left edge using the width-specific smooth weights.  R64x16 has an
/// implicitly selected DCT-DCT residual transform because its transform
/// dimensions reach the AV1 large-transform limit.
fn reconstruct_lossy_luma_64x16_smooth_horizontal(
    top: [u16; 64],
    left: [u16; 16],
    coefficients: Option<Lossy64x16TransformCoefficients>,
) -> ReconstructedPlane {
    const SMOOTH_WEIGHTS_64: [i32; 64] = [
        255, 248, 240, 233, 225, 218, 210, 203, 196, 189, 182, 176, 169, 163, 156, 150, 144, 138,
        133, 127, 121, 116, 111, 106, 101, 96, 91, 86, 82, 77, 73, 69, 65, 61, 57, 54, 50, 47, 44,
        41, 38, 35, 32, 29, 27, 25, 22, 20, 18, 16, 15, 13, 12, 10, 9, 8, 7, 6, 6, 5, 5, 4, 4, 4,
    ];
    let right = i32::from(top[63]);
    let prediction: [u16; 1024] = std::array::from_fn(|index| {
        let row = index / 64;
        let column = index % 64;
        let weight = SMOOTH_WEIGHTS_64[column];
        let value = weight
            .saturating_mul(i32::from(left[row]))
            .saturating_add((256_i32.saturating_sub(weight)).saturating_mul(right))
            .saturating_add(128)
            >> 8;
        #[expect(
            clippy::cast_sign_loss,
            reason = "the smooth predictor is explicitly clamped to eight-bit range"
        )]
        {
            value.clamp(0, 255) as u16
        }
    });
    reconstruct_lossy_luma_64x16_from_prediction(prediction, coefficients)
}

/// Reconstruct an R64x16 luma block whose transform tree split into two
/// horizontal R32x16 children.
fn reconstruct_lossy_luma_64x16_horizontal_split(
    predictor: LumaPredictor,
    top: [u16; 64],
    left: [u16; 16],
    has_left: bool,
    split: LossyLuma32x16HorizontalSplit,
) -> PortableResult<ReconstructedPlane> {
    const SMOOTH_WEIGHTS_32: [i32; 32] = [
        255, 240, 225, 210, 196, 182, 169, 157, 145, 133, 122, 111, 101, 92, 83, 74, 66, 59, 52,
        45, 39, 34, 29, 25, 21, 17, 14, 12, 10, 9, 8, 8,
    ];
    let mut samples = vec![0_u16; 1024];
    for column in 0_usize..2 {
        let offset_x = column.saturating_mul(32);
        let child_top: [u16; 32] = top[offset_x..offset_x.saturating_add(32)]
            .try_into()
            .map_err(|_| PortableUnavailable)?;
        let child_left: [u16; 16] = if column == 0 {
            left
        } else {
            std::array::from_fn(|row| samples[row * 64 + offset_x - 1])
        };
        let top_left = if column == 0 {
            child_top[0]
        } else {
            top[offset_x - 1]
        };
        let child_prediction: [u16; 512] = match predictor {
            LumaPredictor::Dc => {
                let value = if has_left || column != 0 {
                    rectangular_dc_predictor(&child_top, &child_left)
                } else {
                    one_sided_dc_predictor_32(child_top)
                };
                [value; 512]
            }
            LumaPredictor::Vertical => std::array::from_fn(|index| child_top[index % 32]),
            LumaPredictor::Horizontal => std::array::from_fn(|index| child_left[index / 32]),
            LumaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(child_top[index % 32], child_left[index / 32], top_left)
            }),
            LumaPredictor::SmoothHorizontal => std::array::from_fn(|index| {
                let row = index / 32;
                let column = index % 32;
                let weight = SMOOTH_WEIGHTS_32[column];
                let right = i32::from(child_top[31]);
                let value = weight
                    .saturating_mul(i32::from(child_left[row]))
                    .saturating_add((256_i32.saturating_sub(weight)).saturating_mul(right))
                    .saturating_add(128)
                    >> 8;
                #[expect(
                    clippy::cast_sign_loss,
                    reason = "the smooth predictor is explicitly clamped to eight-bit range"
                )]
                {
                    value.clamp(0, 255) as u16
                }
            }),
            _ => return Err(PortableUnavailable),
        };
        let child = reconstruct_lossy_luma_32x16_from_prediction(
            child_prediction,
            split.coefficients[column],
        );
        for (row, source) in child.samples.as_chunks::<32>().0.iter().enumerate() {
            let output_start = row * 64 + offset_x;
            samples[output_start..output_start + 32].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_luma_64x16_horizontal_split_from_prediction(
    prediction: [u16; 1024],
    split: LossyLuma32x16HorizontalSplit,
) -> ReconstructedPlane {
    let mut samples = vec![0_u16; 1024];
    for column in 0_usize..2 {
        let offset_x = column.saturating_mul(32);
        let child_prediction: [u16; 512] = std::array::from_fn(|index| {
            let row = index / 32;
            let x = index % 32;
            prediction[row * 64 + offset_x + x]
        });
        let child = reconstruct_lossy_luma_32x16_from_prediction(
            child_prediction,
            split.coefficients[column],
        );
        for (row, source) in child.samples.as_chunks::<32>().0.iter().enumerate() {
            let output_start = row * 64 + offset_x;
            samples[output_start..output_start + 32].copy_from_slice(source);
        }
    }
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_chroma_32x8(
    predictor: u16,
    coefficients: Option<Lossy32x8TransformCoefficients>,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 256]);
    let residual = transform::inverse_dct32x8(&coefficients);
    reconstruct_lossy_residual_plane(predictor, &residual)
}

fn reconstruct_lossy_chroma_32x8_from_prediction(
    prediction: [u16; 256],
    coefficients: Option<Lossy32x8TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    reconstruct_lossy_chroma_32x8_from_prediction_with_transform(
        prediction,
        coefficients,
        LossyTransformKind::DctDct,
    )
}

fn reconstruct_lossy_chroma_32x8_from_prediction_with_transform(
    prediction: [u16; 256],
    coefficients: Option<Lossy32x8TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    let coefficients = coefficients.unwrap_or([0_i32; 256]);
    let residual = match transform_kind {
        LossyTransformKind::DctDct => transform::inverse_dct32x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst32x8(&coefficients),
        _ => return Err(PortableUnavailable),
    };
    Ok(reconstruct_lossy_predicted_plane(&prediction, &residual))
}

fn reconstruct_lossy_luma_16x64_smooth(
    top: [u16; 16],
    left: [u16; 64],
    coefficients: Option<Lossy16x64TransformCoefficients>,
) -> ReconstructedPlane {
    const SMOOTH_WEIGHTS_16: [i32; 16] = [
        255, 225, 196, 170, 145, 123, 102, 84, 68, 54, 43, 33, 26, 20, 17, 16,
    ];
    const SMOOTH_WEIGHTS_64: [i32; 64] = [
        255, 248, 240, 233, 225, 218, 210, 203, 196, 189, 182, 176, 169, 163, 156, 150, 144, 138,
        133, 127, 121, 116, 111, 106, 101, 96, 91, 86, 82, 77, 73, 69, 65, 61, 57, 54, 50, 47, 44,
        41, 38, 35, 32, 29, 27, 25, 22, 20, 18, 16, 15, 13, 12, 10, 9, 8, 7, 6, 6, 5, 5, 4, 4, 4,
    ];
    let right = i32::from(top[15]);
    let bottom = i32::from(left[63]);
    let prediction: [u16; 1024] = std::array::from_fn(|index| {
        let y = index / 16;
        let x = index % 16;
        let vertical_weight = SMOOTH_WEIGHTS_64[y];
        let horizontal_weight = SMOOTH_WEIGHTS_16[x];
        let value = vertical_weight
            .saturating_mul(i32::from(top[x]))
            .saturating_add(
                256_i32
                    .saturating_sub(vertical_weight)
                    .saturating_mul(bottom),
            )
            .saturating_add(horizontal_weight.saturating_mul(i32::from(left[y])))
            .saturating_add(
                256_i32
                    .saturating_sub(horizontal_weight)
                    .saturating_mul(right),
            )
            .saturating_add(256)
            >> 9;
        #[expect(
            clippy::cast_sign_loss,
            reason = "the smooth predictor is explicitly clamped to eight-bit range"
        )]
        {
            value.clamp(0, 255) as u16
        }
    });
    let coefficients = coefficients.unwrap_or([0_i32; 512]);
    let residual = transform::inverse_dct16x64(&coefficients);
    reconstruct_lossy_predicted_plane(&prediction, &residual)
}

fn reconstruct_lossy_luma_16x64_diagonal_z3(
    left: [u16; 64],
    angle: i32,
    coefficients: Option<Lossy16x64TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (180 < angle && angle < 270).then_some(()).portable()?;
    let dy_index =
        usize::try_from(270_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let mut prediction = [0_u16; 1024];
    for y in 0_usize..64 {
        for x in 0_usize..16 {
            prediction[y.saturating_mul(16).saturating_add(x)] =
                diagonal_z3_predictor_sample(&left, 63, dy, 1, x, y)?;
        }
    }
    let coefficients = coefficients.unwrap_or([0_i32; 512]);
    let residual = transform::inverse_dct16x64(&coefficients);
    Ok(reconstruct_lossy_predicted_plane(&prediction, &residual))
}

fn reconstruct_lossy_chroma_8x32_diagonal_z2(
    top: [u16; 8],
    left: [u16; 32],
    angle: i32,
    coefficients: Option<Lossy8x32TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;
    const WIDTH: usize = 8;
    const HEIGHT: usize = 32;
    const TOP_LEFT: usize = HEIGHT;
    let mut edge = [0_i32; HEIGHT * 2 + 1];
    edge[TOP_LEFT] = i32::from(top[0]);
    for (index, sample) in top.into_iter().enumerate() {
        *edge
            .get_mut(TOP_LEFT.saturating_add(1).saturating_add(index))
            .portable()? = i32::from(sample);
    }
    for (index, sample) in left.into_iter().enumerate() {
        *edge
            .get_mut(TOP_LEFT.saturating_sub(1).saturating_sub(index))
            .portable()? = i32::from(sample);
    }
    let mut prediction = [0_u16; WIDTH * HEIGHT];
    for y in 0..HEIGHT {
        let y_i32 = i32::try_from(y).map_err(|_| PortableUnavailable)?;
        let xpos = 64_i32.saturating_sub(dx.saturating_mul(y_i32.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x in 0..WIDTH {
            let x_i32 = i32::try_from(x).map_err(|_| PortableUnavailable)?;
            let sample = if base_x >= 0 {
                let first_index = usize::try_from(
                    i32::try_from(TOP_LEFT)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_add(base_x)
                        .saturating_add(x_i32),
                )
                .map_err(|_| PortableUnavailable)?;
                let second_index = first_index.saturating_add(1);
                let first = *edge.get(first_index).portable()?;
                let second = *edge.get(second_index).portable()?;
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let ypos = y_i32
                    .saturating_mul(64)
                    .saturating_sub(dy.saturating_mul(x_i32.saturating_add(1)));
                let base_y = ypos >> 6;
                let first_index = usize::try_from(
                    i32::try_from(TOP_LEFT.saturating_sub(1))
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(base_y),
                )
                .map_err(|_| PortableUnavailable)?;
                let second_index = first_index.saturating_add(1);
                let frac_y = ypos & 0x3e;
                let first = *edge.get(first_index).portable()?;
                let second = *edge.get(second_index).portable()?;
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            #[expect(
                clippy::cast_sign_loss,
                reason = "the directional predictor is explicitly clamped to eight-bit range"
            )]
            let sample = sample.clamp(0, 255) as u16;
            *prediction
                .get_mut(y.saturating_mul(WIDTH).saturating_add(x))
                .portable()? = sample;
        }
    }
    let coefficients = coefficients.unwrap_or([0_i32; 256]);
    let residual = transform::inverse_dct8x32(&coefficients);
    Ok(reconstruct_lossy_predicted_plane(&prediction, &residual))
}

fn reconstruct_lossy_luma_16x64_diagonal_z2(
    top: [u16; 16],
    left: [u16; 64],
    angle: i32,
    coefficients: Option<Lossy16x64TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;
    const WIDTH: usize = 16;
    const HEIGHT: usize = 64;
    const TOP_LEFT: usize = HEIGHT;
    let mut edge = [0_i32; HEIGHT * 2 + 1];
    edge[TOP_LEFT] = i32::from(top[0]);
    for (index, sample) in top.into_iter().enumerate() {
        *edge
            .get_mut(TOP_LEFT.saturating_add(1).saturating_add(index))
            .portable()? = i32::from(sample);
    }
    for (index, sample) in left.into_iter().enumerate() {
        *edge
            .get_mut(TOP_LEFT.saturating_sub(1).saturating_sub(index))
            .portable()? = i32::from(sample);
    }

    let mut prediction = [0_u16; WIDTH * HEIGHT];
    for y in 0..HEIGHT {
        let y_i32 = i32::try_from(y).map_err(|_| PortableUnavailable)?;
        let xpos = 64_i32.saturating_sub(dx.saturating_mul(y_i32.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x in 0..WIDTH {
            let x_i32 = i32::try_from(x).map_err(|_| PortableUnavailable)?;
            let sample = if base_x >= 0 {
                let first_index = i32::try_from(TOP_LEFT)
                    .map_err(|_| PortableUnavailable)?
                    .saturating_add(base_x)
                    .saturating_add(x_i32);
                let first_index = usize::try_from(first_index).map_err(|_| PortableUnavailable)?;
                let second_index = first_index.saturating_add(1);
                let first = *edge.get(first_index).portable()?;
                let second = *edge.get(second_index).portable()?;
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let ypos = y_i32
                    .saturating_mul(64)
                    .saturating_sub(dy.saturating_mul(x_i32.saturating_add(1)));
                let base_y = ypos >> 6;
                let first_index = i32::try_from(TOP_LEFT.saturating_sub(1))
                    .map_err(|_| PortableUnavailable)?
                    .saturating_sub(base_y);
                let second_index = first_index.saturating_add(1);
                let first_index = usize::try_from(first_index).map_err(|_| PortableUnavailable)?;
                let second_index =
                    usize::try_from(second_index).map_err(|_| PortableUnavailable)?;
                let frac_y = ypos & 0x3e;
                let first = *edge.get(first_index).portable()?;
                let second = *edge.get(second_index).portable()?;
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            #[expect(
                clippy::cast_sign_loss,
                reason = "the directional predictor is explicitly clamped to eight-bit range"
            )]
            let sample = sample.clamp(0, 255) as u16;
            *prediction
                .get_mut(y.saturating_mul(WIDTH).saturating_add(x))
                .portable()? = sample;
        }
    }
    let coefficients = coefficients.unwrap_or([0_i32; 512]);
    let residual = transform::inverse_dct16x64(&coefficients);
    Ok(reconstruct_lossy_predicted_plane(&prediction, &residual))
}

fn reconstruct_lossy_luma_8x32(
    predictor: u16,
    coefficients: Option<Lossy8x32TransformCoefficients>,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 256]);
    let residual = transform::inverse_dct8x32(&coefficients);
    reconstruct_lossy_residual_plane(predictor, &residual)
}

fn reconstruct_lossy_chroma_8x32_smooth(
    top: [u16; 8],
    left: [u16; 32],
    coefficients: Option<Lossy8x32TransformCoefficients>,
) -> ReconstructedPlane {
    const SMOOTH_WEIGHTS_8: [i32; 8] = [255, 197, 146, 105, 73, 50, 37, 32];
    const SMOOTH_WEIGHTS_32: [i32; 32] = [
        255, 240, 225, 210, 196, 182, 169, 157, 145, 133, 122, 111, 101, 92, 83, 74, 66, 59, 52,
        45, 39, 34, 29, 25, 21, 17, 14, 12, 10, 9, 8, 8,
    ];
    let right = i32::from(top[7]);
    let bottom = i32::from(left[31]);
    let prediction: [u16; 256] = std::array::from_fn(|index| {
        let y = index / 8;
        let x = index % 8;
        let vertical_weight = SMOOTH_WEIGHTS_32[y];
        let horizontal_weight = SMOOTH_WEIGHTS_8[x];
        let value = vertical_weight
            .saturating_mul(i32::from(top[x]))
            .saturating_add(
                256_i32
                    .saturating_sub(vertical_weight)
                    .saturating_mul(bottom),
            )
            .saturating_add(horizontal_weight.saturating_mul(i32::from(left[y])))
            .saturating_add(
                256_i32
                    .saturating_sub(horizontal_weight)
                    .saturating_mul(right),
            )
            .saturating_add(256)
            >> 9;
        #[expect(
            clippy::cast_sign_loss,
            reason = "the smooth predictor is explicitly clamped to eight-bit range"
        )]
        {
            value.clamp(0, 255) as u16
        }
    });
    let coefficients = coefficients.unwrap_or([0_i32; 256]);
    let residual = transform::inverse_dct8x32(&coefficients);
    reconstruct_lossy_predicted_plane(&prediction, &residual)
}

fn reconstruct_lossy_luma_16x8(
    predictor: u16,
    coefficients: Option<Lossy16x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> ReconstructedPlane {
    reconstruct_lossy_luma_16x8_from_prediction([predictor; 128], coefficients, transform_kind)
}

fn reconstruct_lossy_luma_16x8_from_prediction(
    prediction: [u16; 128],
    coefficients: Option<Lossy16x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 128]);
    let residual = match transform_kind {
        Lossy4x8TransformKind::IdentityIdentity => transform::inverse_identity16x8(&coefficients),
        Lossy4x8TransformKind::DctDct => transform::inverse_dct16x8(&coefficients),
        Lossy4x8TransformKind::IdentityDct => transform::inverse_identity_dct16x8(&coefficients),
        Lossy4x8TransformKind::DctIdentity => transform::inverse_dct_identity16x8(&coefficients),
        Lossy4x8TransformKind::AdstAdst => transform::inverse_adst_adst16x8(&coefficients),
        Lossy4x8TransformKind::AdstDct => transform::inverse_adst_dct16x8(&coefficients),
        Lossy4x8TransformKind::DctAdst => transform::inverse_dct_adst16x8(&coefficients),
    };
    reconstruct_lossy_predicted_plane(&prediction, &residual)
}

