fn reconstruct_lossy_chroma_8x8(
    predictor: u16,
    coefficients: Option<[i32; 64]>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 64]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity8x8(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct8x8(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct8x8(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst8x8(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct8x8(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity8x8(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst8x8(&coefficients),
    };
    let samples = residual
        .into_iter()
        .map(|value| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_4x4(
    predictor: u16,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 16]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity4x4(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct4x4(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct4x4(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst4x4(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct4x4(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity4x4(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst4x4(&coefficients),
    };

    let samples: Vec<u16> = residual
        .into_iter()
        .map(|value| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();

    ReconstructedPlane { samples }
}

fn reconstruct_lossy_4x4_from_prediction(
    prediction: [u16; 16],
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let coefficients = coefficients.unwrap_or([0_i32; 16]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity4x4(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct4x4(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct4x4(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst4x4(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct4x4(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity4x4(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst4x4(&coefficients),
    };

    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();

    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_8x8_split_from_prediction(
    prediction: [u16; 64],
    split: LossyLuma4x4Split,
) -> ReconstructedPlane {
    let mut samples = vec![0_u16; 64];
    for transform_index in 0_usize..4 {
        let transform_x = (transform_index % 2).saturating_mul(4);
        let transform_y = (transform_index / 2).saturating_mul(4);
        let block_prediction = std::array::from_fn(|index| {
            let row = index / 4;
            let column = index % 4;
            prediction[(transform_y + row).saturating_mul(8) + transform_x + column]
        });
        let block = reconstruct_lossy_4x4_from_prediction(
            block_prediction,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        );
        for (row, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (transform_y + row).saturating_mul(8) + transform_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_8x8_split_dc_horizontal(
    left: [u16; 8],
    split: LossyLuma4x4Split,
) -> ReconstructedPlane {
    let mut samples = vec![0_u16; 64];
    for transform_index in 0_usize..4 {
        let transform_x = (transform_index % 2).saturating_mul(4);
        let transform_y = (transform_index / 2).saturating_mul(4);
        let left_edge = std::array::from_fn(|row| {
            if transform_x == 0 {
                left[transform_y + row]
            } else {
                samples[(transform_y + row).saturating_mul(8) + transform_x - 1]
            }
        });
        let predictor = if transform_y == 0 {
            one_sided_dc_predictor_4(left_edge)
        } else {
            let top_edge = std::array::from_fn(|column| {
                samples[(transform_y - 1).saturating_mul(8) + transform_x + column]
            });
            dc_predictor(top_edge, left_edge)
        };
        let block = reconstruct_lossy_4x4_from_prediction(
            [predictor; 16],
            split.coefficients[transform_index],
            split.transforms[transform_index],
        );
        for (row, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (transform_y + row).saturating_mul(8) + transform_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_luma_8x8_split_smooth_horizontal(
    left: [u16; 8],
    split: LossyLuma4x4Split,
) -> ReconstructedPlane {
    let mut samples = vec![0_u16; 64];
    for transform_index in 0_usize..4 {
        let transform_x = (transform_index % 2).saturating_mul(4);
        let transform_y = (transform_index / 2).saturating_mul(4);
        let left_edge = std::array::from_fn(|row| {
            if transform_x == 0 {
                left[transform_y + row]
            } else {
                samples[(transform_y + row).saturating_mul(8) + transform_x - 1]
            }
        });
        let top_edge: [u16; 4] = if transform_y == 0 {
            [left_edge[0]; 4]
        } else {
            std::array::from_fn(|column| {
                samples[(transform_y - 1).saturating_mul(8) + transform_x + column]
            })
        };
        let block = reconstruct_lossy_4x4_smooth(
            top_edge,
            top_edge[3],
            left_edge,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        );
        for (row, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (transform_y + row).saturating_mul(8) + transform_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }
    ReconstructedPlane { samples }
}

