fn reconstruct_lossy_luma_8x8_split_paeth(
    top: [u16; 8],
    left: Option<[u16; 8]>,
    top_left: u16,
    split: LossyLuma4x4Split,
) -> ReconstructedPlane {
    // A split 8×8 luma block is four independently predicted 4×4 blocks.
    // Each later block sees the already reconstructed top or left edge of its
    // sibling, just as dav1d's transform-grid walker does.
    let mut samples = vec![0_u16; 64];
    for transform_index in 0_usize..4 {
        let transform_x = (transform_index % 2).saturating_mul(4);
        let transform_y = (transform_index / 2).saturating_mul(4);
        let top_edge: [u16; 4] = if transform_y == 0 {
            std::array::from_fn(|column| top[transform_x + column])
        } else {
            std::array::from_fn(|column| {
                samples[(transform_y - 1).saturating_mul(8) + transform_x + column]
            })
        };
        let left_edge: [u16; 4] = if transform_x == 0 {
            left.map_or([top_edge[0]; 4], |edge| {
                std::array::from_fn(|row| edge[transform_y + row])
            })
        } else {
            std::array::from_fn(|row| {
                samples[(transform_y + row).saturating_mul(8) + transform_x - 1]
            })
        };
        let block_top_left = match (transform_y, transform_x) {
            (0, 0) => top_left,
            (0, _) => top[transform_x - 1],
            (_, 0) => left.map_or(top_edge[0], |edge| edge[transform_y - 1]),
            _ => samples[(transform_y - 1).saturating_mul(8) + transform_x - 1],
        };
        let prediction = std::array::from_fn(|index| {
            paeth_predictor(top_edge[index % 4], left_edge[index / 4], block_top_left)
        });
        let block = reconstruct_lossy_4x4_from_prediction(
            prediction,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        );
        for (row, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (transform_y + row).saturating_mul(8) + transform_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }
    ReconstructedPlane { samples }
}

fn reconstruct_lossy_4x4_diagonal_z2(
    top: [u16; 4],
    left: [u16; 4],
    top_left: u16,
    angle: i32,
    smooth_edges: bool,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    // This is dav1d's Zone-2 predictor for a 4×4 transform. The shallow
    // angular range upsamples the left edge; omitting that step changes the
    // predictor even when every coefficient is skipped.
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let mut dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let mut dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;
    const TOP_LEFT_INDEX: usize = 16;
    let mut edge = [0_u16; 32];
    edge[TOP_LEFT_INDEX] = top_left;
    let upsample_above = angle.saturating_sub(90) < 40;
    let upsample_left = 180_i32.saturating_sub(angle) < 40;
    let top = filter_intra_top_edge_4(top, top_left, angle.saturating_sub(90), smooth_edges);
    let left =
        filter_intra_left_edge_4(left, top_left, 180_i32.saturating_sub(angle), smooth_edges);
    if upsample_above {
        let source = [top_left, top[0], top[1], top[2], top[3]];
        let mut upsampled = [0_u16; 9];
        const KERNEL: [i32; 4] = [-1, 9, 9, -1];
        for index in 0_usize..4 {
            upsampled[index.saturating_mul(2)] = source[index];
            let mut sum = 0_i32;
            for (tap, weight) in KERNEL.into_iter().enumerate() {
                let source_index = index
                    .saturating_add(tap)
                    .saturating_sub(1)
                    .min(source.len().saturating_sub(1));
                sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
            }
            #[expect(
                clippy::cast_sign_loss,
                reason = "the upsampled angular edge is explicitly clamped"
            )]
            {
                upsampled[index.saturating_mul(2).saturating_add(1)] =
                    ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
            }
        }
        upsampled[8] = source[4];
        edge[TOP_LEFT_INDEX..TOP_LEFT_INDEX.saturating_add(9)].copy_from_slice(&upsampled);
        dx = dx.saturating_mul(2);
    } else {
        edge[TOP_LEFT_INDEX.saturating_add(1)..TOP_LEFT_INDEX.saturating_add(5)]
            .copy_from_slice(&top);
    }
    if upsample_left {
        let source = [left[3], left[2], left[1], left[0], top_left];
        let mut upsampled = [0_u16; 9];
        const KERNEL: [i32; 4] = [-1, 9, 9, -1];
        for index in 0_usize..4 {
            upsampled[index.saturating_mul(2)] = source[index];
            let mut sum = 0_i32;
            for (tap, weight) in KERNEL.into_iter().enumerate() {
                let source_index = index
                    .saturating_add(tap)
                    .saturating_sub(1)
                    .min(source.len().saturating_sub(1));
                sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
            }
            #[expect(
                clippy::cast_sign_loss,
                reason = "the upsampled angular edge is explicitly clamped"
            )]
            {
                upsampled[index.saturating_mul(2).saturating_add(1)] =
                    ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
            }
        }
        upsampled[8] = source[4];
        edge[TOP_LEFT_INDEX.saturating_sub(8)..=TOP_LEFT_INDEX].copy_from_slice(&upsampled);
        dy = dy.saturating_mul(2);
    } else {
        for (index, sample) in left.into_iter().enumerate() {
            edge[TOP_LEFT_INDEX.saturating_sub(1).saturating_sub(index)] = sample;
        }
    }

    let mut prediction = [0_u16; 16];
    let left_index = TOP_LEFT_INDEX.saturating_sub(if upsample_left { 2 } else { 1 });
    for y_index in 0_usize..4 {
        let y = i32::try_from(y_index).map_err(|_| PortableUnavailable)?;
        let xpos = (if upsample_above { 2_i32 } else { 1_i32 })
            .saturating_mul(64)
            .saturating_sub(dx.saturating_mul(y.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x_index in 0_usize..4 {
            let x = i32::try_from(x_index).map_err(|_| PortableUnavailable)?;
            let base_x = base_x
                .saturating_add((if upsample_above { 2_i32 } else { 1_i32 }).saturating_mul(x));
            let ypos = y
                .saturating_mul(if upsample_left { 128 } else { 64 })
                .saturating_sub(dy.saturating_mul(x.saturating_add(1)));
            let sample = if base_x >= 0 {
                let first = usize::try_from(
                    i32::try_from(TOP_LEFT_INDEX)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_add(base_x),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = first.saturating_add(1);
                let first = i32::from(*edge.get(first).portable()?);
                let second = i32::from(*edge.get(second).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let base_y = ypos >> 6;
                let frac_y = ypos & 0x3e;
                let first = usize::try_from(
                    i32::try_from(left_index)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(base_y),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = usize::try_from(
                    i32::try_from(left_index)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(base_y.saturating_add(1)),
                )
                .map_err(|_| PortableUnavailable)?;
                let first = i32::from(*edge.get(first).portable()?);
                let second = i32::from(*edge.get(second).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            #[expect(
                clippy::cast_sign_loss,
                reason = "the directional predictor is explicitly clamped to eight-bit range"
            )]
            let sample = sample.clamp(0, 255) as u16;
            prediction[y_index.saturating_mul(4).saturating_add(x_index)] = sample;
        }
    }

    Ok(reconstruct_lossy_4x4_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn filter_intra_filter_strength_4(angle: i32, smooth_edges: bool) -> usize {
    if smooth_edges {
        if angle >= 64 {
            2
        } else if angle >= 40 {
            1
        } else {
            0
        }
    } else if angle >= 56 {
        1
    } else {
        0
    }
}

fn filter_intra_top_edge_4(
    edge: [u16; 4],
    top_left: u16,
    angle: i32,
    smooth_edges: bool,
) -> [u16; 4] {
    filter_intra_top_edge_4_with_max(edge, top_left, angle, smooth_edges, 255)
}

fn filter_intra_top_edge_4_with_max(
    edge: [u16; 4],
    top_left: u16,
    angle: i32,
    smooth_edges: bool,
    maximum: u16,
) -> [u16; 4] {
    let strength = filter_intra_filter_strength_4(angle, smooth_edges);
    let kernel = match strength {
        1 => [0_i32, 4, 8, 4, 0],
        2 => [0_i32, 5, 6, 5, 0],
        _ => return edge,
    };
    let source = [top_left, edge[0], edge[1], edge[2], edge[3]];
    std::array::from_fn(|index| {
        let sum = (0..5).fold(0_i32, |sum, tap| {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .clamp(0, source.len().saturating_sub(1));
            sum.saturating_add(i32::from(source[source_index]).saturating_mul(kernel[tap]))
        });
        u16::try_from((sum.saturating_add(8) >> 4).clamp(0, i32::from(maximum))).unwrap_or(maximum)
    })
}

fn filter_intra_left_edge_4(
    edge: [u16; 4],
    top_left: u16,
    angle: i32,
    smooth_edges: bool,
) -> [u16; 4] {
    filter_intra_left_edge_4_with_max(edge, top_left, angle, smooth_edges, 255)
}

fn filter_intra_left_edge_4_with_max(
    edge: [u16; 4],
    top_left: u16,
    angle: i32,
    smooth_edges: bool,
    maximum: u16,
) -> [u16; 4] {
    let strength = filter_intra_filter_strength_4(angle, smooth_edges);
    let kernel = match strength {
        1 => [0_i32, 4, 8, 4, 0],
        2 => [0_i32, 5, 6, 5, 0],
        _ => return edge,
    };
    let source = [edge[3], edge[2], edge[1], edge[0], top_left];
    let filtered: [u16; 4] = std::array::from_fn(|index| {
        let sum = (0..5).fold(0_i32, |sum, tap| {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(2)
                .clamp(0, source.len().saturating_sub(1));
            sum.saturating_add(i32::from(source[source_index]).saturating_mul(kernel[tap]))
        });
        u16::try_from((sum.saturating_add(8) >> 4).clamp(0, i32::from(maximum))).unwrap_or(maximum)
    });
    std::array::from_fn(|index| filtered[3_usize.saturating_sub(index)])
}

fn reconstruct_lossy_luma_8x8_split_diagonal_vertical(
    top: [u16; 8],
    left: Option<[u16; 8]>,
    top_left: Option<u16>,
    angle: i32,
    top_available: bool,
    smooth_edges: bool,
    split: LossyLuma4x4Split,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 64];
    for transform_index in 0_usize..4 {
        let transform_x = (transform_index % 2).saturating_mul(4);
        let transform_y = (transform_index / 2).saturating_mul(4);
        let left_edge = if transform_x == 0 {
            left.map_or([top[transform_x]; 4], |edge| {
                std::array::from_fn(|row| edge[transform_y + row])
            })
        } else {
            std::array::from_fn(|row| {
                samples[(transform_y + row).saturating_mul(8) + transform_x - 1]
            })
        };
        let top_edge: [u16; 4] = if transform_y == 0 {
            if top_available {
                std::array::from_fn(|column| top[transform_x + column])
            } else {
                [left_edge[0]; 4]
            }
        } else {
            std::array::from_fn(|column| {
                samples[(transform_y - 1).saturating_mul(8) + transform_x + column]
            })
        };
        let block_top_left = match (transform_x, transform_y) {
            (0, 0) => top_left.unwrap_or(top_edge[0]),
            (_, 0) if top_available => top[transform_x - 1],
            (_, 0) => left_edge[0],
            (0, _) => left.map_or(top_edge[0], |edge| edge[transform_y - 1]),
            _ => samples[(transform_y - 1).saturating_mul(8) + transform_x - 1],
        };
        let block = reconstruct_lossy_4x4_diagonal_z2(
            top_edge,
            left_edge,
            block_top_left,
            angle,
            smooth_edges,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        )?;

        for (row, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (transform_y + row).saturating_mul(8) + transform_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }

    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_luma_8x8_split_diagonal_z1(
    top: [u16; 8],
    left: Option<[u16; 8]>,
    top_left: Option<u16>,
    angle: i32,
    top_available: bool,
    split: LossyLuma4x4Split,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 64];
    for transform_index in 0_usize..4 {
        let transform_x = (transform_index % 2).saturating_mul(4);
        let transform_y = (transform_index / 2).saturating_mul(4);
        let top_edge = if transform_y == 0 {
            if top_available {
                std::array::from_fn(|column| top[transform_x + column])
            } else if transform_x == 0 {
                [left.map_or(top[0], |edge| edge[0]); 4]
            } else {
                [samples[transform_y * 8 + transform_x - 1]; 4]
            }
        } else {
            std::array::from_fn(|column| {
                samples[(transform_y - 1).saturating_mul(8) + transform_x + column]
            })
        };
        let top_extension = if transform_y == 0 {
            if top_available {
                if transform_x == 0 {
                    top[4..8].try_into().map_err(|_| PortableUnavailable)?
                } else {
                    [top[7]; 4]
                }
            } else {
                [top_edge[3]; 4]
            }
        } else if transform_x == 0 {
            std::array::from_fn(|column| samples[(transform_y - 1).saturating_mul(8) + 4 + column])
        } else {
            [samples[(transform_y - 1).saturating_mul(8) + 7]; 4]
        };
        let block_top_left = match (transform_x, transform_y) {
            (0, 0) if top_available => top_left.unwrap_or(top_edge[0]),
            (0, 0) => left.map_or(128, |edge| edge[0]),
            (_, 0) if top_available => top[transform_x - 1],
            (_, 0) => samples[transform_y * 8 + transform_x - 1],
            (0, _) => left.map_or(top_edge[0], |edge| edge[transform_y - 1]),
            _ => samples[(transform_y - 1).saturating_mul(8) + transform_x - 1],
        };
        let block = reconstruct_lossy_4x4_diagonal_z1_extended(
            [
                top_edge[0],
                top_edge[1],
                top_edge[2],
                top_edge[3],
                top_extension[0],
                top_extension[1],
                top_extension[2],
                top_extension[3],
            ],
            block_top_left,
            angle,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        )?;
        for (row, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (transform_y + row).saturating_mul(8) + transform_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }

    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_4x4_diagonal_z1_with_edge(
    edge: [u16; 8],
    top_left: u16,
    angle: i32,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (0 < angle && angle < 90).then_some(()).portable()?;
    let dx_index = usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?;
    let dx = *DR_INTRA_DERIVATIVE
        .get(dx_index)
        .filter(|&&value| value > 0)
        .portable()?;
    let upsample = enable_intra_edge_filter
        && intra_edge_upsample(8, 90_i32.saturating_sub(angle), smooth_edges);

    let filtered_edge = if enable_intra_edge_filter && !upsample {
        let strength = intra_edge_filter_strength(8, 90_i32.saturating_sub(angle), smooth_edges);
        if strength == 0 {
            edge
        } else {
            filter_intra_top_edge_8(edge, top_left, strength)
        }
    } else {
        edge
    };
    let upsampled_edge = upsample_intra_top_edge(filtered_edge, top_left);
    let (edge, max_base_x, dx, base_increment) = if upsample {
        (&upsampled_edge[..], 14, dx.saturating_mul(2), 2)
    } else {
        (&filtered_edge[..], 7, dx, 1)
    };
    let mut prediction = [0_u16; 16];
    for y in 0_usize..4 {
        for x in 0_usize..4 {
            prediction[y.saturating_mul(4).saturating_add(x)] =
                diagonal_z1_predictor_sample(edge, max_base_x, dx, base_increment, x, y)?;
        }
    }

    let result = reconstruct_lossy_4x4_from_prediction(prediction, coefficients, transform_kind);

    Ok(result)
}

fn reconstruct_lossy_luma_8x8_split_diagonal_z1_extended(
    top: [u16; 16],
    left: Option<[u16; 8]>,
    top_left: Option<u16>,
    angle: i32,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
    split: LossyLuma4x4Split,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 64];
    for transform_index in 0_usize..4 {
        let transform_x = (transform_index % 2).saturating_mul(4);
        let transform_y = (transform_index / 2).saturating_mul(4);
        let top_edge = if transform_y == 0 {
            std::array::from_fn(|column| {
                top.get(transform_x.saturating_add(column))
                    .copied()
                    .unwrap_or_else(|| top[15])
            })
        } else {
            std::array::from_fn(|column| {
                let source_x = transform_x.saturating_add(column);
                if source_x < 8 {
                    samples[(transform_y - 1).saturating_mul(8) + source_x]
                } else {
                    samples[(transform_y - 1).saturating_mul(8) + 7]
                }
            })
        };
        let block_top_left = match (transform_x, transform_y) {
            (0, 0) => top_left.unwrap_or(top[0]),
            (_, 0) => top[transform_x - 1],
            (0, _) => left
                .and_then(|edge| edge.get(transform_y.saturating_sub(1)).copied())
                .unwrap_or_else(|| samples[(transform_y - 1).saturating_mul(8)]),
            _ => samples[(transform_y - 1).saturating_mul(8) + transform_x - 1],
        };
        let block = reconstruct_lossy_4x4_diagonal_z1_with_edge(
            top_edge,
            block_top_left,
            angle,
            enable_intra_edge_filter,
            smooth_edges,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        )?;

        for (row, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (transform_y + row).saturating_mul(8) + transform_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }

    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_luma_8x8_split_diagonal_z3(
    left: [u16; 8],
    top: [u16; 8],
    top_left: u16,
    bottom_left: Option<[u16; 8]>,
    angle: i32,
    enable_intra_edge_filter: bool,
    split: LossyLuma4x4Split,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (180 < angle && angle < 270).then_some(()).portable()?;
    let dy_index =
        usize::try_from(270_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;

    let mut samples = vec![0_u16; 64];
    for transform_index in 0_usize..4 {
        let transform_x = (transform_index % 2).saturating_mul(4);
        let transform_y = (transform_index / 2).saturating_mul(4);
        let block_left: [u16; 4] = if transform_x == 0 {
            std::array::from_fn(|row| left[transform_y + row])
        } else {
            std::array::from_fn(|row| {
                samples[(transform_y + row).saturating_mul(8) + transform_x - 1]
            })
        };
        let block_top_left = match (transform_x, transform_y) {
            (0, 0) => top_left,
            (_, 0) => top[transform_x - 1],
            (0, _) => left[transform_y - 1],
            _ => samples[(transform_y - 1).saturating_mul(8) + transform_x - 1],
        };
        let mut edge = [0_u16; 8];
        if transform_index == 0 {
            edge = left;
        } else if transform_index == 2 {
            edge[..4].copy_from_slice(&block_left);
            if let Some(bottom_left) = bottom_left {
                edge[4..].copy_from_slice(&bottom_left[..4]);
            } else {
                edge[4..].fill(block_left[3]);
            }
        } else {
            edge[..4].copy_from_slice(&block_left);
            edge[4..].fill(block_left[3]);
        }
        let mut block_prediction = [0_u16; 16];
        if enable_intra_edge_filter && angle < 220 {
            let upsampled_edge = upsample_intra_left_edge(edge, block_top_left);
            for y in 0_usize..4 {
                for x in 0_usize..4 {
                    block_prediction[y.saturating_mul(4).saturating_add(x)] =
                        diagonal_z3_predictor_sample(
                            &upsampled_edge,
                            14,
                            dy.saturating_mul(2),
                            2,
                            x,
                            y,
                        )?;
                }
            }
        } else {
            for y in 0_usize..4 {
                for x in 0_usize..4 {
                    block_prediction[y.saturating_mul(4).saturating_add(x)] =
                        diagonal_z3_predictor_sample(&edge, 7, dy, 1, x, y)?;
                }
            }
        }

        let block = reconstruct_lossy_4x4_from_prediction(
            block_prediction,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        );

        for (row, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (transform_y + row).saturating_mul(8) + transform_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }

    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_luma_8x8_split_filter_intra_no_top(
    left: [u16; 8],
    split: LossyLuma4x4Split,
    mode: usize,
) -> PortableResult<ReconstructedPlane> {
    (mode < FILTER_INTRA_TAPS.len()).then_some(()).portable()?;
    let mut samples = [0_u16; 64];
    for transform_index in 0_usize..4 {
        let transform_x = (transform_index % 2).saturating_mul(4);
        let transform_y = (transform_index / 2).saturating_mul(4);
        let top = if transform_y == 0 {
            let value = if transform_x == 0 {
                left[0]
            } else {
                samples[transform_x.saturating_sub(1)]
            };
            [value; 4]
        } else {
            std::array::from_fn(|column| {
                samples[(transform_y - 1).saturating_mul(8) + transform_x + column]
            })
        };
        let left_edge = std::array::from_fn(|row| {
            if transform_x == 0 {
                left[transform_y + row]
            } else {
                samples[(transform_y + row).saturating_mul(8) + transform_x - 1]
            }
        });
        let top_left = if transform_y == 0 {
            if transform_x == 0 {
                left[0]
            } else {
                samples[transform_x.saturating_sub(1)]
            }
        } else if transform_x == 0 {
            left[transform_y - 1]
        } else {
            samples[(transform_y - 1).saturating_mul(8) + transform_x - 1]
        };
        let prediction = reconstruct_filter_intra_4x4_prediction(mode, top_left, top, left_edge);
        let block = reconstruct_lossy_4x4_from_prediction(
            prediction,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        );
        for (row, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (transform_y + row).saturating_mul(8) + transform_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane {
        samples: samples.to_vec(),
    })
}

fn reconstruct_lossy_luma_8x8_split_filter_intra(
    top: [u16; 8],
    left: [u16; 8],
    top_left: u16,
    split: LossyLuma4x4Split,
    mode: usize,
) -> PortableResult<ReconstructedPlane> {
    (mode < FILTER_INTRA_TAPS.len()).then_some(()).portable()?;
    let mut samples = [0_u16; 64];
    for transform_index in 0_usize..4 {
        let transform_x = (transform_index % 2).saturating_mul(4);
        let transform_y = (transform_index / 2).saturating_mul(4);
        let top_edge = if transform_y == 0 {
            std::array::from_fn(|column| top[transform_x + column])
        } else {
            std::array::from_fn(|column| {
                samples[(transform_y - 1).saturating_mul(8) + transform_x + column]
            })
        };
        let left_edge = std::array::from_fn(|row| {
            if transform_x == 0 {
                left[transform_y + row]
            } else {
                samples[(transform_y + row).saturating_mul(8) + transform_x - 1]
            }
        });
        let block_top_left = if transform_y == 0 {
            if transform_x == 0 {
                top_left
            } else {
                top[transform_x - 1]
            }
        } else if transform_x == 0 {
            left[transform_y - 1]
        } else {
            samples[(transform_y - 1).saturating_mul(8) + transform_x - 1]
        };
        let prediction =
            reconstruct_filter_intra_4x4_prediction(mode, block_top_left, top_edge, left_edge);
        let block = reconstruct_lossy_4x4_from_prediction(
            prediction,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        );
        for (row, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
            let output_start = (transform_y + row).saturating_mul(8) + transform_x;
            samples[output_start..output_start.saturating_add(4)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane {
        samples: samples.to_vec(),
    })
}

fn reconstruct_filter_intra_4x4_prediction(
    mode: usize,
    top_left: u16,
    top: [u16; 4],
    left: [u16; 4],
) -> [u16; 16] {
    let mut prediction = [0_u16; 16];
    for y in (0_usize..4).step_by(2) {
        let p0 = if y == 0 {
            i32::from(top_left)
        } else {
            i32::from(left[y - 1])
        };
        let p1 = if y == 0 {
            i32::from(top[0])
        } else {
            i32::from(prediction[(y - 1).saturating_mul(4)])
        };
        let p2 = if y == 0 {
            i32::from(top[1])
        } else {
            i32::from(prediction[(y - 1).saturating_mul(4).saturating_add(1)])
        };
        let p3 = if y == 0 {
            i32::from(top[2])
        } else {
            i32::from(prediction[(y - 1).saturating_mul(4).saturating_add(2)])
        };
        let p4 = if y == 0 {
            i32::from(top[3])
        } else {
            i32::from(prediction[(y - 1).saturating_mul(4).saturating_add(3)])
        };
        let inputs = [
            p0,
            p1,
            p2,
            p3,
            p4,
            i32::from(left[y]),
            i32::from(left[y + 1]),
        ];
        for yy in 0_usize..2 {
            for xx in 0_usize..4 {
                let taps = FILTER_INTRA_TAPS[mode][yy.saturating_mul(4).saturating_add(xx)];
                let accumulator = taps
                    .into_iter()
                    .zip(inputs)
                    .fold(0_i32, |sum, (weight, input)| {
                        sum.saturating_add(weight.saturating_mul(input))
                    });
                #[expect(
                    clippy::cast_sign_loss,
                    reason = "filter-intra output is explicitly clamped to eight-bit range"
                )]
                let value = accumulator.saturating_add(8).div_euclid(16).clamp(0, 255) as u16;
                prediction[(y + yy).saturating_mul(4) + xx] = value;
            }
        }
    }
    prediction
}

fn reconstruct_lossy_chroma_4x4_vertical(
    top: [u16; 4],
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let prediction = std::array::from_fn(|index| top[index % 4]);
    reconstruct_lossy_4x4_from_prediction(prediction, coefficients, transform_kind)
}

fn reconstruct_lossy_4x4_smooth_vertical(
    top: [u16; 4],
    bottom: u16,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    const SMOOTH_WEIGHTS_4: [i32; 4] = [255, 149, 85, 64];
    let prediction = std::array::from_fn(|index| {
        let y = index / 4;
        let weight = SMOOTH_WEIGHTS_4[y];
        let value = weight
            .saturating_mul(i32::from(top[index % 4]))
            .saturating_add(
                256_i32
                    .saturating_sub(weight)
                    .saturating_mul(i32::from(bottom)),
            )
            .saturating_add(128)
            >> 8;
        #[expect(
            clippy::cast_sign_loss,
            reason = "the smooth predictor is explicitly clamped to eight-bit range"
        )]
        {
            value.clamp(0, 255) as u16
        }
    });

    reconstruct_lossy_4x4_from_prediction(prediction, coefficients, transform_kind)
}

fn reconstruct_lossy_4x4_smooth_horizontal(
    left: [u16; 4],
    right: u16,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    const SMOOTH_WEIGHTS_4: [i32; 4] = [255, 149, 85, 64];
    let right = i32::from(right);
    let prediction = std::array::from_fn(|index| {
        let x = index % 4;
        let weight = SMOOTH_WEIGHTS_4[x];
        let value = weight
            .saturating_mul(i32::from(left[index / 4]))
            .saturating_add(256_i32.saturating_sub(weight).saturating_mul(right))
            .saturating_add(128)
            >> 8;
        #[expect(
            clippy::cast_sign_loss,
            reason = "the smooth predictor is explicitly clamped to eight-bit range"
        )]
        {
            value.clamp(0, 255) as u16
        }
    });
    reconstruct_lossy_4x4_from_prediction(prediction, coefficients, transform_kind)
}

fn reconstruct_lossy_4x4_paeth(
    top: [u16; 4],
    left: [u16; 4],
    top_left: u16,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    let prediction =
        std::array::from_fn(|index| paeth_predictor(top[index % 4], left[index / 4], top_left));
    reconstruct_lossy_4x4_from_prediction(prediction, coefficients, transform_kind)
}

fn reconstruct_lossy_4x4_diagonal_z1(
    top: [u16; 4],
    top_left: u16,
    angle: i32,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    reconstruct_lossy_4x4_diagonal_z1_extended(
        [
            top[0], top[1], top[2], top[3], top[3], top[3], top[3], top[3],
        ],
        top_left,
        angle,
        coefficients,
        transform_kind,
    )
}

fn reconstruct_lossy_4x4_diagonal_z1_extended(
    top: [u16; 8],
    top_left: u16,
    angle: i32,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (0 < angle && angle < 90).then_some(()).portable()?;
    let dx_index = usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?;
    let dx = *DR_INTRA_DERIVATIVE
        .get(dx_index)
        .filter(|&&value| value > 0)
        .portable()?;
    let upsample = 50 < angle;
    let upsampled_edge = upsample_intra_top_edge(top, top_left);
    let (edge, max_base_x, dx, base_increment) = if upsample {
        (&upsampled_edge[..], 14, dx.saturating_mul(2), 2)
    } else {
        (&top[..], 7, dx, 1)
    };
    let mut prediction = [0_u16; 16];
    for y in 0_usize..4 {
        for x in 0_usize..4 {
            prediction[y.saturating_mul(4).saturating_add(x)] =
                diagonal_z1_predictor_sample(edge, max_base_x, dx, base_increment, x, y)?;
        }
    }
    Ok(reconstruct_lossy_4x4_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn reconstruct_lossy_luma_4x8_diagonal_z1(
    top: [u16; 4],
    top_left: u16,
    angle: i32,
    coefficients: Option<Lossy4x8TransformCoefficients>,
    transform_kind: Lossy4x8TransformKind,
) -> PortableResult<ReconstructedPlane> {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:881-963. Zone 1 uses the
    // top edge only; the eight-row terminal extends the final top sample in
    // the same checked edge layout as the reference decoder.
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (0 < angle && angle < 90).then_some(()).portable()?;
    let dx_index = usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?;
    let dx = *DR_INTRA_DERIVATIVE
        .get(dx_index)
        .filter(|&&value| value > 0)
        .portable()?;
    let edge = [
        top[0], top[1], top[2], top[3], top[3], top[3], top[3], top[3],
    ];
    let upsample = 50 < angle;
    let upsampled_edge = upsample_intra_top_edge(edge, top_left);
    let (edge, max_base_x, dx, base_increment) = if upsample {
        (&upsampled_edge[..], 14, dx.saturating_mul(2), 2)
    } else {
        (&edge[..], 7, dx, 1)
    };
    let mut prediction = [0_u16; 32];
    for y in 0_usize..8 {
        for x in 0_usize..4 {
            prediction[y.saturating_mul(4).saturating_add(x)] =
                diagonal_z1_predictor_sample(edge, max_base_x, dx, base_increment, x, y)?;
        }
    }
    Ok(reconstruct_lossy_luma_4x8_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

