fn reconstruct_lossy_chroma_4x4_diagonal_z3_with_bottom_left(
    left: [u16; 4],
    bottom_left: Option<[u16; 4]>,
    top_left: u16,
    angle: i32,
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (180 < angle && angle < 270).then_some(()).portable()?;
    let dy_index =
        usize::try_from(270_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let mut edge = [0_u16; 8];
    edge[..4].copy_from_slice(&left);
    edge[4..].copy_from_slice(&bottom_left.unwrap_or([left[3]; 4]));
    let upsampled_edge = upsample_intra_left_edge(edge, top_left);
    let mut prediction = [0_u16; 16];
    for y in 0_usize..4 {
        for x in 0_usize..4 {
            prediction[y.saturating_mul(4).saturating_add(x)] =
                diagonal_z3_predictor_sample(&upsampled_edge, 14, dy.saturating_mul(2), 2, x, y)?;
        }
    }

    let coefficients = coefficients.unwrap_or([0_i32; 16]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity4x4(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct4x4(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct4x4(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst4x4(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct4x4(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity4x4(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst4x4(&coefficients),
    };

    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_4x4_smooth(
    top: [u16; 4],
    top_right: u16,
    left: [u16; 4],
    coefficients: Option<TransformCoefficients>,
    transform_kind: LossyTransformKind,
) -> ReconstructedPlane {
    // ✅ VERIFIED: rav1d 1.1.0 src/ipred.rs:631-665 and
    // src/tables.rs:1073-1080. Width four uses the weights at table offset
    // four: [255, 149, 85, 64]. Missing left-edge samples are extended from
    // the top-left sample before this helper is called.
    const SMOOTH_WEIGHTS_4: [i32; 4] = [255, 149, 85, 64];
    let right = i32::from(top_right);
    let bottom = i32::from(left[3]);
    let mut prediction = [0_u16; 16];
    for y in 0_usize..4 {
        for x in 0_usize..4 {
            let vertical_weight = SMOOTH_WEIGHTS_4[y];
            let horizontal_weight = SMOOTH_WEIGHTS_4[x];
            let value = vertical_weight
                .saturating_mul(i32::from(top[x]))
                .saturating_add(
                    256_i32
                        .saturating_sub(vertical_weight)
                        .saturating_mul(bottom),
                )
                .saturating_add(horizontal_weight.saturating_mul(i32::from(left[y])))
                .saturating_add(
                    256_i32
                        .saturating_sub(horizontal_weight)
                        .saturating_mul(right),
                )
                .saturating_add(256)
                >> 9;
            #[expect(
                clippy::cast_sign_loss,
                reason = "the smooth predictor is explicitly clamped to eight-bit range"
            )]
            let value = value.clamp(0, 255) as u16;
            prediction[y.saturating_mul(4).saturating_add(x)] = value;
        }
    }

    let coefficients = coefficients.unwrap_or([0_i32; 16]);
    let residual = match transform_kind {
        LossyTransformKind::IdentityIdentity => transform::inverse_identity4x4(&coefficients),
        LossyTransformKind::IdentityDct => transform::inverse_identity_dct4x4(&coefficients),
        LossyTransformKind::DctDct => transform::inverse_dct4x4(&coefficients),
        LossyTransformKind::DctAdst => transform::inverse_dct_adst4x4(&coefficients),
        LossyTransformKind::AdstDct => transform::inverse_adst_dct4x4(&coefficients),
        LossyTransformKind::DctIdentity => transform::inverse_dct_identity4x4(&coefficients),
        LossyTransformKind::AdstAdst => transform::inverse_adst_adst4x4(&coefficients),
    };
    let samples = prediction
        .into_iter()
        .zip(residual)
        .map(|(predictor, value)| {
            let reconstructed = i32::from(predictor).saturating_add(value).clamp(0, 255);
            #[expect(
                clippy::cast_sign_loss,
                reason = "the reconstructed eight-bit sample is explicitly clamped to 0..=255"
            )]
            {
                reconstructed as u16
            }
        })
        .collect();

    ReconstructedPlane { samples }
}

fn reconstruct_lossy_chroma_4x4_smooth(
    top: [u16; 4],
    top_right: u16,
    left: [u16; 4],
    coefficients: Option<TransformCoefficients>,
) -> ReconstructedPlane {
    reconstruct_lossy_4x4_smooth(
        top,
        top_right,
        left,
        coefficients,
        LossyTransformKind::AdstAdst,
    )
}

#[expect(
    clippy::too_many_arguments,
    reason = "the 4:2:0 square leaf receives the complete neighboring luma/chroma edge state"
)]
fn reconstruct_following_lossy_420_square4_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    _above_right: &ClosedLeaf,
    top_left_neighbor: Option<&ClosedLeaf>,
    left_neighbor: Option<&ClosedLeaf>,
    above_chroma_neighbor: Option<&ClosedLeaf>,
    above_chroma_width: u32,
    above_chroma_x_offset: u32,
    left_chroma_neighbor: Option<&ClosedLeaf>,
    left_chroma_width: u32,
    left_chroma_height: u32,
    left_chroma_y_offset: u32,
    top_available: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        chroma_predictor,
        chroma_angle,
        lossy_luma_coefficients,
        lossy_luma_transform,
        lossy_chroma_coefficients,
        reconstruction: ReconstructionPolicy::Lossy420Dct4x4,
        ..
    } = syntax
    else {
        return Err(PortableUnavailable);
    };

    let luma_top = bottom_edge_for_square4(&above_left.planes[0]);
    let luma_top_left = top_left_neighbor.map_or_else(
        || bottom_right_for_square4(&above_left.planes[0]),
        |neighbor| bottom_right_for_square4(&neighbor.planes[0]),
    );
    let luma_left = left_neighbor.map_or([luma_top[0]; 4], |neighbor| {
        right_edge_for_square4(&neighbor.planes[0])
    });
    let luma_left = if left_neighbor.is_some() {
        luma_left
    } else {
        [luma_top_left; 4]
    };
    let luma_coefficients = lossy_luma_coefficients
        .map(|coefficients| std::array::from_fn(|index| coefficients[index]));

    let luma = match luma_predictor {
        LumaPredictor::Dc => reconstruct_lossy_4x4(
            if left_neighbor.is_some() && top_available {
                dc_predictor(luma_top, luma_left)
            } else {
                one_sided_dc_predictor_4(if left_neighbor.is_some() {
                    luma_left
                } else {
                    luma_top
                })
            },
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::Vertical => reconstruct_lossy_4x4_from_prediction(
            std::array::from_fn(|index| luma_top[index % 4]),
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::Horizontal => reconstruct_lossy_4x4_from_prediction(
            std::array::from_fn(|index| luma_left[index / 4]),
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::Smooth => reconstruct_lossy_4x4_smooth(
            luma_top,
            luma_top[3],
            luma_left,
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            luma_top,
            luma_left[3],
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            luma_left,
            luma_top[3],
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            luma_top,
            luma_left,
            luma_top_left,
            luma_coefficients,
            lossy_luma_transform,
        ),
        LumaPredictor::DiagonalDownRight
        | LumaPredictor::Diagonal113
        | LumaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            [
                luma_top[0],
                luma_top[1],
                luma_top[2],
                luma_top[3],
                luma_top[3],
                luma_top[3],
                luma_top[3],
                luma_top[3],
            ],
            luma_left,
            luma_angle.ok_or(PortableUnavailable)?,
            luma_coefficients,
            lossy_luma_transform,
        )?,
        LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => reconstruct_lossy_4x4_diagonal_z1(
            luma_top,
            bottom_right_for_square4(&above_left.planes[0]),
            luma_angle.ok_or(PortableUnavailable)?,
            luma_coefficients,
            lossy_luma_transform,
        )?,
        LumaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
            luma_left,
            luma_left[0],
            luma_angle.ok_or(PortableUnavailable)?,
            luma_coefficients,
            lossy_luma_transform,
        )?,
    };
    // Chroma availability follows the subsampled block grid, not the luma
    // leaf grid. When top is unavailable but left is present, dav1d's
    // prepare_intra_edges() synthesizes the top edge from the first left
    // sample; when neither edge is present it uses top=127 and left=129.
    let chroma_left_u = left_chroma_neighbor.map_or([129; 4], |neighbor| {
        right_edge_at::<4>(
            &neighbor.planes[1],
            left_chroma_width.div_ceil(2).max(4),
            left_chroma_height.div_ceil(2).max(4),
            left_chroma_y_offset,
        )
    });
    let chroma_left_v = left_chroma_neighbor.map_or([129; 4], |neighbor| {
        right_edge_at::<4>(
            &neighbor.planes[2],
            left_chroma_width.div_ceil(2).max(4),
            left_chroma_height.div_ceil(2).max(4),
            left_chroma_y_offset,
        )
    });
    let chroma_top_u = above_chroma_neighbor.map_or_else(
        || {
            if left_chroma_neighbor.is_some() {
                [chroma_left_u[0]; 4]
            } else {
                [127; 4]
            }
        },
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[1],
                above_chroma_width.div_ceil(2).max(4),
                above_chroma_x_offset,
            )
        },
    );
    let chroma_top_v = above_chroma_neighbor.map_or_else(
        || {
            if left_chroma_neighbor.is_some() {
                [chroma_left_v[0]; 4]
            } else {
                [127; 4]
            }
        },
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[2],
                above_chroma_width.div_ceil(2).max(4),
                above_chroma_x_offset,
            )
        },
    );
    // When only the top edge exists, dav1d extends the missing left edge from
    // the first top sample. Keep the all-unavailable fallback at 129, but do
    // not use it when a real top edge is available.
    let chroma_left_u = if left_chroma_neighbor.is_none() && above_chroma_neighbor.is_some() {
        [chroma_top_u[0]; 4]
    } else {
        chroma_left_u
    };
    let chroma_left_v = if left_chroma_neighbor.is_none() && above_chroma_neighbor.is_some() {
        [chroma_top_v[0]; 4]
    } else {
        chroma_left_v
    };
    let chroma_top_left_u = match (above_chroma_neighbor, left_chroma_neighbor) {
        (None, None) => 128,
        (None, Some(_)) => chroma_left_u[0],
        (Some(_), None) => chroma_top_u[0],
        (Some(above), Some(left)) => {
            if left_chroma_y_offset > 0 {
                right_edge_at::<1>(
                    &left.planes[1],
                    left_chroma_width.div_ceil(2).max(4),
                    left_chroma_height.div_ceil(2).max(4),
                    left_chroma_y_offset.saturating_sub(1),
                )[0]
            } else if above_chroma_x_offset > 0 {
                bottom_edge_at::<1>(
                    &above.planes[1],
                    above_chroma_width.div_ceil(2).max(4),
                    above_chroma_x_offset.saturating_sub(1),
                )[0]
            } else {
                top_left_neighbor.map_or(128, |neighbor| {
                    bottom_right_for_square4(&neighbor.planes[1])
                })
            }
        }
    };
    let chroma_top_left_v = match (above_chroma_neighbor, left_chroma_neighbor) {
        (None, None) => 128,
        (None, Some(_)) => chroma_left_v[0],
        (Some(_), None) => chroma_top_v[0],
        (Some(above), Some(left)) => {
            if left_chroma_y_offset > 0 {
                right_edge_at::<1>(
                    &left.planes[2],
                    left_chroma_width.div_ceil(2).max(4),
                    left_chroma_height.div_ceil(2).max(4),
                    left_chroma_y_offset.saturating_sub(1),
                )[0]
            } else if above_chroma_x_offset > 0 {
                bottom_edge_at::<1>(
                    &above.planes[2],
                    above_chroma_width.div_ceil(2).max(4),
                    above_chroma_x_offset.saturating_sub(1),
                )[0]
            } else {
                top_left_neighbor.map_or(128, |neighbor| {
                    bottom_right_for_square4(&neighbor.planes[2])
                })
            }
        }
    };
    let chroma_u = match chroma_predictor {
        ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
            if above_chroma_neighbor.is_some() {
                dc_predictor(chroma_top_u, chroma_left_u)
            } else {
                one_sided_dc_predictor_4(chroma_left_u)
            },
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Vertical => reconstruct_lossy_chroma_4x4_vertical(
            chroma_top_u,
            lossy_chroma_coefficients[0],
            chroma_transform_kind(chroma_predictor),
        ),
        ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
            chroma_left_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
            chroma_left_u,
            chroma_top_u[0],
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        )?,
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            [
                chroma_top_u[0],
                chroma_top_u[1],
                chroma_top_u[2],
                chroma_top_u[3],
                chroma_top_u[3],
                chroma_top_u[3],
                chroma_top_u[3],
                chroma_top_u[3],
            ],
            chroma_left_u,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        )?,
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1(
                chroma_top_u,
                chroma_top_left_u,
                chroma_angle.ok_or(PortableUnavailable)?,
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            )?
        }
        ChromaPredictor::Smooth => reconstruct_lossy_chroma_4x4_smooth(
            chroma_top_u,
            chroma_top_u[3],
            chroma_left_u,
            lossy_chroma_coefficients[0],
        ),
        ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            chroma_top_u,
            chroma_left_u[3],
            lossy_chroma_coefficients[0],
            LossyTransformKind::AdstDct,
        ),
        ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            chroma_left_u,
            chroma_top_u[3],
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            chroma_top_u,
            chroma_left_u,
            chroma_top_left_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Cfl { alpha_u, .. } => {
            let result = reconstruct_lossy_chroma_4x4_cfl(
                &luma,
                dc_predictor(chroma_top_u, chroma_left_u),
                alpha_u,
                lossy_chroma_coefficients[0],
            );
            result?
        }
    };
    let chroma_v = match chroma_predictor {
        ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
            if above_chroma_neighbor.is_some() {
                dc_predictor(chroma_top_v, chroma_left_v)
            } else {
                one_sided_dc_predictor_4(chroma_left_v)
            },
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Vertical => reconstruct_lossy_chroma_4x4_vertical(
            chroma_top_v,
            lossy_chroma_coefficients[1],
            chroma_transform_kind(chroma_predictor),
        ),
        ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
            chroma_left_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
            chroma_left_v,
            chroma_top_v[0],
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        )?,
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            [
                chroma_top_v[0],
                chroma_top_v[1],
                chroma_top_v[2],
                chroma_top_v[3],
                chroma_top_v[3],
                chroma_top_v[3],
                chroma_top_v[3],
                chroma_top_v[3],
            ],
            chroma_left_v,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        )?,
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1(
                chroma_top_v,
                chroma_top_left_v,
                chroma_angle.ok_or(PortableUnavailable)?,
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            )?
        }
        ChromaPredictor::Smooth => reconstruct_lossy_chroma_4x4_smooth(
            chroma_top_v,
            chroma_top_v[3],
            chroma_left_v,
            lossy_chroma_coefficients[1],
        ),
        ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            chroma_top_v,
            chroma_left_v[3],
            lossy_chroma_coefficients[1],
            LossyTransformKind::AdstDct,
        ),
        ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            chroma_left_v,
            chroma_top_v[3],
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            chroma_top_v,
            chroma_left_v,
            chroma_top_left_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Cfl { alpha_v, .. } => {
            let result = reconstruct_lossy_chroma_4x4_cfl(
                &luma,
                dc_predictor(chroma_top_v, chroma_left_v),
                alpha_v,
                lossy_chroma_coefficients[1],
            );
            result?
        }
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

/// Reconstruct a genuine 4×4 leaf reached from the left edge of a partition.
///
/// The horizontal traversal has no decoded block above the current leaf, but
/// AV1 still prepares a top edge when a left edge exists. Reuse the complete
/// square-4 predictor implementation by supplying a checked synthetic top
/// block whose edge and top-left sample are the first left-edge sample.
fn reconstruct_following_lossy_420_square4_horizontal_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
) -> PortableResult<ClosedLeaf> {
    let above_left = ClosedLeaf {
        luma_predictor: neighbor.luma_predictor,
        planes: std::array::from_fn(|plane| {
            let left_edge = right_edge_for_square4(&neighbor.planes[plane]);
            ReconstructedPlane {
                samples: vec![left_edge[0]; 16],
            }
        }),
    };
    reconstruct_following_lossy_420_square4_leaf(
        syntax,
        &above_left,
        &above_left,
        None,
        Some(neighbor),
        None,
        0,
        0,
        Some(neighbor),
        4,
        4,
        0,
        false,
    )
}

#[expect(
    clippy::too_many_arguments,
    reason = "the monochrome square leaf receives the complete neighboring luma edge state"
)]
fn reconstruct_following_lossy_monochrome_square4_leaf(
    syntax: BlockSyntax,
    palette_map_arena: &PaletteMapArena,
    above_left: &ClosedLeaf,
    top_left_neighbor: Option<&ClosedLeaf>,
    left_neighbor: Option<&ClosedLeaf>,
    left_luma_edge: Option<[u16; 4]>,
    top_luma_edge: Option<[u16; 4]>,
    top_luma_edge_extended: Option<[u16; 8]>,
    top_luma_left: Option<u16>,
    top_available: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        lossy_luma_coefficients,
        lossy_luma_transform,
        ..
    } = syntax;
    let luma_top = top_luma_edge.unwrap_or_else(|| bottom_edge_for_square4(&above_left.planes[0]));
    let top_left = top_luma_left.unwrap_or_else(|| {
        top_left_neighbor.map_or_else(
            || luma_top[0],
            |neighbor| bottom_right_for_square4(&neighbor.planes[0]),
        )
    });
    let luma_left = left_luma_edge.unwrap_or_else(|| {
        left_neighbor.map_or([top_left; 4], |neighbor| {
            right_edge_for_square4(&neighbor.planes[0])
        })
    });
    let coefficients = lossy_luma_coefficients
        .map(|coefficients| std::array::from_fn(|index| coefficients[index]));

    let luma = if let Some(mode) = filter_intra_mode {
        let prediction =
            reconstruct_filter_intra_prediction(mode, 4, 4, top_left, &luma_top, &luma_left)?
                .try_into()
                .map_err(|_| PortableUnavailable)?;
        reconstruct_lossy_4x4_from_prediction(prediction, coefficients, lossy_luma_transform)
    } else {
        match luma_predictor {
            LumaPredictor::Dc => reconstruct_lossy_4x4(
                if left_neighbor.is_some() && top_available {
                    dc_predictor(luma_top, luma_left)
                } else {
                    one_sided_dc_predictor_4(if left_neighbor.is_some() {
                        luma_left
                    } else {
                        luma_top
                    })
                },
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Vertical => reconstruct_lossy_4x4_from_prediction(
                std::array::from_fn(|index| luma_top[index % 4]),
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Horizontal => reconstruct_lossy_4x4_from_prediction(
                std::array::from_fn(|index| luma_left[index / 4]),
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Smooth => reconstruct_lossy_4x4_smooth(
                luma_top,
                luma_top[3],
                luma_left,
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
                luma_top,
                luma_left[3],
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
                luma_left,
                luma_top[3],
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
                luma_top,
                luma_left,
                top_left,
                coefficients,
                lossy_luma_transform,
            ),
            LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                if let Some(top) = top_luma_edge_extended {
                    reconstruct_lossy_4x4_diagonal_z1_extended(
                        top,
                        top_left,
                        luma_angle.ok_or(PortableUnavailable)?,
                        coefficients,
                        lossy_luma_transform,
                    )?
                } else {
                    reconstruct_lossy_4x4_diagonal_z1(
                        luma_top,
                        top_left,
                        luma_angle.ok_or(PortableUnavailable)?,
                        coefficients,
                        lossy_luma_transform,
                    )?
                }
            }
            LumaPredictor::DiagonalDownRight
            | LumaPredictor::Diagonal113
            | LumaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
                [
                    luma_top[0],
                    luma_top[1],
                    luma_top[2],
                    luma_top[3],
                    luma_top[3],
                    luma_top[3],
                    luma_top[3],
                    luma_top[3],
                ],
                luma_left,
                luma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                lossy_luma_transform,
            )?,
            LumaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3(
                luma_left,
                top_left,
                luma_angle.ok_or(PortableUnavailable)?,
                coefficients,
                lossy_luma_transform,
            )?,
        }
    };
    let mut leaf = reconstruct_leaf(
        syntax,
        [luma_predictor.sample(), 128, 128],
        palette_map_arena,
    )?;
    leaf.planes[0] = luma;
    Ok(leaf)
}

