fn checked_bottom_sample_at(plane: &ReconstructedPlane, width: u32, x_offset: u32) -> Option<u16> {
    let width = usize::try_from(width).ok()?;
    let x_offset = usize::try_from(x_offset).ok()?;
    if width == 0 || x_offset >= width {
        return None;
    }
    let height = plane.samples.len().checked_div(width)?;
    (height > 0).then(|| plane.samples[(height - 1) * width + x_offset])
}

fn checked_right_edge_at<const N: usize>(
    plane: &ReconstructedPlane,
    width: u32,
    height: u32,
    row_offset: u32,
) -> Option<[u16; N]> {
    let width = usize::try_from(width).ok()?;
    let height = usize::try_from(height).ok()?;
    let row_offset = usize::try_from(row_offset).ok()?;
    if width == 0 || row_offset.saturating_add(N) > height {
        return None;
    }
    let mut edge = [0_u16; N];
    for (index, sample) in edge.iter_mut().enumerate() {
        *sample = *plane
            .samples
            .get((row_offset + index) * width + width - 1)?;
    }
    Some(edge)
}

fn validate_leaf_plane_storage(leaf: &FirstLeaf, plane: usize) -> PortableResult<()> {
    let width = usize::try_from(leaf.width).map_err(|_| PortableUnavailable)?;
    let height = usize::try_from(leaf.height).map_err(|_| PortableUnavailable)?;
    (width != 0 && height != 0).then_some(()).portable()?;
    let expected_len = width.checked_mul(height).ok_or(PortableUnavailable)?;
    (leaf.planes[plane].samples.len() == expected_len)
        .then_some(())
        .portable()
}

/// Assemble a complete eight-row full-resolution chroma edge from the
/// owners touching a vertical-following block. A single owner may cover only
/// the first or final rows, so each row is selected independently with the
/// chroma owner taking precedence over the luma owner. The returned source
/// identifies the owner and offset for the row-zero sample, which is needed
/// to derive the exact top-left corner and smooth-edge policy.
fn checked_full_chroma_left_edge<const N: usize>(
    neighbors: &VerticalNeighbors<'_>,
    plane: usize,
) -> PortableResult<(Option<[u16; N]>, Option<(bool, u32)>)> {
    let sample_from = |owner: &FirstLeaf, row_offset: u32, row: u32| {
        let row_offset = row_offset.checked_add(row).ok_or(PortableUnavailable)?;
        let width = usize::try_from(owner.width).map_err(|_| PortableUnavailable)?;
        let height = usize::try_from(owner.height).map_err(|_| PortableUnavailable)?;
        if width == 0 || height == 0 || row_offset >= owner.height {
            return Ok(None);
        }
        let expected_len = width.checked_mul(height).ok_or(PortableUnavailable)?;
        (owner.planes[plane].samples.len() == expected_len)
            .then_some(())
            .portable()?;
        checked_right_edge_at::<1>(&owner.planes[plane], owner.width, owner.height, row_offset)
            .map(|edge| edge[0])
            .ok_or(PortableUnavailable)
            .map(Some)
    };

    let owners_present = neighbors.left_chroma.is_some() || neighbors.left.is_some();
    let mut edge = [0_u16; N];
    let mut complete = true;
    let mut row_zero_owner = None;
    for row in 0..N {
        let row = u32::try_from(row).map_err(|_| PortableUnavailable)?;
        let mut selected = None;
        if let Some(owner) = neighbors.left_chroma {
            if let Some(value) = sample_from(owner, neighbors.left_chroma_y_offset, row)? {
                selected = Some(value);
                if row == 0 {
                    row_zero_owner = Some((true, neighbors.left_chroma_y_offset));
                }
            }
        }
        if selected.is_none() {
            if let Some(owner) = neighbors.left {
                if let Some(value) = sample_from(owner, neighbors.left_y_offset, row)? {
                    selected = Some(value);
                    if row == 0 {
                        row_zero_owner = Some((false, neighbors.left_y_offset));
                    }
                }
            }
        }
        if let Some(value) = selected {
            edge[usize::try_from(row).map_err(|_| PortableUnavailable)?] = value;
        } else {
            complete = false;
        }
    }
    if !complete {
        if owners_present {
            return Err(PortableUnavailable);
        }
        return Ok((None, None));
    }
    Ok((Some(edge), row_zero_owner))
}

fn checked_full_chroma_top_left(
    neighbors: &VerticalNeighbors<'_>,
    plane: usize,
    row_zero_owner: (bool, u32),
) -> PortableResult<u16> {
    let (is_chroma, row_offset) = row_zero_owner;
    if row_offset > 0 {
        let owner = if is_chroma {
            neighbors.left_chroma
        } else {
            neighbors.left
        }
        .ok_or(PortableUnavailable)?;
        validate_leaf_plane_storage(owner, plane)?;
        return checked_right_edge_at::<1>(
            &owner.planes[plane],
            owner.width,
            owner.height,
            row_offset.saturating_sub(1),
        )
        .map(|edge| edge[0])
        .ok_or(PortableUnavailable);
    }
    if let Some(left_top) = neighbors.left_top {
        validate_leaf_plane_storage(left_top, plane)?;
        let row = left_top.height.checked_sub(1).ok_or(PortableUnavailable)?;
        return checked_right_edge_at::<1>(
            &left_top.planes[plane],
            left_top.width,
            left_top.height,
            row,
        )
        .map(|edge| edge[0])
        .ok_or(PortableUnavailable);
    }
    let offset = neighbors
        .above_left_x_offset
        .checked_sub(1)
        .filter(|&offset| offset < neighbors.above_left_width)
        .ok_or(PortableUnavailable)?;
    checked_bottom_sample_at(
        &neighbors.above_left.planes[plane],
        neighbors.above_left_width,
        offset,
    )
    .ok_or(PortableUnavailable)
}

fn positioned_top_edge<const N: usize>(
    plane: usize,
    first: &FirstLeaf,
    first_offset: u32,
    second: &FirstLeaf,
    second_offset: u32,
) -> Option<[u16; N]> {
    let first_available = usize::try_from(first.width.saturating_sub(first_offset))
        .ok()?
        .min(N);
    let mut edge = [0_u16; N];
    let mut last = None;
    for (index, sample) in edge.iter_mut().enumerate() {
        let value = if index < first_available {
            checked_bottom_sample_at(
                &first.planes[plane],
                first.width,
                first_offset.saturating_add(u32::try_from(index).ok()?),
            )
        } else {
            checked_bottom_sample_at(
                &second.planes[plane],
                second.width,
                second_offset
                    .saturating_add(u32::try_from(index.saturating_sub(first_available)).ok()?),
            )
        };
        if let Some(value) = value {
            *sample = value;
            last = Some(value);
        } else {
            let value = last?;
            *sample = value;
        }
    }
    Some(edge)
}

fn full_square4_vertical_edges(
    neighbors: &VerticalNeighbors<'_>,
    plane: usize,
) -> PortableResult<FullSquare4Edges> {
    let (first, first_offset, extension, extension_offset) = if plane == 0 {
        (
            neighbors.above_left,
            neighbors.above_left_x_offset,
            neighbors.above_luma_extension,
            neighbors.above_luma_extension_x_offset,
        )
    } else if let Some(above) = neighbors.above_chroma {
        (
            above,
            neighbors.above_chroma_x_offset,
            neighbors.above_chroma_extension,
            neighbors.above_chroma_extension_x_offset,
        )
    } else {
        (
            neighbors.above_left,
            neighbors.above_left_x_offset,
            neighbors.above_luma_extension,
            neighbors.above_luma_extension_x_offset,
        )
    };
    let second = extension.unwrap_or(neighbors.above_right);
    let second_offset = if extension.is_some() {
        extension_offset
    } else {
        neighbors.above_right_x_offset
    };
    let top = positioned_top_edge::<4>(plane, first, first_offset, second, second_offset)
        .ok_or(PortableUnavailable)?;
    let top_extended = positioned_top_edge::<8>(plane, first, first_offset, second, second_offset)
        .ok_or(PortableUnavailable)?;

    let left_source = if plane == 0 {
        neighbors
            .left
            .map(|neighbor| (neighbor, neighbors.left_y_offset))
    } else {
        neighbors
            .left_chroma
            .map(|neighbor| (neighbor, neighbors.left_chroma_y_offset))
            .or_else(|| {
                neighbors
                    .left
                    .map(|neighbor| (neighbor, neighbors.left_y_offset))
            })
    };
    let left_edge = left_source.and_then(|(neighbor, row_offset)| {
        checked_right_edge_at::<4>(
            &neighbor.planes[plane],
            neighbor.width,
            neighbor.height,
            row_offset,
        )
    });
    let has_left = left_edge.is_some();
    let left = left_edge.unwrap_or([top[0]; 4]);
    let bottom_left = left_source.and_then(|(neighbor, row_offset)| {
        checked_right_edge_at::<4>(
            &neighbor.planes[plane],
            neighbor.width,
            neighbor.height,
            row_offset.saturating_add(4),
        )
    });
    let top_left = if has_left {
        full_resolution_chroma_top_left(neighbors, plane).ok_or(PortableUnavailable)?
    } else {
        top[0]
    };
    Ok(FullSquare4Edges {
        top,
        top_extended,
        left,
        bottom_left,
        top_left,
        has_top: true,
        has_left,
    })
}

fn reconstruct_following_lossy_full_square4_vertical_leaf(
    syntax: BlockSyntax,
    neighbors: &VerticalNeighbors<'_>,
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let edges = [
        full_square4_vertical_edges(neighbors, 0)?,
        full_square4_vertical_edges(neighbors, 1)?,
        full_square4_vertical_edges(neighbors, 2)?,
    ];
    let smooth_edges = matches!(
        neighbors.above_left.luma_predictor,
        LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
    ) || neighbors.left.is_some_and(|neighbor| {
        matches!(
            neighbor.luma_predictor,
            LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
        )
    });
    reconstruct_lossy_full_square4_leaf(syntax, edges, enable_intra_edge_filter, smooth_edges)
}

fn reconstruct_following_lossy_full_square4_horizontal_leaf(
    syntax: BlockSyntax,
    neighbor: &ClosedLeaf,
    neighbor_width: u32,
    neighbor_height: u32,
    chroma_left_edges_8: [Option<[u16; 8]>; 2],
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let mut edges = [
        FullSquare4Edges {
            top: [128; 4],
            top_extended: [128; 8],
            left: [128; 4],
            bottom_left: None,
            top_left: 128,
            has_top: false,
            has_left: true,
        },
        FullSquare4Edges {
            top: [128; 4],
            top_extended: [128; 8],
            left: [128; 4],
            bottom_left: None,
            top_left: 128,
            has_top: false,
            has_left: true,
        },
        FullSquare4Edges {
            top: [128; 4],
            top_extended: [128; 8],
            left: [128; 4],
            bottom_left: None,
            top_left: 128,
            has_top: false,
            has_left: true,
        },
    ];
    for plane in 0..=2 {
        let left = if plane == 0 {
            checked_right_edge_at::<4>(&neighbor.planes[plane], neighbor_width, neighbor_height, 0)
        } else {
            chroma_left_edges_8[plane - 1]
                .map(|edge| [edge[0], edge[1], edge[2], edge[3]])
                .or_else(|| {
                    checked_right_edge_at::<4>(
                        &neighbor.planes[plane],
                        neighbor_width,
                        neighbor_height,
                        0,
                    )
                })
        }
        .ok_or(PortableUnavailable)?;
        let bottom_left =
            checked_right_edge_at::<4>(&neighbor.planes[plane], neighbor_width, neighbor_height, 4);
        edges[plane] = FullSquare4Edges {
            top: [left[0]; 4],
            top_extended: [left[0]; 8],
            left,
            bottom_left,
            top_left: left[0],
            has_top: false,
            has_left: true,
        };
    }
    let smooth_edges = matches!(
        neighbor.luma_predictor,
        LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
    );
    reconstruct_lossy_full_square4_leaf(syntax, edges, enable_intra_edge_filter, smooth_edges)
}

// Every edge, availability flag, coefficient sentence, and predictor state in
// this kernel describes the same checked 8x8 chroma plane.
#[expect(
    clippy::too_many_arguments,
    reason = "8x8 chroma reconstruction carries one plane's complete AV1 edge and transform state"
)]
fn reconstruct_lossy_full_8x8_chroma(
    luma: &ReconstructedPlane,
    predictor: ChromaPredictor,
    cfl_alpha: Option<i32>,
    angle: Option<i32>,
    top: [u16; 8],
    top_extended: [u16; 16],
    left: [u16; 8],
    bottom_left: Option<[u16; 8]>,
    top_left: u16,
    has_top: bool,
    has_left: bool,
    coefficients: Option<LossyTransformCoefficients>,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
) -> PortableResult<ReconstructedPlane> {
    let transform = chroma_transform_kind(predictor);
    match predictor {
        ChromaPredictor::Dc => Ok(reconstruct_lossy_chroma_8x8(
            dc_predictor_8_with_availability(top, left, has_top, has_left),
            coefficients,
            transform,
        )),
        ChromaPredictor::Vertical => match angle {
            None | Some(90) => Ok(reconstruct_lossy_luma_8x8_vertical(
                top,
                coefficients,
                transform,
            )),
            Some(angle) if 0 < angle && angle < 90 => {
                reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                    top_extended,
                    top_left,
                    angle,
                    enable_intra_edge_filter,
                    smooth_edges,
                    coefficients,
                    transform,
                )
            }
            Some(angle) if 90 < angle && angle < 180 => reconstruct_lossy_luma_8x8_diagonal(
                top_extended,
                left,
                top_left,
                angle,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            ),
            _ => Err(PortableUnavailable),
        },
        ChromaPredictor::Horizontal => match angle {
            None | Some(180) => Ok(reconstruct_lossy_luma_8x8_horizontal(
                left,
                coefficients,
                transform,
            )),
            Some(angle) if 90 < angle && angle < 180 => reconstruct_lossy_luma_8x8_diagonal(
                top_extended,
                left,
                top_left,
                angle,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            ),
            Some(angle) if 180 < angle && angle < 270 => {
                reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
                    left,
                    top_left,
                    bottom_left,
                    angle,
                    enable_intra_edge_filter,
                    smooth_edges,
                    coefficients,
                    transform,
                )
            }
            _ => Err(PortableUnavailable),
        },
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                top_extended,
                top_left,
                angle.ok_or(PortableUnavailable)?,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            )
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
            top_extended,
            left,
            top_left,
            angle.ok_or(PortableUnavailable)?,
            enable_intra_edge_filter,
            smooth_edges,
            coefficients,
            transform,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
            left,
            top_left,
            bottom_left,
            angle.ok_or(PortableUnavailable)?,
            enable_intra_edge_filter,
            smooth_edges,
            coefficients,
            transform,
        ),
        ChromaPredictor::Smooth => Ok(reconstruct_lossy_luma_8x8_smooth(
            top,
            top[7],
            left,
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothVertical => Ok(reconstruct_lossy_luma_8x8_smooth_vertical(
            top,
            left[7],
            coefficients,
            transform,
        )),
        ChromaPredictor::SmoothHorizontal => Ok(reconstruct_lossy_luma_8x8_smooth_horizontal(
            left,
            top[7],
            coefficients,
            transform,
        )),
        ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_8x8_paeth(
            top,
            left,
            top_left,
            coefficients,
            transform,
        )),
        ChromaPredictor::Cfl { .. } => reconstruct_lossy_full_8x8_cfl(
            luma,
            dc_predictor_8_with_availability(top, left, has_top, has_left),
            cfl_alpha.ok_or(PortableUnavailable)?,
            coefficients,
        ),
    }
}

fn reconstruct_lossy_full_4x16_cfl(
    luma: &ReconstructedPlane,
    predictor: u16,
    alpha: i32,
    coefficients: Option<Lossy4x16TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if luma.samples.len() != 64 {
        return Err(PortableUnavailable);
    }
    let mut ac = [0_i32; 64];
    let mut sum = 32_i32;
    for (index, sample) in luma.samples.iter().enumerate() {
        ac[index] = i32::from(*sample).saturating_mul(8);
        sum = sum.saturating_add(ac[index]);
    }
    let mean = sum >> 6;
    for value in &mut ac {
        *value = value.saturating_sub(mean);
    }
    let residual = transform::inverse_dct4x16(&coefficients.unwrap_or([0_i32; 64]));
    let samples = residual
        .into_iter()
        .enumerate()
        .map(|(index, value)| reconstruct_cfl_sample(predictor, alpha, ac[index], value))
        .collect();
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_full_4x16_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 4],
    left: [u16; 16],
    coefficients: Option<Lossy4x16TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    let transform = Lossy4x8TransformKind::DctDct;
    match predictor {
        ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_4x16_from_prediction(
            [rectangular_dc_predictor(&top, &left); 64],
            coefficients,
            transform,
        )),
        ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_4x16_from_prediction(
            std::array::from_fn(|index| top[index % 4]),
            coefficients,
            transform,
        )),
        ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_4x16_from_prediction(
            std::array::from_fn(|index| left[index / 4]),
            coefficients,
            transform,
        )),
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_4x16_diagonal_z2(
            top,
            left,
            top[0],
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Diagonal203 => reconstruct_lossy_luma_4x16_diagonal_z3(
            left,
            top[0],
            angle.ok_or(PortableUnavailable)?,
            coefficients,
            transform,
        ),
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            Ok(reconstruct_lossy_luma_4x16_from_prediction(
                std::array::from_fn(|index| top[index % 4]),
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::Smooth => {
            let right = i32::from(top[3]);
            let bottom = i32::from(left[15]);
            let prediction = std::array::from_fn(|index| {
                let y = index / 4;
                let x = index % 4;
                let vertical = [
                    255_i32, 240, 225, 210, 196, 182, 169, 157, 145, 133, 122, 111, 101, 92, 83, 74,
                ][y];
                let horizontal = [255_i32, 149, 85, 64][x];
                let value = vertical
                    .saturating_mul(i32::from(top[x]))
                    .saturating_add((256 - vertical).saturating_mul(bottom))
                    .saturating_add(horizontal.saturating_mul(i32::from(left[y])))
                    .saturating_add((256 - horizontal).saturating_mul(right))
                    .saturating_add(256)
                    >> 9;
                #[expect(clippy::cast_sign_loss, reason = "smooth prediction is clamped")]
                {
                    value.clamp(0, 255) as u16
                }
            });
            Ok(reconstruct_lossy_luma_4x16_from_prediction(
                prediction,
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::SmoothVertical => {
            let bottom = i32::from(left[15]);
            let prediction = std::array::from_fn(|index| {
                let y = index / 4;
                let weight = [
                    255_i32, 240, 225, 210, 196, 182, 169, 157, 145, 133, 122, 111, 101, 92, 83, 74,
                ][y];
                let value = weight
                    .saturating_mul(i32::from(top[index % 4]))
                    .saturating_add((256 - weight).saturating_mul(bottom))
                    .saturating_add(128)
                    >> 8;
                #[expect(clippy::cast_sign_loss, reason = "smooth prediction is clamped")]
                {
                    value.clamp(0, 255) as u16
                }
            });
            Ok(reconstruct_lossy_luma_4x16_from_prediction(
                prediction,
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::SmoothHorizontal => {
            let right = i32::from(top[3]);
            let prediction = std::array::from_fn(|index| {
                let x = index % 4;
                let weight = [255_i32, 149, 85, 64][x];
                let value = weight
                    .saturating_mul(i32::from(left[index / 4]))
                    .saturating_add((256 - weight).saturating_mul(right))
                    .saturating_add(128)
                    >> 8;
                #[expect(clippy::cast_sign_loss, reason = "smooth prediction is clamped")]
                {
                    value.clamp(0, 255) as u16
                }
            });
            Ok(reconstruct_lossy_luma_4x16_from_prediction(
                prediction,
                coefficients,
                transform,
            ))
        }
        ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_4x16_from_prediction(
            std::array::from_fn(|index| paeth_predictor(top[index % 4], left[index / 4], top[0])),
            coefficients,
            transform,
        )),
        ChromaPredictor::Cfl { .. } => Err(PortableUnavailable),
    }
}

#[expect(
    clippy::too_many_arguments,
    reason = "the exact Vertical4x16 chroma path carries positioned edges, availability, filtering, and residual state"
)]
fn reconstruct_lossy_full_4x16_chroma_normalized_target(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 4],
    top_extension: Option<[u16; 4]>,
    left: [u16; 16],
    bottom_left: Option<[u16; 4]>,
    top_left: Option<u16>,
    has_left: bool,
    coefficients: Option<Lossy4x16TransformCoefficients>,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
) -> PortableResult<ReconstructedPlane> {
    match predictor {
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            let angle = angle.ok_or(PortableUnavailable)?;
            (0 < angle && angle < 90).then_some(()).portable()?;
        }
        ChromaPredictor::Diagonal203 => {
            let angle = angle.ok_or(PortableUnavailable)?;
            (180 < angle && angle < 270).then_some(()).portable()?;
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => {
            let angle = angle.ok_or(PortableUnavailable)?;
            (90 < angle && angle < 180).then_some(()).portable()?;
        }
        ChromaPredictor::Smooth
        | ChromaPredictor::SmoothVertical
        | ChromaPredictor::SmoothHorizontal => {}
        _ => return Err(PortableUnavailable),
    }

    let mut top_edge = [0_u16; 8];
    top_edge[..4].copy_from_slice(&top);
    let have_above_right = if matches!(
        predictor,
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67
    ) {
        if let Some(extension) = top_extension {
            top_edge[4..].copy_from_slice(&extension);
            true
        } else {
            false
        }
    } else {
        false
    };
    let top_edge = if have_above_right {
        &top_edge[..]
    } else {
        &top_edge[..4]
    };

    let mut left_edge = [0_u16; 20];
    left_edge[..16].copy_from_slice(&left);
    let have_below_left = if matches!(predictor, ChromaPredictor::Diagonal203) {
        if let Some(extension) = bottom_left {
            left_edge[16..].copy_from_slice(&extension);
            true
        } else {
            false
        }
    } else {
        false
    };
    let left_edge = if have_below_left {
        &left_edge[..]
    } else {
        &left_edge[..16]
    };
    let edges = FullIntraPlaneEdges::prepare(
        4,
        16,
        SampleDepth::EIGHT,
        top_edge,
        left_edge,
        top_left,
        true,
        has_left,
        have_above_right,
        have_below_left,
        smooth_edges,
    )?;
    let mut prediction = [0_u16; 64];
    full_intra_prediction_into(
        &mut prediction,
        lossless_chroma_predictor(predictor),
        angle,
        None,
        4,
        16,
        &edges,
        SampleDepth::EIGHT,
        enable_intra_edge_filter,
    )?;
    Ok(reconstruct_lossy_luma_4x16_from_prediction(
        prediction,
        coefficients,
        chroma_rect_transform_kind(predictor),
    ))
}

#[expect(
    clippy::too_many_arguments,
    reason = "the exact horizontal-following R4x16 chroma path carries normalized edges, continuation, filtering, and residual state"
)]
fn reconstruct_lossy_full_4x16_chroma_horizontal_target(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    left: [u16; 16],
    bottom_left: Option<[u16; 4]>,
    coefficients: Option<Lossy4x16TransformCoefficients>,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
) -> PortableResult<ReconstructedPlane> {
    match predictor {
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            let angle = angle.ok_or(PortableUnavailable)?;
            (0 < angle && angle < 90).then_some(()).portable()?;
        }
        ChromaPredictor::Diagonal203 => {
            let angle = angle.ok_or(PortableUnavailable)?;
            (180 < angle && angle < 270).then_some(()).portable()?;
        }
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => {
            let angle = angle.ok_or(PortableUnavailable)?;
            (90 < angle && angle < 180).then_some(()).portable()?;
        }
        ChromaPredictor::Paeth
        | ChromaPredictor::Smooth
        | ChromaPredictor::SmoothVertical
        | ChromaPredictor::SmoothHorizontal => {}
        _ => return Err(PortableUnavailable),
    }
    let mut left_edge = [0_u16; 20];
    left_edge[..16].copy_from_slice(&left);
    let have_below_left = if matches!(predictor, ChromaPredictor::Diagonal203) {
        if let Some(extension) = bottom_left {
            left_edge[16..].copy_from_slice(&extension);
            true
        } else {
            false
        }
    } else {
        false
    };
    let left_edge = if have_below_left {
        &left_edge[..]
    } else {
        &left_edge[..16]
    };
    // A horizontally following leaf has no normative top carrier. Leaving
    // the top slice empty with `has_top = false` derives the unavailable top
    // edge and corner from the first real left sample.
    let edges = FullIntraPlaneEdges::prepare(
        4,
        16,
        SampleDepth::EIGHT,
        &[],
        left_edge,
        None,
        false,
        true,
        false,
        have_below_left,
        smooth_edges,
    )?;
    let mut prediction = [0_u16; 64];
    full_intra_prediction_into(
        &mut prediction,
        lossless_chroma_predictor(predictor),
        angle,
        None,
        4,
        16,
        &edges,
        SampleDepth::EIGHT,
        enable_intra_edge_filter,
    )?;
    Ok(reconstruct_lossy_luma_4x16_from_prediction(
        prediction,
        coefficients,
        chroma_rect_transform_kind(predictor),
    ))
}

fn chroma_transform_16x16_kind(
    predictor: ChromaPredictor,
) -> PortableResult<Lossy16x16TransformKind> {
    match chroma_transform_kind(predictor) {
        LossyTransformKind::IdentityIdentity => Ok(Lossy16x16TransformKind::IdentityIdentity),
        LossyTransformKind::DctDct => Ok(Lossy16x16TransformKind::DctDct),
        LossyTransformKind::AdstAdst => Ok(Lossy16x16TransformKind::AdstAdst),
        LossyTransformKind::AdstDct => Ok(Lossy16x16TransformKind::AdstDct),
        LossyTransformKind::DctAdst => Ok(Lossy16x16TransformKind::DctAdst),
        LossyTransformKind::IdentityDct | LossyTransformKind::DctIdentity => {
            Err(PortableUnavailable)
        }
    }
}

#[expect(
    clippy::too_many_arguments,
    reason = "full-resolution 16x16 chroma carries normalized edges, availability, filtering, and residual state"
)]
fn reconstruct_lossy_full_16x16_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: &[u16],
    left: &[u16],
    top_left: Option<u16>,
    has_top: bool,
    has_left: bool,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
    coefficients: Option<Lossy16x16TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if matches!(predictor, ChromaPredictor::Cfl { .. }) {
        // CfL owns a separate luma AC surface and must never silently map to
        // an ordinary intra predictor when this edge-only helper is selected.
        return Err(PortableUnavailable);
    }
    let edges = FullIntraPlaneEdges::prepare(
        16,
        16,
        SampleDepth::EIGHT,
        top,
        left,
        top_left,
        has_top,
        has_left,
        false,
        false,
        smooth_edges,
    )?;
    let mut prediction = [0_u16; 256];
    full_intra_prediction_into(
        &mut prediction,
        lossless_chroma_predictor(predictor),
        angle,
        None,
        16,
        16,
        &edges,
        SampleDepth::EIGHT,
        enable_intra_edge_filter,
    )?;
    let transform = chroma_transform_16x16_kind(predictor)?;
    Ok(reconstruct_lossy_luma_16x16_from_prediction(
        prediction,
        coefficients,
        transform,
    ))
}

