#[expect(
    clippy::too_many_arguments,
    reason = "full-resolution 16x16 luma carries normalized edges, filter-intra, availability, and transform state"
)]
fn reconstruct_lossy_full_16x16_luma(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: &[u16],
    left: &[u16],
    top_left: Option<u16>,
    has_top: bool,
    has_left: bool,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
    coefficients: Option<Lossy16x16TransformCoefficients>,
    transform_kind: Lossy16x16TransformKind,
) -> PortableResult<ReconstructedPlane> {
    let edges = if !has_top && !has_left {
        FullIntraPlaneEdges::origin(16, 16, SampleDepth::EIGHT)?
    } else {
        FullIntraPlaneEdges::prepare(
            16,
            16,
            SampleDepth::EIGHT,
            top,
            left,
            top_left,
            has_top,
            has_left,
            false,
            false,
            smooth_edges,
        )?
    };
    let mut prediction = [0_u16; 256];
    full_intra_prediction_into(
        &mut prediction,
        lossless_luma_predictor(predictor),
        angle,
        filter_intra_mode,
        16,
        16,
        &edges,
        SampleDepth::EIGHT,
        enable_intra_edge_filter,
    )?;
    Ok(reconstruct_lossy_luma_16x16_from_prediction(
        prediction,
        coefficients,
        transform_kind,
    ))
}

fn reconstruct_lossy_full_16x32_chroma(
    predictor: ChromaPredictor,
    angle: Option<i32>,
    top: [u16; 16],
    left: [u16; 32],
    top_left: Option<u16>,
    has_top: bool,
    has_left: bool,
    enable_intra_edge_filter: bool,
    coefficients: Option<Lossy16x32TransformCoefficients>,
) -> PortableResult<ReconstructedPlane> {
    if matches!(predictor, ChromaPredictor::Cfl { .. }) {
        // CfL needs the reconstructed luma AC surface, which this legacy
        // direct carrier does not own. Never silently map it to DC.
        return Err(PortableUnavailable);
    }
    let edges = FullIntraPlaneEdges::prepare(
        16,
        32,
        SampleDepth::EIGHT,
        &top,
        &left,
        top_left,
        has_top,
        has_left,
        false,
        false,
        false,
    )?;
    let mut prediction = [0_u16; 512];
    full_intra_prediction_into(
        &mut prediction,
        lossless_chroma_predictor(predictor),
        angle,
        None,
        16,
        32,
        &edges,
        SampleDepth::EIGHT,
        enable_intra_edge_filter,
    )?;
    let coefficients = coefficients.unwrap_or([0_i32; 512]);
    let residual = transform::inverse_dct16x32(&coefficients);
    Ok(reconstruct_lossy_predicted_plane(&prediction, &residual))
}

