#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 split reconstruction needs the predictor edges, filtering state, and decoded child syntax"
)]
fn reconstruct_lossy_luma_16x16_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 16],
    top_left: u16,
    has_top: bool,
    has_left: bool,
    split: LossyLuma8x8Split,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 256];
    for transform_index in 0_usize..4 {
        let row = transform_index / 2;
        let column = transform_index % 2;
        let offset_x = column.saturating_mul(8);
        let offset_y = row.saturating_mul(8);
        let top_edge: [u16; 8] = std::array::from_fn(|index| {
            if row == 0 {
                top[offset_x.saturating_add(index)]
            } else {
                samples[(offset_y - 1).saturating_mul(16) + offset_x + index]
            }
        });
        let top_extension: [u16; 16] = std::array::from_fn(|index| {
            if row == 0 {
                top[offset_x.saturating_add(index).min(15)]
            } else {
                samples[(offset_y - 1).saturating_mul(16) + (offset_x + index).min(15)]
            }
        });
        let left_edge: [u16; 8] = std::array::from_fn(|index| {
            if column == 0 {
                left[offset_y.saturating_add(index)]
            } else {
                samples[(offset_y + index).saturating_mul(16) + offset_x - 1]
            }
        });
        let block_top_left = match (row, column) {
            (0, 0) => top_left,
            (0, 1) => top[offset_x - 1],
            (1, 0) => left[offset_y - 1],
            _ => samples[(offset_y - 1).saturating_mul(16) + offset_x - 1],
        };
        let coefficients = split.coefficients[transform_index];
        let transform = split.transforms[transform_index];
        let block = if let Some(mode) = filter_intra_mode {
            let prediction = reconstruct_filter_intra_prediction(
                mode,
                8,
                8,
                block_top_left,
                &top_edge,
                &left_edge,
            )?;
            let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
            reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
        } else {
            match predictor {
                LumaPredictor::Dc => {
                    let value = match (has_top || row != 0, has_left || column != 0) {
                        (true, true) => dc_predictor_8(top_edge, left_edge),
                        (true, false) => one_sided_dc_predictor_8(top_edge),
                        (false, true) => one_sided_dc_predictor_8(left_edge),
                        (false, false) => 128,
                    };

                    reconstruct_lossy_luma_8x8(value, coefficients, transform)
                }
                LumaPredictor::Vertical => {
                    reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                }
                LumaPredictor::Horizontal => {
                    reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    reconstruct_lossy_luma_8x8_diagonal_z1(
                        top_edge,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        coefficients,
                        transform,
                    )?
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                    top_extension,
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                    top_edge,
                    top_extension[7],
                    left_edge,
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                    top_edge,
                    left_edge[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x8_smooth_horizontal(
                    left_edge,
                    top_extension[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                    top_edge,
                    left_edge,
                    block_top_left,
                    coefficients,
                    transform,
                ),
            }
        };
        for (row_offset, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
            let output_start = (offset_y + row_offset).saturating_mul(16) + offset_x;
            samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R16x64 split reconstruction carries the full vertical edges and child syntax"
)]
fn reconstruct_lossy_luma_16x64_vertical_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 64],
    top_left: u16,
    has_left: bool,
    split: LossyLuma16x16VerticalSplit,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    let mut samples = vec![0_u16; 16 * 16 * split.child_count];

    for row in 0_usize..split.child_count {
        let offset_y = row.saturating_mul(16);
        let top_edge: [u16; 16] = if row == 0 {
            top
        } else {
            samples[(offset_y - 1).saturating_mul(16)..offset_y.saturating_mul(16)]
                .try_into()
                .map_err(|_| PortableUnavailable)?
        };
        let top_extension: [u16; 32] = if row == 0 {
            std::array::from_fn(|index| top[index.min(15)])
        } else {
            std::array::from_fn(|index| samples[(offset_y - 1).saturating_mul(16) + index.min(15)])
        };
        let left_edge: [u16; 16] = left[offset_y..offset_y + 16]
            .try_into()
            .map_err(|_| PortableUnavailable)?;
        let block_top_left = if row == 0 {
            top_left
        } else {
            left[offset_y - 1]
        };
        let coefficients = split.coefficients[row];
        let transform = split.transforms[row];
        let prediction: [u16; 256] = if let Some(mode) = filter_intra_mode {
            reconstruct_filter_intra_prediction(
                mode,
                16,
                16,
                block_top_left,
                &top_edge,
                &left_edge,
            )?
            .try_into()
            .map_err(|_| PortableUnavailable)?
        } else {
            match predictor {
                LumaPredictor::Dc => {
                    let value = if has_left {
                        dc_predictor_16(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor_16(top_edge)
                    };
                    [value; 256]
                }
                LumaPredictor::Vertical => std::array::from_fn(|index| top_edge[index % 16]),
                LumaPredictor::Horizontal => std::array::from_fn(|index| left_edge[index / 16]),
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (0 < angle && angle < 90).then_some(()).portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?)
                        .filter(|&&value| value > 0)
                        .portable()?;
                    let upsample = angle > 50;
                    let mut edge = [0_u16; 31];
                    let (max_base_x, dx, base_increment) = if upsample {
                        edge = upsample_intra_top_edge_16(top_edge, block_top_left);
                        (30, dx.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&top_edge);
                        (15, dx, 1)
                    };
                    let mut prediction = [0_u16; 256];
                    for (index, sample) in prediction.iter_mut().enumerate() {
                        *sample = diagonal_z1_predictor_sample(
                            &edge,
                            max_base_x,
                            dx,
                            base_increment,
                            index % 16,
                            index / 16,
                        )?;
                    }
                    prediction
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (90 < angle && angle < 180).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(angle.saturating_sub(90) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(180_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let mut edge = [0_u16; 65];
                    edge[32] = block_top_left;
                    for (index, value) in top_extension.into_iter().enumerate() {
                        edge[33 + index] = value;
                    }
                    for (index, value) in left_edge.into_iter().enumerate() {
                        edge[31 - index] = value;
                    }
                    let mut prediction = [0_u16; 256];
                    for (index, sample) in prediction.iter_mut().enumerate() {
                        *sample =
                            diagonal_predictor_sample(&edge, 32, dx, dy, index % 16, index / 16)?;
                    }
                    prediction
                }
                LumaPredictor::Diagonal203 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (180 < angle && angle < 270).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(270_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let upsample = angle < 220;
                    let mut edge = [0_u16; 31];
                    let (max_base_y, dy, base_increment) = if upsample {
                        edge = upsample_intra_left_edge_16(left_edge, block_top_left);
                        (30, dy.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&left_edge);
                        (15, dy, 1)
                    };
                    let mut prediction = [0_u16; 256];
                    for (index, sample) in prediction.iter_mut().enumerate() {
                        *sample = diagonal_z3_predictor_sample(
                            &edge,
                            max_base_y,
                            dy,
                            base_increment,
                            index % 16,
                            index / 16,
                        )?;
                    }
                    prediction
                }
                LumaPredictor::Smooth => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    let bottom = i32::from(left_edge[15]);
                    std::array::from_fn(|index| {
                        let x = index % 16;
                        let y = index / 16;
                        let vertical = i32::from(weights[y]);
                        let horizontal = i32::from(weights[x]);
                        let value = vertical
                            .saturating_mul(i32::from(top_edge[x]))
                            .saturating_add((256 - vertical).saturating_mul(bottom))
                            .saturating_add(horizontal.saturating_mul(i32::from(left_edge[y])))
                            .saturating_add((256 - horizontal).saturating_mul(right))
                            .saturating_add(256)
                            >> 9;
                        #[expect(
                            clippy::cast_sign_loss,
                            reason = "the smooth predictor is explicitly clamped"
                        )]
                        {
                            value.clamp(0, 255) as u16
                        }
                    })
                }
                LumaPredictor::SmoothVertical => {
                    let weights = smooth_weight_table(16)?;
                    let bottom = i32::from(left_edge[15]);
                    std::array::from_fn(|index| {
                        let weight = i32::from(weights[index / 16]);
                        let value = weight
                            .saturating_mul(i32::from(top_edge[index % 16]))
                            .saturating_add((256 - weight).saturating_mul(bottom))
                            .saturating_add(128)
                            >> 8;
                        #[expect(
                            clippy::cast_sign_loss,
                            reason = "the smooth predictor is explicitly clamped"
                        )]
                        {
                            value.clamp(0, 255) as u16
                        }
                    })
                }
                LumaPredictor::SmoothHorizontal => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    std::array::from_fn(|index| {
                        let weight = i32::from(weights[index % 16]);
                        let value = weight
                            .saturating_mul(i32::from(left_edge[index / 16]))
                            .saturating_add((256 - weight).saturating_mul(right))
                            .saturating_add(128)
                            >> 8;
                        #[expect(
                            clippy::cast_sign_loss,
                            reason = "the smooth predictor is explicitly clamped"
                        )]
                        {
                            value.clamp(0, 255) as u16
                        }
                    })
                }
                LumaPredictor::Paeth => std::array::from_fn(|index| {
                    paeth_predictor(top_edge[index % 16], left_edge[index / 16], block_top_left)
                }),
            }
        };
        let block =
            reconstruct_lossy_luma_16x16_from_prediction(prediction, coefficients, transform);
        for (row_offset, source) in block.samples.as_chunks::<16>().0.iter().enumerate() {
            let output_start = (offset_y + row_offset) * 16;
            samples[output_start..output_start + 16].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_lossy_luma_8x16_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 16],
    top_left: u16,
    has_left: bool,
    split: LossyLuma8x8Split,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 128];
    for row in 0_usize..2 {
        let offset_y = row.saturating_mul(8);
        let top_edge = if row == 0 {
            top[..8].try_into().map_err(|_| PortableUnavailable)?
        } else {
            std::array::from_fn(|column| samples[(offset_y - 1).saturating_mul(8) + column])
        };
        let top_extension = if row == 0 {
            top
        } else {
            std::array::from_fn(|column| samples[(offset_y - 1).saturating_mul(8) + column.min(7)])
        };
        let left_edge = std::array::from_fn(|index| left[offset_y + index]);
        let block_top_left = if row == 0 {
            top_left
        } else {
            left[offset_y - 1]
        };
        let coefficients = split.coefficients[row];
        let transform = split.transforms[row];
        let block = if let Some(mode) = filter_intra_mode {
            let prediction = reconstruct_filter_intra_prediction(
                mode,
                8,
                8,
                block_top_left,
                &top_edge,
                &left_edge,
            )?;
            let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
            reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
        } else {
            match predictor {
                LumaPredictor::Dc => {
                    // A vertically split block still has an internal top edge
                    // for its second 8x8 transform, but that does not create
                    // an external left edge. When the leaf has no left
                    // neighbor, each child therefore uses one-sided DC from
                    // its available top edge; dav1d does not average it with
                    // the synthetic unavailable-left sentinel.
                    let value = if has_left {
                        dc_predictor_8(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor(top_edge)
                    };
                    reconstruct_lossy_luma_8x8(value, coefficients, transform)
                }
                LumaPredictor::Vertical => {
                    reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                }
                LumaPredictor::Horizontal => {
                    reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    if row == 0 {
                        reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                            top_extension,
                            block_top_left,
                            angle.ok_or(PortableUnavailable)?,
                            false,
                            false,
                            coefficients,
                            transform,
                        )?
                    } else {
                        reconstruct_lossy_luma_8x8_diagonal_z1(
                            top_edge,
                            block_top_left,
                            angle.ok_or(PortableUnavailable)?,
                            coefficients,
                            transform,
                        )?
                    }
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                    top_extension,
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                    top_edge,
                    top_extension[7],
                    left_edge,
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                    top_edge,
                    left_edge[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x8_smooth_horizontal(
                    left_edge,
                    top_extension[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                    top_edge,
                    left_edge,
                    block_top_left,
                    coefficients,
                    transform,
                ),
            }
        };
        for (row_offset, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
            let output_start = (offset_y + row_offset).saturating_mul(8);
            samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

/// Reconstruct the promoted following R8x16 Zone-1 leaf from its 2×4 TX4x4
/// children. Each child is predicted, inverse-transformed with its decoded
/// residual, and committed before the next causal child is visited. The
/// child-local top edge is taken from the real eight samples above the leaf,
/// with the final sample repeated for the right child; lower rows read their
/// top and northwest samples from the private reconstructed raster.
fn reconstruct_lossy_luma_8x16_4x4_grid_diagonal_z1(
    top: [u16; 16],
    top_left: u16,
    angle: i32,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
    split: LossyLuma4x4GridSplit,
) -> PortableResult<ReconstructedPlane> {
    (0 < angle && angle < 90).then_some(()).portable()?;

    let mut samples = vec![0_u16; 128];
    for row in 0_usize..4 {
        let offset_y = row.checked_mul(4).ok_or(PortableUnavailable)?;
        for column in 0_usize..2 {
            let offset_x = column.checked_mul(4).ok_or(PortableUnavailable)?;
            let mut top_edge = [0_u16; 8];
            for (index, sample) in top_edge.iter_mut().enumerate() {
                let source_x = if column == 0 {
                    index
                } else {
                    4_usize.saturating_add(index.min(3))
                };
                let source_index = if row == 0 {
                    source_x
                } else {
                    offset_y
                        .checked_sub(1)
                        .and_then(|row| row.checked_mul(8))
                        .and_then(|row_start| row_start.checked_add(source_x))
                        .ok_or(PortableUnavailable)?
                };
                *sample = if row == 0 {
                    *top.get(source_index).portable()?
                } else {
                    *samples.get(source_index).portable()?
                };
            }

            let block_top_left = if row == 0 {
                if column == 0 {
                    top_left
                } else {
                    *top.get(3).portable()?
                }
            } else {
                let previous_row = offset_y.checked_sub(1).ok_or(PortableUnavailable)?;
                let source_x = if column == 0 { 0 } else { 3 };
                let source_index = previous_row
                    .checked_mul(8)
                    .and_then(|row_start| row_start.checked_add(source_x))
                    .ok_or(PortableUnavailable)?;
                *samples.get(source_index).portable()?
            };

            let transform_index = row
                .checked_mul(2)
                .and_then(|index| index.checked_add(column))
                .ok_or(PortableUnavailable)?;
            let coefficients = *split.coefficients.get(transform_index).portable()?;
            let transform = *split.transforms.get(transform_index).portable()?;
            let block = reconstruct_lossy_4x4_diagonal_z1_with_edge(
                top_edge,
                block_top_left,
                angle,
                enable_intra_edge_filter,
                smooth_edges,
                coefficients,
                transform,
            )?;
            for (row_offset, source) in block.samples.as_chunks::<4>().0.iter().enumerate() {
                let output_row = offset_y
                    .checked_add(row_offset)
                    .ok_or(PortableUnavailable)?;
                let output_start = output_row
                    .checked_mul(8)
                    .and_then(|index| index.checked_add(offset_x))
                    .ok_or(PortableUnavailable)?;
                let output_end = output_start.checked_add(4).ok_or(PortableUnavailable)?;
                samples
                    .get_mut(output_start..output_end)
                    .portable()?
                    .copy_from_slice(source);
            }
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 split reconstruction needs the predictor edges, filtering state, and decoded child syntax"
)]
fn reconstruct_lossy_luma_16x8_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 8],
    top_left: u16,
    has_top: bool,
    has_left: bool,
    split: LossyLuma8x8Split,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 128];
    for column in 0_usize..2 {
        let offset_x = column.saturating_mul(8);
        let top_edge = if has_top {
            top[offset_x..offset_x.saturating_add(8)]
                .try_into()
                .map_err(|_| PortableUnavailable)?
        } else {
            [top[0]; 8]
        };
        let top_extension = if has_top { top } else { [top[0]; 16] };
        let left_edge = if column == 0 {
            left
        } else {
            std::array::from_fn(|row| samples[row.saturating_mul(16) + offset_x - 1])
        };
        let block_top_left = if column == 0 {
            top_left
        } else if has_top {
            top[offset_x - 1]
        } else {
            top[0]
        };
        let coefficients = split.coefficients[column];
        let transform = split.transforms[column];
        let block = if let Some(mode) = filter_intra_mode {
            let prediction = reconstruct_filter_intra_prediction(
                mode,
                8,
                8,
                block_top_left,
                &top_edge,
                &left_edge,
            )?;
            let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
            reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
        } else {
            match predictor {
                LumaPredictor::Dc => {
                    let value = dc_predictor_8_with_availability(
                        top_edge,
                        left_edge,
                        has_top,
                        has_left || column != 0,
                    );
                    reconstruct_lossy_luma_8x8(value, coefficients, transform)
                }
                LumaPredictor::Vertical => {
                    reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                }
                LumaPredictor::Horizontal => {
                    reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                        top_extension,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        false,
                        coefficients,
                        transform,
                    )?
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                    top_extension,
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                    top_edge,
                    top_extension[7],
                    left_edge,
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                    top_edge,
                    left_edge[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x8_smooth_horizontal(
                    left_edge,
                    top_extension[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                    top_edge,
                    left_edge,
                    block_top_left,
                    coefficients,
                    transform,
                ),
            }
        };
        for (row, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
            let output_start = row.saturating_mul(16).saturating_add(offset_x);
            samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R16x32 split reconstruction needs both full edges and the child transform grid"
)]
fn reconstruct_lossy_luma_16x32_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 16],
    left: [u16; 32],
    top_left: u16,
    has_top: bool,
    has_left: bool,
    split: LossyLuma8x8GridSplit,
) -> PortableResult<ReconstructedPlane> {
    let mut samples = vec![0_u16; 512];
    for row in 0_usize..4 {
        for column in 0_usize..2 {
            let transform_index = row.saturating_mul(2).saturating_add(column);
            let offset_x = column.saturating_mul(8);
            let offset_y = row.saturating_mul(8);
            let top_edge: [u16; 8] = if row == 0 {
                top[offset_x..offset_x.saturating_add(8)]
                    .try_into()
                    .map_err(|_| PortableUnavailable)?
            } else {
                std::array::from_fn(|index| {
                    samples[(offset_y - 1).saturating_mul(16) + offset_x + index]
                })
            };
            let top_extension = if row == 0 {
                top
            } else {
                std::array::from_fn(|index| samples[(offset_y - 1).saturating_mul(16) + index])
            };
            let left_edge: [u16; 8] = if column == 0 {
                if has_left || row == 0 {
                    left[offset_y..offset_y.saturating_add(8)]
                        .try_into()
                        .map_err(|_| PortableUnavailable)?
                } else {
                    [top_edge[0]; 8]
                }
            } else {
                std::array::from_fn(|index| {
                    samples[(offset_y + index).saturating_mul(16) + offset_x - 1]
                })
            };
            let block_top_left = match (row, column) {
                (0, 0) => top_left,
                (0, _) => top[offset_x - 1],
                (_, 0) if has_left => left[offset_y - 1],
                (_, 0) => top_edge[0],
                _ => samples[(offset_y - 1).saturating_mul(16) + offset_x - 1],
            };
            let coefficients = split.coefficients[transform_index];
            let transform = split.transforms[transform_index];
            let block = if let Some(mode) = filter_intra_mode {
                let prediction = reconstruct_filter_intra_prediction(
                    mode,
                    8,
                    8,
                    block_top_left,
                    &top_edge,
                    &left_edge,
                )?;
                let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
                reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
            } else {
                match predictor {
                    LumaPredictor::Dc => {
                        let value = dc_predictor_8_with_availability(
                            top_edge,
                            left_edge,
                            has_top || row != 0,
                            has_left || column != 0,
                        );
                        reconstruct_lossy_luma_8x8(value, coefficients, transform)
                    }
                    LumaPredictor::Vertical => {
                        reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                    }
                    LumaPredictor::Horizontal => {
                        reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                    }
                    LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                        if row == 0 {
                            reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                                top_extension,
                                block_top_left,
                                angle.ok_or(PortableUnavailable)?,
                                false,
                                false,
                                coefficients,
                                transform,
                            )?
                        } else {
                            reconstruct_lossy_luma_8x8_diagonal_z1(
                                top_edge,
                                block_top_left,
                                angle.ok_or(PortableUnavailable)?,
                                coefficients,
                                transform,
                            )?
                        }
                    }
                    LumaPredictor::DiagonalDownRight
                    | LumaPredictor::Diagonal113
                    | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                        top_extension,
                        left_edge,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        false,
                        coefficients,
                        transform,
                    )?,
                    LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                        left_edge,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        coefficients,
                        transform,
                    )?,
                    LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                        top_edge,
                        top_extension[7],
                        left_edge,
                        coefficients,
                        transform,
                    ),
                    LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                        top_edge,
                        left_edge[7],
                        coefficients,
                        transform,
                    ),
                    LumaPredictor::SmoothHorizontal => {
                        reconstruct_lossy_luma_8x8_smooth_horizontal(
                            left_edge,
                            top_extension[7],
                            coefficients,
                            transform,
                        )
                    }
                    LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                        top_edge,
                        left_edge,
                        block_top_left,
                        coefficients,
                        transform,
                    ),
                }
            };
            for (row_offset, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
                let output_start = (offset_y + row_offset).saturating_mul(16) + offset_x;
                samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
            }
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R32x16 horizontal split needs both complete predictor edges and child syntax"
)]
fn reconstruct_lossy_luma_32x16_horizontal_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 32],
    left: [u16; 16],
    top_left: u16,
    has_left: bool,
    split: LossyLuma16x16HorizontalSplit,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    let mut samples = vec![0_u16; 512];
    for column in 0_usize..2 {
        let offset_x = column.saturating_mul(16);
        let top_edge: [u16; 16] = std::array::from_fn(|index| top[offset_x + index]);
        let top_extension: [u16; 32] =
            std::array::from_fn(|index| top[offset_x.saturating_add(index).min(31)]);
        let left_edge: [u16; 16] = if column == 0 {
            left
        } else {
            std::array::from_fn(|index| samples[index.saturating_mul(32) + offset_x - 1])
        };
        let block_top_left = if column == 0 {
            top_left
        } else {
            top[offset_x - 1]
        };
        let prediction: [u16; 256] = if let Some(mode) = filter_intra_mode {
            reconstruct_filter_intra_prediction(
                mode,
                16,
                16,
                block_top_left,
                &top_edge,
                &left_edge,
            )?
            .try_into()
            .map_err(|_| PortableUnavailable)?
        } else {
            let mut prediction = [0_u16; 256];
            match predictor {
                LumaPredictor::Dc => {
                    let value = if has_left || column != 0 {
                        dc_predictor_16(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor_16(top_edge)
                    };
                    prediction.fill(value);
                }
                LumaPredictor::Vertical => {
                    for (index, value) in prediction.iter_mut().enumerate() {
                        *value = top_edge[index % 16];
                    }
                }
                LumaPredictor::Horizontal => {
                    for (index, value) in prediction.iter_mut().enumerate() {
                        *value = left_edge[index / 16];
                    }
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (0 < angle && angle < 90).then_some(()).portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?)
                        .filter(|&&value| value > 0)
                        .portable()?;
                    let upsample = 50 < angle;
                    let mut edge = [0_u16; 31];
                    let (max_base_x, dx, base_increment) = if upsample {
                        edge.copy_from_slice(&upsample_intra_top_edge_16(top_edge, block_top_left));
                        (30, dx.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&top_edge);
                        (15, dx, 1)
                    };
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] = diagonal_z1_predictor_sample(
                                &edge,
                                max_base_x,
                                dx,
                                base_increment,
                                x,
                                y,
                            )?;
                        }
                    }
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (90 < angle && angle < 180).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(angle.saturating_sub(90) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(180_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let mut edge = [0_u16; 65];
                    edge[32] = block_top_left;
                    for (index, value) in top_extension.into_iter().enumerate() {
                        edge[33 + index] = value;
                    }
                    for (index, value) in left_edge.into_iter().enumerate() {
                        edge[31 - index] = value;
                    }
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] =
                                diagonal_predictor_sample(&edge, 32, dx, dy, x, y)?;
                        }
                    }
                }
                LumaPredictor::Diagonal203 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (180 < angle && angle < 270).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(270_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let upsample = angle < 220;
                    let mut edge = [0_u16; 31];
                    let (max_base_y, dy, base_increment) = if upsample {
                        edge.copy_from_slice(&upsample_intra_left_edge_16(
                            left_edge,
                            block_top_left,
                        ));
                        (30, dy.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&left_edge);
                        (15, dy, 1)
                    };
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] = diagonal_z3_predictor_sample(
                                &edge,
                                max_base_y,
                                dy,
                                base_increment,
                                x,
                                y,
                            )?;
                        }
                    }
                }
                LumaPredictor::Smooth => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    let bottom = i32::from(left_edge[15]);
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            let vertical = i32::from(weights[y]);
                            let horizontal = i32::from(weights[x]);
                            let value = vertical
                                .saturating_mul(i32::from(top_edge[x]))
                                .saturating_add((256 - vertical).saturating_mul(bottom))
                                .saturating_add(horizontal.saturating_mul(i32::from(left_edge[y])))
                                .saturating_add((256 - horizontal).saturating_mul(right))
                                .saturating_add(256)
                                >> 9;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::SmoothVertical => {
                    let weights = smooth_weight_table(16)?;
                    let bottom = i32::from(left_edge[15]);
                    for y in 0_usize..16 {
                        let weight = i32::from(weights[y]);
                        for x in 0_usize..16 {
                            let value = weight
                                .saturating_mul(i32::from(top_edge[x]))
                                .saturating_add((256 - weight).saturating_mul(bottom))
                                .saturating_add(128)
                                >> 8;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::SmoothHorizontal => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            let weight = i32::from(weights[x]);
                            let value = weight
                                .saturating_mul(i32::from(left_edge[y]))
                                .saturating_add((256 - weight).saturating_mul(right))
                                .saturating_add(128)
                                >> 8;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::Paeth => {
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] =
                                paeth_predictor(top_edge[x], left_edge[y], block_top_left);
                        }
                    }
                }
            }
            prediction
        };
        let block = reconstruct_lossy_luma_16x16_from_prediction(
            prediction,
            split.coefficients[column],
            split.transforms[column],
        );
        for (row_offset, source) in block.samples.as_chunks::<16>().0.iter().enumerate() {
            let output_start = row_offset * 32 + offset_x;
            samples[output_start..output_start + 16].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R32x8 split reconstruction needs both full edges and the child transform grid"
)]
fn reconstruct_lossy_luma_32x8_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 32],
    left: [u16; 8],
    top_left: u16,
    has_left: bool,
    split: LossyLuma8x8GridSplit,
) -> PortableResult<ReconstructedPlane> {
    matches!(split.orientation, SplitOrientation::Horizontal)
        .then_some(())
        .portable()?;
    let mut samples = vec![0_u16; 256];
    for column in 0_usize..4 {
        let transform_index = column;
        let offset_x = column.saturating_mul(8);
        let top_edge: [u16; 8] = top[offset_x..offset_x.saturating_add(8)]
            .try_into()
            .map_err(|_| PortableUnavailable)?;
        let top_extension = std::array::from_fn(|index| top[(offset_x + index).min(31)]);
        let left_edge = if column == 0 {
            left
        } else {
            std::array::from_fn(|index| samples[index.saturating_mul(32) + offset_x - 1])
        };
        let block_top_left = if column == 0 {
            top_left
        } else {
            top[offset_x - 1]
        };
        let coefficients = split.coefficients[transform_index];
        let transform = split.transforms[transform_index];
        let block = if let Some(mode) = filter_intra_mode {
            let prediction = reconstruct_filter_intra_prediction(
                mode,
                8,
                8,
                block_top_left,
                &top_edge,
                &left_edge,
            )?;
            let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
            reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
        } else {
            match predictor {
                LumaPredictor::Dc => {
                    let value = if has_left || column != 0 {
                        dc_predictor_8(top_edge, left_edge)
                    } else {
                        one_sided_dc_predictor(top_edge)
                    };
                    reconstruct_lossy_luma_8x8(value, coefficients, transform)
                }
                LumaPredictor::Vertical => {
                    reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                }
                LumaPredictor::Horizontal => {
                    reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                        top_extension,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        false,
                        coefficients,
                        transform,
                    )?
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                    top_extension,
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                    left_edge,
                    block_top_left,
                    angle.ok_or(PortableUnavailable)?,
                    false,
                    coefficients,
                    transform,
                )?,
                LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                    top_edge,
                    top_extension[7],
                    left_edge,
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                    top_edge,
                    left_edge[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::SmoothHorizontal => reconstruct_lossy_luma_8x8_smooth_horizontal(
                    left_edge,
                    top_extension[7],
                    coefficients,
                    transform,
                ),
                LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                    top_edge,
                    left_edge,
                    block_top_left,
                    coefficients,
                    transform,
                ),
            }
        };
        for (row_offset, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
            let output_start = row_offset.saturating_mul(32) + offset_x;
            samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

#[expect(
    clippy::too_many_arguments,
    reason = "the R32x16 split reconstruction needs both full edges and the child transform grid"
)]
fn reconstruct_lossy_luma_32x16_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 32],
    left: [u16; 16],
    top_left: u16,
    has_left: bool,
    split: LossyLuma8x8GridSplit,
) -> PortableResult<ReconstructedPlane> {
    matches!(split.orientation, SplitOrientation::Horizontal)
        .then_some(())
        .portable()?;
    let mut samples = vec![0_u16; 512];
    for row in 0_usize..2 {
        for column in 0_usize..4 {
            let transform_index = row.saturating_mul(4).saturating_add(column);
            let offset_x = column.saturating_mul(8);
            let offset_y = row.saturating_mul(8);
            let top_edge: [u16; 8] = if row == 0 {
                top[offset_x..offset_x.saturating_add(8)]
                    .try_into()
                    .map_err(|_| PortableUnavailable)?
            } else {
                std::array::from_fn(|index| {
                    samples[(offset_y - 1).saturating_mul(32) + offset_x + index]
                })
            };
            let top_extension: [u16; 16] = if row == 0 {
                std::array::from_fn(|index| top[(offset_x + index).min(31)])
            } else {
                std::array::from_fn(|index| {
                    samples[(offset_y - 1).saturating_mul(32) + (offset_x + index).min(31)]
                })
            };
            let left_edge: [u16; 8] = if column == 0 {
                if has_left || row == 0 {
                    left[offset_y..offset_y.saturating_add(8)]
                        .try_into()
                        .map_err(|_| PortableUnavailable)?
                } else {
                    [top_edge[0]; 8]
                }
            } else {
                std::array::from_fn(|index| {
                    samples[(offset_y + index).saturating_mul(32) + offset_x - 1]
                })
            };
            let block_top_left = match (row, column) {
                (0, 0) => top_left,
                (0, _) => top[offset_x - 1],
                (_, 0) if has_left => left[offset_y - 1],
                (_, 0) => top_edge[0],
                _ => samples[(offset_y - 1).saturating_mul(32) + offset_x - 1],
            };
            let coefficients = split.coefficients[transform_index];
            let transform = split.transforms[transform_index];
            let block = if let Some(mode) = filter_intra_mode {
                let prediction = reconstruct_filter_intra_prediction(
                    mode,
                    8,
                    8,
                    block_top_left,
                    &top_edge,
                    &left_edge,
                )?;
                let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
                reconstruct_lossy_luma_8x8_from_prediction(prediction, coefficients, transform)
            } else {
                match predictor {
                    LumaPredictor::Dc => {
                        let value = if has_left || row != 0 || column != 0 {
                            dc_predictor_8(top_edge, left_edge)
                        } else {
                            one_sided_dc_predictor(top_edge)
                        };
                        reconstruct_lossy_luma_8x8(value, coefficients, transform)
                    }
                    LumaPredictor::Vertical => {
                        reconstruct_lossy_luma_8x8_vertical(top_edge, coefficients, transform)
                    }
                    LumaPredictor::Horizontal => {
                        reconstruct_lossy_luma_8x8_horizontal(left_edge, coefficients, transform)
                    }
                    LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                        if row == 0 {
                            reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                                top_extension,
                                block_top_left,
                                angle.ok_or(PortableUnavailable)?,
                                false,
                                false,
                                coefficients,
                                transform,
                            )?
                        } else {
                            reconstruct_lossy_luma_8x8_diagonal_z1(
                                top_edge,
                                block_top_left,
                                angle.ok_or(PortableUnavailable)?,
                                coefficients,
                                transform,
                            )?
                        }
                    }
                    LumaPredictor::DiagonalDownRight
                    | LumaPredictor::Diagonal113
                    | LumaPredictor::Diagonal157 => reconstruct_lossy_luma_8x8_diagonal(
                        top_extension,
                        left_edge,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        false,
                        coefficients,
                        transform,
                    )?,
                    LumaPredictor::Diagonal203 => reconstruct_lossy_luma_8x8_diagonal_z3(
                        left_edge,
                        block_top_left,
                        angle.ok_or(PortableUnavailable)?,
                        false,
                        coefficients,
                        transform,
                    )?,
                    LumaPredictor::Smooth => reconstruct_lossy_luma_8x8_smooth(
                        top_edge,
                        top_extension[7],
                        left_edge,
                        coefficients,
                        transform,
                    ),
                    LumaPredictor::SmoothVertical => reconstruct_lossy_luma_8x8_smooth_vertical(
                        top_edge,
                        left_edge[7],
                        coefficients,
                        transform,
                    ),
                    LumaPredictor::SmoothHorizontal => {
                        reconstruct_lossy_luma_8x8_smooth_horizontal(
                            left_edge,
                            top_extension[7],
                            coefficients,
                            transform,
                        )
                    }
                    LumaPredictor::Paeth => reconstruct_lossy_luma_8x8_paeth(
                        top_edge,
                        left_edge,
                        block_top_left,
                        coefficients,
                        transform,
                    ),
                }
            };
            for (row_offset, source) in block.samples.as_chunks::<8>().0.iter().enumerate() {
                let output_start = (offset_y + row_offset).saturating_mul(32) + offset_x;
                samples[output_start..output_start.saturating_add(8)].copy_from_slice(source);
            }
        }
    }
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_following_lossy_420_vertical_16x32_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_8x8_grid_split,
        lossy_luma_16x32_coefficients,
        lossy_luma_16x32_transform,
        lossy_chroma_8x16_coefficients,
        ..
    } = syntax;

    let luma_top = if std::ptr::eq(above_left, above_right) {
        bottom_edge_16(&above_left.planes[0])
    } else {
        let left = bottom_edge_8_for_16x4_chroma(&above_left.planes[0]);
        let right = bottom_edge_8_for_16x4_chroma(&above_right.planes[0]);
        std::array::from_fn(|index| {
            if index < 8 {
                left[index]
            } else {
                right[index - 8]
            }
        })
    };
    let luma_left = left_neighbor.map_or([luma_top[0]; 32], |neighbor| {
        let plane = &neighbor.planes[0];
        if plane.samples.len() >= 512 {
            right_edge_at::<32>(plane, 16, 32, 0)
        } else {
            let edge = right_edge_16(plane);
            std::array::from_fn(|index| edge[index % 16])
        }
    });
    let luma_top_left = left_neighbor
        .and_then(|neighbor| neighbor.planes[0].samples.last().copied())
        .unwrap_or(luma_top[0]);
    let luma = if let Some(split) = lossy_luma_8x8_grid_split {
        reconstruct_lossy_luma_16x32_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top_left,
            true,
            left_neighbor.is_some(),
            split,
        )
    } else if lossy_luma_16x32_coefficients.is_some()
        || (filter_intra_mode.is_none()
            && matches!(
                luma_predictor,
                LumaPredictor::Vertical
                    | LumaPredictor::Horizontal
                    | LumaPredictor::Diagonal45
                    | LumaPredictor::DiagonalDownRight
                    | LumaPredictor::Diagonal113
                    | LumaPredictor::Diagonal157
                    | LumaPredictor::Diagonal203
                    | LumaPredictor::Diagonal67
            ))
    {
        reconstruct_lossy_luma_16x32_from_edges(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            luma_top_left,
            true,
            left_neighbor.is_some(),
            enable_intra_edge_filter,
            lossy_luma_16x32_coefficients,
            lossy_luma_16x32_transform,
        )
    } else {
        Err(PortableUnavailable)
    }
    .map_err(|_| PortableUnavailable)?;

    let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
        let top: [u16; 8] = if std::ptr::eq(above_left, above_right) {
            bottom_edge_8_for_16x4_chroma(&above_left.planes[plane])
        } else {
            let left = bottom_edge_4(&above_left.planes[plane]);
            let right = bottom_edge_4(&above_right.planes[plane]);
            std::array::from_fn(|index| {
                if index < 4 {
                    left[index]
                } else {
                    right[index - 4]
                }
            })
        };
        let left: [u16; 16] = left_neighbor.map_or([top[0]; 16], |neighbor| {
            let plane = &neighbor.planes[plane];
            if plane.samples.len() >= 128 {
                right_edge_at::<16>(plane, 8, 16, 0)
            } else {
                let edge = right_edge(plane);
                std::array::from_fn(|index| edge[index % 8])
            }
        });
        let coefficients = lossy_chroma_8x16_coefficients[plane.saturating_sub(1)];
        let transform = chroma_transform_kind(chroma_predictor);

        match chroma_predictor {
            ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                let alpha = if plane == 1 { alpha_u } else { alpha_v };
                reconstruct_lossy_chroma_8x16_cfl(
                    &luma,
                    rectangular_dc_predictor(&top, &left),
                    alpha,
                    coefficients,
                )
            }
            ChromaPredictor::Dc => Ok(reconstruct_lossy_luma_8x16_from_prediction(
                [rectangular_dc_predictor(&top, &left); 128],
                coefficients,
                transform,
            )),
            ChromaPredictor::Vertical => Ok(reconstruct_lossy_luma_8x16_from_prediction(
                std::array::from_fn(|index| top[index % 8]),
                coefficients,
                transform,
            )),
            ChromaPredictor::Horizontal => Ok(reconstruct_lossy_luma_8x16_from_prediction(
                std::array::from_fn(|index| left[index / 8]),
                coefficients,
                transform,
            )),
            ChromaPredictor::Paeth => Ok(reconstruct_lossy_luma_8x16_from_prediction(
                std::array::from_fn(|index| {
                    paeth_predictor(top[index % 8], left[index / 8], top[0])
                }),
                coefficients,
                transform,
            )),
            ChromaPredictor::DiagonalDownRight
            | ChromaPredictor::Diagonal113
            | ChromaPredictor::Diagonal157 => reconstruct_lossy_luma_8x16_diagonal(
                std::array::from_fn(|index| top[index % 8]),
                left,
                chroma_angle.ok_or(PortableUnavailable)?,
                enable_intra_edge_filter,
                coefficients.unwrap_or([0_i32; 128]),
                transform,
            ),
            _ => Err(PortableUnavailable),
        }
    };

    let chroma_u = chroma(1)?;
    let chroma_v = chroma(2)?;
    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_following_lossy_420_vertical_16x16_leaf(
    syntax: BlockSyntax,
    palette_map_arena: &PaletteMapArena,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
    left_luma_edge_16: Option<[u16; 16]>,
    luma_top_left: Option<u16>,
    left_chroma_edges_16: [Option<[u16; 16]>; 2],
    left_chroma_edges_8: [Option<[u16; 8]>; 2],
    chroma_top_left: [Option<u16>; 2],
    above_right_is_above_left: bool,
    enable_intra_edge_filter: bool,
    smooth_luma_edges: bool,
    smooth_chroma_edges: bool,
) -> PortableResult<ClosedLeaf> {
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_16x16_coefficients,
        lossy_luma_16x16_transform,
        lossy_luma_8x8_split,
        lossy_chroma_coefficients: _,
        lossy_chroma_8x8_coefficients,
        lossy_chroma_16x16_coefficients,
        chroma_sampling,
        ..
    } = syntax;
    let above_luma_left = bottom_edge(&above_left.planes[0]);
    let luma_top = if above_right_is_above_left {
        bottom_edge_16(&above_left.planes[0])
    } else {
        let luma_right = bottom_edge(&above_right.planes[0]);
        [
            above_luma_left[0],
            above_luma_left[1],
            above_luma_left[2],
            above_luma_left[3],
            above_luma_left[4],
            above_luma_left[5],
            above_luma_left[6],
            above_luma_left[7],
            luma_right[0],
            luma_right[1],
            luma_right[2],
            luma_right[3],
            luma_right[4],
            luma_right[5],
            luma_right[6],
            luma_right[7],
        ]
    };
    let chroma_top = |plane: usize| {
        if above_right_is_above_left {
            bottom_edge_8_for_16x4_chroma(&above_left.planes[plane])
        } else {
            let left = bottom_edge_4(&above_left.planes[plane]);
            let right = bottom_edge_4(&above_right.planes[plane]);
            [
                left[0], left[1], left[2], left[3], right[0], right[1], right[2], right[3],
            ]
        }
    };
    let luma_left = left_luma_edge_16.unwrap_or_else(|| {
        left_neighbor.map_or([luma_top[0]; 16], |neighbor| {
            right_edge_16(&neighbor.planes[0])
        })
    });

    if let Some(split) = lossy_luma_8x8_split {
        let luma = reconstruct_lossy_luma_16x16_split(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            luma_top,
            luma_left,
            above_left.planes[0].samples.last().copied().unwrap_or(128),
            true,
            left_neighbor.is_some(),
            split,
        )?;
        let mut planes = [
            luma,
            ReconstructedPlane {
                samples: Vec::new(),
            },
            ReconstructedPlane {
                samples: Vec::new(),
            },
        ];
        let luma_for_chroma = planes[0].clone();
        for plane in 1..=2 {
            if matches!(chroma_sampling, ChromaSampling::Full) {
                let top = if above_right_is_above_left {
                    bottom_edge_16(&above_left.planes[plane])
                } else {
                    let left = bottom_edge_16(&above_left.planes[plane]);
                    let right = bottom_edge_16(&above_right.planes[plane]);
                    std::array::from_fn(|index| {
                        if index < 8 {
                            left[index]
                        } else {
                            right[index - 8]
                        }
                    })
                };
                let assembled_left = left_chroma_edges_16[plane - 1];
                let left = assembled_left.unwrap_or_else(|| {
                    left_neighbor.map_or([top[0]; 16], |neighbor| {
                        right_edge_16(&neighbor.planes[plane])
                    })
                });
                let has_left = assembled_left.is_some() || left_neighbor.is_some();
                let predictor = match chroma_predictor {
                    ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                        let alpha = if plane == 1 { alpha_u } else { alpha_v };
                        reconstruct_lossy_full_16x16_cfl(
                            &luma_for_chroma,
                            if has_left {
                                dc_predictor_16(top, left)
                            } else {
                                one_sided_dc_predictor_16(top)
                            },
                            alpha,
                            lossy_chroma_16x16_coefficients[plane - 1],
                        )?
                    }
                    _ => reconstruct_lossy_full_16x16_chroma(
                        chroma_predictor,
                        chroma_angle,
                        &top,
                        &left,
                        if has_left {
                            chroma_top_left[plane - 1]
                        } else {
                            None
                        },
                        true,
                        has_left,
                        enable_intra_edge_filter,
                        smooth_chroma_edges,
                        lossy_chroma_16x16_coefficients[plane - 1],
                    )?,
                };
                planes[plane] = predictor;
                continue;
            }
            let top = chroma_top(plane);
            let left = left_chroma_edges_8[plane - 1].unwrap_or([top[0]; 8]);
            let predictor = if left_neighbor.is_some() {
                dc_predictor_8(top, left)
            } else {
                one_sided_dc_predictor(top)
            };

            planes[plane] = match chroma_predictor {
                ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                    let alpha = if plane == 1 { alpha_u } else { alpha_v };
                    reconstruct_lossy_chroma_8x8_cfl(
                        &planes[0],
                        predictor,
                        alpha,
                        lossy_chroma_8x8_coefficients[plane - 1],
                    )?
                }
                _ => reconstruct_lossy_chroma_8x8(
                    predictor,
                    lossy_chroma_8x8_coefficients[plane - 1],
                    chroma_transform_kind(chroma_predictor),
                ),
            };
        }
        return Ok(ClosedLeaf {
            luma_predictor,
            planes,
        });
    }

    if matches!(chroma_sampling, ChromaSampling::Full) {
        let has_luma_left = left_luma_edge_16.is_some();
        let full_luma_left = left_luma_edge_16.unwrap_or([luma_top[0]; 16]);
        if left_neighbor.is_some() && !has_luma_left {
            // A positioned left owner without a complete 16-sample carrier
            // cannot authorize the normalized Square16 edge. Do not sample
            // it speculatively or turn a partial edge into a full one.
            return Err(PortableUnavailable);
        }
        let luma = reconstruct_lossy_full_16x16_luma(
            luma_predictor,
            luma_angle,
            filter_intra_mode,
            &luma_top,
            &full_luma_left,
            if has_luma_left { luma_top_left } else { None },
            true,
            has_luma_left,
            enable_intra_edge_filter,
            smooth_luma_edges,
            lossy_luma_16x16_coefficients,
            lossy_luma_16x16_transform,
        )?;
        let luma_for_chroma = luma.clone();
        let chroma = |plane: usize| -> PortableResult<ReconstructedPlane> {
            let top = if above_right_is_above_left {
                bottom_edge_16(&above_left.planes[plane])
            } else {
                let left = bottom_edge_16(&above_left.planes[plane]);
                let right = bottom_edge_16(&above_right.planes[plane]);
                std::array::from_fn(|index| {
                    if index < 8 {
                        left[index]
                    } else {
                        right[index - 8]
                    }
                })
            };
            let assembled_left = left_chroma_edges_16[plane - 1];
            let left = assembled_left.unwrap_or_else(|| {
                left_neighbor.map_or([top[0]; 16], |neighbor| {
                    right_edge_16(&neighbor.planes[plane])
                })
            });
            let has_left = assembled_left.is_some() || left_neighbor.is_some();
            match chroma_predictor {
                ChromaPredictor::Cfl { alpha_u, alpha_v } => {
                    let alpha = if plane == 1 { alpha_u } else { alpha_v };
                    reconstruct_lossy_full_16x16_cfl(
                        &luma_for_chroma,
                        if has_left {
                            dc_predictor_16(top, left)
                        } else {
                            one_sided_dc_predictor_16(top)
                        },
                        alpha,
                        lossy_chroma_16x16_coefficients[plane - 1],
                    )
                }
                _ => reconstruct_lossy_full_16x16_chroma(
                    chroma_predictor,
                    chroma_angle,
                    &top,
                    &left,
                    if has_left {
                        chroma_top_left[plane - 1]
                    } else {
                        None
                    },
                    true,
                    has_left,
                    enable_intra_edge_filter,
                    smooth_chroma_edges,
                    lossy_chroma_16x16_coefficients[plane - 1],
                ),
            }
        };
        return Ok(ClosedLeaf {
            luma_predictor,
            planes: [luma, chroma(1)?, chroma(2)?],
        });
    }

    let luma_mode = luma_predictor;
    let luma_predictor = match luma_mode {
        LumaPredictor::Vertical => luma_top[0],
        LumaPredictor::Horizontal if left_neighbor.is_some() => luma_left[0],
        LumaPredictor::Dc if left_neighbor.is_some() => dc_predictor_16(luma_top, luma_left),
        LumaPredictor::Dc => one_sided_dc_predictor_16(luma_top),
        _ => luma_mode.sample(),
    };
    let chroma_left =
        |plane: usize| left_chroma_edges_8[plane - 1].unwrap_or([chroma_top(plane)[0]; 8]);
    let predictors = [
        luma_predictor,
        if left_neighbor.is_some() {
            dc_predictor_8(chroma_top(1), chroma_left(1))
        } else {
            one_sided_dc_predictor(chroma_top(1))
        },
        if left_neighbor.is_some() {
            dc_predictor_8(chroma_top(2), chroma_left(2))
        } else {
            one_sided_dc_predictor(chroma_top(2))
        },
    ];

    reconstruct_leaf(syntax, predictors, palette_map_arena)
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 32x32 split reconstruction receives both full predictor edges and child syntax"
)]
fn reconstruct_lossy_luma_32x32_split(
    predictor: LumaPredictor,
    angle: Option<i32>,
    filter_intra_mode: Option<usize>,
    top: [u16; 32],
    left: [u16; 32],
    top_left: u16,
    has_top: bool,
    has_left: bool,
    split: LossyLuma16x16Split,
) -> PortableResult<ReconstructedPlane> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    let mut samples = vec![0_u16; 1024];
    for transform_index in 0_usize..4 {
        let row = transform_index / 2;
        let column = transform_index % 2;
        let offset_x = column.saturating_mul(16);
        let offset_y = row.saturating_mul(16);
        let top_edge: [u16; 16] = std::array::from_fn(|index| {
            if row == 0 {
                top[offset_x.saturating_add(index)]
            } else {
                samples[(offset_y - 1).saturating_mul(32) + offset_x + index]
            }
        });
        let top_extension: [u16; 32] = std::array::from_fn(|index| {
            if row == 0 {
                top[offset_x.saturating_add(index).min(31)]
            } else {
                samples[(offset_y - 1).saturating_mul(32) + (offset_x + index).min(31)]
            }
        });
        let left_edge: [u16; 16] = std::array::from_fn(|index| {
            if column == 0 {
                left[offset_y.saturating_add(index)]
            } else {
                samples[(offset_y + index).saturating_mul(32) + offset_x - 1]
            }
        });
        let block_top_left = match (row, column) {
            (0, 0) => top_left,
            (0, 1) => top[offset_x - 1],
            (1, 0) => left[offset_y - 1],
            _ => samples[(offset_y - 1).saturating_mul(32) + offset_x - 1],
        };
        let prediction = if let Some(mode) = filter_intra_mode {
            reconstruct_filter_intra_prediction(
                mode,
                16,
                16,
                block_top_left,
                &top_edge,
                &left_edge,
            )?
            .try_into()
            .map_err(|_| PortableUnavailable)?
        } else {
            let mut prediction = [0_u16; 256];
            match predictor {
                LumaPredictor::Dc => {
                    let value = match (has_top || row != 0, has_left || column != 0) {
                        (true, true) => dc_predictor_16(top_edge, left_edge),
                        (true, false) => one_sided_dc_predictor_16(top_edge),
                        (false, true) => one_sided_dc_predictor_16(left_edge),
                        (false, false) => 128,
                    };
                    prediction.fill(value);
                }
                LumaPredictor::Vertical => {
                    for (index, value) in prediction.iter_mut().enumerate() {
                        *value = top_edge[index % 16];
                    }
                }
                LumaPredictor::Horizontal => {
                    for (index, value) in prediction.iter_mut().enumerate() {
                        *value = left_edge[index / 16];
                    }
                }
                LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (0 < angle && angle < 90).then_some(()).portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(usize::try_from(angle / 2).map_err(|_| PortableUnavailable)?)
                        .filter(|&&value| value > 0)
                        .portable()?;
                    let upsample = 50 < angle;
                    let mut edge = [0_u16; 31];
                    let (max_base_x, dx, base_increment) = if upsample {
                        edge.copy_from_slice(&upsample_intra_top_edge_16(top_edge, block_top_left));
                        (30, dx.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&top_edge);
                        (15, dx, 1)
                    };
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] = diagonal_z1_predictor_sample(
                                &edge,
                                max_base_x,
                                dx,
                                base_increment,
                                x,
                                y,
                            )?;
                        }
                    }
                }
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (90 < angle && angle < 180).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(angle.saturating_sub(90) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let dx = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(180_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let mut edge = [0_u16; 65];
                    edge[32] = block_top_left;
                    for (index, value) in top_extension.into_iter().enumerate() {
                        edge[33 + index] = value;
                    }
                    for (index, value) in left_edge.into_iter().enumerate() {
                        edge[31 - index] = value;
                    }
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] =
                                diagonal_predictor_sample(&edge, 32, dx, dy, x, y)?;
                        }
                    }
                }
                LumaPredictor::Diagonal203 => {
                    let angle = angle.ok_or(PortableUnavailable)?;
                    (180 < angle && angle < 270).then_some(()).portable()?;
                    let dy = *DR_INTRA_DERIVATIVE
                        .get(
                            usize::try_from(270_i32.saturating_sub(angle) >> 1)
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .portable()?;
                    let upsample = angle < 220;
                    let mut edge = [0_u16; 31];
                    let (max_base_y, dy, base_increment) = if upsample {
                        edge.copy_from_slice(&upsample_intra_left_edge_16(
                            left_edge,
                            block_top_left,
                        ));
                        (30, dy.saturating_mul(2), 2)
                    } else {
                        edge[..16].copy_from_slice(&left_edge);
                        (15, dy, 1)
                    };
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] = diagonal_z3_predictor_sample(
                                &edge,
                                max_base_y,
                                dy,
                                base_increment,
                                x,
                                y,
                            )?;
                        }
                    }
                }
                LumaPredictor::Smooth => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    let bottom = i32::from(left_edge[15]);
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            let vertical = i32::from(weights[y]);
                            let horizontal = i32::from(weights[x]);
                            let value = vertical
                                .saturating_mul(i32::from(top_edge[x]))
                                .saturating_add((256 - vertical).saturating_mul(bottom))
                                .saturating_add(horizontal.saturating_mul(i32::from(left_edge[y])))
                                .saturating_add((256 - horizontal).saturating_mul(right))
                                .saturating_add(256)
                                >> 9;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::SmoothVertical => {
                    let weights = smooth_weight_table(16)?;
                    let bottom = i32::from(left_edge[15]);
                    for y in 0_usize..16 {
                        let weight = i32::from(weights[y]);
                        for x in 0_usize..16 {
                            let value = weight
                                .saturating_mul(i32::from(top_edge[x]))
                                .saturating_add((256 - weight).saturating_mul(bottom))
                                .saturating_add(128)
                                >> 8;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::SmoothHorizontal => {
                    let weights = smooth_weight_table(16)?;
                    let right = i32::from(top_extension[15]);
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            let weight = i32::from(weights[x]);
                            let value = weight
                                .saturating_mul(i32::from(left_edge[y]))
                                .saturating_add((256 - weight).saturating_mul(right))
                                .saturating_add(128)
                                >> 8;
                            #[expect(
                                clippy::cast_sign_loss,
                                reason = "the smooth predictor is explicitly clamped"
                            )]
                            {
                                prediction[y * 16 + x] = value.clamp(0, 255) as u16;
                            }
                        }
                    }
                }
                LumaPredictor::Paeth => {
                    for y in 0_usize..16 {
                        for x in 0_usize..16 {
                            prediction[y * 16 + x] =
                                paeth_predictor(top_edge[x], left_edge[y], block_top_left);
                        }
                    }
                }
            }
            prediction
        };
        let block = reconstruct_lossy_luma_16x16_from_prediction(
            prediction,
            split.coefficients[transform_index],
            split.transforms[transform_index],
        );
        for (row_offset, source) in block.samples.as_chunks::<16>().0.iter().enumerate() {
            let output_start = (offset_y + row_offset) * 32 + offset_x;
            samples[output_start..output_start + 16].copy_from_slice(source);
        }
    }
    Ok(ReconstructedPlane { samples })
}

fn reconstruct_following_lossy_420_vertical_32x32_leaf(
    syntax: BlockSyntax,
    palette_map_arena: &PaletteMapArena,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    left_neighbor: Option<&ClosedLeaf>,
    left_luma_edge: Option<[u16; 32]>,
) -> PortableResult<ClosedLeaf> {
    let luma_top = if std::ptr::eq(above_left, above_right) {
        bottom_edge_32(&above_left.planes[0])
    } else {
        let left = bottom_edge_16(&above_left.planes[0]);
        let right = bottom_edge_16(&above_right.planes[0]);
        std::array::from_fn(|index| {
            if index < 16 {
                left[index]
            } else {
                right[index - 16]
            }
        })
    };
    let luma_left = left_luma_edge.unwrap_or([luma_top[0]; 32]);
    let luma_top_left = left_neighbor
        .and_then(|neighbor| neighbor.planes[0].samples.last().copied())
        .unwrap_or(luma_top[0]);
    let luma = if let Some(split) = syntax.lossy_luma_16x16_split {
        reconstruct_lossy_luma_32x32_split(
            syntax.luma_predictor,
            syntax.luma_angle,
            syntax.filter_intra_mode,
            luma_top,
            luma_left,
            luma_top_left,
            true,
            left_neighbor.is_some(),
            split,
        )
        .unwrap_or_else(|_| ReconstructedPlane {
            samples: vec![syntax.luma_predictor.sample(); 1024],
        })
    } else {
        let prediction = match syntax.luma_predictor {
            LumaPredictor::Dc => {
                let predictor = if left_neighbor.is_some() {
                    rectangular_dc_predictor(&luma_top, &luma_left)
                } else {
                    one_sided_dc_predictor_32(luma_top)
                };
                [predictor; 1024]
            }
            LumaPredictor::Vertical => std::array::from_fn(|index| luma_top[index % 32]),
            LumaPredictor::Horizontal => std::array::from_fn(|index| luma_left[index / 32]),
            LumaPredictor::Paeth => std::array::from_fn(|index| {
                paeth_predictor(luma_top[index % 32], luma_left[index / 32], luma_top_left)
            }),
            predictor => [predictor.sample(); 1024],
        };
        reconstruct_lossy_32x32_from_prediction(prediction, syntax.lossy_luma_32x32_coefficients)
    };
    let chroma_top = |plane: usize| {
        if std::ptr::eq(above_left, above_right) {
            bottom_edge_32(&above_left.planes[plane])
        } else {
            let left = bottom_edge_16(&above_left.planes[plane]);
            let right = bottom_edge_16(&above_right.planes[plane]);
            std::array::from_fn(|index| {
                if index < 16 {
                    left[index]
                } else {
                    right[index - 16]
                }
            })
        }
    };
    let chroma_predictor = match syntax.chroma_predictor {
        ChromaPredictor::Dc => [
            one_sided_dc_predictor_32(chroma_top(1)),
            one_sided_dc_predictor_32(chroma_top(2)),
        ],
        _ => [128; 2],
    };
    let mut leaf = reconstruct_leaf(
        syntax,
        [
            syntax.luma_predictor.sample(),
            chroma_predictor[0],
            chroma_predictor[1],
        ],
        palette_map_arena,
    )?;
    leaf.planes[0] = luma;
    if matches!(syntax.chroma_sampling, ChromaSampling::Full) {
        for plane in 1..=2 {
            let predictor = if matches!(syntax.chroma_predictor, ChromaPredictor::Dc) {
                one_sided_dc_predictor_32(chroma_top(plane))
            } else {
                128
            };
            leaf.planes[plane] = reconstruct_lossy_chroma_32x32(
                predictor,
                syntax.lossy_chroma_32x32_coefficients[plane - 1],
            );
        }
    }
    Ok(leaf)
}

#[expect(
    clippy::too_many_arguments,
    reason = "the AV1 vertical leaf path receives each independently resolved neighbor edge and tool flag"
)]
fn reconstruct_following_lossy_420_vertical_leaf(
    syntax: BlockSyntax,
    above_left: &ClosedLeaf,
    above_right: &ClosedLeaf,
    above_left_width: u32,
    above_right_width: u32,
    above_left_x_offset: u32,
    above_right_x_offset: u32,
    above_right_is_above_left: bool,
    above_luma_extension: Option<[u16; 8]>,
    above_chroma_extension: Option<&ClosedLeaf>,
    above_chroma_extension_width: u32,
    above_chroma_extension_x_offset: u32,
    left_top_neighbor: Option<&ClosedLeaf>,
    left_luma_top_neighbor: Option<&ClosedLeaf>,
    left_neighbor: Option<&ClosedLeaf>,
    above_chroma_neighbor: Option<&ClosedLeaf>,
    above_chroma_width: u32,
    above_chroma_x_offset: u32,
    left_chroma_neighbor: Option<&ClosedLeaf>,
    left_chroma_width: u32,
    left_chroma_height: u32,
    left_chroma_y_offset: u32,
    left_luma_edge: Option<[u16; 8]>,
    left_luma_bottom: Option<[u16; 8]>,
    left_chroma_bottom: [Option<[u16; 4]>; 2],
    left_top_left_sample: Option<u16>,
    left_chroma_edges: [Option<[u16; 4]>; 2],
    enable_intra_edge_filter: bool,
) -> PortableResult<ClosedLeaf> {
    if matches!(syntax.transform_grid, TransformGrid::Square4) {
        return reconstruct_following_lossy_420_square4_leaf(
            syntax,
            above_left,
            above_right,
            left_top_neighbor,
            left_neighbor,
            above_chroma_neighbor,
            above_chroma_width,
            above_chroma_x_offset,
            left_chroma_neighbor,
            left_chroma_width,
            left_chroma_height,
            left_chroma_y_offset,
            true,
        );
    }
    let BlockSyntax {
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        chroma_predictor,
        chroma_angle,
        lossy_luma_coefficients,
        lossy_luma_transform,
        lossy_luma_4x4_split,
        lossy_chroma_coefficients,
        ..
    } = syntax;
    // AV1 converts PAETH to the predictor supported by the available edges
    // during reconstruction. The transform is still derived from the coded
    // chroma mode, so keep `chroma_predictor` unchanged for transform lookup.
    let chroma_reconstruction_predictor = match (
        chroma_predictor,
        left_chroma_neighbor.is_some(),
        above_chroma_neighbor.is_some(),
    ) {
        (ChromaPredictor::Paeth, false, true) => ChromaPredictor::Vertical,
        (ChromaPredictor::Paeth, true, false) => ChromaPredictor::Horizontal,
        (ChromaPredictor::Paeth, false, false) => ChromaPredictor::Dc,
        (predictor, _, _) => predictor,
    };
    let luma_top_left = combined_bottom_edge::<8>(
        &above_left.planes[0],
        above_left_width,
        above_left_x_offset,
        &above_right.planes[0],
        above_right_width,
        above_right_x_offset,
    );
    let use_luma_extension = matches!(
        luma_predictor,
        LumaPredictor::Vertical | LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67
    ) && luma_angle.is_some_and(|angle| 0 < angle && angle < 90);
    let luma_top_right = if use_luma_extension {
        above_luma_extension.unwrap_or_else(|| {
            if above_right_x_offset.saturating_add(8) > above_right_width {
                luma_top_left
            } else {
                bottom_edge_at::<8>(
                    &above_right.planes[0],
                    above_right_width,
                    above_right_x_offset,
                )
            }
        })
    } else if above_right_x_offset.saturating_add(8) > above_right_width {
        luma_top_left
    } else {
        bottom_edge_at::<8>(
            &above_right.planes[0],
            above_right_width,
            above_right_x_offset,
        )
    };
    let luma_top_left_sample = left_top_left_sample
        .or_else(|| {
            left_top_neighbor.and_then(|neighbor| neighbor.planes[0].samples.last().copied())
        })
        .unwrap_or_else(|| {
            above_left_x_offset.checked_sub(1).map_or_else(
                || above_left.planes[0].samples.last().copied().unwrap_or(128),
                |offset| bottom_sample_at(&above_left.planes[0], above_left_width, offset),
            )
        });

    let mut luma_top = [0_u16; 16];
    luma_top[..8].copy_from_slice(&luma_top_left);
    if luma_top_right == luma_top_left {
        luma_top[8..].fill(luma_top_left[7]);
    } else {
        luma_top[8..].copy_from_slice(&luma_top_right);
    }

    let luma_left = left_luma_edge.unwrap_or([luma_top[0]; 8]);

    let filter_intra_top_left = if left_neighbor.is_some() {
        luma_top_left_sample
    } else {
        luma_top[0]
    };

    // With no left neighbor, dav1d's prepared edge uses the first top sample
    // as the effective top-left for angular prediction.
    let luma_top_left_for_prediction = filter_intra_top_left;
    let smooth_edges = |predictor: LumaPredictor| {
        matches!(
            predictor,
            LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
        )
    };
    let smooth_neighbor_edges = smooth_edges(above_left.luma_predictor)
        || left_luma_top_neighbor.is_some_and(|neighbor| smooth_edges(neighbor.luma_predictor));
    let unupsampled_diagonal67 = above_right_is_above_left
        && above_luma_extension.is_none()
        && above_left_width == 8
        && above_right_width == 8
        && above_left_x_offset == 0
        && above_right_x_offset == 0
        && left_neighbor.is_none()
        && left_top_neighbor.is_none()
        && left_luma_top_neighbor.is_none()
        && left_luma_edge.is_none()
        && luma_angle == Some(67)
        && matches!(lossy_luma_transform, LossyTransformKind::DctDct);
    let unupsampled_diagonal67_split_angle70 = lossy_luma_4x4_split.is_some()
        && matches!(luma_predictor, LumaPredictor::Diagonal67)
        && above_right_is_above_left
        && above_luma_extension.is_none()
        && above_left_width == 8
        && above_right_width == 8
        && above_left_x_offset == 0
        && above_right_x_offset == 0
        && left_neighbor.is_none()
        && left_top_neighbor.is_none()
        && left_luma_top_neighbor.is_none()
        && left_luma_edge.is_none()
        && luma_angle == Some(70)
        && matches!(lossy_luma_transform, LossyTransformKind::DctDct);
    let disable_luma_edge_filter = unupsampled_diagonal67 || unupsampled_diagonal67_split_angle70;

    let luma = if let Some(split) = lossy_luma_4x4_split {
        match (filter_intra_mode, luma_predictor) {
            (None, LumaPredictor::Dc) => Ok(reconstruct_lossy_luma_8x8_split_dc_vertical(
                luma_top_left,
                left_luma_edge,
                split,
            )),
            (None, LumaPredictor::Smooth) => Ok(reconstruct_lossy_luma_8x8_split_smooth_vertical(
                luma_top_left,
                left_luma_edge,
                split,
            )),
            (None, LumaPredictor::SmoothVertical) => {
                Ok(reconstruct_lossy_luma_8x8_split_smooth_vertical_only(
                    luma_top_left,
                    left_luma_edge,
                    split,
                ))
            }
            (None, LumaPredictor::SmoothHorizontal) => {
                Ok(reconstruct_lossy_luma_8x8_split_smooth_horizontal_vertical(
                    luma_top_left,
                    left_luma_edge,
                    split,
                ))
            }
            (None, LumaPredictor::Diagonal45 | LumaPredictor::Diagonal67) => {
                reconstruct_lossy_luma_8x8_split_diagonal_z1_extended(
                    luma_top,
                    left_luma_edge,
                    Some(luma_top_left_for_prediction),
                    luma_angle.ok_or(PortableUnavailable)?,
                    !disable_luma_edge_filter,
                    smooth_neighbor_edges,
                    split,
                )
            }
            (None, LumaPredictor::Vertical) => match luma_angle {
                None | Some(90) => Ok(reconstruct_lossy_luma_8x8_split_vertical(
                    luma_top_left,
                    split,
                )),
                Some(angle) if 0 < angle && angle < 90 => {
                    reconstruct_lossy_luma_8x8_split_diagonal_z1_extended(
                        luma_top,
                        left_luma_edge,
                        Some(luma_top_left_for_prediction),
                        angle,
                        true,
                        smooth_neighbor_edges,
                        split,
                    )
                }
                Some(angle) if 90 < angle && angle < 180 => {
                    reconstruct_lossy_luma_8x8_split_diagonal_vertical(
                        luma_top_left,
                        left_luma_edge,
                        Some(luma_top_left_for_prediction),
                        angle,
                        true,
                        smooth_neighbor_edges,
                        split,
                    )
                }
                _ => Err(PortableUnavailable),
            },
            (None, LumaPredictor::Horizontal) => match luma_angle {
                None | Some(180) => Ok(reconstruct_lossy_luma_8x8_split_horizontal_vertical(
                    luma_top_left,
                    left_luma_edge,
                    split,
                )),
                Some(angle) if 90 < angle && angle < 180 => {
                    reconstruct_lossy_luma_8x8_split_diagonal_vertical(
                        luma_top_left,
                        left_luma_edge,
                        Some(luma_top_left_for_prediction),
                        angle,
                        true,
                        smooth_neighbor_edges,
                        split,
                    )
                }
                Some(angle) if 180 < angle && angle < 270 => {
                    reconstruct_lossy_luma_8x8_split_diagonal_z3(
                        luma_left,
                        luma_top_left,
                        luma_top_left_sample,
                        left_luma_bottom,
                        angle,
                        enable_intra_edge_filter,
                        split,
                    )
                }
                _ => Err(PortableUnavailable),
            },
            (None, LumaPredictor::Paeth) => Ok(reconstruct_lossy_luma_8x8_split_paeth(
                luma_top_left,
                left_luma_edge,
                filter_intra_top_left,
                split,
            )),
            (Some(mode), _) => {
                let left = left_neighbor.map_or([luma_top_left[0]; 8], |_| {
                    left_luma_edge.unwrap_or([luma_top_left[0]; 8])
                });
                reconstruct_lossy_luma_8x8_split_filter_intra(
                    luma_top_left,
                    left,
                    filter_intra_top_left,
                    split,
                    mode,
                )
            }
            (
                None,
                LumaPredictor::DiagonalDownRight
                | LumaPredictor::Diagonal113
                | LumaPredictor::Diagonal157,
            ) => reconstruct_lossy_luma_8x8_split_diagonal_vertical(
                luma_top_left,
                left_luma_edge,
                Some(luma_top_left_for_prediction),
                luma_angle.ok_or(PortableUnavailable)?,
                true,
                smooth_neighbor_edges,
                split,
            ),
            (None, LumaPredictor::Diagonal203) => reconstruct_lossy_luma_8x8_split_diagonal_z3(
                luma_left,
                luma_top_left,
                luma_top_left_sample,
                left_luma_bottom,
                luma_angle.ok_or(PortableUnavailable)?,
                enable_intra_edge_filter,
                split,
            ),
        }?
    } else {
        if let Some(mode) = filter_intra_mode {
            let prediction = reconstruct_filter_intra_prediction(
                mode,
                8,
                8,
                filter_intra_top_left,
                &luma_top_left,
                &luma_left,
            )?;
            let prediction = prediction.try_into().map_err(|_| PortableUnavailable)?;
            reconstruct_lossy_luma_8x8_from_prediction(
                prediction,
                lossy_luma_coefficients,
                lossy_luma_transform,
            )
        } else {
            match (luma_predictor, luma_angle) {
                (LumaPredictor::Dc, _) => reconstruct_lossy_luma_8x8(
                    if left_neighbor.is_some() {
                        dc_predictor_8(luma_top_left, luma_left)
                    } else {
                        one_sided_dc_predictor(luma_top_left)
                    },
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                (LumaPredictor::Vertical, None | Some(90)) => reconstruct_lossy_luma_8x8_vertical(
                    luma_top_left,
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                (LumaPredictor::Vertical, Some(angle)) if 0 < angle && angle < 90 => {
                    reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                        luma_top,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Vertical, Some(angle)) if 90 < angle && angle < 180 => {
                    reconstruct_lossy_luma_8x8_diagonal(
                        luma_top,
                        luma_left,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Horizontal, None | Some(180)) => {
                    reconstruct_lossy_luma_8x8_horizontal(
                        luma_left,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )
                }
                (LumaPredictor::Horizontal, Some(angle)) if 180 < angle && angle < 270 => {
                    reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
                        luma_left,
                        luma_top_left_for_prediction,
                        left_luma_bottom,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Horizontal, Some(angle)) if 90 < angle && angle < 180 => {
                    reconstruct_lossy_luma_8x8_diagonal(
                        luma_top,
                        luma_left,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Diagonal45, Some(angle)) => {
                    reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                        luma_top,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Diagonal67, Some(angle @ 67)) if unupsampled_diagonal67 => {
                    reconstruct_lossy_luma_8x8_diagonal_z1_without_upsampling(
                        luma_top_left,
                        luma_top_left_for_prediction,
                        angle,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Diagonal67, Some(angle)) => {
                    reconstruct_lossy_luma_8x8_diagonal_z1_extended(
                        luma_top,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::DiagonalDownRight | LumaPredictor::Diagonal113, Some(angle))
                    if (90..180).contains(&angle) =>
                {
                    reconstruct_lossy_luma_8x8_diagonal(
                        luma_top,
                        luma_left,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Diagonal157, Some(angle)) if (90..180).contains(&angle) => {
                    reconstruct_lossy_luma_8x8_diagonal(
                        luma_top,
                        luma_left,
                        luma_top_left_for_prediction,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Diagonal203, Some(angle)) => {
                    reconstruct_lossy_luma_8x8_diagonal_z3_with_bottom_left(
                        luma_left,
                        luma_top_left_for_prediction,
                        left_luma_bottom,
                        angle,
                        enable_intra_edge_filter,
                        smooth_neighbor_edges,
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )?
                }
                (LumaPredictor::Smooth, None) => reconstruct_lossy_luma_8x8_smooth(
                    luma_top_left,
                    luma_top_left[7],
                    luma_left,
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                (LumaPredictor::Smooth, Some(_)) => reconstruct_lossy_luma_8x8_smooth(
                    luma_top_right,
                    luma_top_right[7],
                    luma_left,
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                (LumaPredictor::SmoothVertical, _) => reconstruct_lossy_luma_8x8_smooth_vertical(
                    luma_top_left,
                    luma_left[7],
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                (LumaPredictor::SmoothHorizontal, _) => {
                    reconstruct_lossy_luma_8x8_smooth_horizontal(
                        luma_left,
                        luma_top_left[7],
                        lossy_luma_coefficients,
                        lossy_luma_transform,
                    )
                }
                (LumaPredictor::Paeth, _) => reconstruct_lossy_luma_8x8_paeth(
                    luma_top_left,
                    luma_left,
                    filter_intra_top_left,
                    lossy_luma_coefficients,
                    lossy_luma_transform,
                ),
                _ => return Err(PortableUnavailable),
            }
        }
    };

    let chroma_top_left = above_chroma_neighbor.map_or_else(
        || {
            combined_bottom_edge::<4>(
                &above_left.planes[1],
                above_left_width.div_ceil(2).max(4),
                above_left_x_offset / 2,
                &above_right.planes[1],
                above_right_width.div_ceil(2).max(4),
                above_right_x_offset / 2,
            )
        },
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[1],
                above_chroma_width.div_ceil(2).max(4),
                above_chroma_x_offset,
            )
        },
    );
    let chroma_top_right_available = above_chroma_extension.is_some();
    let chroma_top_right = above_chroma_extension.map_or_else(
        || {
            if chroma_top_right_available {
                bottom_edge_at::<4>(
                    &above_right.planes[1],
                    above_right_width.div_ceil(2).max(4),
                    above_right_x_offset / 2,
                )
            } else {
                [chroma_top_left[3]; 4]
            }
        },
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[1],
                above_chroma_extension_width.div_ceil(2).max(4),
                above_chroma_extension_x_offset,
            )
        },
    );
    // A split 8×8 luma leaf leaves the final four luma edge samples in the
    // shared AV1 intra-edge scratch region. At a tile boundary the following
    // 4×4 chroma Zone-2 predictor consumes that bounded continuation rather
    // than repeating the last chroma-top sample.
    let chroma_top_z2_right = if lossy_luma_4x4_split.is_some() && !chroma_top_right_available {
        left_top_neighbor.map_or(chroma_top_right, |neighbor| {
            if neighbor.planes[0].samples.len() >= 64 {
                bottom_edge_at::<4>(&neighbor.planes[0], 8, 4)
            } else {
                bottom_edge_4(&neighbor.planes[0])
            }
        })
    } else {
        chroma_top_right
    };
    let chroma_top_z2 = [
        chroma_top_left[0],
        chroma_top_left[1],
        chroma_top_left[2],
        chroma_top_left[3],
        chroma_top_z2_right[0],
        chroma_top_z2_right[1],
        chroma_top_z2_right[2],
        chroma_top_z2_right[3],
    ];
    let chroma_top_z1 = [
        chroma_top_left[0],
        chroma_top_left[1],
        chroma_top_left[2],
        chroma_top_left[3],
        chroma_top_right[0],
        chroma_top_right[1],
        chroma_top_right[2],
        chroma_top_right[3],
    ];
    let chroma_left_u = left_chroma_edges[0].unwrap_or([chroma_top_left[0]; 4]);
    let chroma_top_left_u = match (above_chroma_neighbor, left_chroma_neighbor) {
        (None, None) => 128,
        (None, Some(_)) => chroma_left_u[0],
        (Some(_), None) => chroma_top_left[0],
        (Some(above), Some(left)) => {
            if left_chroma_y_offset > 0 {
                right_edge_at::<1>(
                    &left.planes[1],
                    left_chroma_width.div_ceil(2).max(4),
                    left_chroma_height.div_ceil(2).max(4),
                    left_chroma_y_offset.saturating_sub(1),
                )[0]
            } else if above_chroma_x_offset > 0 {
                bottom_edge_at::<1>(
                    &above.planes[1],
                    above_chroma_width.div_ceil(2).max(4),
                    above_chroma_x_offset.saturating_sub(1),
                )[0]
            } else {
                left_top_neighbor.map_or(128, |neighbor| {
                    bottom_right_for_square4(&neighbor.planes[1])
                })
            }
        }
    };
    let chroma_dc_u = left_chroma_edges[0].map_or_else(
        || one_sided_dc_predictor_4(chroma_top_left),
        |left| dc_predictor(chroma_top_left, left),
    );

    let chroma_u = match chroma_reconstruction_predictor {
        ChromaPredictor::Cfl { alpha_u, .. } => reconstruct_lossy_chroma_4x4_cfl(
            &luma,
            chroma_dc_u,
            alpha_u,
            lossy_chroma_coefficients[0],
        )?,
        ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
            chroma_dc_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Vertical => match chroma_angle {
            None | Some(90) => Ok(reconstruct_lossy_chroma_4x4_vertical(
                chroma_top_left,
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            )),
            Some(angle) if 0 < angle && angle < 90 => reconstruct_lossy_4x4_diagonal_z1_extended(
                chroma_top_z1,
                chroma_top_left_u,
                angle,
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            ),
            Some(angle) if 90 < angle && angle < 180 => {
                reconstruct_lossy_chroma_4x4_diagonal_with_filter(
                    chroma_top_z2,
                    chroma_left_u,
                    chroma_top_left_u,
                    angle,
                    lossy_chroma_coefficients[0],
                    chroma_transform_kind(chroma_predictor),
                    enable_intra_edge_filter,
                )
            }
            _ => Err(PortableUnavailable),
        }?,
        ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
            chroma_left_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            chroma_top_z2,
            chroma_left_u,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[0],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3_with_bottom_left(
            chroma_left_u,
            left_chroma_bottom[0],
            chroma_top_left_u,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[0],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1_with_edge(
                chroma_top_z1,
                chroma_top_left_u,
                chroma_angle.ok_or(PortableUnavailable)?,
                enable_intra_edge_filter,
                smooth_neighbor_edges,
                lossy_chroma_coefficients[0],
                chroma_transform_kind(chroma_predictor),
            )?
        }
        ChromaPredictor::Smooth => reconstruct_lossy_chroma_4x4_smooth(
            chroma_top_left,
            chroma_top_left[3],
            chroma_left_u,
            lossy_chroma_coefficients[0],
        ),
        ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            chroma_top_left,
            chroma_left_u[3],
            lossy_chroma_coefficients[0],
            LossyTransformKind::AdstDct,
        ),
        ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            chroma_left_u,
            chroma_top_right[3],
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            chroma_top_left,
            chroma_left_u,
            chroma_top_left_u,
            lossy_chroma_coefficients[0],
            LossyTransformKind::DctDct,
        ),
    };

    let chroma_top_left_v_edge = above_chroma_neighbor.map_or_else(
        || bottom_edge_4(&above_left.planes[2]),
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[2],
                above_chroma_width.div_ceil(2).max(4),
                above_chroma_x_offset,
            )
        },
    );
    let chroma_top_right_v = above_chroma_extension.map_or_else(
        || {
            if chroma_top_right_available {
                bottom_edge_at::<4>(
                    &above_right.planes[2],
                    above_right_width.div_ceil(2).max(4),
                    above_right_x_offset / 2,
                )
            } else {
                [chroma_top_left_v_edge[3]; 4]
            }
        },
        |neighbor| {
            bottom_edge_at::<4>(
                &neighbor.planes[2],
                above_chroma_extension_width.div_ceil(2).max(4),
                above_chroma_extension_x_offset,
            )
        },
    );
    let chroma_top_z1_v = [
        chroma_top_left_v_edge[0],
        chroma_top_left_v_edge[1],
        chroma_top_left_v_edge[2],
        chroma_top_left_v_edge[3],
        chroma_top_right_v[0],
        chroma_top_right_v[1],
        chroma_top_right_v[2],
        chroma_top_right_v[3],
    ];
    let chroma_top_z2_right_v = if lossy_luma_4x4_split.is_some() && !chroma_top_right_available {
        left_top_neighbor.map_or(chroma_top_right_v, |neighbor| {
            if neighbor.planes[0].samples.len() >= 64 {
                bottom_edge_at::<4>(&neighbor.planes[0], 8, 4)
            } else {
                bottom_edge_4(&neighbor.planes[0])
            }
        })
    } else {
        chroma_top_right_v
    };
    let chroma_top_z2_v = [
        chroma_top_left_v_edge[0],
        chroma_top_left_v_edge[1],
        chroma_top_left_v_edge[2],
        chroma_top_left_v_edge[3],
        chroma_top_z2_right_v[0],
        chroma_top_z2_right_v[1],
        chroma_top_z2_right_v[2],
        chroma_top_z2_right_v[3],
    ];
    let chroma_left_v = left_chroma_edges[1].unwrap_or([chroma_top_left_v_edge[0]; 4]);
    let chroma_top_left_v = match (above_chroma_neighbor, left_chroma_neighbor) {
        (None, None) => 128,
        (None, Some(_)) => chroma_left_v[0],
        (Some(_), None) => chroma_top_left_v_edge[0],
        (Some(above), Some(left)) => {
            if left_chroma_y_offset > 0 {
                right_edge_at::<1>(
                    &left.planes[2],
                    left_chroma_width.div_ceil(2).max(4),
                    left_chroma_height.div_ceil(2).max(4),
                    left_chroma_y_offset.saturating_sub(1),
                )[0]
            } else if above_chroma_x_offset > 0 {
                bottom_edge_at::<1>(
                    &above.planes[2],
                    above_chroma_width.div_ceil(2).max(4),
                    above_chroma_x_offset.saturating_sub(1),
                )[0]
            } else {
                left_top_neighbor.map_or(128, |neighbor| {
                    bottom_right_for_square4(&neighbor.planes[2])
                })
            }
        }
    };
    let chroma_dc_v = left_chroma_edges[1].map_or_else(
        || one_sided_dc_predictor_4(chroma_top_left_v_edge),
        |left| dc_predictor(chroma_top_left_v_edge, left),
    );
    let chroma_v = match chroma_reconstruction_predictor {
        ChromaPredictor::Cfl { alpha_v, .. } => reconstruct_lossy_chroma_4x4_cfl(
            &luma,
            chroma_dc_v,
            alpha_v,
            lossy_chroma_coefficients[1],
        )?,
        ChromaPredictor::Dc => reconstruct_lossy_chroma_4x4(
            chroma_dc_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        ),
        ChromaPredictor::Vertical => match chroma_angle {
            None | Some(90) => Ok(reconstruct_lossy_chroma_4x4_vertical(
                chroma_top_left_v_edge,
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            )),
            Some(angle) if 0 < angle && angle < 90 => reconstruct_lossy_4x4_diagonal_z1_extended(
                chroma_top_z1_v,
                chroma_top_left_v,
                angle,
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            ),
            Some(angle) if 90 < angle && angle < 180 => {
                reconstruct_lossy_chroma_4x4_diagonal_with_filter(
                    chroma_top_z2_v,
                    chroma_left_v,
                    chroma_top_left_v,
                    angle,
                    lossy_chroma_coefficients[1],
                    chroma_transform_kind(chroma_predictor),
                    enable_intra_edge_filter,
                )
            }
            _ => Err(PortableUnavailable),
        }?,
        ChromaPredictor::Horizontal => reconstruct_lossy_chroma_4x4_horizontal(
            chroma_left_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::DiagonalDownRight
        | ChromaPredictor::Diagonal113
        | ChromaPredictor::Diagonal157 => reconstruct_lossy_chroma_4x4_diagonal(
            chroma_top_z2_v,
            chroma_left_v,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[1],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Diagonal203 => reconstruct_lossy_chroma_4x4_diagonal_z3_with_bottom_left(
            chroma_left_v,
            left_chroma_bottom[1],
            chroma_top_left_v,
            chroma_angle.ok_or(PortableUnavailable)?,
            lossy_chroma_coefficients[1],
            chroma_transform_kind(chroma_predictor),
        )?,
        ChromaPredictor::Diagonal45 | ChromaPredictor::Diagonal67 => {
            reconstruct_lossy_4x4_diagonal_z1_with_edge(
                chroma_top_z1_v,
                chroma_top_left_v,
                chroma_angle.ok_or(PortableUnavailable)?,
                enable_intra_edge_filter,
                smooth_neighbor_edges,
                lossy_chroma_coefficients[1],
                chroma_transform_kind(chroma_predictor),
            )?
        }
        ChromaPredictor::Smooth => reconstruct_lossy_chroma_4x4_smooth(
            chroma_top_left_v_edge,
            chroma_top_left_v_edge[3],
            chroma_left_v,
            lossy_chroma_coefficients[1],
        ),
        ChromaPredictor::SmoothVertical => reconstruct_lossy_4x4_smooth_vertical(
            chroma_top_left_v_edge,
            chroma_left_v[3],
            lossy_chroma_coefficients[1],
            LossyTransformKind::AdstDct,
        ),
        ChromaPredictor::SmoothHorizontal => reconstruct_lossy_4x4_smooth_horizontal(
            chroma_left_v,
            chroma_top_right_v[3],
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctAdst,
        ),
        ChromaPredictor::Paeth => reconstruct_lossy_4x4_paeth(
            chroma_top_left_v_edge,
            chroma_left_v,
            chroma_top_left_v,
            lossy_chroma_coefficients[1],
            LossyTransformKind::DctDct,
        ),
    };

    Ok(ClosedLeaf {
        luma_predictor,
        planes: [luma, chroma_u, chroma_v],
    })
}

fn reconstruct_boundary_leaf(
    syntax: BlockSyntax,
    above: &ClosedLeaf,
    left: &ClosedLeaf,
    palette_map_arena: &PaletteMapArena,
) -> PortableResult<ClosedLeaf> {
    let has_y_palette = syntax.palette.y.is_present();
    let has_uv_palette = syntax.palette.u.is_present() && syntax.palette.v.is_present();
    if syntax.palette.is_present() && !(has_y_palette && has_uv_palette) {
        // This legacy boundary owns only one scalar predictor per non-palette
        // plane. Exact partial-plane reconstruction is performed by the
        // persistent edge-aware walker; never flatten it here.
        return Err(PortableUnavailable);
    }
    if syntax.palette.y.is_present()
        && matches!(syntax.chroma_predictor, ChromaPredictor::Cfl { .. })
    {
        return Err(PortableUnavailable);
    }
    let uv_map = if syntax.palette.u.is_present() || syntax.palette.v.is_present() {
        Some(syntax.palette.uv_view(palette_map_arena)?)
    } else {
        None
    };
    let plane = |index: usize, palette: PalettePlane| -> PortableResult<ReconstructedPlane> {
        if palette.is_present() {
            let map = if index == 0 {
                syntax.palette.y_view(palette_map_arena)?
            } else {
                uv_map.ok_or(PortableUnavailable)?
            };
            reconstruct_lossless_palette_plane(syntax, index, palette, map)
        } else {
            Ok(reconstruct_boundary_plane(
                &above.planes[index],
                &left.planes[index],
                syntax.coefficients[index],
            ))
        }
    };
    let planes = [
        plane(0, syntax.palette.y)?,
        plane(1, syntax.palette.u)?,
        plane(2, syntax.palette.v)?,
    ];
    Ok(ClosedLeaf {
        luma_predictor: syntax.luma_predictor,
        planes,
    })
}

fn reconstruct_boundary_420_leaf(
    syntax: BlockSyntax,
    above: &ClosedLeaf,
    left: &ClosedLeaf,
    palette_map_arena: &PaletteMapArena,
) -> PortableResult<ClosedLeaf> {
    let has_y_palette = syntax.palette.y.is_present();
    let has_uv_palette = syntax.palette.u.is_present() && syntax.palette.v.is_present();
    if has_y_palette
        && !has_uv_palette
        && matches!(syntax.chroma_predictor, ChromaPredictor::Cfl { .. })
    {
        return reconstruct_lossless_palette_leaf(
            syntax,
            [
                dc_predictor_8(bottom_edge(&above.planes[0]), right_edge(&left.planes[0])),
                dc_predictor(
                    bottom_edge_4(&above.planes[1]),
                    right_edge_4(&left.planes[1]),
                ),
                dc_predictor(
                    bottom_edge_4(&above.planes[2]),
                    right_edge_4(&left.planes[2]),
                ),
            ],
            None,
            palette_map_arena,
        );
    }
    if syntax.palette.is_present() && !(has_y_palette && has_uv_palette) {
        return Err(PortableUnavailable);
    }
    let uv_map = if syntax.palette.u.is_present() || syntax.palette.v.is_present() {
        Some(syntax.palette.uv_view(palette_map_arena)?)
    } else {
        None
    };
    let luma = if syntax.palette.y.is_present() {
        reconstruct_lossless_palette_plane(
            syntax,
            0,
            syntax.palette.y,
            syntax.palette.y_view(palette_map_arena)?,
        )?
    } else {
        reconstruct_boundary_plane(&above.planes[0], &left.planes[0], syntax.coefficients[0])
    };
    let chroma = |index: usize, palette: PalettePlane| -> PortableResult<ReconstructedPlane> {
        if palette.is_present() {
            reconstruct_lossless_palette_plane(
                syntax,
                index,
                palette,
                uv_map.ok_or(PortableUnavailable)?,
            )
        } else {
            Ok(reconstruct_subsampled_boundary_plane(
                &above.planes[index],
                &left.planes[index],
                syntax.coefficients[index],
            ))
        }
    };
    let planes = [
        luma,
        chroma(1, syntax.palette.u)?,
        chroma(2, syntax.palette.v)?,
    ];
    Ok(ClosedLeaf {
        luma_predictor: syntax.luma_predictor,
        planes,
    })
}

fn decode_following_square_syntax<F>(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    cdfs: &mut BlockCdfs,
    palette_map_arena: &mut PaletteMapArena,
    context: FollowingSyntaxContext,
    between_leaves: &mut F,
) -> PortableResult<BlockSyntax>
where
    F: FnMut(&mut RangeDecoder<'_, '_, '_>) -> PortableResult<()>,
{
    let FollowingSyntaxContext {
        transform_grid,
        chroma_sampling,
        palette_entropy_dimensions,
        spatial_luma_context,
        coefficient_policy,
        tools,
    } = context;
    between_leaves(decoder)?;
    palette_map_arena.begin_leaf()?;
    decode_syntax_with_palette_entropy(
        decoder,
        cdfs,
        palette_map_arena,
        transform_grid,
        chroma_sampling,
        SyntaxPolicy {
            spatial_luma_context,
            coefficient_policy,
            quantization_syntax: QuantizationSyntax::Lossless,
            allow_horizontal_chroma: false,
            allow_diagonal_chroma: false,
            allow_diagonal_luma: false,
            allow_smooth_chroma: false,
            allow_smooth_luma: false,
        },
        tools,
        Some(palette_entropy_dimensions),
    )
}

#[expect(
    clippy::too_many_arguments,
    reason = "the visible leaf carries the decoded block, geometry, transform context, and edge context together"
)]
fn visible_leaf(
    leaf: ClosedLeaf,
    block_skipped: bool,
    chroma_predictor: Option<ChromaPredictor>,
    transform_grid: TransformGrid,
    width: u32,
    height: u32,
    chroma_sampling: ChromaSampling,
    tx_context: (u8, u8),
    luma_transform_split: bool,
    luma_edge_contexts: ([u8; 16], [u8; 16]),
) -> FirstLeaf {
    let (transform_grid_width, _, _) = transform_grid.properties();
    let coded_width = transform_grid_width.saturating_mul(4);
    let (chroma_coded_width, chroma_width, chroma_height) = match chroma_sampling {
        ChromaSampling::Subsampled420 => (
            transform_grid_width.div_ceil(2).saturating_mul(4),
            width.div_ceil(2).max(4),
            height.div_ceil(2).max(4),
        ),
        ChromaSampling::Subsampled422 => (
            transform_grid_width.div_ceil(2).saturating_mul(4),
            width.div_ceil(2).max(4),
            height.max(4),
        ),
        ChromaSampling::Full | ChromaSampling::Monochrome => (coded_width, width, height),
    };
    let planes = [
        visible_plane(&leaf.planes[0], coded_width, width, height),
        visible_plane(
            &leaf.planes[1],
            chroma_coded_width,
            chroma_width,
            chroma_height,
        ),
        visible_plane(
            &leaf.planes[2],
            chroma_coded_width,
            chroma_width,
            chroma_height,
        ),
    ];
    FirstLeaf {
        width,
        height,
        block_skipped,
        planes,
        luma_predictor: leaf.luma_predictor,
        chroma_predictor,
        luma_context: 0x40,
        chroma_contexts: [0x40; 2],
        chroma_right_contexts: [[0x40; 16]; 2],
        chroma_bottom_contexts: [[0x40; 16]; 2],
        tx_context_width: tx_context.0,
        tx_context_height: tx_context.1,
        luma_transform_split,
        luma_right_contexts: luma_edge_contexts.0,
        luma_bottom_contexts: luma_edge_contexts.1,
        wide_coefficient_contexts: None,
        palette_cache: PaletteCacheState::default(),
        #[cfg(coverage)]
        entropy_operations: Vec::new(),
    }
}

fn with_palette_cache(mut leaf: FirstLeaf, palette_cache: PaletteCacheState) -> FirstLeaf {
    leaf.palette_cache = palette_cache;
    leaf
}

fn luma_edge_contexts_for_syntax(syntax: &BlockSyntax) -> ([u8; 16], [u8; 16]) {
    let fallback = lossy_luma_context(syntax);
    let mut right = [fallback; 16];
    let mut bottom = [fallback; 16];
    if let Some(split) = syntax.lossy_luma_8x4_split.as_ref() {
        right[..4].fill(split.right_context);
        bottom[..2].fill(split.bottom_contexts[0]);
        bottom[2..4].fill(split.bottom_contexts[1]);
    } else if let Some(split) = syntax.lossy_luma_8x8_grid_split.as_ref() {
        match split.orientation {
            SplitOrientation::Vertical => {
                for (index, context) in split.right_contexts.into_iter().enumerate() {
                    right[index * 2..index * 2 + 2].fill(context);
                }
                for (index, context) in split.bottom_contexts.into_iter().take(2).enumerate() {
                    bottom[index * 2..index * 2 + 2].fill(context);
                }
            }
            SplitOrientation::Horizontal => {
                for (index, context) in split.right_contexts.into_iter().take(2).enumerate() {
                    right[index * 2..index * 2 + 2].fill(context);
                }
                for (index, context) in split.bottom_contexts.into_iter().enumerate() {
                    bottom[index * 2..index * 2 + 2].fill(context);
                }
            }
        }
    } else if let Some(split) = syntax.lossy_luma_16x16_vertical_split.as_ref() {
        // Each TX16x16 child contributes four 4x4 segments to the right
        // boundary. Preserve every active child for the 16x32 and 16x64
        // variants; the bottom edge shares the final child's context.
        for (index, context) in split
            .right_contexts
            .into_iter()
            .take(split.child_count)
            .enumerate()
        {
            right[index * 4..index * 4 + 4].fill(context);
        }
        bottom[..4].fill(split.bottom_context);
    } else if let Some(split) = syntax.lossy_luma_16x16_horizontal_split.as_ref() {
        right[..4].fill(split.right_context);
        for (index, context) in split.bottom_contexts.into_iter().enumerate() {
            bottom[index * 4..index * 4 + 4].fill(context);
        }
    } else if let Some(split) = syntax.lossy_luma_32x16_horizontal_split.as_ref() {
        // The right edge is four 4×4 segments high. The bottom edge spans all
        // sixteen 4×4 segments: each R32x16 child contributes eight slots.
        right[..4].fill(split.right_contexts[1]);
        bottom[..8].fill(split.bottom_contexts[0]);
        bottom[8..].fill(split.bottom_contexts[1]);
    } else if let Some(split) = syntax.lossy_luma_64x64_split.as_ref() {
        // The S64x64 depth-one tree has two TX32x32 children on each edge.
        // Each child context covers eight 4x4 edge segments.
        right[..8].fill(split.right_contexts[0]);
        right[8..16].fill(split.right_contexts[1]);
        bottom[..8].fill(split.bottom_contexts[0]);
        bottom[8..16].fill(split.bottom_contexts[1]);
    } else if let Some(split) = syntax.lossy_luma_16x16_split.as_ref() {
        for (index, context) in split.right_contexts.into_iter().enumerate() {
            right[index * 4..index * 4 + 4].fill(context);
        }
        for (index, context) in split.bottom_contexts.into_iter().enumerate() {
            bottom[index * 4..index * 4 + 4].fill(context);
        }
    } else if let Some(split) = syntax.lossy_luma_8x8_split.as_ref() {
        for (index, context) in split.right_contexts.into_iter().enumerate() {
            right[index * 2..index * 2 + 2].fill(context);
        }
        for (index, context) in split.bottom_contexts.into_iter().enumerate() {
            bottom[index * 2..index * 2 + 2].fill(context);
        }
    } else if let Some(split) = syntax.lossy_luma_4x4_grid_split.as_ref() {
        right[..4].copy_from_slice(&split.right_contexts);
        bottom[..2].copy_from_slice(&split.bottom_contexts);
    } else if let Some(split) = syntax.lossy_luma_4x4_split.as_ref() {
        match (split.grid_width, split.grid_height) {
            (1, 4) => {
                right[..4].copy_from_slice(&split.right_contexts[..4]);
                bottom[0] = split.bottom_contexts[0];
            }
            (4, 1) => {
                right[..4].fill(split.right_contexts[0]);
                bottom[..4].copy_from_slice(&split.bottom_contexts[..4]);
            }
            _ => {
                right[..2].copy_from_slice(&split.right_contexts[..2]);
                bottom[..2].copy_from_slice(&split.bottom_contexts[..2]);
            }
        }
    }
    (right, bottom)
}

fn chroma_edge_contexts_for_syntax(syntax: &BlockSyntax) -> ([[u8; 16]; 2], [[u8; 16]; 2]) {
    let fallback = lossy_chroma_contexts(syntax);
    let mut right = fallback.map(|context| [context; 16]);
    let mut bottom = fallback.map(|context| [context; 16]);
    for plane in 0..2 {
        if let Some(grid) = syntax.full_large_chroma_grids[plane].as_ref() {
            right[plane] = grid.right_contexts;
            bottom[plane] = grid.bottom_contexts;
        }
    }
    (right, bottom)
}

fn combined_luma_edge_contexts(
    first: Option<&FirstLeaf>,
    second: Option<&FirstLeaf>,
    needed: usize,
    bottom_edge: bool,
) -> [u8; 16] {
    combined_luma_edge_contexts_from_neighbors(&[first, second], needed, bottom_edge)
}

pub(super) fn combined_luma_edge_contexts_from_neighbors(
    neighbors: &[Option<&FirstLeaf>],
    needed: usize,
    bottom_edge: bool,
) -> [u8; 16] {
    combined_luma_edge_contexts_from_positioned_neighbors(
        neighbors
            .iter()
            .copied()
            .flatten()
            .map(|neighbor| (neighbor, 0)),
        needed,
        bottom_edge,
    )
}

fn combined_luma_edge_contexts_from_positioned_neighbors<'a>(
    neighbors: impl IntoIterator<Item = (&'a FirstLeaf, usize)>,
    needed: usize,
    bottom_edge: bool,
) -> [u8; 16] {
    let mut contexts = [0x40_u8; 16];
    let mut offset = 0_usize;
    let mut previous = None;
    for (neighbor, edge_offset) in neighbors {
        if previous.is_some_and(|prior| std::ptr::eq(prior, neighbor)) {
            continue;
        }
        if offset >= needed {
            break;
        }
        // A normal transform contributes its finalized residual context over
        // the whole edge. The per-edge arrays are only meaningful for the
        // admitted split 8x8 tree, where each 4x4 child can leave a different
        // context. Using those arrays for a normal leaf replays the syntax's
        // input fallback rather than the context dav1d stores after coding.
        let fallback_edge = [neighbor.luma_context; 16];
        let has_split_edge =
            neighbor.luma_transform_split && (neighbor.width >= 8 || neighbor.height >= 8);
        let edge = if has_split_edge {
            if bottom_edge {
                &neighbor.luma_bottom_contexts
            } else {
                &neighbor.luma_right_contexts
            }
        } else {
            &fallback_edge
        };
        let dimension = if bottom_edge {
            neighbor.width
        } else {
            neighbor.height
        };
        let edge_offset = edge_offset.min(edge.len());
        let available = usize::try_from(dimension.div_ceil(4))
            .unwrap_or(0)
            .saturating_sub(edge_offset)
            .min(edge.len().saturating_sub(edge_offset));
        let count = available.min(needed.saturating_sub(offset));
        if let Some(destination) = contexts.get_mut(offset..offset.saturating_add(count))
            && let Some(source) = edge.get(edge_offset..edge_offset.saturating_add(count))
        {
            destination.copy_from_slice(source);
        }
        offset = offset.saturating_add(count);
        previous = Some(neighbor);
    }
    contexts
}

fn combined_chroma_edge_contexts(
    first: Option<&FirstLeaf>,
    second: Option<&FirstLeaf>,
    plane: usize,
    needed: usize,
    bottom_edge: bool,
) -> [u8; 16] {
    combined_chroma_edge_contexts_from_neighbors(&[first, second], plane, needed, bottom_edge)
}

pub(super) fn combined_chroma_edge_contexts_from_neighbors(
    neighbors: &[Option<&FirstLeaf>],
    plane: usize,
    needed: usize,
    bottom_edge: bool,
) -> [u8; 16] {
    combined_chroma_edge_contexts_from_positioned_neighbors_with_stride(
        neighbors
            .iter()
            .copied()
            .flatten()
            .map(|neighbor| (neighbor, 0)),
        plane,
        needed,
        bottom_edge,
        8,
    )
}

fn combined_chroma_edge_contexts_from_positioned_neighbors_with_stride<'a, const COUNT: usize>(
    neighbors: impl IntoIterator<Item = (&'a FirstLeaf, usize)>,
    plane: usize,
    needed: usize,
    bottom_edge: bool,
    context_stride_pixels: u32,
) -> [u8; COUNT] {
    let mut contexts = [0x40_u8; COUNT];
    let mut offset = 0_usize;
    let mut previous = None;
    for (neighbor, edge_offset) in neighbors {
        if previous.is_some_and(|prior| std::ptr::eq(prior, neighbor)) {
            continue;
        }
        if offset >= needed {
            break;
        }
        let edge = if bottom_edge {
            &neighbor.chroma_bottom_contexts[plane]
        } else {
            &neighbor.chroma_right_contexts[plane]
        };
        let dimension = if bottom_edge {
            neighbor.width
        } else {
            neighbor.height
        };
        let edge_offset = edge_offset.min(edge.len());
        let available = usize::try_from(dimension.div_ceil(context_stride_pixels))
            .unwrap_or(0)
            .saturating_sub(edge_offset)
            .min(edge.len().saturating_sub(edge_offset));
        let count = available.min(needed.saturating_sub(offset));
        if let Some(destination) = contexts.get_mut(offset..offset.saturating_add(count))
            && let Some(source) = edge.get(edge_offset..edge_offset.saturating_add(count))
        {
            destination.copy_from_slice(source);
        }
        offset = offset.saturating_add(count);
        previous = Some(neighbor);
    }
    contexts
}

fn transform_context_dimension(units: usize) -> u8 {
    match units {
        1 => 0,
        2 => 1,
        4 => 2,
        8 => 3,
        16 => 4,
        _ => 0,
    }
}

fn luma_transform_context(transform_grid: TransformGrid, split: bool) -> (u8, u8) {
    if split {
        // A split transform publishes the size of its terminal transform on
        // the corresponding edge. Square8 is split into 4x4 transforms,
        // while Square16 is split into 8x8 transforms. The latter distinction
        // is observable by the next block's transform-size CDF context.
        return match transform_grid {
            TransformGrid::Horizontal16x8 | TransformGrid::Vertical8x16 => (1, 1),
            TransformGrid::Horizontal32x8 => (1, 1),
            TransformGrid::Square16 => (1, 1),
            TransformGrid::Vertical16x32 => (1, 1),
            TransformGrid::Vertical16x64 => (2, 2),
            TransformGrid::Horizontal64x16 => (3, 2),
            TransformGrid::Square32 => (2, 2),
            TransformGrid::Square64 => (3, 3),
            _ => (0, 0),
        };
    }
    let (width, height, _) = transform_grid.properties();
    (
        transform_context_dimension(width),
        transform_context_dimension(height),
    )
}

fn luma_transform_context_for_syntax(
    transform_grid: TransformGrid,
    split: bool,
    vertical_16x32_uses_16x16_children: bool,
    horizontal_16x4_uses_8x4_children: bool,
) -> (u8, u8) {
    if vertical_16x32_uses_16x16_children && matches!(transform_grid, TransformGrid::Vertical16x32)
    {
        // A depth-one R16x32 tree ends in TX_16X16 children. The generic
        // split mapping is also used by the depth-two 8x8 grid, so its
        // terminal size must be selected from the retained syntax state.
        (2, 2)
    } else if horizontal_16x4_uses_8x4_children
        && matches!(transform_grid, TransformGrid::Horizontal16x4)
    {
        // A depth-one R16x4 tree ends in two TX8x4 children. The depth-two
        // TX4x4 grid remains the `(0, 0)` terminal context selected by the
        // generic split mapping.
        (1, 0)
    } else {
        luma_transform_context(transform_grid, split)
    }
}

/// Publish the terminal transform dimensions selected by the decoded tree.
///
/// The legacy helper above needs geometry-specific booleans because its
/// callers progressively migrated one split carrier at a time. The normalized
/// walker has the complete syntax object and can select the exact terminal
/// size directly, including rectangular depth-two grids.
fn normalized_luma_transform_context(
    transform_grid: TransformGrid,
    syntax: &BlockSyntax,
) -> PortableResult<(u8, u8)> {
    let split_count = [
        syntax.lossy_luma_64x64_split.is_some(),
        syntax.lossy_luma_4x4_split.is_some(),
        syntax.lossy_luma_4x4_grid_split.is_some(),
        syntax.lossy_luma_8x4_split.is_some(),
        syntax.lossy_luma_8x8_split.is_some(),
        syntax.lossy_luma_8x8_grid_split.is_some(),
        syntax.lossy_luma_16x16_split.is_some(),
        syntax.lossy_luma_16x16_horizontal_split.is_some(),
        syntax.lossy_luma_32x16_horizontal_split.is_some(),
        syntax.lossy_luma_16x16_vertical_split.is_some(),
    ]
    .into_iter()
    .filter(|present| *present)
    .count();
    (split_count <= 1).then_some(()).portable()?;
    if split_count == 0 {
        return Ok(luma_transform_context(transform_grid, false));
    }
    if syntax.lossy_luma_4x4_split.is_some() || syntax.lossy_luma_4x4_grid_split.is_some() {
        return Ok((0, 0));
    }
    if syntax.lossy_luma_8x4_split.is_some() {
        return Ok((1, 0));
    }
    if syntax.lossy_luma_8x8_split.is_some() || syntax.lossy_luma_8x8_grid_split.is_some() {
        return Ok((1, 1));
    }
    if syntax.lossy_luma_16x16_split.is_some()
        || syntax.lossy_luma_16x16_horizontal_split.is_some()
        || syntax.lossy_luma_16x16_vertical_split.is_some()
    {
        return Ok((2, 2));
    }
    if syntax.lossy_luma_32x16_horizontal_split.is_some() {
        return Ok((3, 2));
    }
    if syntax.lossy_luma_64x64_split.is_some() {
        return Ok((3, 3));
    }
    Err(PortableUnavailable)
}

fn with_lossy_chroma_edge_contexts(
    mut leaf: FirstLeaf,
    contexts: [u8; 2],
    right: [[u8; 16]; 2],
    bottom: [[u8; 16]; 2],
) -> FirstLeaf {
    leaf.chroma_contexts = contexts;
    leaf.chroma_right_contexts = right;
    leaf.chroma_bottom_contexts = bottom;
    leaf
}

fn with_lossy_chroma_contexts(leaf: FirstLeaf, contexts: [u8; 2]) -> FirstLeaf {
    with_lossy_chroma_edge_contexts(
        leaf,
        contexts,
        contexts.map(|context| [context; 16]),
        contexts.map(|context| [context; 16]),
    )
}

fn with_lossy_luma_context(mut leaf: FirstLeaf, context: u8) -> FirstLeaf {
    leaf.luma_context = context;
    leaf
}

/// Decode and reconstruct the first complete closed leaf syntax class.
pub(super) fn decode_first_lossless_444_leaf(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    width: u32,
    height: u32,
    transform_grid: TransformGrid,
    tools: BlockTools,
) -> PortableResult<FirstLeaf> {
    let (_, _, use_filter_intra) = transform_grid.properties();
    let mut cdfs = BlockCdfs::defaults(use_filter_intra);
    let mut palette_map_arena = PaletteMapArena::new();
    palette_map_arena.begin_leaf()?;
    let syntax = decode_syntax_with_palette_entropy(
        decoder,
        &mut cdfs,
        &mut palette_map_arena,
        transform_grid,
        ChromaSampling::Full,
        SyntaxPolicy {
            spatial_luma_context: SpatialLumaContext::Origin,
            coefficient_policy: CoefficientPolicy::DcOrSkipped,
            quantization_syntax: QuantizationSyntax::Lossless,
            allow_horizontal_chroma: false,
            allow_diagonal_chroma: false,
            allow_diagonal_luma: false,
            allow_smooth_chroma: false,
            allow_smooth_luma: false,
        },
        tools,
        Some(PaletteEntropyDimensions::from_visible(
            transform_grid.block_size(),
            width,
            height,
        )?),
    )?;
    let predictors = origin_predictors(syntax.luma_predictor);
    let leaf = reconstruct_leaf(syntax, predictors, &palette_map_arena)?;
    Ok(with_palette_cache(
        visible_leaf(
            leaf,
            syntax.block_skipped,
            Some(syntax.chroma_predictor),
            transform_grid,
            width,
            height,
            ChromaSampling::Full,
            luma_transform_context(transform_grid, false),
            false,
            ([0x40; 16], [0x40; 16]),
        ),
        syntax.palette.cache_state(),
    ))
}

impl Lossless444Leaf {
    fn new(
        geometry: Lossless444BlockGeometry,
        block_skipped: bool,
        right_contexts: [[u8; LOSSLESS444_NEIGHBOR_CAPACITY]; 3],
        bottom_contexts: [[u8; LOSSLESS444_NEIGHBOR_CAPACITY]; 3],
        palette_cache: PaletteCacheState,
        closed: ClosedLeaf,
    ) -> PortableResult<Self> {
        let (grid_width, grid_height, _) = geometry.transform_grid.properties();
        let expected_width =
            u32::try_from(grid_width.saturating_mul(4)).map_err(|_| PortableUnavailable)?;
        let expected_height =
            u32::try_from(grid_height.saturating_mul(4)).map_err(|_| PortableUnavailable)?;
        let expected_samples = usize::try_from(geometry.width)
            .ok()
            .and_then(|width| {
                usize::try_from(geometry.height)
                    .ok()
                    .and_then(|height| width.checked_mul(height))
            })
            .ok_or(PortableUnavailable)?;
        if geometry.width != expected_width
            || geometry.height != expected_height
            || closed
                .planes
                .iter()
                .any(|plane| plane.samples.len() != expected_samples)
        {
            return Err(PortableUnavailable);
        }
        Ok(Self {
            origin_x: geometry.origin_x,
            origin_y: geometry.origin_y,
            width: geometry.width,
            height: geometry.height,
            block_skipped,
            closed,
            right_contexts,
            bottom_contexts,
            palette_cache,
        })
    }

    pub(super) const fn origin_x(&self) -> u32 {
        self.origin_x
    }

    pub(super) const fn origin_y(&self) -> u32 {
        self.origin_y
    }

    pub(super) const fn width(&self) -> u32 {
        self.width
    }

    pub(super) const fn height(&self) -> u32 {
        self.height
    }

    pub(super) const fn block_skipped(&self) -> bool {
        self.block_skipped
    }

    pub(super) fn planes(&self) -> &[ReconstructedPlane; 3] {
        &self.closed.planes
    }
}

impl Lossless444Decoder {
    pub(super) fn new(sample_depth: SampleDepth) -> Self {
        Self {
            cdfs: BlockCdfs::defaults([24_902, 0]),
            palette_map_arena: PaletteMapArena::new(),
            lossless_square64_arena: LosslessSquare64CoefficientArena::new(),
            sample_depth,
        }
    }

    pub(super) fn decode_origin(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        geometry: Lossless444BlockGeometry,
        tools: BlockTools,
    ) -> PortableResult<Lossless444Leaf> {
        self.lossless_square64_arena.begin_leaf()?;
        self.palette_map_arena.begin_leaf()?;
        let syntax = match decode_syntax_with_palette_entropy_lossless_square64(
            decoder,
            &mut self.cdfs,
            &mut self.palette_map_arena,
            geometry.transform_grid,
            SyntaxPolicy {
                spatial_luma_context: SpatialLumaContext::Origin,
                coefficient_policy: CoefficientPolicy::ColorFrameTopLeft,
                quantization_syntax: QuantizationSyntax::Lossless,
                allow_horizontal_chroma: true,
                allow_diagonal_chroma: true,
                allow_diagonal_luma: true,
                allow_smooth_chroma: true,
                allow_smooth_luma: true,
            },
            tools,
            Some(PaletteEntropyDimensions::from_visible(
                geometry.transform_grid.block_size(),
                geometry.width,
                geometry.height,
            )?),
            &mut self.lossless_square64_arena,
        ) {
            Ok(syntax) => syntax,
            Err(error) => {
                return Err(error);
            }
        };
        let right_contexts = if matches!(
            syntax.transform_grid,
            TransformGrid::Vertical16x64
                | TransformGrid::Vertical32x64
                | TransformGrid::Horizontal64x16
                | TransformGrid::Horizontal64x32
                | TransformGrid::Square64
        ) {
            lossless_large_edge_contexts(
                &syntax,
                &self.lossless_square64_arena,
                SplitOrientation::Horizontal,
            )?
        } else {
            coefficient_edge_contexts_wide(
                &syntax.coefficients,
                SplitOrientation::Horizontal,
                syntax.transform_grid,
                ChromaSampling::Full,
            )?
        };
        let bottom_contexts = if matches!(
            syntax.transform_grid,
            TransformGrid::Vertical16x64
                | TransformGrid::Vertical32x64
                | TransformGrid::Horizontal64x16
                | TransformGrid::Horizontal64x32
                | TransformGrid::Square64
        ) {
            lossless_large_edge_contexts(
                &syntax,
                &self.lossless_square64_arena,
                SplitOrientation::Vertical,
            )?
        } else {
            coefficient_edge_contexts_wide(
                &syntax.coefficients,
                SplitOrientation::Vertical,
                syntax.transform_grid,
                ChromaSampling::Full,
            )?
        };
        let block_skipped = syntax.block_skipped;
        let palette_cache = syntax.palette.cache_state();
        let closed = reconstruct_lossless444_leaf(
            syntax,
            geometry,
            self.sample_depth,
            &self.palette_map_arena,
            &self.lossless_square64_arena,
            None,
            [None; LOSSLESS444_NEIGHBOR_CAPACITY],
            None,
            [None; LOSSLESS444_NEIGHBOR_CAPACITY],
            [None; 8],
            tools.enable_intra_edge_filter,
        )?;
        Lossless444Leaf::new(
            geometry,
            block_skipped,
            right_contexts,
            bottom_contexts,
            palette_cache,
            closed,
        )
    }

    pub(super) fn decode_following(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        geometry: Lossless444BlockGeometry,
        neighbors: Lossless444Neighbors<'_>,
        mut tools: BlockTools,
    ) -> PortableResult<Lossless444Leaf> {
        let Lossless444Neighbors {
            above_left,
            above,
            above_right,
            left,
            left_below,
        } = neighbors;
        let above_leaf = above.iter().flatten().next().copied();
        let left_leaf = left.iter().flatten().next().copied();
        let above_contexts = lossless444_neighbor_contexts(above, geometry, true)?;
        let left_contexts = lossless444_neighbor_contexts(left, geometry, false)?;
        let (spatial_luma_context, coefficient_policy, _orientation) = match (above, left) {
            (above, left)
                if above.iter().all(Option::is_none) && left.iter().all(Option::is_none) =>
            {
                (
                    SpatialLumaContext::Origin,
                    CoefficientPolicy::DcOrSkipped,
                    None,
                )
            }
            (_, _) if left.iter().all(Option::is_none) => (
                SpatialLumaContext::from_neighbor(
                    SplitOrientation::Vertical,
                    above_leaf.ok_or(PortableUnavailable)?.closed.luma_predictor,
                ),
                CoefficientPolicy::ColorFrameSquareContextual {
                    neighbor_contexts: above_contexts,
                    orientation: SplitOrientation::Vertical,
                },
                Some(SplitOrientation::Vertical),
            ),
            (_, _) if above.iter().all(Option::is_none) => (
                SpatialLumaContext::from_neighbor(
                    SplitOrientation::Horizontal,
                    left_leaf.ok_or(PortableUnavailable)?.closed.luma_predictor,
                ),
                CoefficientPolicy::ColorFrameSquareContextual {
                    neighbor_contexts: left_contexts,
                    orientation: SplitOrientation::Horizontal,
                },
                Some(SplitOrientation::Horizontal),
            ),
            (_, _) => (
                SpatialLumaContext::from_two_neighbors(
                    above_leaf.ok_or(PortableUnavailable)?.closed.luma_predictor,
                    left_leaf.ok_or(PortableUnavailable)?.closed.luma_predictor,
                )?,
                CoefficientPolicy::ColorFrameBoundaryContextual {
                    above_contexts,
                    left_contexts,
                },
                None,
            ),
        };
        tools.palette_context = PaletteNeighborContext::from_cache_states(
            geometry.origin_y / 4,
            above_leaf.map(|leaf| leaf.palette_cache),
            left_leaf.map(|leaf| leaf.palette_cache),
        );
        tools.skip_context = usize::from(above_leaf.is_some_and(Lossless444Leaf::block_skipped))
            .saturating_add(usize::from(
                left_leaf.is_some_and(Lossless444Leaf::block_skipped),
            ));
        self.lossless_square64_arena.begin_leaf()?;
        self.palette_map_arena.begin_leaf()?;
        let syntax = match decode_syntax_with_palette_entropy_lossless_square64(
            decoder,
            &mut self.cdfs,
            &mut self.palette_map_arena,
            geometry.transform_grid,
            SyntaxPolicy {
                spatial_luma_context,
                coefficient_policy,
                quantization_syntax: QuantizationSyntax::Lossless,
                allow_horizontal_chroma: true,
                allow_diagonal_chroma: true,
                allow_diagonal_luma: true,
                allow_smooth_chroma: true,
                allow_smooth_luma: true,
            },
            tools,
            Some(PaletteEntropyDimensions::from_visible(
                geometry.transform_grid.block_size(),
                geometry.width,
                geometry.height,
            )?),
            &mut self.lossless_square64_arena,
        ) {
            Ok(syntax) => syntax,
            Err(error) => {
                return Err(error);
            }
        };
        let right_contexts = if matches!(
            syntax.transform_grid,
            TransformGrid::Vertical16x64
                | TransformGrid::Vertical32x64
                | TransformGrid::Horizontal64x16
                | TransformGrid::Horizontal64x32
                | TransformGrid::Square64
        ) {
            lossless_large_edge_contexts(
                &syntax,
                &self.lossless_square64_arena,
                SplitOrientation::Horizontal,
            )?
        } else {
            coefficient_edge_contexts_wide(
                &syntax.coefficients,
                SplitOrientation::Horizontal,
                syntax.transform_grid,
                ChromaSampling::Full,
            )?
        };
        let bottom_contexts = if matches!(
            syntax.transform_grid,
            TransformGrid::Vertical16x64
                | TransformGrid::Vertical32x64
                | TransformGrid::Horizontal64x16
                | TransformGrid::Horizontal64x32
                | TransformGrid::Square64
        ) {
            lossless_large_edge_contexts(
                &syntax,
                &self.lossless_square64_arena,
                SplitOrientation::Vertical,
            )?
        } else {
            coefficient_edge_contexts_wide(
                &syntax.coefficients,
                SplitOrientation::Vertical,
                syntax.transform_grid,
                ChromaSampling::Full,
            )?
        };
        let block_skipped = syntax.block_skipped;
        let palette_cache = syntax.palette.cache_state();
        let closed = match reconstruct_lossless444_leaf(
            syntax,
            geometry,
            self.sample_depth,
            &self.palette_map_arena,
            &self.lossless_square64_arena,
            above_left,
            above,
            above_right,
            left,
            left_below,
            tools.enable_intra_edge_filter,
        ) {
            Ok(closed) => closed,
            Err(error) => {
                return Err(error);
            }
        };
        Lossless444Leaf::new(
            geometry,
            block_skipped,
            right_contexts,
            bottom_contexts,
            palette_cache,
            closed,
        )
    }
}

impl MonochromeLosslessDecoder {
    pub(super) fn new() -> Self {
        Self {
            cdfs: BlockCdfs::defaults([20_360, 0]),
            palette_map_arena: PaletteMapArena::new(),
            lossless_square64_arena: LosslessSquare64CoefficientArena::new(),
        }
    }

    pub(super) fn decode_origin(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        geometry: MonochromeBlockGeometry,
        tools: BlockTools,
    ) -> PortableResult<MonochromeLeaf> {
        self.decode(
            decoder,
            MonochromeDecodeContext {
                geometry,
                spatial_luma_context: SpatialLumaContext::Origin,
                above_contexts: [0x40; 16],
                left_contexts: [0x40; 16],
                tools,
                above_left: None,
                above: None,
                above_right: [None; MONOCHROME_NEIGHBOR_CAPACITY],
                left: None,
                left_below: [None; MONOCHROME_NEIGHBOR_CAPACITY],
            },
        )
    }

    pub(super) fn decode_following(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        geometry: MonochromeBlockGeometry,
        neighbors: MonochromeNeighbors<'_>,
        mut tools: BlockTools,
    ) -> PortableResult<MonochromeLeaf> {
        let MonochromeNeighbors {
            above_left,
            above,
            above_right,
            left,
            left_below,
        } = neighbors;
        tools.skip_context = usize::from(above.is_some_and(MonochromeLeaf::block_skipped))
            .saturating_add(usize::from(left.is_some_and(MonochromeLeaf::block_skipped)));
        let spatial_left = left.or_else(|| left_below.iter().flatten().next().copied());
        tools.palette_context = PaletteNeighborContext::from_cache_states(
            geometry.origin_y / 4,
            above.map(|leaf| leaf.palette_cache),
            spatial_left.map(|leaf| leaf.palette_cache),
        );
        let spatial_luma_context = match (above, spatial_left) {
            (None, None) => SpatialLumaContext::Origin,
            (Some(above), None) => {
                SpatialLumaContext::from_neighbor(SplitOrientation::Vertical, above.predictor)
            }
            (None, Some(left)) => {
                SpatialLumaContext::from_neighbor(SplitOrientation::Horizontal, left.predictor)
            }
            (Some(above), Some(left)) => {
                SpatialLumaContext::from_two_monochrome_neighbors(above.predictor, left.predictor)?
            }
        };
        let above_contexts = if above.is_some() || above_right.iter().any(Option::is_some) {
            aligned_above_edge_contexts(above, &above_right, geometry.origin_x, geometry.origin_y)?
        } else {
            [0x40; 16]
        };
        let left_contexts = match left {
            Some(leaf) => aligned_edge_contexts(leaf, geometry.origin_x, geometry.origin_y, false)?,
            None => [0x40; 16],
        };
        let mut left_contexts = left_contexts;
        for leaf in left_below.iter().flatten() {
            if leaf.origin_y < geometry.origin_y {
                return Err(PortableUnavailable);
            }
            let row_offset = usize::try_from(
                leaf.origin_y
                    .saturating_sub(geometry.origin_y)
                    .checked_div(4)
                    .ok_or(PortableUnavailable)?,
            )
            .map_err(|_| PortableUnavailable)?;
            for (index, context) in leaf.right_contexts.iter().enumerate() {
                if let Some(slot) = left_contexts.get_mut(row_offset.saturating_add(index)) {
                    *slot = *context;
                }
            }
        }
        self.decode(
            decoder,
            MonochromeDecodeContext {
                geometry,
                spatial_luma_context,
                above_contexts,
                left_contexts,
                tools,
                above_left,
                above,
                above_right,
                left,
                left_below,
            },
        )
    }

    fn decode<'a>(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        context: MonochromeDecodeContext<'a>,
    ) -> PortableResult<MonochromeLeaf> {
        let MonochromeDecodeContext {
            geometry,
            spatial_luma_context,
            above_contexts,
            left_contexts,
            tools,
            above_left,
            above,
            above_right,
            left,
            left_below,
        } = context;
        self.palette_map_arena.begin_leaf()?;
        self.lossless_square64_arena.begin_leaf()?;
        let syntax_result = decode_syntax_with_palette_entropy_lossless_monochrome(
            decoder,
            &mut self.cdfs,
            &mut self.palette_map_arena,
            geometry.transform_grid,
            SyntaxPolicy {
                spatial_luma_context,
                coefficient_policy: CoefficientPolicy::MonochromeContextual {
                    above_contexts,
                    left_contexts,
                    active_grid_width: usize::try_from(geometry.active_grid_width)
                        .map_err(|_| PortableUnavailable)?,
                    active_grid_height: usize::try_from(geometry.active_grid_height)
                        .map_err(|_| PortableUnavailable)?,
                },
                quantization_syntax: QuantizationSyntax::Lossless,
                allow_horizontal_chroma: true,
                allow_diagonal_chroma: true,
                allow_diagonal_luma: true,
                allow_smooth_chroma: false,
                allow_smooth_luma: true,
            },
            tools,
            Some(PaletteEntropyDimensions::from_visible(
                geometry.transform_grid.block_size(),
                geometry.width,
                geometry.height,
            )?),
            &mut self.lossless_square64_arena,
        );
        let syntax = match syntax_result {
            Ok(syntax) => syntax,
            Err(error) => {
                return Err(error);
            }
        };

        reconstruct_monochrome_leaf(
            syntax,
            geometry,
            MonochromeNeighbors {
                above_left,
                above,
                above_right,
                left,
                left_below,
            },
            tools.sample_depth,
            &self.palette_map_arena,
            &self.lossless_square64_arena,
            tools.enable_intra_edge_filter,
        )
    }
}

fn paeth_predictor(top: u16, left: u16, top_left: u16) -> u16 {
    let top = i32::from(top);
    let left = i32::from(left);
    let top_left = i32::from(top_left);
    let estimate = top.saturating_add(left).saturating_sub(top_left);
    let top_distance = estimate.saturating_sub(top).unsigned_abs();
    let left_distance = estimate.saturating_sub(left).unsigned_abs();
    let top_left_distance = estimate.saturating_sub(top_left).unsigned_abs();
    if top_distance <= left_distance && top_distance <= top_left_distance {
        return u16::try_from(top).unwrap_or(0);
    }
    if left_distance <= top_left_distance {
        return u16::try_from(left).unwrap_or(0);
    }
    u16::try_from(top_left).unwrap_or(0)
}

fn smooth_weight_table(size: usize) -> PortableResult<&'static [u16]> {
    // ✅ VERIFIED: dav1d 1.5.3 src/tables.c `dav1d_sm_weights`, indexed by
    // the coded block width or height. These are the AV1 smooth-predictor
    // weights, not an approximation derived from the fixture.
    const WEIGHTS_8: [u16; 8] = [255, 197, 146, 105, 73, 50, 37, 32];
    const WEIGHTS_4: [u16; 4] = [255, 149, 85, 64];
    const WEIGHTS_16: [u16; 16] = [
        255, 225, 196, 170, 145, 123, 102, 84, 68, 54, 43, 33, 26, 20, 17, 16,
    ];
    const WEIGHTS_32: [u16; 32] = [
        255, 240, 225, 210, 196, 182, 169, 157, 145, 133, 122, 111, 101, 92, 83, 74, 66, 59, 52,
        45, 39, 34, 29, 25, 21, 17, 14, 12, 10, 9, 8, 8,
    ];
    const WEIGHTS_64: [u16; 64] = [
        255, 248, 240, 233, 225, 218, 210, 203, 196, 189, 182, 176, 169, 163, 156, 150, 144, 138,
        133, 127, 121, 116, 111, 106, 101, 96, 91, 86, 82, 77, 73, 69, 65, 61, 57, 54, 50, 47, 44,
        41, 38, 35, 32, 29, 27, 25, 22, 20, 18, 16, 15, 13, 12, 10, 9, 8, 7, 6, 6, 5, 5, 4, 4, 4,
    ];
    match size {
        4 => Ok(&WEIGHTS_4),
        8 => Ok(&WEIGHTS_8),
        16 => Ok(&WEIGHTS_16),
        32 => Ok(&WEIGHTS_32),
        64 => Ok(&WEIGHTS_64),
        _ => Err(PortableUnavailable),
    }
}

fn aligned_edge_contexts(
    leaf: &MonochromeLeaf,
    origin_x: u32,
    origin_y: u32,
    above: bool,
) -> PortableResult<[u8; 16]> {
    let (neighbor_origin, edge_contexts) = if above {
        (leaf.origin_x, leaf.bottom_contexts)
    } else {
        (leaf.origin_y, leaf.right_contexts)
    };
    if origin_x < leaf.origin_x || origin_y < leaf.origin_y {
        return Err(PortableUnavailable);
    }
    let offset = if above {
        origin_x.saturating_sub(neighbor_origin)
    } else {
        origin_y.saturating_sub(neighbor_origin)
    };
    if offset % 4 != 0 {
        return Err(PortableUnavailable);
    }
    let start = usize::try_from(offset / 4).map_err(|_| PortableUnavailable)?;
    if start > edge_contexts.len() {
        return Err(PortableUnavailable);
    }
    let mut result = [0x40_u8; 16];
    for (index, context) in result.iter_mut().enumerate() {
        if let Some(value) = edge_contexts.get(start.saturating_add(index)) {
            *context = *value;
        }
    }
    Ok(result)
}

fn aligned_above_edge_contexts(
    above: Option<&MonochromeLeaf>,
    above_right: &[Option<&MonochromeLeaf>; MONOCHROME_NEIGHBOR_CAPACITY],
    origin_x: u32,
    origin_y: u32,
) -> PortableResult<[u8; 16]> {
    let mut result = [0x40_u8; 16];
    let mut copy_edge = |leaf: &MonochromeLeaf| -> PortableResult<()> {
        if leaf.origin_y.checked_add(leaf.height) != Some(origin_y) {
            return Ok(());
        }
        let (source_start, destination_start) = if leaf.origin_x <= origin_x {
            let offset = origin_x
                .checked_sub(leaf.origin_x)
                .filter(|offset| offset % 4 == 0)
                .ok_or(PortableUnavailable)?;
            (
                usize::try_from(offset / 4).map_err(|_| PortableUnavailable)?,
                0,
            )
        } else {
            let offset = leaf
                .origin_x
                .checked_sub(origin_x)
                .filter(|offset| offset % 4 == 0)
                .ok_or(PortableUnavailable)?;
            (
                0,
                usize::try_from(offset / 4).map_err(|_| PortableUnavailable)?,
            )
        };
        let source_count = usize::try_from(leaf.width.div_ceil(4))
            .map_err(|_| PortableUnavailable)?
            .min(leaf.bottom_contexts.len().saturating_sub(source_start));
        for source_index in 0..source_count {
            let destination = destination_start.saturating_add(source_index);
            if let Some(slot) = result.get_mut(destination) {
                *slot = leaf.bottom_contexts[source_start.saturating_add(source_index)];
            }
        }
        Ok(())
    };
    if let Some(leaf) = above {
        copy_edge(leaf)?;
    }
    for leaf in above_right.iter().flatten() {
        copy_edge(leaf)?;
    }
    Ok(result)
}

fn monochrome_sample_at(leaf: &MonochromeLeaf, x: u32, y: u32) -> Option<u16> {
    let local_x = x.checked_sub(leaf.origin_x)?;
    let local_y = y.checked_sub(leaf.origin_y)?;
    if local_x >= leaf.width || local_y >= leaf.height {
        return None;
    }
    let width = usize::try_from(leaf.width).ok()?;
    let local_x = usize::try_from(local_x).ok()?;
    let local_y = usize::try_from(local_y).ok()?;
    let index = local_y.checked_mul(width)?.checked_add(local_x)?;
    leaf.plane.samples.get(index).copied()
}

fn monochrome_sample_from_neighbors(
    first: Option<&MonochromeLeaf>,
    second: &[Option<&MonochromeLeaf>; MONOCHROME_NEIGHBOR_CAPACITY],
    x: u32,
    y: u32,
) -> Option<u16> {
    first
        .and_then(|leaf| monochrome_sample_at(leaf, x, y))
        .or_else(|| {
            second
                .iter()
                .flatten()
                .find_map(|leaf| monochrome_sample_at(leaf, x, y))
        })
}

fn diagonal_predictor_sample(
    edge: &[u16],
    left_length: usize,
    dx: i32,
    dy: i32,
    x: usize,
    y: usize,
) -> PortableResult<u16> {
    diagonal_predictor_sample_with_max(edge, left_length, dx, dy, x, y, 255)
}

fn diagonal_predictor_sample_with_max(
    edge: &[u16],
    left_length: usize,
    dx: i32,
    dy: i32,
    x: usize,
    y: usize,
    maximum: u16,
) -> PortableResult<u16> {
    let x = i32::try_from(x).map_err(|_| PortableUnavailable)?;
    let y = i32::try_from(y).map_err(|_| PortableUnavailable)?;
    let xpos = 64_i32.saturating_sub(dx.saturating_mul(y.saturating_add(1)));
    let base_x = xpos >> 6;
    let frac_x = xpos & 0x3e;
    let sample = if base_x.saturating_add(x) >= 0 {
        let first = i32::try_from(left_length)
            .map_err(|_| PortableUnavailable)?
            .saturating_add(1)
            .saturating_add(base_x)
            .saturating_add(x);
        let first = usize::try_from(first).map_err(|_| PortableUnavailable)?;
        let second = first.checked_add(1).ok_or(PortableUnavailable)?;
        let first = i32::from(*edge.get(first).ok_or(PortableUnavailable)?);
        let second = i32::from(*edge.get(second).ok_or(PortableUnavailable)?);
        first
            .saturating_mul(64_i32.saturating_sub(frac_x))
            .saturating_add(second.saturating_mul(frac_x))
            .saturating_add(32)
            >> 6
    } else {
        let ypos = y
            .saturating_mul(64)
            .saturating_sub(dy.saturating_mul(x.saturating_add(1)));
        let base_y = ypos >> 6;
        let frac_y = ypos & 0x3e;
        let first = i32::try_from(left_length)
            .map_err(|_| PortableUnavailable)?
            .saturating_sub(1)
            .saturating_sub(base_y);
        let second = first.saturating_sub(1);
        let first = usize::try_from(first).map_err(|_| PortableUnavailable)?;
        let second = usize::try_from(second).map_err(|_| PortableUnavailable)?;
        let first = i32::from(*edge.get(first).ok_or(PortableUnavailable)?);
        let second = i32::from(*edge.get(second).ok_or(PortableUnavailable)?);
        first
            .saturating_mul(64_i32.saturating_sub(frac_y))
            .saturating_add(second.saturating_mul(frac_y))
            .saturating_add(32)
            >> 6
    };
    u16::try_from(sample.clamp(0, i32::from(maximum))).map_err(|_| PortableUnavailable)
}

/// Apply AV1's four-tap intra-edge upsampler to one eight-sample edge.
///
/// Upsample the top edge for a Zone 1 directional predictor.
///
/// The reference edge starts one sample after top-left, so the first filtered
/// sample uses top-left as the left tap.  The bounded array implementation is
/// equivalent and remains entirely safe.
fn upsample_z2_top_edge(top: [u16; 16], top_left: u16) -> [u16; 17] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let source: [u16; 9] = std::array::from_fn(|index| {
        if index == 0 {
            top_left
        } else {
            top[index.saturating_sub(1)]
        }
    });
    let mut upsampled = [0_u16; 17];
    for index in 0_usize..8 {
        upsampled[index.saturating_mul(2)] = source[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .min(source.len().saturating_sub(1));
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the upsampled intra edge is explicitly clamped to eight-bit range"
        )]
        {
            upsampled[index.saturating_mul(2).saturating_add(1)] =
                ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
        }
    }
    upsampled[16] = source[8];
    upsampled
}

/// Apply the AV1 Zone-2 four-tap upsampler to a 4×4 chroma top edge.
fn upsample_z2_top_edge_4(top: [u16; 8], top_left: u16) -> [u16; 9] {
    upsample_z2_top_edge_4_with_max(top, top_left, 255)
}

fn upsample_z2_top_edge_4_with_max(top: [u16; 8], top_left: u16, maximum: u16) -> [u16; 9] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let source = [top_left, top[0], top[1], top[2], top[3]];
    let mut upsampled = [0_u16; 9];
    for index in 0_usize..4 {
        upsampled[index.saturating_mul(2)] = source[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .min(source.len().saturating_sub(1));
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        upsampled[index.saturating_mul(2).saturating_add(1)] =
            u16::try_from((sum.saturating_add(8) >> 4).clamp(0, i32::from(maximum)))
                .unwrap_or(maximum);
    }
    upsampled[8] = source[4];
    upsampled
}

/// Apply the AV1 Zone-2 four-tap upsampler to a lossless 4×4 left edge.
fn upsample_z2_left_edge_4_with_max(left: [u16; 4], top_left: u16, maximum: u16) -> [u16; 9] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let source = [left[3], left[2], left[1], left[0], top_left];
    let mut upsampled = [0_u16; 9];
    for index in 0_usize..4 {
        upsampled[index.saturating_mul(2)] = source[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .min(source.len().saturating_sub(1));
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        upsampled[index.saturating_mul(2).saturating_add(1)] =
            u16::try_from((sum.saturating_add(8) >> 4).clamp(0, i32::from(maximum)))
                .unwrap_or(maximum);
    }
    upsampled[8] = source[4];
    upsampled
}

fn upsample_z2_left_edge(left: [u16; 8], top_left: u16) -> [u16; 17] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let source: [u16; 9] = std::array::from_fn(|index| {
        if index < left.len() {
            left[left.len().saturating_sub(1).saturating_sub(index)]
        } else {
            top_left
        }
    });
    let mut upsampled = [0_u16; 17];
    for index in 0_usize..8 {
        upsampled[index.saturating_mul(2)] = source[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .min(source.len().saturating_sub(1));
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the upsampled intra edge is explicitly clamped to eight-bit range"
        )]
        {
            upsampled[index.saturating_mul(2).saturating_add(1)] =
                ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
        }
    }
    upsampled[16] = source[8];
    upsampled
}

fn filter_z2_left_edge(edge: [u16; 8], top_left: u16, strength: usize) -> [u16; 8] {
    filter_z2_left_edge_with_max(edge, top_left, strength, 255)
}

fn filter_z2_left_edge_with_max(
    edge: [u16; 8],
    top_left: u16,
    strength: usize,
    maximum: u16,
) -> [u16; 8] {
    if strength == 0 {
        return edge;
    }
    const KERNELS: [[i32; 5]; 3] = [[0, 4, 8, 4, 0], [0, 5, 6, 5, 0], [2, 4, 4, 4, 2]];
    let kernel = KERNELS[strength.saturating_sub(1).min(2)];
    let source: [u16; 9] = std::array::from_fn(|index| {
        if index < edge.len() {
            edge[edge.len().saturating_sub(1).saturating_sub(index)]
        } else {
            top_left
        }
    });
    let filtered_reverse: [u16; 8] = std::array::from_fn(|index| {
        let mut sum = 0_i32;
        for (tap, weight) in kernel.into_iter().enumerate() {
            let source_index = i32::try_from(index)
                .unwrap_or(0)
                .saturating_add(i32::try_from(tap).unwrap_or(0))
                .saturating_sub(2)
                .clamp(
                    0,
                    i32::try_from(source.len().saturating_sub(1)).unwrap_or(0),
                );
            let source_index = usize::try_from(source_index).unwrap_or(0);
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        u16::try_from((sum.saturating_add(8) >> 4).clamp(0, i32::from(maximum))).unwrap_or(maximum)
    });
    std::array::from_fn(|index| {
        filtered_reverse[edge.len().saturating_sub(1).saturating_sub(index)]
    })
}

fn filter_z3_left_edge_16(edge: [u16; 16], top_left: u16, strength: usize) -> [u16; 16] {
    if strength == 0 {
        return edge;
    }
    const KERNELS: [[i32; 5]; 3] = [[0, 4, 8, 4, 0], [0, 5, 6, 5, 0], [2, 4, 4, 4, 2]];
    let kernel = KERNELS[strength.saturating_sub(1).min(2)];
    let filtered_reverse: [u16; 16] = std::array::from_fn(|index| {
        let mut sum = 0_i32;
        for (tap, weight) in kernel.into_iter().enumerate() {
            let source_index = i32::try_from(index)
                .unwrap_or(0)
                .saturating_add(i32::try_from(tap).unwrap_or(0))
                .saturating_sub(2)
                .clamp(0, 16);
            let source = if source_index == 16 {
                top_left
            } else {
                edge[15_usize.saturating_sub(usize::try_from(source_index).unwrap_or(0))]
            };
            sum = sum.saturating_add(i32::from(source).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the filtered intra edge is explicitly clamped to eight-bit range"
        )]
        {
            ((sum.saturating_add(8) >> 4).clamp(0, 255)) as u16
        }
    });
    std::array::from_fn(|index| filtered_reverse[15_usize.saturating_sub(index)])
}

fn filter_z3_left_edge_24(edge: [u16; 24], top_left: u16, strength: usize) -> [u16; 24] {
    if strength == 0 {
        return edge;
    }
    const KERNELS: [[i32; 5]; 3] = [[0, 4, 8, 4, 0], [0, 5, 6, 5, 0], [2, 4, 4, 4, 2]];
    let kernel = KERNELS[strength.saturating_sub(1).min(2)];
    let filtered_reverse: [u16; 24] = std::array::from_fn(|index| {
        let mut sum = 0_i32;
        for (tap, weight) in kernel.into_iter().enumerate() {
            let source_index = i32::try_from(index)
                .unwrap_or(0)
                .saturating_add(i32::try_from(tap).unwrap_or(0))
                .saturating_sub(2)
                .clamp(0, 24);
            let source = if source_index == 24 {
                top_left
            } else {
                edge[23_usize.saturating_sub(usize::try_from(source_index).unwrap_or(0))]
            };
            sum = sum.saturating_add(i32::from(source).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the filtered intra edge is explicitly clamped"
        )]
        {
            ((sum.saturating_add(8) >> 4).clamp(0, 255)) as u16
        }
    });
    std::array::from_fn(|index| filtered_reverse[23_usize.saturating_sub(index)])
}

fn filter_z2_top_edge(edge: [u16; 16], top_left: u16, strength: usize) -> [u16; 16] {
    if strength == 0 {
        return edge;
    }
    const KERNELS: [[i32; 5]; 3] = [[0, 4, 8, 4, 0], [0, 5, 6, 5, 0], [2, 4, 4, 4, 2]];
    let kernel = KERNELS[strength.saturating_sub(1).min(2)];
    let mut filtered = edge;
    for (index, sample) in filtered.iter_mut().enumerate().take(8) {
        let mut sum = 0_i32;
        for (tap, weight) in kernel.into_iter().enumerate() {
            let source_index = i32::try_from(index)
                .unwrap_or(0)
                .saturating_add(i32::try_from(tap).unwrap_or(0))
                .saturating_sub(2)
                .clamp(-1, 7);
            let source = if source_index < 0 {
                top_left
            } else {
                edge[usize::try_from(source_index).unwrap_or(0)]
            };
            sum = sum.saturating_add(i32::from(source).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the filtered intra edge is explicitly clamped to eight-bit range"
        )]
        {
            *sample = ((sum.saturating_add(8) >> 4).clamp(0, 255)) as u16;
        }
    }
    filtered
}

fn upsample_intra_top_edge(edge: [u16; 8], top_left: u16) -> [u16; 15] {
    upsample_intra_top_edge_with_max(edge, top_left, 255)
}

fn upsample_intra_top_edge_with_max(edge: [u16; 8], top_left: u16, maximum: u16) -> [u16; 15] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let mut upsampled = [0_u16; 15];
    for index in 0_usize..7 {
        upsampled[index.saturating_mul(2)] = edge[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index.saturating_add(tap);
            let sample = if source_index == 0 {
                top_left
            } else {
                edge.get(
                    source_index
                        .saturating_sub(1)
                        .min(edge.len().saturating_sub(1)),
                )
                .copied()
                .unwrap_or(top_left)
            };
            sum = sum.saturating_add(i32::from(sample).saturating_mul(weight));
        }
        let filtered = (sum.saturating_add(8) >> 4).clamp(0, i32::from(maximum));
        upsampled[index.saturating_mul(2).saturating_add(1)] =
            u16::try_from(filtered).unwrap_or(maximum);
    }
    upsampled[14] = edge[7];
    upsampled
}

/// Apply AV1's four-tap intra-edge upsampler to a sixteen-sample top edge.
fn upsample_intra_top_edge_16(edge: [u16; 16], top_left: u16) -> [u16; 31] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let mut upsampled = [0_u16; 31];
    for index in 0_usize..15 {
        upsampled[index.saturating_mul(2)] = edge[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index.saturating_add(tap);
            let sample = if source_index == 0 {
                top_left
            } else {
                edge.get(
                    source_index
                        .saturating_sub(1)
                        .min(edge.len().saturating_sub(1)),
                )
                .copied()
                .unwrap_or(top_left)
            };
            sum = sum.saturating_add(i32::from(sample).saturating_mul(weight));
        }
        let filtered = (sum.saturating_add(8) >> 4).clamp(0, 255);
        #[expect(
            clippy::cast_sign_loss,
            reason = "the upsampled intra edge is explicitly clamped to eight-bit range"
        )]
        {
            upsampled[index.saturating_mul(2).saturating_add(1)] = filtered as u16;
        }
    }
    upsampled[30] = edge[15];
    upsampled
}

/// Upsample the left edge for a Zone 3 directional predictor.
///
/// The decoder stores the edge in forward pixel order, while the reference
/// implementation walks the same edge backwards from the top-left corner.
/// The ninth source sample is top-left, which matters for the last filter
/// tap on non-flat edges.
fn upsample_intra_left_edge(edge: [u16; 8], top_left: u16) -> [u16; 15] {
    upsample_intra_left_edge_with_max(edge, top_left, 255)
}

fn upsample_intra_left_edge_with_max(edge: [u16; 8], top_left: u16, maximum: u16) -> [u16; 15] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let source: [u16; 9] = std::array::from_fn(|index| {
        if index < edge.len() {
            edge[7 - index]
        } else {
            top_left
        }
    });
    let mut upsampled = [0_u16; 15];
    for index in 0_usize..7 {
        upsampled[index.saturating_mul(2)] = source[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .min(source.len().saturating_sub(1));
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        let filtered = (sum.saturating_add(8) >> 4).clamp(0, i32::from(maximum));
        upsampled[index.saturating_mul(2).saturating_add(1)] =
            u16::try_from(filtered).unwrap_or(maximum);
    }
    upsampled[14] = source[7];
    let mut forward = [0_u16; 15];
    for (index, sample) in forward.iter_mut().enumerate() {
        *sample = upsampled[14 - index];
    }
    forward
}

#[expect(
    clippy::arithmetic_side_effects,
    reason = "the fixed sixteen-sample edge makes every reversed index in range"
)]
fn upsample_intra_left_edge_16(edge: [u16; 16], top_left: u16) -> [u16; 31] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let source: [u16; 17] = std::array::from_fn(|index| {
        if index < edge.len() {
            edge[15 - index]
        } else {
            top_left
        }
    });
    let mut upsampled = [0_u16; 31];
    for index in 0_usize..15 {
        upsampled[index.saturating_mul(2)] = source[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .min(source.len().saturating_sub(1));
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the upsampled intra edge is explicitly clamped to eight-bit range"
        )]
        {
            upsampled[index.saturating_mul(2).saturating_add(1)] =
                ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
        }
    }
    upsampled[30] = source[15];
    let mut forward = [0_u16; 31];
    for (index, sample) in forward.iter_mut().enumerate() {
        *sample = upsampled[30 - index];
    }
    forward
}

fn upsample_intra_left_edge_24(edge: [u16; 24], top_left: u16) -> [u16; 47] {
    const KERNEL: [i32; 4] = [-1, 9, 9, -1];
    let source: [u16; 25] = std::array::from_fn(|index| {
        if index < edge.len() {
            edge[23 - index]
        } else {
            top_left
        }
    });
    let mut upsampled = [0_u16; 47];
    for index in 0_usize..23 {
        upsampled[index.saturating_mul(2)] = source[index];
        let mut sum = 0_i32;
        for (tap, weight) in KERNEL.into_iter().enumerate() {
            let source_index = index
                .saturating_add(tap)
                .saturating_sub(1)
                .min(source.len().saturating_sub(1));
            sum = sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight));
        }
        #[expect(
            clippy::cast_sign_loss,
            reason = "the upsampled intra edge is explicitly clamped"
        )]
        {
            upsampled[index.saturating_mul(2).saturating_add(1)] =
                ((sum.saturating_add(8)) >> 4).clamp(0, 255) as u16;
        }
    }
    upsampled[46] = source[23];
    let mut forward = [0_u16; 47];
    for (index, sample) in forward.iter_mut().enumerate() {
        *sample = upsampled[46 - index];
    }
    forward
}

fn filter_intra_top_edge_16(edge: [u16; 16], top_left: u16, strength: usize) -> [u16; 16] {
    const KERNELS: [[i32; 5]; 3] = [[0, 4, 8, 4, 0], [0, 5, 6, 5, 0], [2, 4, 4, 4, 2]];
    let kernel = KERNELS[strength.saturating_sub(1).min(2)];
    std::array::from_fn(|index| {
        let sum = kernel
            .into_iter()
            .enumerate()
            .fold(0_i32, |sum, (tap, weight)| {
                let source_index = index.saturating_add(tap);
                let source = if source_index < 2 {
                    top_left
                } else {
                    edge[source_index
                        .saturating_sub(2)
                        .min(edge.len().saturating_sub(1))]
                };
                sum.saturating_add(i32::from(source).saturating_mul(weight))
            });
        #[expect(
            clippy::cast_sign_loss,
            reason = "the filtered intra edge is explicitly clamped to eight-bit range"
        )]
        {
            ((sum.saturating_add(8) >> 4).clamp(0, 255)) as u16
        }
    })
}

fn filter_intra_top_edge_16x4(edge: [u16; 16], top_left: u16, strength: usize) -> [u16; 20] {
    const KERNELS: [[i32; 5]; 3] = [[0, 4, 8, 4, 0], [0, 5, 6, 5, 0], [2, 4, 4, 4, 2]];
    let kernel = KERNELS[strength.saturating_sub(1).min(2)];
    let source: [u16; 21] = std::array::from_fn(|index| match index {
        0 => top_left,
        1..=16 => edge[index - 1],
        _ => edge[15],
    });
    std::array::from_fn(|index| {
        let sum = kernel
            .into_iter()
            .enumerate()
            .fold(0_i32, |sum, (tap, weight)| {
                let source_index = index
                    .saturating_add(tap)
                    .saturating_sub(1)
                    .min(source.len().saturating_sub(1));
                sum.saturating_add(i32::from(source[source_index]).saturating_mul(weight))
            });
        #[expect(
            clippy::cast_sign_loss,
            reason = "the filtered intra edge is explicitly clamped to eight-bit range"
        )]
        {
            ((sum.saturating_add(8) >> 4).clamp(0, 255)) as u16
        }
    })
}

fn filter_intra_top_edge_8(edge: [u16; 8], top_left: u16, strength: usize) -> [u16; 8] {
    filter_intra_top_edge_8_with_max(edge, top_left, strength, 255)
}

fn filter_intra_top_edge_8_with_max(
    edge: [u16; 8],
    top_left: u16,
    strength: usize,
    maximum: u16,
) -> [u16; 8] {
    const KERNELS: [[i32; 5]; 3] = [[0, 4, 8, 4, 0], [0, 5, 6, 5, 0], [2, 4, 4, 4, 2]];
    let kernel = KERNELS[strength.saturating_sub(1).min(2)];
    std::array::from_fn(|index| {
        let sum = kernel
            .into_iter()
            .enumerate()
            .fold(0_i32, |sum, (tap, weight)| {
                let source_index = index.saturating_add(tap).saturating_sub(1).min(edge.len());
                let source = if source_index == 0 {
                    top_left
                } else {
                    edge[source_index.saturating_sub(1)]
                };
                sum.saturating_add(i32::from(source).saturating_mul(weight))
            });
        u16::try_from((sum.saturating_add(8) >> 4).clamp(0, i32::from(maximum))).unwrap_or(maximum)
    })
}

fn intra_edge_filter_strength(edge_length: usize, angle: i32, smooth: bool) -> usize {
    if smooth {
        if edge_length <= 8 {
            if angle >= 64 {
                return 2;
            }
            if angle >= 40 {
                return 1;
            }
        } else if edge_length <= 16 {
            if angle >= 48 {
                return 2;
            }
            if angle >= 20 {
                return 1;
            }
        } else if edge_length <= 24 {
            if angle >= 4 {
                return 3;
            }
        } else {
            return 3;
        }
    } else if edge_length <= 8 {
        if angle >= 56 {
            return 1;
        }
    } else if edge_length <= 16 {
        if angle >= 40 {
            return 1;
        }
    } else if edge_length <= 24 {
        if angle >= 32 {
            return 3;
        }
        if angle >= 16 {
            return 2;
        }
        if angle >= 8 {
            return 1;
        }
    } else if edge_length <= 32 {
        if angle >= 32 {
            return 3;
        }
        if angle >= 4 {
            return 2;
        }
        return 1;
    } else {
        return 3;
    }
    0
}

/// Return whether AV1's intra-edge filter requests two-times edge sampling.
///
/// The reference predicate is intentionally based on the complete directional
/// edge extent, not on the transform's shorter side. Smooth predictors use
/// the sixteen-pixel limit after the reference's one-bit size adjustment.
fn intra_edge_upsample(edge_length: usize, angle: i32, smooth: bool) -> bool {
    let maximum_length = 16_usize >> usize::from(smooth);
    angle != 0 && angle < 40 && edge_length <= maximum_length
}

/// Build the AV1 Zone-2 predictor for one lossless 4×4 transform.
///
/// Lossless transform grids still run the ordinary intra predictor separately
/// for every transform.  In particular, the intra-edge filter is selected from
/// the transform dimensions (`4 + 4 == 8`) and consumes the transform's
/// already reconstructed top/left edges.  Preparing this state per transform
/// keeps the predictor independent of the enclosing leaf size.
fn lossless_diagonal_z2_prediction_4x4(
    top: [u16; 4],
    left: [u16; 4],
    top_left: u16,
    angle: i32,
    enable_intra_edge_filter: bool,
    smooth_edges: bool,
    maximum: u16,
) -> PortableResult<[u16; 16]> {
    const DR_INTRA_DERIVATIVE: [i32; 44] = [
        0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0, 71,
        64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
    ];
    (90 < angle && angle < 180).then_some(()).portable()?;
    let dy_index =
        usize::try_from(angle.saturating_sub(90) >> 1).map_err(|_| PortableUnavailable)?;
    let dx_index =
        usize::try_from(180_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
    let mut dy = *DR_INTRA_DERIVATIVE.get(dy_index).portable()?;
    let mut dx = *DR_INTRA_DERIVATIVE.get(dx_index).portable()?;
    let upsample_above = enable_intra_edge_filter && angle.saturating_sub(90) < 40;
    let upsample_left = enable_intra_edge_filter && 180_i32.saturating_sub(angle) < 40;

    let top = if enable_intra_edge_filter && !upsample_above {
        filter_intra_top_edge_4_with_max(
            top,
            top_left,
            angle.saturating_sub(90),
            smooth_edges,
            maximum,
        )
    } else {
        top
    };
    let left = if enable_intra_edge_filter && !upsample_left {
        filter_intra_left_edge_4_with_max(
            left,
            top_left,
            180_i32.saturating_sub(angle),
            smooth_edges,
            maximum,
        )
    } else {
        left
    };

    const TOP_LEFT_INDEX: usize = 16;
    let mut edge = [0_u16; 32];
    edge[TOP_LEFT_INDEX] = top_left;
    if upsample_above {
        let upsampled = upsample_z2_top_edge_4_with_max(
            [top[0], top[1], top[2], top[3], 0, 0, 0, 0],
            top_left,
            maximum,
        );
        edge[TOP_LEFT_INDEX..TOP_LEFT_INDEX.saturating_add(9)].copy_from_slice(&upsampled);
        dx = dx.saturating_mul(2);
    } else {
        edge[TOP_LEFT_INDEX.saturating_add(1)..TOP_LEFT_INDEX.saturating_add(5)]
            .copy_from_slice(&top);
    }

    if upsample_left {
        let upsampled = upsample_z2_left_edge_4_with_max(left, top_left, maximum);
        edge[TOP_LEFT_INDEX.saturating_sub(8)..=TOP_LEFT_INDEX].copy_from_slice(&upsampled);
        dy = dy.saturating_mul(2);
    } else {
        for (index, sample) in left.into_iter().enumerate() {
            edge[TOP_LEFT_INDEX.saturating_sub(1).saturating_sub(index)] = sample;
        }
    }

    let base_increment = if upsample_above { 2_i32 } else { 1_i32 };
    let left_index = TOP_LEFT_INDEX.saturating_sub(if upsample_left { 2 } else { 1 });
    let mut prediction = [0_u16; 16];
    for y_index in 0_usize..4 {
        let y = i32::try_from(y_index).map_err(|_| PortableUnavailable)?;
        let xpos = (if upsample_above { 128_i32 } else { 64_i32 })
            .saturating_sub(dx.saturating_mul(y.saturating_add(1)));
        let base_x = xpos >> 6;
        let frac_x = xpos & 0x3e;
        for x_index in 0_usize..4 {
            let x = i32::try_from(x_index).map_err(|_| PortableUnavailable)?;
            let base_x = base_x.saturating_add(base_increment.saturating_mul(x));
            let ypos = y
                .saturating_mul(if upsample_left { 128 } else { 64 })
                .saturating_sub(dy.saturating_mul(x.saturating_add(1)));
            let sample = if base_x >= 0 {
                let first = usize::try_from(
                    i32::try_from(TOP_LEFT_INDEX)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_add(base_x),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = first.saturating_add(1);
                let first = i32::from(*edge.get(first).portable()?);
                let second = i32::from(*edge.get(second).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_x))
                    .saturating_add(second.saturating_mul(frac_x))
                    .saturating_add(32)
                    >> 6
            } else {
                let base_y = ypos >> 6;
                let frac_y = ypos & 0x3e;
                let first = usize::try_from(
                    i32::try_from(left_index)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(base_y),
                )
                .map_err(|_| PortableUnavailable)?;
                let second = usize::try_from(
                    i32::try_from(left_index)
                        .map_err(|_| PortableUnavailable)?
                        .saturating_sub(base_y.saturating_add(1)),
                )
                .map_err(|_| PortableUnavailable)?;
                let first = i32::from(*edge.get(first).portable()?);
                let second = i32::from(*edge.get(second).portable()?);
                first
                    .saturating_mul(64_i32.saturating_sub(frac_y))
                    .saturating_add(second.saturating_mul(frac_y))
                    .saturating_add(32)
                    >> 6
            };
            prediction[y_index.saturating_mul(4).saturating_add(x_index)] =
                u16::try_from(sample.clamp(0, i32::from(maximum)))
                    .map_err(|_| PortableUnavailable)?;
        }
    }
    Ok(prediction)
}

fn diagonal_z3_predictor_sample(
    edge: &[u16],
    max_base_y: usize,
    dy: i32,
    base_increment: usize,
    x: usize,
    y: usize,
) -> PortableResult<u16> {
    diagonal_z3_predictor_sample_with_max(edge, max_base_y, dy, base_increment, x, y, 255)
}

fn diagonal_z3_predictor_sample_with_max(
    edge: &[u16],
    max_base_y: usize,
    dy: i32,
    base_increment: usize,
    x: usize,
    y: usize,
    maximum: u16,
) -> PortableResult<u16> {
    let x = i32::try_from(x).map_err(|_| PortableUnavailable)?;
    let y = i32::try_from(y).map_err(|_| PortableUnavailable)?;
    let base_increment = i32::try_from(base_increment).map_err(|_| PortableUnavailable)?;
    let position = dy.saturating_mul(x.saturating_add(1));
    let base = position >> 6;
    let fraction = position & 0x3e;
    let base = base.saturating_add(y.saturating_mul(base_increment));
    let base = usize::try_from(base).map_err(|_| PortableUnavailable)?;
    if base >= max_base_y {
        return edge.get(max_base_y).copied().ok_or(PortableUnavailable);
    }
    let first = i32::from(*edge.get(base).ok_or(PortableUnavailable)?);
    let second = i32::from(
        *edge
            .get(base.saturating_add(1))
            .ok_or(PortableUnavailable)?,
    );
    let sample = first
        .saturating_mul(64_i32.saturating_sub(fraction))
        .saturating_add(second.saturating_mul(fraction))
        .saturating_add(32)
        >> 6;
    u16::try_from(sample.clamp(0, i32::from(maximum))).map_err(|_| PortableUnavailable)
}

fn diagonal_z1_predictor_sample(
    edge: &[u16],
    max_base_x: usize,
    dx: i32,
    base_increment: usize,
    x: usize,
    y: usize,
) -> PortableResult<u16> {
    diagonal_z1_predictor_sample_with_max(edge, max_base_x, dx, base_increment, x, y, 255)
}

fn diagonal_z1_predictor_sample_with_max(
    edge: &[u16],
    max_base_x: usize,
    dx: i32,
    base_increment: usize,
    x: usize,
    y: usize,
    maximum: u16,
) -> PortableResult<u16> {
    let x = i32::try_from(x).map_err(|_| PortableUnavailable)?;
    let y = i32::try_from(y).map_err(|_| PortableUnavailable)?;
    let base_increment = i32::try_from(base_increment).map_err(|_| PortableUnavailable)?;
    let position = dx.saturating_mul(y.saturating_add(1));
    let base = (position >> 6).saturating_add(x.saturating_mul(base_increment));
    let fraction = position & 0x3e;
    let base = usize::try_from(base).map_err(|_| PortableUnavailable)?;
    if base >= max_base_x {
        return edge.get(max_base_x).copied().ok_or(PortableUnavailable);
    }
    let first = i32::from(*edge.get(base).ok_or(PortableUnavailable)?);
    let second = i32::from(
        *edge
            .get(base.saturating_add(1))
            .ok_or(PortableUnavailable)?,
    );
    let sample = first
        .saturating_mul(64_i32.saturating_sub(fraction))
        .saturating_add(second.saturating_mul(fraction))
        .saturating_add(32)
        >> 6;
    u16::try_from(sample.clamp(0, i32::from(maximum))).map_err(|_| PortableUnavailable)
}

fn monochrome_sample_from_above_neighbors(
    above: Option<&MonochromeLeaf>,
    above_right: &[Option<&MonochromeLeaf>; MONOCHROME_NEIGHBOR_CAPACITY],
    x: u32,
    y: u32,
) -> Option<u16> {
    above
        .and_then(|leaf| monochrome_sample_at(leaf, x, y))
        .or_else(|| {
            above_right
                .iter()
                .flatten()
                .find_map(|leaf| monochrome_sample_at(leaf, x, y))
        })
}

fn monochrome_sample_from_top_edge(
    above: Option<&MonochromeLeaf>,
    above_right: &[Option<&MonochromeLeaf>; MONOCHROME_NEIGHBOR_CAPACITY],
    x: u32,
    y: u32,
    origin_x: u32,
    coded_width: u32,
    intra_edges: super::geometry::IntraEdgeFlags,
) -> Option<u16> {
    let end_x = origin_x.checked_add(coded_width)?;
    if x >= end_x && !intra_edges.top_has_right(PixelLayout::Monochrome) {
        return None;
    }
    monochrome_sample_from_above_neighbors(above, above_right, x, y)
}

fn monochrome_sample_from_left_edge(
    left: Option<&MonochromeLeaf>,
    left_below: &[Option<&MonochromeLeaf>; MONOCHROME_NEIGHBOR_CAPACITY],
    x: u32,
    y: u32,
    origin_y: u32,
    coded_height: u32,
    intra_edges: super::geometry::IntraEdgeFlags,
) -> Option<u16> {
    let end_y = origin_y.checked_add(coded_height)?;
    if y >= end_y && !intra_edges.left_has_bottom(PixelLayout::Monochrome) {
        return None;
    }
    monochrome_sample_from_neighbors(left, left_below, x, y)
}

fn finish_monochrome_leaf(
    origin_x: u32,
    origin_y: u32,
    width: u32,
    height: u32,
    block_skipped: bool,
    coded_width: usize,
    grid_width: usize,
    grid_height: usize,
    active_grid_width: usize,
    active_grid_height: usize,
    coded_plane: ReconstructedPlane,
    predictor: LumaPredictor,
    coefficients: &[TransformCoefficients],
    palette_cache: PaletteCacheState,
) -> PortableResult<MonochromeLeaf> {
    let visible_width = usize::try_from(width).map_err(|_| PortableUnavailable)?;
    let visible_height = usize::try_from(height).map_err(|_| PortableUnavailable)?;
    let coded_height = grid_height.checked_mul(4).portable()?;
    let active_width = active_grid_width.checked_mul(4).portable()?;
    let active_height = active_grid_height.checked_mul(4).portable()?;
    let nominal_transform_count = grid_width.checked_mul(grid_height).portable()?;
    (visible_width != 0
        && visible_width == active_width
        && visible_width <= coded_width
        && visible_height != 0
        && visible_height == active_height
        && visible_height <= coded_height
        && active_grid_width <= grid_width
        && active_grid_height <= grid_height
        && coefficients.len() == nominal_transform_count
        && coded_plane.samples.len() == coded_width.checked_mul(coded_height).portable()?)
    .then_some(())
    .portable()?;
    let visible_len = visible_width.checked_mul(visible_height).portable()?;
    let mut visible = Vec::new();
    visible
        .try_reserve_exact(visible_len)
        .map_err(|_| PortableUnavailable)?;
    for row in coded_plane
        .samples
        .chunks_exact(coded_width)
        .take(visible_height)
    {
        visible.extend_from_slice(row.get(..visible_width).portable()?);
    }
    let mut right_contexts = [0x40_u8; 16];
    let mut bottom_contexts = [0x40_u8; 16];
    let transform_width = active_grid_width;
    let transform_height = active_grid_height;
    for row in 0..transform_height {
        right_contexts[row] = coefficient_residual_context(
            coefficients
                .get(
                    row.checked_mul(grid_width)
                        .and_then(|offset| offset.checked_add(transform_width.checked_sub(1)?))
                        .portable()?,
                )
                .portable()?,
        );
    }
    for column in 0..transform_width {
        bottom_contexts[column] = coefficient_residual_context(
            coefficients
                .get(
                    transform_height
                        .checked_sub(1)
                        .and_then(|row| row.checked_mul(grid_width))
                        .and_then(|offset| offset.checked_add(column))
                        .portable()?,
                )
                .portable()?,
        );
    }
    Ok(MonochromeLeaf {
        origin_x,
        origin_y,
        width,
        height,
        block_skipped,
        plane: ReconstructedPlane { samples: visible },
        predictor,
        right_contexts,
        bottom_contexts,
        palette_cache,
    })
}

fn reconstruct_monochrome_leaf(
    syntax: BlockSyntax,
    geometry: MonochromeBlockGeometry,
    neighbors: MonochromeNeighbors<'_>,
    sample_depth: SampleDepth,
    palette_map_arena: &PaletteMapArena,
    lossless_square64_arena: &LosslessSquare64CoefficientArena,
    enable_intra_edge_filter: bool,
) -> PortableResult<MonochromeLeaf> {
    let MonochromeBlockGeometry {
        origin_x,
        origin_y,
        width,
        height,
        active_grid_width: active_grid_width_u32,
        active_grid_height: active_grid_height_u32,
        transform_grid: _,
        intra_edges,
    } = geometry;
    let MonochromeNeighbors {
        above_left,
        above,
        above_right,
        left,
        left_below,
    } = neighbors;
    let smooth_edges = [above, left].into_iter().flatten().any(|leaf| {
        matches!(
            leaf.predictor,
            LumaPredictor::Smooth | LumaPredictor::SmoothVertical | LumaPredictor::SmoothHorizontal
        )
    });
    let BlockSyntax {
        block_skipped,
        luma_predictor,
        luma_angle,
        filter_intra_mode,
        coefficients,
        palette,
        transform_grid,
        chroma_sampling: ChromaSampling::Monochrome,
        reconstruction: ReconstructionPolicy::LosslessWht4x4,
        lossless_square64_coefficients,
        ..
    } = syntax
    else {
        return Err(PortableUnavailable);
    };
    let (grid_width, grid_height, _) = transform_grid.properties();
    let active_grid_width =
        usize::try_from(active_grid_width_u32).map_err(|_| PortableUnavailable)?;
    let active_grid_height =
        usize::try_from(active_grid_height_u32).map_err(|_| PortableUnavailable)?;
    let nominal_transform_count = grid_width.checked_mul(grid_height).portable()?;
    let active_transform_count = active_grid_width
        .checked_mul(active_grid_height)
        .portable()?;
    let large_grid = matches!(
        transform_grid,
        TransformGrid::Vertical16x64
            | TransformGrid::Vertical32x64
            | TransformGrid::Horizontal64x16
            | TransformGrid::Horizontal64x32
            | TransformGrid::Square64
    );
    (if large_grid {
        nominal_transform_count <= LosslessSquare64CoefficientArena::TRANSFORM_COUNT
    } else {
        nominal_transform_count <= 64
    } && active_transform_count != 0
        && active_transform_count <= nominal_transform_count
        && active_grid_width <= grid_width
        && active_grid_height <= grid_height)
        .then_some(())
        .portable()?;
    let zero_large = [[0_i32; 16]; LosslessSquare64CoefficientArena::TRANSFORM_COUNT];
    let coefficient_slice: &[TransformCoefficients] = if large_grid {
        lossless_square64_coefficients[1..]
            .iter()
            .all(Option::is_none)
            .then_some(())
            .portable()?;
        if block_skipped {
            lossless_square64_coefficients[0]
                .is_none()
                .then_some(())
                .portable()?;
            zero_large.get(..nominal_transform_count).portable()?
        } else {
            let span = lossless_square64_coefficients[0].portable()?;
            let coefficients = lossless_square64_arena.coefficients(span)?;
            (coefficients.len() == nominal_transform_count)
                .then_some(())
                .portable()?;
            coefficients
        }
    } else {
        lossless_square64_coefficients
            .iter()
            .all(Option::is_none)
            .then_some(())
            .portable()?;
        coefficients[0].get(..nominal_transform_count).portable()?
    };
    let coded_width = grid_width.saturating_mul(4);
    let coded_height = grid_height.saturating_mul(4);
    let active_width_pixels = active_grid_width.checked_mul(4).portable()?;
    let active_height_pixels = active_grid_height.checked_mul(4).portable()?;
    let active_width_u32 = u32::try_from(active_width_pixels).map_err(|_| PortableUnavailable)?;
    let active_height_u32 = u32::try_from(active_height_pixels).map_err(|_| PortableUnavailable)?;
    let has_top = above.is_some() || above_right.iter().any(Option::is_some);
    let has_left = left.is_some() || left_below.iter().any(Option::is_some);
    let sample_top = |x: u32, y: u32| {
        monochrome_sample_from_top_edge(
            above,
            &above_right,
            x,
            y,
            origin_x,
            active_width_u32,
            intra_edges,
        )
    };
    let sample_left = |x: u32, y: u32| {
        monochrome_sample_from_left_edge(
            left,
            &left_below,
            x,
            y,
            origin_y,
            active_height_u32,
            intra_edges,
        )
    };
    let top_default = sample_depth.top_edge_default();
    let left_default = sample_depth.left_edge_default();
    let midpoint = sample_depth.midpoint();
    let maximum = sample_depth.maximum();
    let palette_cache = palette.cache_state();
    if palette.y.is_present() {
        let prediction_len = coded_width.checked_mul(coded_height).portable()?;
        let mut prediction = Vec::new();
        prediction
            .try_reserve_exact(prediction_len)
            .map_err(|_| PortableUnavailable)?;
        prediction.resize(prediction_len, 0);
        full_palette_prediction_into(
            &mut prediction,
            palette.y,
            palette.y_view(palette_map_arena)?,
        )?;
        let coded_plane = reconstruct_lossless_wht_prediction(
            prediction,
            coefficient_slice,
            grid_width,
            grid_height,
            sample_depth,
        )?;
        return finish_monochrome_leaf(
            origin_x,
            origin_y,
            width,
            height,
            block_skipped,
            coded_width,
            grid_width,
            grid_height,
            active_grid_width,
            active_grid_height,
            coded_plane,
            luma_predictor,
            coefficient_slice,
            palette_cache,
        );
    }
    let sample_len = coded_width.checked_mul(coded_height).portable()?;
    let mut samples = Vec::new();
    samples
        .try_reserve_exact(sample_len)
        .map_err(|_| PortableUnavailable)?;
    samples.resize(sample_len, 0);
    let fallback_top = if !has_top {
        origin_x
            .checked_sub(1)
            .and_then(|left_x| sample_left(left_x, origin_y))
            .unwrap_or(top_default)
    } else {
        top_default
    };
    let fallback_left = if !has_left {
        origin_y
            .checked_sub(1)
            .and_then(|top_y| sample_top(origin_x, top_y))
            .unwrap_or(left_default)
    } else {
        left_default
    };
    let angular_luma_predictor = matches!(
        luma_predictor,
        LumaPredictor::Vertical
            | LumaPredictor::Horizontal
            | LumaPredictor::Diagonal45
            | LumaPredictor::DiagonalDownRight
            | LumaPredictor::Diagonal113
            | LumaPredictor::Diagonal157
            | LumaPredictor::Diagonal203
            | LumaPredictor::Diagonal67
    );
    let z1_upsample =
        enable_intra_edge_filter && luma_angle.is_some_and(|angle| 50 < angle && angle < 90);
    let z3_upsample =
        enable_intra_edge_filter && luma_angle.is_some_and(|angle| 180 < angle && angle < 220);
    let filter_intra_prediction = if let Some(mode) = filter_intra_mode {
        let mut top = Vec::new();
        top.try_reserve_exact(coded_width)
            .map_err(|_| PortableUnavailable)?;
        let mut top_last = fallback_top;
        for column in 0..coded_width {
            if has_top {
                let x = origin_x
                    .checked_add(u32::try_from(column).map_err(|_| PortableUnavailable)?)
                    .ok_or(PortableUnavailable)?;
                if let Some(sample) =
                    sample_top(x, origin_y.checked_sub(1).ok_or(PortableUnavailable)?)
                {
                    top_last = sample;
                }
            }
            top.push(top_last);
        }
        let mut left_edge = Vec::new();
        left_edge
            .try_reserve_exact(coded_height)
            .map_err(|_| PortableUnavailable)?;
        let mut left_last = fallback_left;
        for row in 0..coded_height {
            if has_left {
                let y = origin_y
                    .checked_add(u32::try_from(row).map_err(|_| PortableUnavailable)?)
                    .ok_or(PortableUnavailable)?;
                if let Some(sample) =
                    sample_left(origin_x.checked_sub(1).ok_or(PortableUnavailable)?, y)
                {
                    left_last = sample;
                }
            }
            left_edge.push(left_last);
        }
        let top_left = if has_top {
            if has_left && origin_x > 0 && origin_y > 0 {
                let top_left_x = origin_x.saturating_sub(1);
                let top_left_y = origin_y.saturating_sub(1);
                [above_left, above, left]
                    .into_iter()
                    .flatten()
                    .find_map(|leaf| monochrome_sample_at(leaf, top_left_x, top_left_y))
                    .or_else(|| {
                        left_below
                            .iter()
                            .flatten()
                            .find_map(|leaf| monochrome_sample_at(leaf, top_left_x, top_left_y))
                    })
                    .or_else(|| top.first().copied())
                    .unwrap_or(midpoint)
            } else {
                top.first().copied().unwrap_or(midpoint)
            }
        } else if has_left {
            left_edge.first().copied().unwrap_or(midpoint)
        } else {
            midpoint
        };
        Some(reconstruct_filter_intra_prediction_with_max(
            mode,
            coded_width,
            coded_height,
            top_left,
            &top,
            &left_edge,
            maximum,
        )?)
    } else {
        None
    };
    let diagonal_z3_edges = if angular_luma_predictor && luma_angle.is_some_and(|angle| angle > 180)
    {
        const DR_INTRA_DERIVATIVE: [i32; 44] = [
            0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0,
            71, 64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
        ];
        let angle = luma_angle.ok_or(PortableUnavailable)?;
        let dy_index =
            usize::try_from(270_i32.saturating_sub(angle) >> 1).map_err(|_| PortableUnavailable)?;
        let dy = *DR_INTRA_DERIVATIVE
            .get(dy_index)
            .ok_or(PortableUnavailable)?;
        let max_base_y = active_width_pixels
            .saturating_add(active_height_pixels)
            .saturating_sub(1);
        let left_x = origin_x.checked_sub(1);
        let edge_len = max_base_y.saturating_add(1);
        let mut edge = Vec::new();
        edge.try_reserve_exact(edge_len)
            .map_err(|_| PortableUnavailable)?;
        let mut last = midpoint;
        for row in 0..=max_base_y {
            if let (Some(left_x), Some(row)) = (
                left_x,
                u32::try_from(row)
                    .ok()
                    .and_then(|row| origin_y.checked_add(row)),
            ) && let Some(sample) = sample_left(left_x, row)
            {
                last = sample;
            }
            edge.push(last);
        }
        Some((edge, max_base_y, dy))
    } else {
        None
    };
    let diagonal_z1_edges = if angular_luma_predictor && luma_angle.is_some_and(|angle| angle < 90)
    {
        // ✅ VERIFIED: AOM v3.13.1 `reconintra.c` zone-1 prediction. D45
        // advances through the top edge and extends the last available
        // top-right sample when the neighboring leaf ends early.
        const DR_INTRA_DERIVATIVE: [i32; 44] = [
            0, 1023, 0, 547, 372, 0, 0, 273, 215, 0, 178, 151, 0, 132, 116, 0, 102, 0, 90, 80, 0,
            71, 64, 0, 57, 51, 0, 45, 0, 40, 35, 0, 31, 27, 0, 23, 19, 0, 15, 0, 11, 0, 7, 3,
        ];
        let angle = luma_angle.ok_or(PortableUnavailable)?;
        let angle_index =
            usize::try_from(angle.saturating_div(2)).map_err(|_| PortableUnavailable)?;
        let dx = *DR_INTRA_DERIVATIVE
            .get(angle_index)
            .filter(|&&value| value > 0)
            .ok_or(PortableUnavailable)?;
        let max_base_x = active_width_pixels
            .saturating_add(active_height_pixels)
            .saturating_sub(1);
        let top_y = origin_y.checked_sub(1);
        let left_x = origin_x.checked_sub(1);
        let mut last = if above.is_none() {
            left_x
                .and_then(|x| sample_left(x, origin_y))
                .unwrap_or(top_default)
        } else {
            top_default
        };
        let edge_len = max_base_x.saturating_add(1);
        let mut edge = Vec::new();
        edge.try_reserve_exact(edge_len)
            .map_err(|_| PortableUnavailable)?;
        for column in 0..=max_base_x {
            if let (Some(top_y), Some(column)) = (
                top_y,
                u32::try_from(column)
                    .ok()
                    .and_then(|column| origin_x.checked_add(column)),
            ) && let Some(sample) = sample_top(column, top_y)
            {
                last = sample;
            }
            edge.push(last);
        }
        Some((edge, max_base_x, dx))
    } else {
        None
    };
    for row in 0..active_grid_height {
        for column in 0..active_grid_width {
            let transform_index = row
                .checked_mul(grid_width)
                .and_then(|offset| offset.checked_add(column))
                .portable()?;
            let coefficient = *coefficient_slice.get(transform_index).portable()?;
            let mut top = [fallback_top; 4];
            let mut left_edge = [fallback_left; 4];
            if row > 0 {
                let source_start = row
                    .saturating_mul(4)
                    .saturating_sub(1)
                    .saturating_mul(coded_width)
                    .saturating_add(column.saturating_mul(4));
                top.copy_from_slice(&samples[source_start..source_start.saturating_add(4)]);
            } else if above.is_some() || above_right.iter().any(Option::is_some) {
                let top_y = origin_y.checked_sub(1).ok_or(PortableUnavailable)?;
                for (offset, value) in top.iter_mut().enumerate() {
                    let x = origin_x
                        .checked_add(
                            u32::try_from(column.saturating_mul(4).saturating_add(offset))
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .ok_or(PortableUnavailable)?;
                    *value = sample_top(x, top_y).ok_or(PortableUnavailable)?;
                }
            }
            if column > 0 {
                for (offset, value) in left_edge.iter_mut().enumerate() {
                    let index = row
                        .saturating_mul(4)
                        .saturating_add(offset)
                        .saturating_mul(coded_width)
                        .saturating_add(column.saturating_mul(4).saturating_sub(1));
                    *value = samples[index];
                }
            } else if has_left {
                let left_x = origin_x.checked_sub(1).ok_or(PortableUnavailable)?;
                let mut last = left_below
                    .iter()
                    .flatten()
                    .next()
                    .copied()
                    .or(left)
                    .and_then(|leaf| {
                        leaf.origin_y
                            .checked_add(leaf.height.saturating_sub(1))
                            .and_then(|y| monochrome_sample_at(leaf, left_x, y))
                    })
                    .unwrap_or(fallback_left);
                for (offset, value) in left_edge.iter_mut().enumerate() {
                    let y = origin_y
                        .checked_add(
                            u32::try_from(row.saturating_mul(4).saturating_add(offset))
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .ok_or(PortableUnavailable)?;
                    if let Some(sample) = sample_left(left_x, y) {
                        last = sample;
                    }
                    *value = last;
                }
            }
            // AV1 extends a missing edge from the edge that is available. This
            // matters for transform blocks inside an origin leaf: when the frame
            // has no external top edge but the transform has a reconstructed left
            // edge, the top edge is the left edge's first sample. The symmetric
            // rule applies to the first transform column below a reconstructed
            // top edge. Filling both edges with the frame midpoint changes DC
            // prediction for every skipped transform in a lossless block.
            if row == 0 && above.is_none() && (column > 0 || has_left) {
                top.fill(left_edge[0]);
            }
            if column == 0 && left.is_none() && !has_left && (row > 0 || has_top) {
                left_edge.fill(top[0]);
            }
            let top_available = row > 0 || has_top;
            let left_available = column > 0 || has_left;
            let transform_predictor = resolve_lossless_predictor(
                lossless_luma_predictor(luma_predictor),
                luma_angle,
                top_available,
                left_available,
            );
            let prediction_top_left = if row > 0 && column > 0 {
                let index = row
                    .saturating_mul(4)
                    .saturating_sub(1)
                    .saturating_mul(coded_width)
                    .saturating_add(column.saturating_mul(4).saturating_sub(1));
                *samples.get(index).ok_or(PortableUnavailable)?
            } else if row > 0 {
                if has_left && origin_x > 0 {
                    let x = origin_x.saturating_sub(1);
                    let y = origin_y
                        .checked_add(
                            u32::try_from(row.saturating_mul(4).saturating_sub(1))
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .ok_or(PortableUnavailable)?;
                    sample_left(x, y).unwrap_or(top[0])
                } else {
                    top[0]
                }
            } else if column > 0 {
                if (above.is_some() || above_right.iter().any(Option::is_some)) && origin_y > 0 {
                    let x = origin_x
                        .checked_add(
                            u32::try_from(column.saturating_mul(4).saturating_sub(1))
                                .map_err(|_| PortableUnavailable)?,
                        )
                        .ok_or(PortableUnavailable)?;
                    let y = origin_y.saturating_sub(1);
                    sample_top(x, y).unwrap_or(left_edge[0])
                } else {
                    left_edge[0]
                }
            } else if has_top {
                if has_left {
                    let x = origin_x.checked_sub(1).ok_or(PortableUnavailable)?;
                    let y = origin_y.checked_sub(1).ok_or(PortableUnavailable)?;
                    [above_left, above, left]
                        .into_iter()
                        .flatten()
                        .find_map(|leaf| monochrome_sample_at(leaf, x, y))
                        .or_else(|| {
                            left_below
                                .iter()
                                .flatten()
                                .find_map(|leaf| monochrome_sample_at(leaf, x, y))
                        })
                        .unwrap_or(top[0])
                } else {
                    top[0]
                }
            } else if has_left {
                left_edge[0]
            } else {
                midpoint
            };

            let predictor = match luma_predictor {
                LumaPredictor::Dc => dc_predictor(top, left_edge),
                LumaPredictor::Vertical => top[0],
                LumaPredictor::Horizontal => left_edge[0],
                LumaPredictor::Diagonal45 => midpoint,
                LumaPredictor::DiagonalDownRight => midpoint,
                LumaPredictor::Diagonal113 => midpoint,
                LumaPredictor::Diagonal157 => midpoint,
                LumaPredictor::Diagonal67 => midpoint,
                LumaPredictor::Diagonal203 => midpoint,
                LumaPredictor::Paeth => midpoint,
                LumaPredictor::Smooth => midpoint,
                LumaPredictor::SmoothVertical => midpoint,
                LumaPredictor::SmoothHorizontal => midpoint,
            };
            let residual = inverse_wht_4x4(coefficient);
            for (offset, value) in residual.into_iter().enumerate() {
                let local_row = offset / 4;
                let local_column = offset % 4;
                let prediction = match transform_predictor {
                    LosslessPredictor::Vertical => top[local_column],
                    LosslessPredictor::Horizontal => left_edge[local_row],
                    LosslessPredictor::Dc => {
                        if let Some(filter_prediction) = filter_intra_prediction.as_ref() {
                            let index = row
                                .saturating_mul(4)
                                .saturating_add(local_row)
                                .saturating_mul(coded_width)
                                .saturating_add(column.saturating_mul(4))
                                .saturating_add(local_column);
                            *filter_prediction.get(index).ok_or(PortableUnavailable)?
                        } else {
                            predictor
                        }
                    }
                    LosslessPredictor::Diagonal45 | LosslessPredictor::Diagonal67 => {
                        let (_, _, dx) = diagonal_z1_edges.as_ref().ok_or(PortableUnavailable)?;
                        let angle = luma_angle.ok_or(PortableUnavailable)?;
                        let mut edge = [top_default; 8];
                        if row > 0 {
                            let start = row
                                .saturating_mul(4)
                                .saturating_sub(1)
                                .saturating_mul(coded_width)
                                .saturating_add(column.saturating_mul(4));
                            let count = 8_usize
                                .min(active_width_pixels.saturating_sub(column.saturating_mul(4)));
                            let available = samples
                                .get(start..start.saturating_add(count))
                                .ok_or(PortableUnavailable)?;
                            for (index, sample) in available.iter().copied().enumerate() {
                                edge[index] = sample;
                            }
                            if let Some(&last) = available.last() {
                                edge[available.len()..].fill(last);
                            }
                        } else if let Some(top_y) = origin_y.checked_sub(1) {
                            let mut last = top[0];
                            for (index, value) in edge.iter_mut().enumerate() {
                                let x = origin_x
                                    .checked_add(
                                        u32::try_from(
                                            column.saturating_mul(4).saturating_add(index),
                                        )
                                        .map_err(|_| PortableUnavailable)?,
                                    )
                                    .ok_or(PortableUnavailable)?;
                                if let Some(sample) = sample_top(x, top_y) {
                                    last = sample;
                                }
                                *value = last;
                            }
                        } else {
                            edge.fill(top[0]);
                        }
                        let filtered_edge = if enable_intra_edge_filter && !z1_upsample {
                            let strength = intra_edge_filter_strength(
                                8,
                                90_i32.saturating_sub(angle),
                                smooth_edges,
                            );
                            if strength == 0 {
                                edge
                            } else {
                                filter_intra_top_edge_8_with_max(
                                    edge,
                                    prediction_top_left,
                                    strength,
                                    maximum,
                                )
                            }
                        } else {
                            edge
                        };
                        let upsampled_edge = upsample_intra_top_edge_with_max(
                            filtered_edge,
                            prediction_top_left,
                            maximum,
                        );
                        let (edge, max_base_x, dx) = if z1_upsample {
                            (&upsampled_edge[..], 14, (*dx).saturating_mul(2))
                        } else {
                            (&filtered_edge[..], 7, *dx)
                        };
                        diagonal_z1_predictor_sample_with_max(
                            edge,
                            max_base_x,
                            dx,
                            if z1_upsample { 2 } else { 1 },
                            local_column,
                            local_row,
                            maximum,
                        )?
                    }
                    LosslessPredictor::DiagonalDownRight
                    | LosslessPredictor::Diagonal113
                    | LosslessPredictor::Diagonal157 => {
                        let diagonal_prediction = lossless_diagonal_z2_prediction_4x4(
                            top,
                            left_edge,
                            prediction_top_left,
                            luma_angle.ok_or(PortableUnavailable)?,
                            enable_intra_edge_filter,
                            smooth_edges,
                            maximum,
                        )?;
                        diagonal_prediction
                            .get(offset)
                            .copied()
                            .ok_or(PortableUnavailable)?
                    }
                    LosslessPredictor::Diagonal203 => {
                        let (_, _, dy) = diagonal_z3_edges.as_ref().ok_or(PortableUnavailable)?;
                        let angle = luma_angle.ok_or(PortableUnavailable)?;
                        let mut edge = [left_default; 8];
                        if column > 0 {
                            let start = row
                                .saturating_mul(4)
                                .saturating_mul(coded_width)
                                .saturating_add(column.saturating_mul(4).saturating_sub(1));
                            let available_height = 4_usize
                                .min(active_height_pixels.saturating_sub(row.saturating_mul(4)));
                            for (offset, sample) in
                                edge.iter_mut().take(available_height).enumerate()
                            {
                                *sample = *samples
                                    .get(start.saturating_add(offset.saturating_mul(coded_width)))
                                    .ok_or(PortableUnavailable)?;
                            }
                            let last = edge
                                .get(available_height.saturating_sub(1))
                                .copied()
                                .unwrap_or(left_default);
                            edge[available_height..].fill(last);
                        } else {
                            let mut last = left_edge[3];
                            for (index, value) in edge.iter_mut().enumerate() {
                                let y = origin_y
                                    .checked_add(
                                        u32::try_from(row.saturating_mul(4).saturating_add(index))
                                            .map_err(|_| PortableUnavailable)?,
                                    )
                                    .ok_or(PortableUnavailable)?;
                                if let Some(sample) = sample_left(
                                    origin_x.checked_sub(1).ok_or(PortableUnavailable)?,
                                    y,
                                ) {
                                    last = sample;
                                }
                                *value = last;
                            }
                        }
                        let filtered_edge = if enable_intra_edge_filter && !z3_upsample {
                            let strength = intra_edge_filter_strength(
                                8,
                                angle.saturating_sub(180),
                                smooth_edges,
                            );
                            if strength == 0 {
                                edge
                            } else {
                                filter_z2_left_edge_with_max(
                                    edge,
                                    prediction_top_left,
                                    strength,
                                    maximum,
                                )
                            }
                        } else {
                            edge
                        };
                        let upsampled_edge = upsample_intra_left_edge_with_max(
                            filtered_edge,
                            prediction_top_left,
                            maximum,
                        );
                        let (edge, max_base_y, dy) = if z3_upsample {
                            (&upsampled_edge[..], 14, (*dy).saturating_mul(2))
                        } else {
                            (&filtered_edge[..], 7, *dy)
                        };
                        diagonal_z3_predictor_sample_with_max(
                            edge,
                            max_base_y,
                            dy,
                            if z3_upsample { 2 } else { 1 },
                            local_column,
                            local_row,
                            maximum,
                        )?
                    }
                    LosslessPredictor::SmoothVertical => {
                        let vertical_weight = i32::from(
                            *smooth_weight_table(4)?
                                .get(local_row)
                                .ok_or(PortableUnavailable)?,
                        );
                        let bottom = *left_edge.last().ok_or(PortableUnavailable)?;
                        let value = vertical_weight
                            .saturating_mul(i32::from(top[local_column]))
                            .saturating_add(
                                256_i32
                                    .saturating_sub(vertical_weight)
                                    .saturating_mul(i32::from(bottom)),
                            )
                            .saturating_add(128)
                            >> 8;
                        u16::try_from(value.clamp(0, i32::from(maximum)))
                            .map_err(|_| PortableUnavailable)?
                    }
                    LosslessPredictor::Paeth => paeth_predictor(
                        top[local_column],
                        left_edge[local_row],
                        prediction_top_left,
                    ),
                    LosslessPredictor::Smooth => {
                        let vertical_weights = smooth_weight_table(4)?;
                        let horizontal_weights = smooth_weight_table(4)?;
                        let right = *top.last().ok_or(PortableUnavailable)?;
                        let bottom = *left_edge.last().ok_or(PortableUnavailable)?;
                        let vertical_weight =
                            i32::from(*vertical_weights.get(local_row).ok_or(PortableUnavailable)?);
                        let horizontal_weight = i32::from(
                            *horizontal_weights
                                .get(local_column)
                                .ok_or(PortableUnavailable)?,
                        );
                        let value = vertical_weight
                            .saturating_mul(i32::from(top[local_column]))
                            .saturating_add(
                                256_i32
                                    .saturating_sub(vertical_weight)
                                    .saturating_mul(i32::from(bottom)),
                            )
                            .saturating_add(
                                horizontal_weight.saturating_mul(i32::from(left_edge[local_row])),
                            )
                            .saturating_add(
                                256_i32
                                    .saturating_sub(horizontal_weight)
                                    .saturating_mul(i32::from(right)),
                            )
                            .saturating_add(256)
                            >> 9;
                        u16::try_from(value.clamp(0, i32::from(maximum)))
                            .map_err(|_| PortableUnavailable)?
                    }
                    LosslessPredictor::SmoothHorizontal => {
                        let horizontal_weight = i32::from(
                            *smooth_weight_table(4)?
                                .get(local_column)
                                .ok_or(PortableUnavailable)?,
                        );
                        let right = *top.last().ok_or(PortableUnavailable)?;
                        let value = horizontal_weight
                            .saturating_mul(i32::from(left_edge[local_row]))
                            .saturating_add(
                                256_i32
                                    .saturating_sub(horizontal_weight)
                                    .saturating_mul(i32::from(right)),
                            )
                            .saturating_add(128)
                            >> 8;
                        u16::try_from(value.clamp(0, i32::from(maximum)))
                            .map_err(|_| PortableUnavailable)?
                    }
                };
                let reconstructed = u16::try_from(
                    i32::from(prediction)
                        .saturating_add(value)
                        .clamp(0, i32::from(maximum)),
                )
                .map_err(|_| PortableUnavailable)?;
                let output_index = row
                    .saturating_mul(4)
                    .saturating_add(local_row)
                    .saturating_mul(coded_width)
                    .saturating_add(column.saturating_mul(4))
                    .saturating_add(local_column);
                samples[output_index] = reconstructed;
            }
        }
    }
    finish_monochrome_leaf(
        origin_x,
        origin_y,
        width,
        height,
        block_skipped,
        coded_width,
        grid_width,
        grid_height,
        active_grid_width,
        active_grid_height,
        ReconstructedPlane { samples },
        luma_predictor,
        coefficient_slice,
        palette_cache,
    )
}

/// Decode one closed 4:2:0 lossless leaf.
pub(super) fn decode_first_lossless_420_leaf(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    width: u32,
    height: u32,
    transform_grid: TransformGrid,
    tools: BlockTools,
) -> PortableResult<FirstLeaf> {
    let (_, _, use_filter_intra) = transform_grid.properties();
    let mut cdfs = BlockCdfs::defaults(use_filter_intra);
    let mut palette_map_arena = PaletteMapArena::new();
    palette_map_arena.begin_leaf()?;
    let syntax = decode_syntax_with_palette_entropy(
        decoder,
        &mut cdfs,
        &mut palette_map_arena,
        transform_grid,
        ChromaSampling::Subsampled420,
        SyntaxPolicy {
            spatial_luma_context: SpatialLumaContext::Origin,
            coefficient_policy: CoefficientPolicy::DcOrSkipped,
            quantization_syntax: QuantizationSyntax::Lossless,
            allow_horizontal_chroma: false,
            allow_diagonal_chroma: false,
            allow_diagonal_luma: false,
            allow_smooth_chroma: false,
            allow_smooth_luma: false,
        },
        tools,
        Some(PaletteEntropyDimensions::from_visible(
            transform_grid.block_size(),
            width,
            height,
        )?),
    )?;
    let predictors = origin_predictors(syntax.luma_predictor);
    let leaf = reconstruct_leaf(syntax, predictors, &palette_map_arena)?;
    Ok(crop_lossless_420_leaf(with_palette_cache(
        visible_leaf(
            leaf,
            syntax.block_skipped,
            Some(syntax.chroma_predictor),
            transform_grid,
            width,
            height,
            ChromaSampling::Subsampled420,
            luma_transform_context(transform_grid, false),
            false,
            ([0x40; 16], [0x40; 16]),
        ),
        syntax.palette.cache_state(),
    )))
}

fn crop_lossless_420_leaf(mut leaf: FirstLeaf) -> FirstLeaf {
    let chroma_width = leaf.width.div_ceil(2);
    let chroma_height = leaf.height.div_ceil(2);
    let coded_chroma_width = chroma_width.max(4) as usize;
    let [luma, u, v] = leaf.planes;
    leaf.planes = [
        luma,
        visible_plane(&u, coded_chroma_width, chroma_width, chroma_height),
        visible_plane(&v, coded_chroma_width, chroma_width, chroma_height),
    ];
    leaf
}

/// Decode the first closed lossy 4:2:0 leaf syntax class.
pub(super) fn decode_first_lossy_420_leaf(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    width: u32,
    height: u32,
    quantization: LossyQuantization,
    tools: BlockTools,
) -> PortableResult<FirstLeaf> {
    let mut state = Lossy420Decoder::with_qindex(quantization.qindex, false).portable()?;
    state.decode_origin(decoder, width, height, quantization, tools)
}

/// Decode the narrow origin 16x16 lossy I444 reconstruction class.
pub(super) fn decode_first_lossy_444_16x16_leaf(
    decoder: &mut RangeDecoder<'_, '_, '_>,
    quantization: LossyQuantization,
    tools: BlockTools,
) -> PortableResult<FirstLeaf> {
    let mut state = Lossy420Decoder::with_qindex(quantization.qindex, false).portable()?;
    let decoded = state.decode_origin_full(
        decoder,
        16,
        16,
        TransformGrid::Square16,
        quantization,
        tools,
    );
    let leaf = decoded?;
    let has_nonzero_cfl = matches!(
        leaf.chroma_predictor,
        Some(ChromaPredictor::Cfl { alpha_u, alpha_v })
            if alpha_u != 0 && alpha_v != 0
    );
    let all_planes_are_square16 = leaf
        .planes
        .iter()
        .all(|plane| plane.samples.len() == 16 * 16);
    if leaf.width != 16
        || leaf.height != 16
        || !matches!(leaf.luma_predictor, LumaPredictor::Dc)
        || !has_nonzero_cfl
        || leaf.luma_transform_split
        || !all_planes_are_square16
    {
        return Err(PortableUnavailable);
    }
    Ok(leaf)
}

fn reject_unhandled_lossy_luma_64x64_split(syntax: &BlockSyntax) -> PortableResult<()> {
    syntax
        .lossy_luma_64x64_split
        .is_none()
        .then_some(())
        .portable()
}

/// Shared adaptive state for a sequence of lossy 4:2:0 leaves.
///
/// AV1 updates the block CDFs after every symbol. A frame walker therefore
/// cannot create a fresh `BlockCdfs` for each terminal block without changing
/// the meaning of all later range-coded bits. This state is private decoder
/// machinery; it is not exposed as a public codec API.
#[derive(Clone, Copy)]
struct PendingBlockGeometry {
    block_size: BlockSize,
    palette_entropy_dimensions: PaletteEntropyDimensions,
    cdef_slot: usize,
    cdef_coverage: u8,
}

struct GenericCoefficientState {
    above: [[u8; 32]; 3],
    left: [[u8; 32]; 3],
}

impl GenericCoefficientState {
    const fn origin() -> Self {
        Self {
            above: [[0x40; 32]; 3],
            left: [[0x40; 32]; 3],
        }
    }

    fn following(neighbors: SpatialNeighbors) -> Self {
        Self {
            above: [
                neighbors.above_luma_contexts,
                neighbors.above_chroma_contexts[0],
                neighbors.above_chroma_contexts[1],
            ],
            left: [
                neighbors.left_luma_contexts,
                neighbors.left_chroma_contexts[0],
                neighbors.left_chroma_contexts[1],
            ],
        }
    }
}

pub(super) fn generic_plane_geometry(
    block_size: BlockSize,
    chroma_sampling: ChromaSampling,
    plane: usize,
    visible_width: u32,
    visible_height: u32,
) -> PortableResult<(usize, usize, usize, usize)> {
    fn sampled_axis(pixels: u32, scale: u32) -> PortableResult<usize> {
        (pixels != 0 && scale != 0).then_some(()).portable()?;
        let samples = if scale == 1 {
            pixels
        } else {
            // Subsampling operates on complete 4x4 luma units, not on the
            // raw pixel count. An odd final luma MI therefore owns one full
            // 4px chroma unit instead of a two-pixel partial unit.
            pixels
                .div_ceil(4)
                .div_ceil(scale)
                .checked_mul(4)
                .portable()?
        };
        usize::try_from(samples).map_err(|_| PortableUnavailable)
    }

    if plane != 0 && matches!(chroma_sampling, ChromaSampling::Monochrome) {
        // `FirstLeaf` intentionally retains a three-plane carrier, but a
        // monochrome leaf never visits or publishes U/V. Keep only the
        // canonical dummy transform footprint instead of allocating two
        // block-sized midpoint rasters for 128-pixel leaves.
        return Ok((4, 4, 4, 4));
    }
    let (coded_width, coded_height) = block_size.pixel_dimensions();
    let (scale_x, scale_y) = chroma_sampling.plane_subsampling(plane);
    let scale_x = u32::try_from(scale_x).map_err(|_| PortableUnavailable)?;
    let scale_y = u32::try_from(scale_y).map_err(|_| PortableUnavailable)?;
    let coded_width = sampled_axis(coded_width, scale_x)?.max(usize::from(plane != 0) * 4);
    let coded_height = sampled_axis(coded_height, scale_y)?.max(usize::from(plane != 0) * 4);
    let active_width = sampled_axis(visible_width, scale_x)?
        .max(usize::from(plane != 0) * 4)
        .min(coded_width);
    let active_height = sampled_axis(visible_height, scale_y)?
        .max(usize::from(plane != 0) * 4)
        .min(coded_height);
    Ok((coded_width, coded_height, active_width, active_height))
}

#[derive(Clone, Copy)]
struct BlockSegmentState {
    delta_q: i32,
    qindex: u32,
    lossless: bool,
}

#[derive(Clone, Copy)]
pub(super) struct ObmcNeighbor<'a> {
    pub(super) surface: &'a FrameSurface,
    pub(super) scale: ScaleFactors,
    pub(super) motion: MotionVector,
    pub(super) filters: [InterpolationFilter; 2],
    /// Absolute origin of the current block in the tile's 4x4 grid.
    pub(super) origin_x_b4: u32,
    pub(super) origin_y_b4: u32,
    /// Staged and blended dimensions in 4x4 units.  The top pass stores the
    /// rounded source height separately from its full overlap height.
    pub(super) request_width_b4: u32,
    pub(super) request_height_b4: u32,
    pub(super) overlap_width_b4: u32,
    pub(super) overlap_height_b4: u32,
    /// Horizontal (top) or vertical (left) destination offset in 4x4 units.
    pub(super) destination_offset_b4: u32,
}

#[derive(Clone, Copy)]
pub(super) struct ObmcContext<'a> {
    pub(super) top: [Option<ObmcNeighbor<'a>>; 4],
    pub(super) left: [Option<ObmcNeighbor<'a>>; 4],
}

#[derive(Clone, Copy)]
pub(super) struct InterIntraPrediction<'a> {
    pub(super) mode: u8,
    pub(super) wedge_index: Option<u8>,
    pub(super) edges: &'a FullIntraEdges,
}

#[derive(Clone, Copy)]
struct InterPrediction<'a> {
    references: [&'a FrameSurface; 2],
    scales: [ScaleFactors; 2],
    motions: [MotionVector; 2],
    block_x_b4: u32,
    block_y_b4: u32,
    compound: Option<PreparedCompound>,
    inter_intra: Option<InterIntraPrediction<'a>>,
    obmc: Option<ObmcContext<'a>>,
}

/// A compound blend that has already consumed and validated its entropy
/// sentence.  Keeping the prepared weight separate from
/// [`super::motion::CompoundType`]
/// prevents a single-reference block's default `Average` metadata from being
/// mistaken for an actual compound predictor. Mask signs remain explicit so
/// luma-derived difference masks and canonical wedge masks can share the
/// checked SIMD blender without losing their distinct chroma rules.
#[derive(Clone, Copy)]
pub(super) enum PreparedCompound {
    Average,
    Distance(u8),
    Difference(bool),
    Wedge { index: u8, inverted: bool },
}

/// Tile-local coefficient edges captured before an inter leaf is decoded.
///
/// Inter residual syntax is decoded one transform at a time, before the
/// completed block is published to [`TileState`].  Keeping the edge arrays in
/// a copy-only carrier lets the block decoder consume the existing tile
/// neighbors without borrowing or mutating the external state during
/// reconstruction. The arrays are intentionally bounded to the largest
/// admitted 128-pixel block edge (32 four-pixel cells); the remaining space
/// stays neutral for exact-length slicing at each transform.
#[derive(Clone, Copy)]
pub(super) struct InterCoefficientContexts {
    pub(super) above: [[u8; 32]; 3],
    pub(super) left: [[u8; 32]; 3],
}

/// Complete mode-2 transform topology for the large I420 128-axis blocks.
/// Root entries are 64x64 regions in raster order; child entries are the
/// corresponding 32x32 quadrants in the global 4x4 grid.
#[derive(Clone, Copy)]
pub(super) struct WideMode2Topology {
    pub(super) root_splits: [[bool; 2]; 2],
    pub(super) child_splits: [[bool; 4]; 4],
}

/// Complete TX64→TX32/TX16 topology for an exact B64x64 luma block.
///
/// Each entry describes one 32x32 child in raster order. A false entry owns
/// one TX32 terminal; a true entry owns four TX16 terminals. I420 keeps one
/// TX32 chroma terminal inheriting the TL origin; I422/I444 retain their
/// fixed TX32 grids and inherit each child's corresponding origin.
#[derive(Clone, Copy)]
pub(super) struct B64SplitTopology {
    pub(super) child_splits: [[bool; 2]; 2],
}

/// Mixed depth-two topology for an exact square inter leaf. The four entries
/// are ordered in raster order (TL, TR, BL, BR). A true child owns four
/// terminals at the next smaller transform size while a false child owns one
/// terminal at the shallow split size.
#[derive(Clone, Copy)]
pub(super) enum SquareSplitTopology {
    B16 { child_splits: [[bool; 2]; 2] },
    B32 { child_splits: [[bool; 2]; 2] },
}

/// Mixed depth-two topology for an exact rectangular inter leaf. The two
/// entries are ordered along the long axis: top/bottom for the vertical
/// variants and left/right for the horizontal variants. Exactly one entry
/// must be true; a true child owns the next-smaller transform grid while a
/// false child owns one terminal at the shallow split size.
#[derive(Clone, Copy)]
pub(super) enum RectSplitTopology {
    B4x16 { child_splits: [bool; 2] },
    B16x4 { child_splits: [bool; 2] },
    B8x16 { child_splits: [bool; 2] },
    B16x8 { child_splits: [bool; 2] },
    B8x32 { child_splits: [bool; 2] },
    B32x8 { child_splits: [bool; 2] },
    B16x64 { child_splits: [bool; 2] },
    B64x16 { child_splits: [bool; 2] },
    B32x64 { child_splits: [bool; 2] },
    B64x32 { child_splits: [bool; 2] },
    B16x32 { child_splits: [bool; 2] },
    B32x16 { child_splits: [bool; 2] },
}

/// Residual contexts published by one bounded lossless transform grid.
///
/// The terminal at the bottom-right supplies the scalar context for the next
/// plane/block.  The two edge vectors retain the last-column and last-row
/// contexts so a following partition can consume only the edge cells it
/// owns; unused entries remain neutral.
const LOSSLESS_GRID_EDGE_CAPACITY: usize = 32;

#[derive(Clone, Copy)]
struct LosslessGridContexts {
    bottom_right: u8,
    right: [u8; LOSSLESS_GRID_EDGE_CAPACITY],
    bottom: [u8; LOSSLESS_GRID_EDGE_CAPACITY],
}

#[derive(Clone, Copy)]
enum WideChromaTransformSource<'a> {
    Mode0Tx4(&'a [[Av1TransformType; 16]; 16]),
    Mode1Dct,
    Mode2UnsplitDct,
    Mode2Split32(&'a [[Av1TransformType; 2]; 2]),
    Mode2Deep16(&'a [[Av1TransformType; 4]; 4]),
    Mode2Mixed(&'a [[Av1TransformType; 4]; 4]),
}

#[derive(Clone, Copy)]
enum InterSplitQindexPolicy {
    PositiveOnly,
    Mode2SplitB8Rect,
    Mode2SplitB4LongRect,
    Mode2SplitB8WideRect,
    Mode2SplitB16WideRect,
    Mode2SplitB16Thin64,
    Mode2SplitB32Wide64Rect,
    Mode2SplitB16,
    Mode2SplitB32,
    Mode2SplitB64,
}

#[derive(Clone, Copy)]
enum Tx4ChromaTransformSource {
    Uniform(Av1TransformType),
    VerticalPair([Av1TransformType; 2]),
    VerticalQuad([Av1TransformType; 4]),
    Grid2x4([[Av1TransformType; 2]; 4]),
    Grid2x8([[Av1TransformType; 2]; 4]),
}

