    #[expect(
        clippy::too_many_arguments,
        reason = "split single-reference reconstruction carries block, frame, prediction, and transform callback state"
    )]
    pub(super) fn decode_inter_translation_split_b8(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        block_size: BlockSize,
        visible_width: u32,
        visible_height: u32,
        prepared_quantization: PreparedInterQuantization,
        tools: BlockTools,
        reference: &FrameSurface,
        scale: ScaleFactors,
        block_x_b4: u32,
        block_y_b4: u32,
        motion: MotionVector,
        filters: [InterpolationFilter; 2],
        coefficient_contexts: InterCoefficientContexts,
        decode_transform_type: impl FnMut(
            &mut RangeDecoder<'_, '_, '_>,
            TxSize,
        ) -> PortableResult<Av1TransformType>,
        deep_b64: bool,
        deep_rect: bool,
        b64_topology: Option<B64SplitTopology>,
        square_topology: Option<SquareSplitTopology>,
        rect_topology: Option<RectSplitTopology>,
        obmc: Option<ObmcContext<'_>>,
        inter_intra: Option<InterIntraPrediction<'_>>,
    ) -> PortableResult<FirstLeaf> {
        if (b64_topology.is_some() || square_topology.is_some() || rect_topology.is_some())
            && deep_b64
        {
            return Err(PortableUnavailable);
        }
        let transform_plan = match block_size {
            BlockSize::B8x8 => InterTransformPlan::SplitB8,
            BlockSize::B4x8 => InterTransformPlan::SplitB4x8,
            BlockSize::B8x4 => InterTransformPlan::SplitB8x4,
            BlockSize::B4x16
                if let Some(RectSplitTopology::B4x16 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB4x16Topology { child_splits }
            }
            BlockSize::B16x4
                if let Some(RectSplitTopology::B16x4 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB16x4Topology { child_splits }
            }
            BlockSize::B16x4 if deep_rect => InterTransformPlan::SplitB16x4Deep,
            BlockSize::B4x16 if deep_rect => InterTransformPlan::SplitB4x16Deep,
            BlockSize::B4x16 => InterTransformPlan::SplitB4x16,
            BlockSize::B16x4 => InterTransformPlan::SplitB16x4,
            BlockSize::B8x16
                if let Some(RectSplitTopology::B8x16 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB8x16Topology { child_splits }
            }
            BlockSize::B16x8
                if let Some(RectSplitTopology::B16x8 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB16x8Topology { child_splits }
            }
            BlockSize::B8x32
                if let Some(RectSplitTopology::B8x32 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB8x32Topology { child_splits }
            }
            BlockSize::B8x16 if deep_rect => InterTransformPlan::SplitB8x16Deep,
            BlockSize::B8x16 => InterTransformPlan::SplitB8x16,
            BlockSize::B16x8 if deep_rect => InterTransformPlan::SplitB16x8Deep,
            BlockSize::B16x8 => InterTransformPlan::SplitB16x8,
            BlockSize::B8x32 if deep_rect => InterTransformPlan::SplitB8x32Deep,
            BlockSize::B8x32 => InterTransformPlan::SplitB8x32,
            BlockSize::B32x8
                if let Some(RectSplitTopology::B32x8 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB32x8Topology { child_splits }
            }
            BlockSize::B16x64
                if let Some(RectSplitTopology::B16x64 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB16x64Topology { child_splits }
            }
            BlockSize::B64x16
                if let Some(RectSplitTopology::B64x16 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB64x16Topology { child_splits }
            }
            BlockSize::B32x64
                if let Some(RectSplitTopology::B32x64 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB32x64Topology { child_splits }
            }
            BlockSize::B64x32
                if let Some(RectSplitTopology::B64x32 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB64x32Topology { child_splits }
            }
            BlockSize::B32x8 if deep_rect => InterTransformPlan::SplitB32x8Deep,
            BlockSize::B32x8 => InterTransformPlan::SplitB32x8,
            BlockSize::B16x64 if deep_rect => InterTransformPlan::SplitB16x64Deep,
            BlockSize::B16x64 => InterTransformPlan::SplitB16x64,
            BlockSize::B64x16 if deep_rect => InterTransformPlan::SplitB64x16Deep,
            BlockSize::B64x16 => InterTransformPlan::SplitB64x16,
            BlockSize::B32x64 if deep_rect => InterTransformPlan::SplitB32x64Deep,
            BlockSize::B32x64 => InterTransformPlan::SplitB32x64,
            BlockSize::B64x32 if deep_rect => InterTransformPlan::SplitB64x32Deep,
            BlockSize::B64x32 => InterTransformPlan::SplitB64x32,
            BlockSize::B64x64 if let Some(topology) = b64_topology => {
                InterTransformPlan::SplitB64Topology {
                    child_splits: topology.child_splits,
                }
            }
            BlockSize::B16x16
                if let Some(SquareSplitTopology::B16 { child_splits }) = square_topology =>
            {
                InterTransformPlan::SplitB16Topology { child_splits }
            }
            BlockSize::B16x32
                if let Some(RectSplitTopology::B16x32 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB16x32Topology { child_splits }
            }
            BlockSize::B32x16
                if let Some(RectSplitTopology::B32x16 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB32x16Topology { child_splits }
            }
            BlockSize::B32x32
                if let Some(SquareSplitTopology::B32 { child_splits }) = square_topology =>
            {
                InterTransformPlan::SplitB32Topology { child_splits }
            }
            BlockSize::B64x64 if deep_b64 => InterTransformPlan::SplitB64Deep,
            BlockSize::B16x16 if deep_rect => InterTransformPlan::SplitB16Deep,
            BlockSize::B16x16 => InterTransformPlan::SplitB16,
            BlockSize::B16x32 if deep_rect => InterTransformPlan::SplitB16x32Deep,
            BlockSize::B16x32 => InterTransformPlan::SplitB16x32,
            BlockSize::B32x16 if deep_rect => InterTransformPlan::SplitB32x16Deep,
            BlockSize::B32x16 => InterTransformPlan::SplitB32x16,
            BlockSize::B32x32 if deep_rect => InterTransformPlan::SplitB32Deep,
            BlockSize::B32x32 => InterTransformPlan::SplitB32,
            BlockSize::B64x64 => InterTransformPlan::SplitB64,
            _ => return Err(PortableUnavailable),
        };
        self.decode_inter_translation_impl(
            decoder,
            block_size,
            visible_width,
            visible_height,
            prepared_quantization,
            tools,
            InterPrediction {
                references: [reference, reference],
                scales: [scale, scale],
                motions: [motion, MotionVector::ZERO],
                block_x_b4,
                block_y_b4,
                compound: None,
                inter_intra,
                obmc,
            },
            false,
            transform_plan,
            filters,
            coefficient_contexts,
            decode_transform_type,
        )
    }

    #[expect(
        clippy::too_many_arguments,
        reason = "split compound reconstruction carries block, frame, prediction, and transform callback state"
    )]
    pub(super) fn decode_inter_compound_translation_split_b8(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        block_size: BlockSize,
        visible_width: u32,
        visible_height: u32,
        prepared_quantization: PreparedInterQuantization,
        tools: BlockTools,
        references: [&FrameSurface; 2],
        scales: [ScaleFactors; 2],
        block_x_b4: u32,
        block_y_b4: u32,
        motions: [MotionVector; 2],
        compound: PreparedCompound,
        filters: [InterpolationFilter; 2],
        coefficient_contexts: InterCoefficientContexts,
        decode_transform_type: impl FnMut(
            &mut RangeDecoder<'_, '_, '_>,
            TxSize,
        ) -> PortableResult<Av1TransformType>,
        deep_b64: bool,
        deep_rect: bool,
        b64_topology: Option<B64SplitTopology>,
        square_topology: Option<SquareSplitTopology>,
        rect_topology: Option<RectSplitTopology>,
    ) -> PortableResult<FirstLeaf> {
        if (b64_topology.is_some() || square_topology.is_some() || rect_topology.is_some())
            && deep_b64
        {
            return Err(PortableUnavailable);
        }
        let transform_plan = match block_size {
            BlockSize::B8x8 => InterTransformPlan::SplitB8,
            BlockSize::B4x8 => InterTransformPlan::SplitB4x8,
            BlockSize::B8x4 => InterTransformPlan::SplitB8x4,
            BlockSize::B4x16
                if let Some(RectSplitTopology::B4x16 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB4x16Topology { child_splits }
            }
            BlockSize::B16x4
                if let Some(RectSplitTopology::B16x4 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB16x4Topology { child_splits }
            }
            BlockSize::B4x16 if deep_rect => InterTransformPlan::SplitB4x16Deep,
            BlockSize::B4x16 => InterTransformPlan::SplitB4x16,
            BlockSize::B16x4 => InterTransformPlan::SplitB16x4,
            BlockSize::B8x16
                if let Some(RectSplitTopology::B8x16 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB8x16Topology { child_splits }
            }
            BlockSize::B16x8
                if let Some(RectSplitTopology::B16x8 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB16x8Topology { child_splits }
            }
            BlockSize::B8x32
                if let Some(RectSplitTopology::B8x32 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB8x32Topology { child_splits }
            }
            BlockSize::B8x16 if deep_rect => InterTransformPlan::SplitB8x16Deep,
            BlockSize::B8x16 => InterTransformPlan::SplitB8x16,
            BlockSize::B16x8 if deep_rect => InterTransformPlan::SplitB16x8Deep,
            BlockSize::B16x8 => InterTransformPlan::SplitB16x8,
            BlockSize::B8x32 if deep_rect => InterTransformPlan::SplitB8x32Deep,
            BlockSize::B8x32 => InterTransformPlan::SplitB8x32,
            BlockSize::B32x8
                if let Some(RectSplitTopology::B32x8 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB32x8Topology { child_splits }
            }
            BlockSize::B16x64
                if let Some(RectSplitTopology::B16x64 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB16x64Topology { child_splits }
            }
            BlockSize::B64x16
                if let Some(RectSplitTopology::B64x16 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB64x16Topology { child_splits }
            }
            BlockSize::B32x64
                if let Some(RectSplitTopology::B32x64 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB32x64Topology { child_splits }
            }
            BlockSize::B64x32
                if let Some(RectSplitTopology::B64x32 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB64x32Topology { child_splits }
            }
            BlockSize::B32x8 if deep_rect => InterTransformPlan::SplitB32x8Deep,
            BlockSize::B32x8 => InterTransformPlan::SplitB32x8,
            BlockSize::B16x64 if deep_rect => InterTransformPlan::SplitB16x64Deep,
            BlockSize::B16x64 => InterTransformPlan::SplitB16x64,
            BlockSize::B64x16 if deep_rect => InterTransformPlan::SplitB64x16Deep,
            BlockSize::B64x16 => InterTransformPlan::SplitB64x16,
            BlockSize::B32x64 if deep_rect => InterTransformPlan::SplitB32x64Deep,
            BlockSize::B32x64 => InterTransformPlan::SplitB32x64,
            BlockSize::B64x32 if deep_rect => InterTransformPlan::SplitB64x32Deep,
            BlockSize::B64x32 => InterTransformPlan::SplitB64x32,
            BlockSize::B64x64 if let Some(topology) = b64_topology => {
                InterTransformPlan::SplitB64Topology {
                    child_splits: topology.child_splits,
                }
            }
            BlockSize::B16x16
                if let Some(SquareSplitTopology::B16 { child_splits }) = square_topology =>
            {
                InterTransformPlan::SplitB16Topology { child_splits }
            }
            BlockSize::B16x32
                if let Some(RectSplitTopology::B16x32 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB16x32Topology { child_splits }
            }
            BlockSize::B32x16
                if let Some(RectSplitTopology::B32x16 { child_splits }) = rect_topology =>
            {
                InterTransformPlan::SplitB32x16Topology { child_splits }
            }
            BlockSize::B32x32
                if let Some(SquareSplitTopology::B32 { child_splits }) = square_topology =>
            {
                InterTransformPlan::SplitB32Topology { child_splits }
            }
            BlockSize::B64x64 if deep_b64 => InterTransformPlan::SplitB64Deep,
            BlockSize::B16x16 if deep_rect => InterTransformPlan::SplitB16Deep,
            BlockSize::B16x16 => InterTransformPlan::SplitB16,
            BlockSize::B16x32 if deep_rect => InterTransformPlan::SplitB16x32Deep,
            BlockSize::B16x32 => InterTransformPlan::SplitB16x32,
            BlockSize::B32x16 if deep_rect => InterTransformPlan::SplitB32x16Deep,
            BlockSize::B32x16 => InterTransformPlan::SplitB32x16,
            BlockSize::B32x32 if deep_rect => InterTransformPlan::SplitB32Deep,
            BlockSize::B32x32 => InterTransformPlan::SplitB32,
            BlockSize::B64x64 => InterTransformPlan::SplitB64,
            _ => return Err(PortableUnavailable),
        };
        self.decode_inter_translation_impl(
            decoder,
            block_size,
            visible_width,
            visible_height,
            prepared_quantization,
            tools,
            InterPrediction {
                references,
                scales,
                motions,
                block_x_b4,
                block_y_b4,
                compound: Some(compound),
                inter_intra: None,
                obmc: None,
            },
            false,
            transform_plan,
            filters,
            coefficient_contexts,
            decode_transform_type,
        )
    }

