    #[expect(
        clippy::too_many_arguments,
        reason = "the bounded deep B64 transform compositor keeps prediction, entropy edges, quantization, and callback state explicit"
    )]
    fn decode_inter_split_luma_b64_deep(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        prediction: &[u16],
        raster: &mut PrivatePlaneRaster,
        quantization: LossyQuantization,
        tools: BlockTools,
        coefficient_contexts: InterCoefficientContexts,
        decode_transform_type: &mut impl FnMut(
            &mut RangeDecoder<'_, '_, '_>,
            TxSize,
        ) -> PortableResult<Av1TransformType>,
    ) -> PortableResult<(
        [[u8; 4]; 4],
        [u8; 16],
        [u8; 16],
        [[Av1TransformType; 2]; 2],
        Av1TransformType,
    )> {
        (prediction.len() == 4096
            && raster.coded_width == 64
            && raster.coded_height == 64
            && raster.active_width == 64
            && raster.active_height == 64
            && tools.sample_depth == quantization.sample_depth
            && matches!(tools.sample_depth.bits(), 8 | 10 | 12)
            && tools.transform_mode == 2
            && !quantization.segment_lossless)
            .then_some(())
            .portable()?;
        let above: [u8; 16] = std::array::from_fn(|index| coefficient_contexts.above[0][index]);
        let left: [u8; 16] = std::array::from_fn(|index| coefficient_contexts.left[0][index]);
        let mut residual_contexts = [[0x40_u8; 4]; 4];
        // Chroma TX32 terminals inherit the transform at the spatial
        // top-left TX16 terminal of their corresponding 32x32 luma quadrant.
        // Retain only that compact 2x2 source matrix after the luma grid is
        // reconstructed; all sixteen terminal transforms are not needed by
        // later planes.
        let mut coarse_transforms = [[Av1TransformType::DctDct; 2]; 2];
        let mut first_transform = Av1TransformType::DctDct;
        for child_row in 0_usize..2 {
            for child_column in 0_usize..2 {
                for local_row in 0_usize..2 {
                    for local_column in 0_usize..2 {
                        let row = child_row
                            .checked_mul(2)
                            .and_then(|value| value.checked_add(local_row))
                            .portable()?;
                        let column = child_column
                            .checked_mul(2)
                            .and_then(|value| value.checked_add(local_column))
                            .portable()?;
                        let above_context: [u8; 4] = if row == 0 {
                            let start = column.checked_mul(4).portable()?;
                            std::array::from_fn(|index| above[start.saturating_add(index)])
                        } else {
                            [residual_contexts[row - 1][column]; 4]
                        };
                        let left_context: [u8; 4] = if column == 0 {
                            let start = row.checked_mul(4).portable()?;
                            std::array::from_fn(|index| left[start.saturating_add(index)])
                        } else {
                            [residual_contexts[row][column - 1]; 4]
                        };
                        let txb_skipped = self.decode_inter_txb_skip(
                            decoder,
                            0,
                            TxSize::Tx16x16,
                            64,
                            64,
                            &above_context,
                            &left_context,
                            false,
                        )?;
                        let transform = if txb_skipped {
                            Av1TransformType::DctDct
                        } else {
                            decode_transform_type(decoder, TxSize::Tx16x16)?
                        };
                        if local_row == 0 && local_column == 0 {
                            coarse_transforms[child_row][child_column] = transform;
                            if row == 0 && column == 0 {
                                first_transform = transform;
                            }
                        }
                        let terminal = decode_inter_lossy_terminal(
                            decoder,
                            0,
                            &mut self.cdfs,
                            &mut self.large_coeff_arena,
                            quantization,
                            TxSize::Tx16x16,
                            64,
                            64,
                            &above_context,
                            &left_context,
                            txb_skipped,
                            transform,
                        )?;
                        let coefficients = if terminal.skipped {
                            None
                        } else {
                            Some(
                                self.large_coeff_arena
                                    .coefficients
                                    .get(..terminal.coefficient_count)
                                    .portable()?,
                            )
                        };
                        let offset_x = column.checked_mul(16).portable()?;
                        let offset_y = row.checked_mul(16).portable()?;
                        let mut child_prediction = Vec::new();
                        child_prediction
                            .try_reserve_exact(256)
                            .map_err(|_| PortableUnavailable)?;
                        for child_row in 0_usize..16 {
                            let source_row = offset_y.checked_add(child_row).portable()?;
                            let start = source_row
                                .checked_mul(64)
                                .and_then(|value| value.checked_add(offset_x))
                                .portable()?;
                            let end = start.checked_add(16).portable()?;
                            child_prediction
                                .extend_from_slice(prediction.get(start..end).portable()?);
                        }
                        let ReconstructionScratch { transform, .. } =
                            &mut self.reconstruction_scratch;
                        let TransformScratch { rows, residual, .. } = transform;
                        reconstruct_full_unsplit_prediction_in_place(
                            &mut child_prediction,
                            CoeffBlockRef {
                                width: 16,
                                height: 16,
                                coefficients,
                                transform: match terminal.transform {
                                    GenericTerminalTransform::Lossy(value) => value,
                                    GenericTerminalTransform::LosslessWht4x4 => {
                                        return Err(PortableUnavailable);
                                    }
                                },
                            },
                            tools.sample_depth,
                            rows,
                            residual,
                        )?;
                        raster.commit_transform(
                            offset_x,
                            offset_y,
                            16,
                            16,
                            &child_prediction,
                            tools.sample_depth,
                        )?;
                        residual_contexts[row][column] = terminal.residual_context;
                    }
                }
            }
        }
        let mut right = [0x40_u8; 16];
        for row in 0_usize..4 {
            let start = row.checked_mul(4).portable()?;
            right[start..start + 4].fill(residual_contexts[row][3]);
        }
        let mut bottom = [0x40_u8; 16];
        for column in 0_usize..4 {
            let start = column.checked_mul(4).portable()?;
            bottom[start..start + 4].fill(residual_contexts[3][column]);
        }
        Ok((
            residual_contexts,
            right,
            bottom,
            coarse_transforms,
            first_transform,
        ))
    }

    #[expect(
        clippy::too_many_arguments,
        reason = "the bounded B16x8 transform compositor keeps prediction, entropy edges, quantization, and callback state explicit"
    )]
    fn decode_inter_split_luma_b16x8(
        &mut self,
        decoder: &mut RangeDecoder<'_, '_, '_>,
        prediction: &[u16],
        raster: &mut PrivatePlaneRaster,
        quantization: LossyQuantization,
        tools: BlockTools,
        coefficient_contexts: InterCoefficientContexts,
        decode_transform_type: &mut impl FnMut(
            &mut RangeDecoder<'_, '_, '_>,
            TxSize,
        ) -> PortableResult<Av1TransformType>,
        qindex_policy: InterSplitQindexPolicy,
    ) -> PortableResult<([u8; 2], [u8; 2], [u8; 4], Av1TransformType)> {
        (prediction.len() == 128
            && raster.coded_width == 16
            && raster.coded_height == 8
            && raster.active_width == 16
            && raster.active_height == 8
            && tools.sample_depth == quantization.sample_depth
            && matches!(tools.sample_depth.bits(), 8 | 10 | 12)
            && tools.transform_mode == 2
            && (quantization.segment_qindex > 0
                || matches!(qindex_policy, InterSplitQindexPolicy::Mode2SplitB8Rect))
            && !quantization.segment_lossless)
            .then_some(())
            .portable()?;
        let above: [u8; 4] = std::array::from_fn(|index| coefficient_contexts.above[0][index]);
        let left: [u8; 2] = std::array::from_fn(|index| coefficient_contexts.left[0][index]);
        let mut residual_contexts = [0x40_u8; 2];
        let mut first_transform = Av1TransformType::DctDct;
        for column in 0_usize..2 {
            let above_start = column.checked_mul(2).portable()?;
            let above_context: [u8; 2] =
                std::array::from_fn(|index| above[above_start.saturating_add(index)]);
            let left_context = if column == 0 {
                left
            } else {
                [residual_contexts[column - 1]; 2]
            };
            let txb_skipped = self.decode_inter_txb_skip(
                decoder,
                0,
                TxSize::Tx8x8,
                16,
                8,
                &above_context,
                &left_context,
                false,
            )?;
            let transform = if txb_skipped {
                Av1TransformType::DctDct
            } else {
                decode_transform_type(decoder, TxSize::Tx8x8)?
            };
            if column == 0 {
                first_transform = transform;
            }
            let terminal = decode_inter_lossy_terminal(
                decoder,
                0,
                &mut self.cdfs,
                &mut self.large_coeff_arena,
                quantization,
                TxSize::Tx8x8,
                16,
                8,
                &above_context,
                &left_context,
                txb_skipped,
                transform,
            )?;
            let coefficients = if terminal.skipped {
                None
            } else {
                Some(
                    self.large_coeff_arena
                        .coefficients
                        .get(..terminal.coefficient_count)
                        .portable()?,
                )
            };
            let offset_x = column.checked_mul(8).portable()?;
            let mut child_prediction = Vec::new();
            child_prediction
                .try_reserve_exact(64)
                .map_err(|_| PortableUnavailable)?;
            for child_row in 0_usize..8 {
                let start = child_row
                    .checked_mul(16)
                    .and_then(|value| value.checked_add(offset_x))
                    .portable()?;
                let end = start.checked_add(8).portable()?;
                child_prediction.extend_from_slice(prediction.get(start..end).portable()?);
            }
            let ReconstructionScratch { transform, .. } = &mut self.reconstruction_scratch;
            let TransformScratch { rows, residual, .. } = transform;
            reconstruct_full_unsplit_prediction_in_place(
                &mut child_prediction,
                CoeffBlockRef {
                    width: 8,
                    height: 8,
                    coefficients,
                    transform: match terminal.transform {
                        GenericTerminalTransform::Lossy(value) => value,
                        GenericTerminalTransform::LosslessWht4x4 => {
                            return Err(PortableUnavailable);
                        }
                    },
                },
                tools.sample_depth,
                rows,
                residual,
            )?;
            raster.commit_transform(offset_x, 0, 8, 8, &child_prediction, tools.sample_depth)?;
            residual_contexts[column] = terminal.residual_context;
        }
        let mut right = [0x40_u8; 2];
        right.fill(residual_contexts[1]);
        let mut bottom = [0x40_u8; 4];
        bottom[..2].fill(residual_contexts[0]);
        bottom[2..].fill(residual_contexts[1]);
        Ok((residual_contexts, right, bottom, first_transform))
    }

